window.DATA_READER_XIA = [{"num": 81, "title_en": "A Heavy Price to Pay", "title_zh": "惨重的代价", "type": "reading", "category": "进阶短文与语法探究", "reading": {"en": ["Tom's father died of lung cancer. He couldn't stop smoking. He tried quitting several times. However, whenever he saw someone smoking, he couldn't resist lighting up. In the end, he gave up trying. It was no use stopping one day and starting again the next. He enjoyed smoking too much. He certainly paid a heavy price, though."], "zh": ["汤姆的父亲死于肺癌。他无法戒烟。他尝试戒了几次。不过，每当他看到有人抽烟时，他就无法抗拒要点根烟。最后，他放弃了尝试。因为一天停下来，第二天又开始是没有用的。他太喜欢抽烟了。不过，他也的确付出了惨重的代价。"], "sentences": [{"en": "Tom's father died of lung cancer.", "zh": "汤姆的父亲死于肺癌。"}, {"en": "He couldn't stop smoking.", "zh": "他无法戒烟。"}, {"en": "He tried quitting several times.", "zh": "他尝试戒了几次。"}, {"en": "However, whenever he saw someone smoking, he couldn't resist lighting up.", "zh": "不过，每当他看到有人抽烟时，他就无法抗拒要点根烟。"}, {"en": "In the end, he gave up trying.", "zh": "最后，他放弃了尝试。"}, {"en": "It was no use stopping one day and starting again the next.", "zh": "因为一天停下来，第二天又开始是没有用的。"}, {"en": "He enjoyed smoking too much.", "zh": "他太喜欢抽烟了。"}, {"en": "He certainly paid a heavy price, though.", "zh": "不过，他也的确付出了惨重的代价。"}]}, "dialog": null, "vocab": [{"num": 1, "word": "die ..", "phonetic": "", "pos": "of.", "meaning": "因··而死去", "examples": [{"en": "Steve's grandmother died of old age.", "zh": "史蒂夫的祖母是高龄去世的。"}], "sub_entries": ["die[dar]vi.死亡"]}, {"num": 2, "word": "lung cancer", "phonetic": "[laɡ kans]", "pos": "n.", "meaning": "肺癌", "examples": [], "sub_entries": []}, {"num": 3, "word": "smoke", "phonetic": "[smoʊk]", "pos": "vi.", "meaning": "&vt.抽烟", "examples": [{"en": "You can't smoke in an elevator. My father smokes a pack of cigarettes a day.", "zh": "你不能在电梯里面抽烟。）（我父亲每天要抽一包烟。"}], "sub_entries": []}, {"num": 4, "word": "try + 动名词", "phonetic": "", "pos": "短语", "meaning": "尝试做某事", "examples": [{"en": "If you want to lose weight, you should try exercising.", "zh": "如果你想减肥，就该试着运动看看。"}], "sub_entries": ["try[trai]vt.尝试"]}, {"num": 5, "word": "quit", "phonetic": "[kwit]", "pos": "vi.", "meaning": "&vt.停止", "examples": [{"en": "Studying music is not easy, but don't quit. The doctor told Jim to quit drinking coffee.", "zh": "学习音乐并不容易，但别放弃。）（医生叫吉姆不要再喝咖啡了。"}], "sub_entries": ["动词三态均为quit。"]}, {"num": 6, "word": "whenever", "phonetic": "[hwenˈev／wenˈev]", "pos": "conj.", "meaning": "无论何时，每当", "examples": [{"en": "I feel sad whenever I read a love story.", "zh": "每当我看爱情小说时我就觉得很伤感。"}], "sub_entries": []}, {"num": 7, "word": "resist", "phonetic": "[rˈzist]", "pos": "vt.", "meaning": "抗拒", "examples": [{"en": "If you are on a diet, you have to resist eating fattyfoods.", "zh": "如果你在节食，你应该抗拒吃油腻的食物。"}], "sub_entries": []}, {"num": 8, "word": "light up", "phonetic": "", "pos": "短语", "meaning": "点火（不及物动词短语）", "examples": [{"en": "You u can't light up here; smoking isn't allowed.", "zh": "你不能在这里点烟，这里是不准抽烟的。"}], "sub_entries": []}, {"num": 9, "word": "in the end", "phonetic": "", "pos": "短语", "meaning": "最后", "examples": [{"en": "It looked like our team was going to lose the game, but in the end we won.", "zh": "看起来好像我们的球队要输了这场球，但最后我们赢了。"}], "sub_entries": []}, {"num": 10, "word": "give ..", "phonetic": "", "pos": "up.", "meaning": "放弃··.·", "examples": [{"en": "John gave up studying French because it was too difficult for him.", "zh": "约翰放弃学法文，因为法文对他而言太难了。"}], "sub_entries": []}, {"num": 11, "word": "It", "phonetic": "", "pos": "", "meaning": "is no use+动名词", "examples": [{"en": "It's no use talking to her; she's not going to listen.", "zh": "跟她讲是没用的，因为她根本不会听。"}], "sub_entries": ["·…是没有用的"]}, {"num": 12, "word": "enjoy", "phonetic": "[ɪnˈdʒɔɪ]", "pos": "vt.", "meaning": "喜欢", "examples": [{"en": "My brother enjoys riding horses, but I'm afraid of them.", "zh": "我哥哥很喜欢骑马，但我很怕马。"}], "sub_entries": []}, {"num": 13, "word": "certainly", "phonetic": "[ˈsatanli]", "pos": "adv.", "meaning": "必然地，当然地", "examples": [{"en": "I certainly enjoyed the Beijing opera last night.", "zh": "我当然很喜欢昨晚演出的京剧。"}], "sub_entries": []}, {"num": 14, "word": "pay a heavy price", "phonetic": "", "pos": "短语", "meaning": "付出惨重／很大的代价", "examples": [], "sub_entries": ["pay [pe ]vt.付", "动词三态：pay，paid，paid。", "heavy['hevi]a.沉重的", "price [prais ] n.代价"]}], "grammar": {"intro": "本课介绍少数及物动词之后须接动名词作宾语的用法。", "items": [{"num": 1, "title": "He couldn't stop smoking.", "body": ["（他无法戒烟。）", "He enjoyed smoking too much.（他太喜欢抽烟了。）以上两句中的smoking均作及物动词stop及 enjoyed的宾语。下列及物动词均须用动名词作宾语：", "enjoy喜欢 practice['praktis]练习 resent[r'zent]愉恨 mind介意 resist[r'zist]抗拒 finish['finif]完成 deny[dr'na1]否认 admit[ad'mit]承认", "例: I enjoy to sing.(×)", "-→ I enjoy singing. (○)（我喜欢唱歌。）He admitted to steal my money. (×)", "→He admitted stealing my money. (○)（他承认偷了我的钱。）She practices to play_the piano two hours a day.(×)", "→ She practices playing the piano two hours a day.(○)（她每天都花两个小时练习弹钢琴。）", "注意：", "a. 有些及物动词如like（喜欢），love（喜爱），hate（痛恨）等，可使用动词不定式或动名词作其宾 语。", "例：I like（或love） to work with him.", "=I like（或love）working withhim.（我喜欢跟他共事。）", "I hate to tell lies.", "=I hate telling lies.（我痛恨说谎。）", "b. stop smoking 戒烟", "=quit smoking", "=give up smoking", "例: I stopped smoking three years ago.（我三年前就戒烟了。）", "The chain smoker tried very hard to give up smoking, but he couldn't.（这位瘾君子拼命设法戒烟，但就是戒不掉)思，以动名词作其宾语。但stop亦可作不及物动 词，表示“停止”的意思，之后接动词不定式，表 示“停止某件事，而改做另一件事”的意思。即：", "stop+动名词停止从事….…stopto+动词原形 停下来开始·····", "例: John stopped talkingtome whenhis father walked in.（约翰的父亲走进来时，约翰就把和我的谈话 打住了。）", "John stopped to talk to me when he saw me.（约翰看到我时，便停下来与我谈话。）"]}, {"num": 2, "title": "He tried quitting several times.", "body": ["（他尝试戒了几次。）try可接动词不定式作其宾语，此时try表示“设法 要...….”的意思·而在本句中，tried则以动名词为其 下：", "tryto+动词原形 设法要.... try+名词／动名词尝试／试试....…", "例: I'll try to call you later today.（我今天晚一点会设法打电话给你。）", "If this way doesn't work, try another way.（如果这个方法行不通，试试另外一个方法。）Don't ever try swimming alone in the river.（千万不要尝试单独在河里游泳。）"]}, {"num": 3, "title": "It was no use stopping one day and starting the next.", "body": ["（一天停下来，第二天又开始是没有用的…—戒烟戒 戒停停是没有用的一一三天打鱼两天晒网是没有用 的。）", "注意：", "a. 此处thenext是 thenextday的省略。", "b. Itisnouse+动名词", "·是没有用的", "例: It is no use learning without thinking.（学而不思则罔。）"]}]}, "substitution": [{"num": 1, "pairs": [{"en": "He couldn't stop smoking.", "zh": "他无法戒烟。"}, {"en": "Do you mind smoking somewhere else?", "zh": "你介意到别处去抽烟吗？"}, {"en": "Will you finish writing your term paper today?", "zh": "你今天可以完成你的学期报告吗？"}, {"en": "Did the man deny stealing the money?", "zh": "那个男人否认偷钱吗？"}], "en": "He couldn't stop smoking.", "zh": "他无法戒烟。"}, {"num": 2, "pairs": [{"en": "It was no use stopping one day and starting the next.", "zh": "一天停下来，第二天又开始是没有用的。"}, {"en": "It is no use crying over spilt milk.", "zh": "覆水难收。—谚语。"}], "en": "It was no use stopping one day and starting the next.", "zh": "一天停下来，第二天又开始是没有用的。"}], "exercises": null}, {"num": 82, "title_en": "Smoking Isn't Allowed", "title_zh": "不准吸烟", "type": "dialogue", "category": "情境实战会话", "reading": null, "dialog": {"turns": [{"speaker_en": "Usher", "speaker_zh": "引座员", "en": "Would you mind putting out your cigarette?", "zh": "请你把烟熄掉好吗？"}, {"speaker_en": "Betty", "speaker_zh": "贝蒂", "en": "I'll just finish smoking this one, OK?", "zh": "我只要把这一根抽完，好吗？"}, {"speaker_en": "Usher", "speaker_zh": "引座员", "en": "Smoking isn't allowed in movie theaters.", "zh": "戏院里是不准吸烟的。"}, {"speaker_en": "Betty", "speaker_zh": "贝蒂", "en": "Oh, I'm sorry. 贝蒂正在看电影。", "zh": "哦，很抱歉。"}]}, "vocab": [{"num": 1, "word": "put ..", "phonetic": "", "pos": "out.", "meaning": "熄灭（火、香烟等）", "examples": [{"en": "The firemen quickly put out the fire.", "zh": "消防队员很快地将火扑灭了。"}], "sub_entries": []}, {"num": 2, "word": "cigarette", "phonetic": "[ˈsiɡa.ret]", "pos": "n.", "meaning": "香烟", "examples": [], "sub_entries": ["a pack of cigarettes", "一包香烟", "a carton of cigarettes", "一条香烟（十包装）"]}, {"num": 3, "word": "allow", "phonetic": "[alau]", "pos": "vt.", "meaning": "允许", "examples": [{"en": "Our teacher doesn't allow us to read comic books.", "zh": "老师不准我们看漫画。）·"}], "sub_entries": ["allow+人+to+动词原形", "尤许某人···"]}, {"num": 4, "word": "movie theater", "phonetic": "[ˈmuvɪ ˈθiətə]", "pos": "n.", "meaning": "电影院", "examples": [], "sub_entries": []}], "grammar": null, "substitution": [], "exercises": {"prompt": "Ⅲ：请选出下列各句中正确的一项", "questions": ["1. I finished", "at about 7:00 p.m.", "(A) to work", "(B)working", "(C) works", "(D) with working", "2. She began", "English three years ago.", "(A) to study", "(B) his study", "(C) with studies", "(D) study", "3. A: Can I park here?", "B: No. We don't allow", "here.", "(A) to park", "(B) parking", "(C) parks", "(D) you park", "4. 1 often practice", "English with my teacher.", "(A) to speak", "(B) speaking", "(C) to say", "(D) saying", "5.Father doesn't", "(A) allow our children smoking", "(B)allow us children to smoke", "(C) allow for smoking", "(D) allow of smoking"], "answers": ["解答1.(B）2.(A）3.(B)4.(B）5.(B)"]}}, {"num": 83, "title_en": "A Nice Person", "title_zh": "大好人", "type": "reading", "category": "进阶短文与语法探究", "reading": {"en": ["Shelly doesn't like people who are unreliable. She especially doesn't like people who tell lies. On the other hand, she likes people who are humorous and honest. She really likes people that are easygoing and sincere. However, regardless of whom she likes or dislikes, she is nice to everyone."], "zh": ["谢莉不喜欢不可靠的人。她特别不喜欢说谎的人。另一方面，她喜欢那些幽默又诚实的人。她实在喜欢随和又诚恳的人。然而，不论她喜欢谁或不喜欢谁，她对每个人都很好。"], "sentences": [{"en": "Shelly doesn't like people who are unreliable.", "zh": "谢莉不喜欢不可靠的人。"}, {"en": "She especially doesn't like people who tell lies.", "zh": "她特别不喜欢说谎的人。"}, {"en": "On the other hand, she likes people who are humorous and honest.", "zh": "另一方面，她喜欢那些幽默又诚实的人。"}, {"en": "She really likes people that are easygoing and sincere.", "zh": "她实在喜欢随和又诚恳的人。"}, {"en": "However, regardless of whom she likes or dislikes, she is nice to everyone.", "zh": "然而，不论她喜欢谁或不喜欢谁，她对每个人都很好。"}]}, "dialog": null, "vocab": [{"num": 1, "word": "unreliable", "phonetic": "[Anrrlarabl]", "pos": "a.", "meaning": "不可靠的；不稳定的", "examples": [{"en": "Jim's car is very unreliable. It's always breaking down.", "zh": "吉姆的车子非常不稳定。它经常出故障。"}], "sub_entries": []}, {"num": 2, "word": "especially", "phonetic": "[ɪˈspeʃəli]", "pos": "adv.", "meaning": "特别地", "examples": [{"en": "I like sleeping late, especially on Sundays.", "zh": "我喜欢睡到很晚，尤其是在星期天。"}], "sub_entries": []}, {"num": 3, "word": "lie", "phonetic": "[lar]", "pos": "n.", "meaning": "谎言&vi.说谎", "examples": [{"en": "Don't lie to me; I'm your father.", "zh": "别对我说谎，我是你父亲。"}], "sub_entries": []}, {"num": 4, "word": "on the other hand", "phonetic": "", "pos": "短语", "meaning": "另-方面", "examples": [{"en": "The food at that restaurant is great. On the other hand, it is expensive.", "zh": "那家餐厅的食物很棒，但就另一方面来说，它的价格也很昂贵。"}], "sub_entries": []}, {"num": 5, "word": "humorous", "phonetic": "[ˈhjumaras]", "pos": "a.", "meaning": "有幽默感的", "examples": [], "sub_entries": []}, {"num": 6, "word": "honest", "phonetic": "[ˈanist]", "pos": "a.", "meaning": "诚实的", "examples": [], "sub_entries": []}, {"num": 7, "word": "easygoing", "phonetic": "[ˈizrˈɡoin]", "pos": "", "meaning": "a．随遇而安的，从容不迫的", "examples": [{"en": "You're too tense. You should be more easygoing.", "zh": "你太紧张了。你应该轻松自在一点。"}], "sub_entries": []}, {"num": 8, "word": "sincere", "phonetic": "[sinˈsir]", "pos": "a.", "meaning": "诚恳的", "examples": [], "sub_entries": []}, {"num": 9, "word": "regardless ..", "phonetic": "", "pos": "of.", "meaning": "不论····", "examples": [{"en": "Regardless of whom you are talking to, you should always be polite.", "zh": "不论你和谁说话，你都应该随时注意礼貌。"}], "sub_entries": ["regardless[rr'gardlis ]a.不论，不管"]}, {"num": 10, "word": "dislike", "phonetic": "[disˈlaik]", "pos": "vt.", "meaning": "不喜欢，讨厌", "examples": [], "sub_entries": []}], "grammar": {"intro": "本课主要介绍关系代词的种类及用法。", "items": [{"num": 1, "title": "Shelly doesn't like people who are unreliable.", "body": ["（谢莉不喜欢不可靠的人。）", "She really likes people that are easygoing and sincere.（她实在喜欢随和又诚恳的人。）以上两句中的who及that所引导的从句称作定语从 句，各修饰之前的名词people。第二句的that就等 于第一句的who，称作关系代词。"]}, {"num": 2, "title": "五大关系代词（who, whom, which, that, whose）的用法", "body": ["关系代词一共有 who、whom、which、that、whose 五个，均视为连词，引导定语从句。该从句视为形容词，修饰之前的名词。兹分项说明这些关系代词的用法：", "a. who、whom 这两个关系代词专门修饰人，换言之，who、whom之前一定有一个表示人的名词。who在从 句中作主语，whom则作宾语。请先看下列的例子：", "John is my good friend, he never lies. (×)（约翰是我的好友，他从不说谎。）这是个错误的句子，因为\"John is my good friend”与“heneverlies\"分别是两个独立句子，两句仅有逗号相隔，却无连词连接。此时我们可将 第二个句子的主语he改为作主语的关系代词who，即成：", "John is my good friend, who never lies. (O）（约翰是我的好友，他从不说谎。）请再看下列的例子：", "John is my good friend, I trust him. (×)（约翰是我的好友'我信任他。）这也是错误的句子，因为\"John is my good friend”与\"Itrusthim\"两句仅有逗号相隔，却无 连词连接。此时我们已知第二句的宾语him指的 就是第一句句尾的mygood friend，故将him 改 为作宾语用的关系代词whom，即成：", "John is my good friend, I trust whom. (×)但关系代词应紧邻被代替的名词后，故应将whom 置于第二句主语I之前，即成：", "John is my good friend, whom I trust. (○)（约翰是我的好友'我信任他。）", "b. which which是用以代替除人以外一切事物（如动物、植 物、静物、地方、概念等）的关系代词，在所引导 的定语从句中，可作主语或宾语。使用时之前一定 要有可被代替（除人以外）的名词。", "例：I love dogs, they are faithful to their", "masters.（x)（我喜欢狗，它们对主人很忠心。）以上两句无连词连接。应将第二个句子的主语 they改为which，即成：", "I love dogs, which are faithful to their A masters.（我喜欢狗，它们对主人很忠心。）又例：", "He doesn't study, it makes his father angry.（×)（他不念书，这点令他父亲生气。）以上两句无连词连接·应将第二个句子的it改为 which，代替前面整个句子“He doesn't study”所 表示的概念，即成：", "-> He doesn't study, which makes his father angry. (O.)（他不念书，这点令他父亲生气。）又例：", "He lives in Shanghai, I want to visit the city soon.（×）（他住在上海，我希望很快能到这城市走一趟。）以上两句无连词连接，由于 the city指的就是 Shanghai，故 the city应改为 which，即成：", "He lives in Shanghai, I want to visit which soon.（×)由于关系代词均应紧邻被代替的名词之后，故上句 应改为：", "He lives in Shanghai, which I want to visit soon.（O）（他住在上海，我希望很快能到这城市走一-趟。）", "c. whose whose 是所有格关系代词，代替his、her、their·its 等人或物的所有格代词。whose之后应置名 词，即\"whose+名词”。\"whose+名词”在所引 导的定语从句中可作主语或宾语。", "例: He is John, his father is my teacher.(×)（他是约翰，他的父亲是我的老师。）", "以上两句无连词连接。应将his 改为whose，即 成：", "He is John, whose father is my teacher.(○)A（他是约翰，他的父亲是我的老师。）又例：", "He is John, I used to teach his son. (×)（他是约翰，我以前曾经教过他的儿子。）以上两句无连词连接。应将his 改为whose，即 成：", "He is John, I used to teach whose son. (×)由于所有格关系代词与关系代词-一样，均应紧邻被 代替的名词之后，故上句应改为：", "He is John, whose son I used to teach. (○)（他是约翰，我以前曾经教过他的儿子。）又例：", "I like this watch, its workmanship is good.（×)（我喜欢这只手表，它的做工不错。）以上两句无连词连接。应将 its 改为whose，即成：", "I like this watch, whose workmanship is good.(○)（我喜欢这只手表，它的做工不错。）", "d. that that 亦可作关系代词，可等于who、whom 或 which。但that之前不可置逗号。who、whom 或which之前则视需要置逗号或不置逗号。", "例：He is the man whom you can trust.", "=He is the man that you can trust.（他是你可以信赖的人。）", "She really likes people who are easygoing and sincere.", "=She really likes people that are easygoing and sincere.（她实在喜欢随和又诚恳的人。）", "Where is the watch which I bought yesterday?", "= Where is the watch that I bought yesterday?（我昨天买的那只手表在哪里？）John is my friend, that I trust. (×)", "→ John is my friend, whom I trust. (○)（约翰是我的朋友，我信任他。）"]}, {"num": 3, "title": "关系代词的限制性修饰及非限制性修饰用法", "body": ["a. 限制性修饰", "关系代词引导的定语从句旨在修饰名词，使该名词 有其特殊性，此时关系代词之前不置逗号，译成中 文时，先译定语从句（译成“.….··的”），再译被修 饰的名词·这种之前无逗号的定语从句就是限制性 修饰。英文:He is a person who never lies. 中文：他是个人，他从不说谎。（×）他是个丛不说谎的人。（○）", "b. 非限制性修饰", "有些名词本身就具有特殊性，如gentleman（君 子）、saint（圣人）。或该名词之前已有形容词修 饰，增加其特殊性，如a good person（好人）、a great man（伟人）。此时这些名词之后若有定 语从句修饰时，该从句并非必要，只是附加说明主 语而已，故关系代词之前可置逗号，以减低该从句 的重要性·这种之前有逗号的定语从句就是非限制 性修饰·译成中文时，先译被修饰的名词，再译之 后的定语从句。英文:He is a gentleman, who never lies.（他是君子，从不说谎。）He is a great man, whom everyone respects.（他是伟人，大家都尊敬他。）不过以上两句亦可采限制性修饰，以更增加被修饰 的名词之特殊性。即：", "He is a gentleman who never lies.（他是个从不说谎的君子。）He is a great man whom everyone respects.（他是个人人尊敬的伟人。）c．专有名词（如John、Peter、Shanghai）或少数 的名词（如my father、his mother）本身就有普 遍强烈的特殊性（即一提到这些名词，大家都知道 指的是谁），故之后的定语从句一定采非限制性修 饰，即关系代词之前一定要有逗号。", "例: Here comes Mary who is my girlfriend.（×)（那个是我女友的玛丽来了。一~一暗示我另外 可能还有别的女友。)", "→Here comes Mary, who is my girlfriend.（o)（玛丽来了，她是我的女友。）I wish to visit Guilin whose scenery is beautiful.(×)（我希望到那个风景很美的桂林走一趟。一 暗示可能还有别的城市也叫桂林，那儿的景色 很差。）", "→I wish to visit Guilin, whose scenery is beautiful.(○)（我希望到桂林走一趟，那儿的风景很美。）I know his father who teaches us English.（×)（我认识他那位教我们英语的父亲。一—暗示他 可能还有别的父亲，那个父亲可能教法语。)>I know his father, who teaches us English.（0）（我认识他父亲，他父亲教我们英语。）"]}]}, "substitution": [{"num": 1, "pairs": [{"en": "Shelly doesn't like people who are unreliable.", "zh": "谢莉不喜欢不可靠的人。"}], "en": "Shelly doesn't like people who are unreliable.", "zh": "谢莉不喜欢不可靠的人。"}, {"num": 2, "pairs": [{"en": "Shelly likes people that are patient and kind.", "zh": "谢莉喜欢那些有耐心又亲切的人。"}], "en": "Shelly likes people that are patient and kind.", "zh": "谢莉喜欢那些有耐心又亲切的人。"}, {"num": 3, "pairs": [{"en": "Shelly has a brother whom I like very much.", "zh": "谢莉有一位我非常喜欢的兄弟。"}], "en": "Shelly has a brother whom I like very much.", "zh": "谢莉有一位我非常喜欢的兄弟。"}, {"num": 4, "pairs": [{"en": "Shelly, whose father is my boss, is very rich.", "zh": "谢莉很有钱，她的父亲是我的老板。"}], "en": "Shelly, whose father is my boss, is very rich.", "zh": "谢莉很有钱，她的父亲是我的老板。"}, {"num": 5, "pairs": [{"en": "Paul doesn't like animals which are vicious.", "zh": "保罗不喜欢那些凶恶的动物。"}], "en": "Paul doesn't like animals which are vicious.", "zh": "保罗不喜欢那些凶恶的动物。"}, {"num": 6, "pairs": [{"en": "Tammy attends the university which I graduated from.", "zh": "黛咪念的那所大学是我母校。"}], "en": "Tammy attends the university which I graduated from.", "zh": "黛咪念的那所大学是我母校。"}], "exercises": null}, {"num": 84, "title_en": "What's She Like?", "title_zh": "她是什么样的人呢？", "type": "dialogue", "category": "情境实战会话", "reading": null, "dialog": {"turns": [{"speaker_en": "Anna", "speaker_zh": "安娜", "en": "Hi, Larry! Would you like to meet my roommate, Sally?", "zh": "嗨，拉里！你要不要见-见我的室友萨莉？"}, {"speaker_en": "Larry", "speaker_zh": "拉里", "en": "Sure. What's she like?", "zh": "好啊·她是什么样的人呢？"}, {"speaker_en": "Anna", "speaker_zh": "安娜", "en": "She's just your type.", "zh": "她是属于你这一型的。"}, {"speaker_en": "Larry", "speaker_zh": "拉里", "en": "What do you mean?", "zh": "你是什么意思啊？"}, {"speaker_en": "Anna", "speaker_zh": "安娜", "en": "She's just like you, a bookworm.", "zh": "她就像你一样，是个书呆子。"}]}, "vocab": [{"num": 1, "word": "Would you like to + 动词原形？", "phonetic": "", "pos": "句型", "meaning": "你想要...吗？", "examples": [{"en": "Would you like to go to the school dance with me?", "zh": "你要不要和我一起去参加学校的舞会？"}, {"en": "I would like to go swimming with them. = I'd like to go swimming with them.", "zh": "我想要跟他们游泳去。（比较：I like to go swimming with them. 我喜欢跟他们去游泳。）"}], "sub_entries": ["本句型用于表达客气的邀请、询问或建议。"]}, {"num": 2, "word": "meet", "phonetic": "[miːt]", "pos": "vt.", "meaning": "会见，与.….….见面", "examples": [], "sub_entries": []}, {"num": 3, "word": "roommate", "phonetic": "[ˈrum.met]", "pos": "n.", "meaning": "室友", "examples": [], "sub_entries": []}, {"num": 4, "word": "bookworm", "phonetic": "[ˈbuk.wɚm]", "pos": "n.", "meaning": "书呆子", "examples": [], "sub_entries": []}], "grammar": null, "substitution": [], "exercises": {"prompt": "Ⅲ·请选出下列各句中正确的一项", "questions": ["1. She is the woman", "I love.", "(A) whom", "(B) which", "(C) who", "(D) whose", "2. That is the zoo", "I went to last weekend.", "(A)which", "(B) of", "(C) and", "(D) when", "3. I really like this watch,", "price is very", "reasonable.", "(A) its", "(B) whose", "(C) that", "(D)and", "4.This is the suit", "I'm going to wear for the", "party.", "(A) that", "(B)where", "(C) and", "(D) who", "5. She is a famous movie star,", "everyone", "loves..", "(A) whom", "(B) which", "(C) who", "(D) she", "6. 1", "go to the movies with them, but I don't", "have the time.", "(A) wouldn't like to", "(B) would like", "(C) would like to", "(D) like to would to"], "answers": ["解答1.(A)2.(A)3.(B)4.(A)5.(A)6.(C)"]}}, {"num": 85, "title_en": "Blood Types", "title_zh": "血型", "type": "reading", "category": "进阶短文与语法探究", "reading": {"en": ["Some people believe that one's personality is related to one's blood type. There are three main blood types: A, B and O. Type A people are introverts whereas type O people are extroverts. Type B people are a mixture of both A and O. They are more relaxed and don't get bothered easily. When it comes to choosing a spouse, remember some of these facts."], "zh": ["有些人相信一个人的个性与他的血型有关。一共有三种主要的血型：A型、B型及O型。A型人内向而O型人则外向·B型人是A型和O型的混合，他们比较轻松自在而且不容易觉得烦·谈到择偶的时候，切记以上这些事实。"], "sentences": [{"en": "Some people believe that one's personality is related to one's blood type.", "zh": "有些人相信一个人的个性与他的血型密切相关。"}, {"en": "There are three main blood types: A, B and O.", "zh": "主要有三种常见血型：A型、B型及O型。"}, {"en": "Type A people are introverts whereas type O people are extroverts.", "zh": "A型人通常较内向，而O型人则外向活泼。"}, {"en": "Type B people are a combination of types A and O. They are more relaxed and don't get upset easily.", "zh": "B型人兼具A型与O型的特质，更随和开朗且不易烦躁。"}, {"en": "Keep these facts in mind when looking for a husband or wife.", "zh": "在寻找人生伴侣时，不妨牢记这些有趣的特点。"}]}, "dialog": null, "vocab": [{"num": 1, "word": "blood type", "phonetic": "[ˈblad .taip]", "pos": "n.", "meaning": "血型", "examples": [], "sub_entries": []}, {"num": 2, "word": "personality", "phonetic": "[ˌpɜːrsəˈnæləti]", "pos": "n.", "meaning": "个性", "examples": [], "sub_entries": []}, {"num": 3, "word": "be related to...", "phonetic": "[rɪˈleɪtɪd]", "pos": "短语", "meaning": "与...有关", "examples": [{"en": "A: Is Mike related to Jim? B: Yes. They're cousins.", "zh": "甲：迈克与吉姆有关系吗？ 乙：有的。他们是表兄弟。"}], "sub_entries": ["related [rɪˈleɪtɪd] a. 有关连的"]}, {"num": 4, "word": "main", "phonetic": "[men]", "pos": "a.", "meaning": "主要的", "examples": [{"en": "What is the main point of this lesson?", "zh": "这一课的重点是什么？"}], "sub_entries": []}, {"num": 5, "word": "introvert", "phonetic": "[ˈɪntrəvɜːrt]", "pos": "n.", "meaning": "内向的人", "examples": [], "sub_entries": []}, {"num": 6, "word": "whereas", "phonetic": "[ˌweərˈæz]", "pos": "conj.", "meaning": "而，然而", "examples": [{"en": "Apples are red whereas bananas are yellow.", "zh": "苹果是红色的而香蕉则是黄色的。"}], "sub_entries": []}, {"num": 7, "word": "extrovert", "phonetic": "[ˈekstrəvɜːrt]", "pos": "n.", "meaning": "外向的人", "examples": [], "sub_entries": []}, {"num": 8, "word": "mixture", "phonetic": "[ˈmɪkstʃər]", "pos": "n.", "meaning": "混合", "examples": [], "sub_entries": []}, {"num": 9, "word": "relaxed", "phonetic": "[rɪˈlækst]", "pos": "a.", "meaning": "感到轻松自在的", "examples": [{"en": "When I drink tea, I feel very relaxed.", "zh": "喝茶时，我便觉得很轻松自在。"}], "sub_entries": []}, {"num": 10, "word": "bothered", "phonetic": "[ˈbɑːðərd]", "pos": "a.", "meaning": "烦（恼）的，感到讨厌的", "examples": [{"en": "Jessica gets bothered when people smoke cigarettes in her house.", "zh": "当有人在杰西卡的屋子里抽烟时她便觉得很讨厌。"}], "sub_entries": []}, {"num": 11, "word": "when it comes to + 名词/动名词", "phonetic": "", "pos": "短语", "meaning": "一谈到...，涉及...时", "examples": [{"en": "When it comes to spelling, Sam is the best in our class.", "zh": "说到拼字，萨姆是我们班上最行的。"}], "sub_entries": ["一说到····…·"]}, {"num": 12, "word": "spouse", "phonetic": "[spauz]", "pos": "n.", "meaning": "配偶", "examples": [], "sub_entries": []}], "grammar": {"intro": "本课介绍名词性从句的形成及用法。 Some people believe that one's personality is related to one's blood type. =Some people believe one's personality is related to one's blood type. （有些人相信一个人的个性与他的血型有关。） 上句中\"that one's personality is related to one's blood type”称作名词性从句，因作及物动词believe 的宾语，故that可省略。以下为名词性从句的种类及其 功能：", "items": [{"num": 1, "title": "名词性从句的种类", "body": ["a. that引导的名词性从句", "这种从句乃由陈述句变化而成。我们在陈述句之前 冠以that，即成名词性从句。陈述句：He works hard.（他很努力。）名词性从句：that he works hard（他很努力）", "b. whether（是否）引导的名词性从句", "这种从句乃由一般疑问句（即可用Yes或No回答的问句）变化而成。在一般疑问句前冠以 whether，原倒装的句子结构还原成不倒装的型态 即成名词性从句。", "1)be 动词 一般疑问句：Is he happy?（他快乐吗？）", "名词性从句：whether he is happy（他是否快乐）", "2）助动词（如can、will、have等）", "一般疑问句：Will he come?（他会来吗？）Have you been to Xi'an?（你去过西安吗？）名词性从句：whether he will come（他是否会来）whether you have been to Xi'an（你是否去过西安）", "3）do、does、did等助动词引导的疑问句变成 名词性从句时，先冠以whether，次将do does或did去除，疑问句中的动词原形再按 do、does、did及主语还原成应有的时态。一般疑问句：Do they like it?（他们喜欢它吗？）", "Does she hate him?（她恨他吗？）Did you go there?（你去了那里吗？）名词性从句：whether they like it（他们是否喜欢它）whether she hates him（她是否恨他）whether you went there（你是否去了那里）", "c. 疑问词（what、where、when、how、why、who等）引导的名词性从句\n这种从句乃由特殊疑问句（即不能用Yes或No回答的问句）变化而成。我们保留原疑问词，原来倒装的句子结构还原成不倒装的型态而成名词性从句。", "1）be 动词 特殊疑问句：Who is he?（他是谁？）", "Whose bike is this?（这是谁的自行车？）名词性从句：who he is（他是谁）whose bike this is(这是谁的自行车)", "2）助动词 特殊疑问句：When will he come?（他什么时候会来？）", "What has he done?（他做了什么？）名词性从句：when he will come（他什么时候会来）what he has done（他做了什么）", "3）含有do、does、did 的疑问句 此类疑问句变成名词性从句时，先保留句首的 疑问词，次将 do、does 或did 去除，疑问句 中的动词原形按do、does或did及主语还原 成应有的时态。特殊疑问句：How did he do it?（他如何做这件事情的？）", "Why do they want to leave?（他们为什么要离开？）Which does she like?（她喜欢哪一个？）Whom did he see?（他看到谁了？）名词性从句：how he did it（他如何做这件事情的）why they want to leave（他们为什么要离开）which she likes（她喜欢哪一个）whom he saw（他看到谁了）", "注意：", "特殊疑问句中，若疑问代词who、what、which作主语，该疑问句变成名词性从句时，句子结构不变。特殊疑问句：Who will come?主语（谁会来？）名词性从句：who will come（谁会来）特殊疑问句：What happened?主语（发生什么事了？）名词性从句：what happened（发生什么事了）特殊疑问句：Which has been bought?主语（哪一个被买了下来？）名词性从句：which has been bought（哪一个被买了下来）"]}, {"num": 2, "title": "名词性从句的功能", "body": ["名词性从句可说是一种用作名词的句子，所不同的是：", "第一，从句之前一定要有that、whether 或疑问词(who、when等);第二，从句不能做句子使用，换言之，从句不能独立 存在。", "例：That he works hard.（×，此为从句）", "He works hard.（O，此为句子）Who he is？（×，此为从句）Whoishe？（O，此为特殊疑问句）Whether he will come？（×，此为从句）Willhecome？（O，此为一般疑问句）名词性从句与名词-样，在句中可用作主语、及物动 词的宾语、或置于be动词之后作主语补足语。", "a. 主语", "例: That he is a good student is true.（他是好学生，这是事实。）", "Whether he'll come is not known yet.（他是否会来尚不得而知。）How he'll do it is still a mystery.（他将如何做这件事仍是个谜。）", "注意：", "名词性从句作主语时，往往会形成主语过大 的毛病，故一般皆用代词it代替这些从句，形成下列句子结构：", "It is true that he is a good student.", "It is not known yet whether he'll come.", "It is still a mystery how he'll do it.", "b. 宾语：", "例：I believe that he can do it.", "vt.（我相信他能做这件事。）I don't know whether he'll come. vt.（我不知道他是否会来。）He asked me where I live. vt.（他问我住在何处。）", "注意：", "1）that引导的名词性从句作及物动词的宾语 时，that可予省略。例]: I believe that he can do it.", "=I believe he can do it.（我相信他能做这件事。）", "2）whether引导的名词性从句作及物动词的 宾语时，whether可被if取代，if仍译成“是否”而非“如果”。", "例: I don't know whether he'll come.", "=I don't know if he'll come.（我不知道他是否会来。）", "c. 主语补足语", "例: The truth is that he has no money.（事实的真相是他没钱。）", "The question is whether he'll come.（问题是他是否会来。）The trouble is when we can finish it.（问题是我们什么时候才能做完这件事。）"]}]}, "substitution": [{"num": 1, "pairs": [{"en": "Some people believe that one's personality is related to one's blood type.", "zh": "有些人相信一个人的个性与他的血型有关。"}], "en": "Some people believe that one's personality is related to one's blood type.", "zh": "有些人相信一个人的个性与他的血型有关。"}, {"num": 2, "pairs": [{"en": "I don't know how he is going to handle the problem.", "zh": "我不知道他准备如何来处理这个问题。"}], "en": "I don't know how he is going to handle the problem.", "zh": "我不知道他准备如何来处理这个问题。"}, {"num": 3, "pairs": [{"en": "Whether one's personality is related to one's blood type has not been proved.", "zh": "一个人的个性与他的血型是否有关尚未证实。"}], "en": "Whether one's personality is related to one's blood type has not been proved.", "zh": "一个人的个性与他的血型是否有关尚未证实。"}], "exercises": null}, {"num": 86, "title_en": "What's Your Blood Type?", "title_zh": "你是什么血型？", "type": "dialogue", "category": "情境实战会话", "reading": null, "dialog": {"turns": [{"speaker_en": "Bella", "speaker_zh": "贝拉", "en": "What's your blood type, Luke?", "zh": "卢克，你是什么血型？"}, {"speaker_en": "Luke", "speaker_zh": "卢克", "en": "It's A, I think. Why do you ask?", "zh": "我想是A型。你问这干嘛？"}, {"speaker_en": "Bella", "speaker_zh": "贝拉", "en": "Well, mine's B.", "zh": "，我的血型是B。"}, {"speaker_en": "Luke", "speaker_zh": "卢克", "en": "So?", "zh": "那又怎么样呢？"}, {"speaker_en": "Bella", "speaker_zh": "贝拉", "en": "They say people with A blood type get along very well with those with B blood type.", "zh": "据说A型的人与B型的人相处得很好。"}, {"speaker_en": "Luke", "speaker_zh": "卢克", "en": "Really?", "zh": "真的吗？"}]}, "vocab": [{"num": 1, "word": "Well,", "phonetic": "", "pos": "B.", "meaning": "咂，我的血型是B。", "examples": [], "sub_entries": ["= Well, my blood type is B."]}, {"num": 2, "word": "They say people with A blood type get along", "phonetic": "", "pos": "短语", "meaning": "据说A型的人与B型的人相处得很好。", "examples": [{"en": "They say that swimming is the best kind of exercise. b. get along well with...", "zh": "有人说游泳是最好的运动。）与...·相处得很好"}, {"en": "Mary gets along well with her younger sister.", "zh": "玛丽和她妹妹处得很好。"}], "sub_entries": ["very well with those with B blood type.", "= They say that people with A blood type get", "along very well with people with B blood type.", "a. They say that...", "据说……···有人说…··", "= It is said that..."]}], "grammar": null, "substitution": [], "exercises": {"prompt": "Ⅲ·请选出下列各句中正确的一项", "questions": ["1. No one cares when", "arrive.", "(A) will we (B) do we (C)we will (D) can we", "2. Bill knows who", "(A) our teacher is", "(B) is our teacher", "(C) teacher is our", "(D） the teacher is ours", "3.", "youngest girl is the smartest in the class", "is amazing.", "(A) Is the (B) That (C) That the (D) The", "4.Fred is the only one that believed", "(A) what did Nancy say", "(B) what did Nancy said", "(C) what Nancy said", "(D) what will Nancy say", "5. We can only guess", "come.", "(A)whether will he", "(B) whether he will", "(C) he will whether", "(D) will he", "6.1", "him; he has a terrible temper.", "(A) can't get alone with", "(B) can't get even with", "(C) can't get well with", "(D) can't get along with"], "answers": ["解答→1.(C)2.(A）3.(C)4.(C）5.(B）6.(D)"]}}, {"num": 87, "title_en": "Society Is Changing Rapidly", "title_zh": "社会正快速地变化", "type": "reading", "category": "进阶短文与语法探究", "reading": {"en": ["Society is changing rapidly. As a result, more and more people are suffering from stress. Those who are stressed out are often nervous, angry or ill. People must, therefore, learn to deal with this \"new\" kind of problem. Regular exercise is one way. The best way, however, is to keep a good sense of humor."], "zh": ["社会正快速地变化。因此，越来越多的人正遭受压力之苦。凡是压力过大的人经常会紧张、生气或生病·因此，人们必须学会处理这种“新”问题。规律的运动是一种方法。不过，最好的方法就是保持良好的幽默感。"], "sentences": [{"en": "Society is changing rapidly.", "zh": "社会正快速地变化。"}, {"en": "As a result, more and more people are suffering from stress.", "zh": "因此，越来越多的人正遭受压力之苦。"}, {"en": "Those who are stressed out are often nervous, angry or ill.", "zh": "凡是压力过大的人经常会紧张、生气或生病。"}, {"en": "People must, therefore, learn to deal with this \"new\" kind of problem.", "zh": "因此，人们必须学会处理这种“新”问题。"}, {"en": "Regular exercise is one way.", "zh": "规律的运动是一种方法。"}, {"en": "The best way, however, is to keep a good sense of humor.", "zh": "不过，最好的方法就是保持良好的幽默感。"}]}, "dialog": null, "vocab": [{"num": 1, "word": "society", "phonetic": "[səˈsaɪəti]", "pos": "n.", "meaning": "社会", "examples": [{"en": "Killer Carl is a danger to society.", "zh": "杀手卡尔对社会是一种危害。"}], "sub_entries": ["*使用该单词时，通常不与冠词并用。"]}, {"num": 2, "word": "change", "phonetic": "[tʃeɪndʒ]", "pos": "vi.", "meaning": "收变", "examples": [{"en": "May really changed. She used to be ugly; now she's beautiful.", "zh": "梅真的变了·她以前很丑，但现在她很美。"}], "sub_entries": []}, {"num": 3, "word": "rapidly", "phonetic": "[ˈræpɪdli]", "pos": "adv.", "meaning": "迅速地", "examples": [{"en": "Our society is changing rapidly.", "zh": "我们的社会正在快速地变化。"}], "sub_entries": []}, {"num": 4, "word": "suffer ..", "phonetic": "", "pos": "from.", "meaning": "遭受···…", "examples": [{"en": "My dad suffers from high blood pressure.", "zh": "我爸爸患有高血压。"}], "sub_entries": ["suffer['sAfo]vi.遭受，患（病）"]}, {"num": 5, "word": "stress", "phonetic": "[stres]", "pos": "n.", "meaning": "压力，紧张", "examples": [{"en": "Paul's new job gives him a lot of stress. Jack is stressedout because he has too much work.", "zh": "保罗的新工作给他很大的压力。）（杰克因为工作太多而饱受压力。"}], "sub_entries": ["stressed[strest ]a.紧张的，有压力的", "be stressed out", "饱受压力"]}, {"num": 6, "word": "nervous", "phonetic": "[ˈnɜːrvəs]", "pos": "a.", "meaning": "紧张的", "examples": [], "sub_entries": []}, {"num": 7, "word": "angry", "phonetic": "", "pos": "a.", "meaning": "生气的", "examples": [], "sub_entries": []}, {"num": 8, "word": "ill", "phonetic": "[l]", "pos": "a.", "meaning": "生病的", "examples": [], "sub_entries": []}, {"num": 9, "word": "deal ..", "phonetic": "", "pos": "with.", "meaning": "应付….…，处理...···", "examples": [{"en": "I don't know how that mother deals with so many children.", "zh": "我不知道那位母亲是如何应付这么多孩子的。"}], "sub_entries": ["deal[dil]vi.处理"]}, {"num": 10, "word": "regular", "phonetic": "[ˈreɡjala]", "pos": "a.", "meaning": "规律的", "examples": [{"en": "It is important to have regular meals.", "zh": "规律的饮食是很重要的。"}], "sub_entries": []}, {"num": 11, "word": "exercise", "phonetic": "[εksosaiz]", "pos": "n.", "meaning": "运动（不可数）", "examples": [{"en": "Fred does exercise at six o'clock every morning.", "zh": "弗雷德每天早上六点钟都从事运动。"}], "sub_entries": ["do exercise", "从事运动（美式用法）", "take exercise", "从事运动（英式用法）"]}, {"num": 12, "word": "sense of humor", "phonetic": "", "pos": "短语", "meaning": "幽默感", "examples": [{"en": "People who have a sense of humor are very popular.", "zh": "有幽默感的人很受欢迎。"}], "sub_entries": ["humor['hjuma ]n.幽默"]}], "grammar": {"intro": "本课介绍more andmore作形容词及副词的用法，另外 介绍\"thosewho..\"（凡是.…的人）的用法及however、 therefore作插人语的用法。", "items": [{"num": 1, "title": "As a result, more and more people are suffering from stress.", "body": ["（因此，越来越多的人正遭受压力之苦。）moreandmore可作形容词或副词，多用于进行时 的句子中，用法如下：", "a. 作形容词", "more andmore译成“越来越多的”，之后接复 数名词或不可数名词。: More and more students are learning 复数名词 English.（学英文的学生越来越多了。）He is making more and more money. 不可数名词（他的钱越挣越多了。）", "b. 作副词", "moreandmore译成“越来越多”，之后接副词 或形容词。", "例:He is doing things more and more carefully.", "adv.（他做事越来越谨慎了。）", "She is getting more and more beautiful.", "a.（她变得越来越漂亮了。）", "注意：", "被修饰的形容词或副词若属单音节（偶有两个音 节），则通常直接将该形容词或副词变成比较级，形成下列用法：", "比较级+and+比较级", "例：His English is getting moreand more", "good.（×)", "→His English is getting better and better.(○)（他的英文越求越好了。）He is walking more and more fast. (×)", "→He is walking faster and faster. (○)（他走得越来越快了。）"]}, {"num": 2, "title": "Those who are stressed out are often nervous, angry or ill.", "body": ["（凡是压力过大的人经常会紧张、生气或生病。）本句分析如下：", "a. 代词Those（那些人，等于People）作主语；", "b. Those 之后的who are stressed out 是关系代词 who所引导的定语从句，作限制性修饰（who之 前无逗号），修饰Those；", "c. are则为be 动词，之后的often是副词，修饰该 be动词；", "d. nervous、angry及 ill 以并列连词or连接，共作 主语的补足语。thosewho...+复数动词 凡是...·的人·…··", "=onewho...+单数动词", "=hewho...+单数动词 m: Those who work hard are sure to succeed.", "=One who works hard is sure to succeed.", "=He who works hard is sure to succeed.（凡是努力的人一定会成功。）"]}, {"num": 3, "title": "People must, therefore, learn to deal with this \"new\" kind of problem.", "body": ["（因此，人们必须学会处理这种“新”问题。）The best way, however, is to keep a good sense of humor.（不过，最好的方法就是保持良好的幽默感。）以上两句中的therefore（因此）及however（然 而、不过）均为插人在句中的副词。它们亦均可置于 句首，即：", "Therefore, people must learn to deal with this \"new\" kind of problem. However, the best way is to keep a good sense of humor.", "注意：", "therefore或however 插人在句中时，这两个字两旁 应各置一逗号；习惯的用法是，它们多插于主语与动 词之间，助动词（如will、can、may）与动词之间，或主语与助动词之间。", "a. 主语与动词之间", "例: He is nice. I, therefore, like him.", "主语·动词（他人很好，因此我喜欢他。）This car is good. That one, however, is 主语 动词 bad.（这辆车不错，不过那一辆却不好。）", "b. 助动词与动词之间／主语与助动词之间", "例: Father gave me some money yesterday. 1 can , therefore, buy a pen.", "助动词 动词", "=Father gave me some money yesterday. I , 主语 therefore, can buy a pen. 助动词（昨天父亲给了我一些钱，因此我可买枝笔 了。）"]}]}, "substitution": [{"num": 1, "pairs": [{"en": "More and more people are suffering from stress.", "zh": "越来越多的人正遭受压力之苦。"}, {"en": "More and more people are moving to the city.", "zh": "越来越多的人正搬到城市去。"}, {"en": "This tree is getting taller and taller every day.", "zh": "这棵树每天越长越高。"}, {"en": "Sandy's grades are getting better and better.", "zh": "珊蒂的成绩越来越好。"}], "en": "More and more people are suffering from stress.", "zh": "越来越多的人正遭受压力之苦。"}, {"num": 2, "pairs": [{"en": "People must, therefore, learn to deal with this problem.", "zh": "因此，人们必须学会处理这种问题。"}, {"en": "Joe is too fat. He should, therefore, go on a diet.", "zh": "乔太胖了。因此，他必须节食。"}, {"en": "My wife and I argue a lot. I, however, still love her.", "zh": "我和太太经常争吵。不过，我仍然爱她。"}, {"en": "It's supposed to rain today. However, it is sunny now.", "zh": "今天应该会下雨。不过，现在是晴天。"}], "en": "People must, therefore, learn to deal with this problem.", "zh": "因此，人们必须学会处理这种问题。"}], "exercises": null}, {"num": 88, "title_en": "You Need a Vacation", "title_zh": "你需要度个假", "type": "dialogue", "category": "情境实战会话", "reading": null, "dialog": {"turns": [{"speaker_en": "Shirley", "speaker_zh": "雪莉", "en": "What's the matter, Luke? You look stressed out.", "zh": "卢克，你怎么了？你看来像是受到很大的压力。"}, {"speaker_en": "Luke", "speaker_zh": "卢克", "en": "I'm under a lot of pressure at work.", "zh": "我在工作上受到很大的压力。"}, {"speaker_en": "Shirley", "speaker_zh": "雪莉", "en": "You need a long vacation.", "zh": "你需要度个长假。"}, {"speaker_en": "Luke", "speaker_zh": "卢克", "en": "I know, but I really don't have the time.", "zh": "我知道，但我真地没有时间。"}]}, "vocab": [{"num": 1, "word": "What's", "phonetic": "", "pos": "", "meaning": "the matter（with you)？（你）怎么了？", "examples": [{"en": "A: What's the matter with you? B: I just failed my French exam.", "zh": "甲：你怎么了？）（乙：我的法文测验考砸了。"}], "sub_entries": ["= What's wrong (with you)?", "= What happened (to you)?"]}, {"num": 2, "word": "be under a lot of pressure", "phonetic": "", "pos": "短语", "meaning": "受到很大的压力", "examples": [{"en": "Some people work better when they are under a lot of pressure.", "zh": "有些人在受到很大的压力时会作得比较好。"}], "sub_entries": ["pressure['pref ]n.压力"]}, {"num": 3, "word": "at work", "phonetic": "", "pos": "短语", "meaning": "在工作中，上班中", "examples": [{"en": "Steve is at work fixing the car in the garage.", "zh": "史蒂夫正在车库里修车。"}], "sub_entries": []}, {"num": 4, "word": "vacation", "phonetic": "[veˈkejan]", "pos": "n.", "meaning": "假期", "examples": [], "sub_entries": []}], "grammar": null, "substitution": [], "exercises": {"prompt": "Ⅲ·请选出下列各句中正确的一项", "questions": ["1. Bobby is getting", "(A) taller and taller", "(B) more and more tall", "(C) worser and worser", "(D) more and more good", "2. Roger is becoming", "every day.", "(A) more and more intelligent", "(B) intelligently and intelligently", "(C) carefully and carefully", "(D） quicklier and quicklier", "3. George studies very hard. He,", ",has good", "grades.", "(A) however (B) therefore (C) so (D) a result", "4. 1 like to read books. I don't,", "，like love", "stories.", "(A) therefore", "(B） although", "(C) however", "(D) as a result", "5. Those who", "hard workers", "also", "successful.", "(A) is, is", "(B) is, are", "(C) are, is", "(D) are, are", "6. Connie's crying again.", "her this time?", "(A)What's matter with", "(B) What's wrong with", "(C) What's the wrong with", "(D) What's happened with"], "answers": ["解答>1.(A）2.(A）3.(B）4.(C）5.(D）6.(B)"]}}, {"num": 89, "title_en": "Australia", "title_zh": "澳大利亚", "type": "reading", "category": "进阶短文与语法探究", "reading": {"en": ["Australia is a unique country. It's the world's largest island, but it's also the world's smallest continent. In fact, Australia is the only country that is also a continent. It's about the size of the United States, but it has a population of only 16.5 million. If it sounds like an interesting place to visit, that's because it is."], "zh": ["澳大利亚是一个非常独特的国家。它是世界上最大的岛，但它也是世界上最小的洲。事实上，澳大利亚是唯一也是个洲的国家。它大约与美国-样大，但它的人口却只有1650万。如果它听起来像是个值得走访的好去处的话·那是因为它的确是个值得走访的好去处。"], "sentences": [{"en": "Australia is a fascinating country.", "zh": "澳大利亚是一个充满魅力的国家。"}, {"en": "It is located in the Southern Hemisphere, between the Pacific and Indian oceans.", "zh": "它位于南半球，地处太平洋与印度洋之间。"}, {"en": "It is famous for unique animals such as kangaroos and koalas.", "zh": "它以袋鼠和考拉等独特的野生动物闻名于世。"}, {"en": "Although it is as large as the United States, its population is relatively small.", "zh": "尽管其国土面积与美国相当，但人口却相对较少。"}, {"en": "If you are looking for an exciting vacation, Australia is definitely worth visiting.", "zh": "如果你渴望一次精彩难忘的假期，澳大利亚绝对值得一游。"}]}, "dialog": null, "vocab": [{"num": 1, "word": "Australia", "phonetic": "[ɔːˈstreɪliə]", "pos": "n.", "meaning": "澳洲；澳大利亚", "examples": [], "sub_entries": []}, {"num": 2, "word": "unique", "phonetic": "[juˈnik]", "pos": "a.", "meaning": "独特的", "examples": [{"en": "Mary has a unique way of walking.", "zh": "玛丽走路的方式很奇特。"}], "sub_entries": []}, {"num": 3, "word": "island", "phonetic": "[ˈailand]", "pos": "n.", "meaning": "岛（屿）", "examples": [], "sub_entries": []}, {"num": 4, "word": "continent", "phonetic": "[ˈkontanant]", "pos": "n.", "meaning": "洲", "examples": [], "sub_entries": []}, {"num": 5, "word": "be ..", "phonetic": "", "pos": "of.", "meaning": "约...一样大", "examples": [{"en": "Bill's living room is about the size of my house.", "zh": "比尔家的客厅大约和我整个家一样大。"}], "sub_entries": ["about[abaut ] adv.大约", "size[saiz]n.大小，面积"]}, {"num": 6, "word": "population", "phonetic": "", "pos": "n.", "meaning": "人", "examples": [{"en": "Hong Kong has a population of about six million people.", "zh": "香港大约有六百万人口。"}], "sub_entries": []}, {"num": 7, "word": "sound like + 名词", "phonetic": "", "pos": "短语", "meaning": "听起来像...", "examples": [{"en": "Your voice sounds very much like your mother's.", "zh": "你的声音听起来很像你母亲。"}], "sub_entries": ["听起来像····", "sound[saund]vi.听起来"]}, {"num": 8, "word": "visit", "phonetic": "[ˈvizit]", "pos": "vt.", "meaning": "拜访", "examples": [{"en": "Gary visited his sick grandmother yesterday.", "zh": "昨天加里去探望他生病的祖母。"}], "sub_entries": []}], "grammar": {"intro": "本课介绍关系代词that使用的时机，并介绍知觉动词的 用法。", "items": [{"num": 1, "title": "In fact, Australia is the only country that is also a continent.", "body": ["（事实上，澳大利亚是唯一也是个洲的国家。)本句中的 that是关系代词，理论上等于which，但因 之前的名词用 theonly（唯一的）来修饰，故此处仅 能使用that。下列情况中必须使用that取代关系代词who whom或which:", "a. 在有最高级形容词修饰的名词之后", "例：He is the best student whom nI'veever", "taught. (×)-→He is thebest student(that)）I'veever taught. (○)（他是我所教过最好的学生。）*that 因作taught 的宾语，故可省略。", "b. 在有 the only 修饰的名词之后", "例: He is the only boy who knows the answer.（劣）", "→ He is the only boy that knows the answer.（佳）（他是唯一知道答案的男孩。）", "c. 在有序数词（如thefirst、thesecond...thelast）", "修饰的名词之后", "例：The last question which he asked was", "interesting.（x)", "→The last question (that) he asked was interesting. (○)（他问的最后…个问题很有趣。）"]}, {"num": 2, "title": "It's about the size of the United States...", "body": ["= It's about as large as the United States.,..（它大约与美国一样大...·）", "a. 本句的about是副词，表示“大约”的意思，通常 用以修饰数字。", "例：About thirty students passed the exam.（这次考试大约有30个学生考及格了。）", "b. be the size of... 与·…··…一般大小（一样大）", "例: The baby's eyes are the size of a penny.（那个婴儿的眼睛和一分钱的硬币一样大。）"]}, {"num": 3, "title": "If it sounds like an interesting place to visit, that's because it is.", "body": ["", "=If it sounds like an interesting place to visit, that's because it is an interesting place to visit.（如果它听起来像是个值得走访的好去处的话，那是 因为它的确是个值得走访的好去处。）", "注意：", "a. 原句because itis之后省略了aninteresting place tovisit，以避免与主句重复。", "b. sound like+名词 听起来像···知觉动词一共有下列五个：", "sound 听起来 look 看起来 feel 觉得 taste 尝起来 smell 闻起来 这些知觉动词之后应置形容词作主语补足语。", "例:The idea sounds good.", "a.（这个主意听起来不错。）", "The flower smells bad.", "a.（这朵花不好闻。）", "但这些知觉动词后亦可置like（像），此时like 为介词，之后再置名词作其宾语。sound like+名词 听起来像··looklike+名词 看起来像··feel like+名词 觉得像····. taste like+名词 尝起来像·smell like+名词 闻起来像···", "例: It sounds like a good idea.", "n.（这听起来像个好主意。）", "I felt like an ugly duck before the", "n. beautiful girl.（在这位漂亮的女孩子面前，我觉得自已像只丑 小鸭。）"]}]}, "substitution": [{"num": 1, "pairs": [{"en": "Australia is the only country that is also a continent.", "zh": "澳大利亚是唯·也是个洲的国家。"}, {"en": "Paul is the only boy in our class that is from Nanjing.", "zh": "保罗是我们班上唯一来自南京的男孩。"}, {"en": "Chinese food is the only kind of food that Mary likes.", "zh": "中国菜是玛丽唯一喜欢的食物。"}], "en": "Australia is the only country that is also a continent.", "zh": "澳大利亚是唯·也是个洲的国家。"}, {"num": 2, "pairs": [{"en": "If it sounds like an interesting place to visit, that's because it is.", "zh": "如果它听起来像是个值得走访的好去处的话，那是因为它的确是个值得走访的好去处。"}, {"en": "If they look like intelligent children, that's because they are.", "zh": "如果他们看起来像是聪明的孩子的话，那是因为他们的确是聪明的孩子。"}, {"en": "That ballerina looks graceful when she dances.", "zh": "那位女芭蕾舞者跳舞时看起来很优雅。"}, {"en": "That piece of cloth feels like silk.", "zh": "那块布感觉起来像丝。"}], "en": "If it sounds like an interesting place to visit, that's because it is.", "zh": "如果它听起来像是个值得走访的好去处的话，那是因为它的确是个值得走访的好去处。"}], "exercises": null}, {"num": 90, "title_en": "A Good Place to Visit", "title_zh": "一个好玩的地方", "type": "dialogue", "category": "情境实战会话", "reading": null, "dialog": {"turns": [{"speaker_en": "Donna", "speaker_zh": "唐娜", "en": "Where's a good place to visit, Richie?", "zh": "瑞琪，哪儿有好玩的地方啊？"}, {"speaker_en": "Richie", "speaker_zh": "瑞琪", "en": "Phuket.", "zh": "普吉岛。"}, {"speaker_en": "Donna", "speaker_zh": "唐娜", "en": "Phu...what?", "zh": "普什么？"}, {"speaker_en": "Richie", "speaker_zh": "瑞琪", "en": "Phuket, in Thailand. It's a beautiful resort island with fantastic beaches.", "zh": "泰国的普吉岛。那是个拥有很棒海滩的美丽度假岛屿。"}, {"speaker_en": "Donna", "speaker_zh": "唐娜", "en": "Wow! Sounds great!", "zh": "哇！听起来眞棒！"}]}, "vocab": [{"num": 1, "word": "Phuket", "phonetic": "[puˈke]", "pos": "n.", "meaning": "普吉岛（地名）", "examples": [], "sub_entries": []}, {"num": 2, "word": "Thailand", "phonetic": "[ˈtailand]", "pos": "n.", "meaning": "泰国", "examples": [], "sub_entries": []}, {"num": 3, "word": "resort", "phonetic": "[riˈzart]", "pos": "n.", "meaning": "度假胜地", "examples": [], "sub_entries": []}, {"num": 4, "word": "fantastic", "phonetic": "[fenˈtestik]", "pos": "a.", "meaning": "很棒的（=wonderful,", "examples": [{"en": "That singer has a fantastic voice.", "zh": "那位歌手的嗓音很棒。"}], "sub_entries": ["great)"]}, {"num": 5, "word": "beach", "phonetic": "[bitf]", "pos": "n.", "meaning": "海滩", "examples": [], "sub_entries": []}, {"num": 6, "word": "wow", "phonetic": "[waʊ]", "pos": "int.", "meaning": "哇（表惊叹、喜悦、痛苦等）", "examples": [], "sub_entries": []}, {"num": 7, "word": "Sounds great!", "phonetic": "", "pos": "日常口语", "meaning": "听起来眞棒！", "examples": [], "sub_entries": ["=That/It sounds great!"]}], "grammar": null, "substitution": [], "exercises": {"prompt": "Ⅲ·请选出下列各句中正确的一项", "questions": ["1.Billy thinks French food", "delicious.", "(A) seems (B) tastes (C) taste (D) look", "2. lf they", "like brothers, that's because they", "(A) looks, are", "(B)look, is", "(C) look, are", "(D) smell, are", "3. The last job", "he had was very boring.", "(A)where(B) that(C)when(D)who", "4. Your dress", "beautiful.", "(A) tastes (B)looks (C) smell (D) are", "5. Rich Ricky's house is", "a castle.", "(A) about same as", "(B) about the size as", "(C) about the large of", "(D) about the size of", "6. Mack : Let's go to the beach today.", "Grace:", ". I love swimming.", "(A) That sounds like good", "(B）That looks fine", "(C) That sounds great", "(D) That feels so nice"], "answers": ["解答1.(B）2.(C）3.(B）4.(B）5.(D）6.(C)"]}}, {"num": 91, "title_en": "Computers", "title_zh": "电子计算机", "type": "reading", "category": "进阶短文与语法探究", "reading": {"en": ["Computers are becoming a part of our everyday life. in fact, they are almost everywhere. In many countries, more and more companies are replacing people with computers. Telephone companies are no exception. When making a long-distance call on a pay phone in America, you will no longer talk to an operator. Instead, a computer will answer. It will tell you what to do. No wonder people say that computers are taking over the world."], "zh": ["电子计算机正渐渐成为我们日常生活的一部分。事实上，它们几乎无所不在。在许多国家有越来越多的公司使用电子计算机来取代人。电话公司也不例外。在美国，当你使用投币电话打长途电话时，你不再对总机说话。相反地，电子计算机会来答话。"], "sentences": [{"en": "Computers have revolutionized the modern world.", "zh": "电子计算机深刻变革了现代世界。"}, {"en": "They are used in schools, offices, hospitals and homes.", "zh": "学校、办公室、医院和千家万户都离不开计算机。"}, {"en": "With computers, we can store huge amounts of data and solve complex problems quickly.", "zh": "借助计算机，我们能储存海量数据并迅速解决复杂难题。"}, {"en": "Moreover, the internet connects computers worldwide, making communication faster than ever.", "zh": "此外，互联网将全球计算机紧密相连，让信息传递前所未有地迅捷。"}, {"en": "However, we shouldn't rely on computers too much.", "zh": "然而，我们也不应过度依赖电子设备。"}, {"en": "After all, human creativity and critical thinking are irreplaceable.", "zh": "毕竟，人类的创造力与独立思考是永远无可替代的。"}]}, "dialog": null, "vocab": [{"num": 1, "word": "computer", "phonetic": "[kamˈpjuta]", "pos": "n.", "meaning": "电子计算机", "examples": [], "sub_entries": []}, {"num": 2, "word": "a ..", "phonetic": "", "pos": "of.", "meaning": "·…··的一部分", "examples": [{"en": "We should all make exercise a part of our lives.", "zh": "我们都应使运动成为生活的…部分。"}], "sub_entries": ["part[part]n.部分"]}, {"num": 3, "word": "everyday", "phonetic": "[ˈevride]", "pos": "a.", "meaning": "每天的；日常的", "examples": [{"en": "Thistextbookwaswrittenforeverydayuse. I read the newspaper every day.", "zh": "这本教科书是为日常应用所写的。）（我每天都看报纸。"}], "sub_entries": ["注意：", "a.使用该单词时其后需接名词。", "b.everyday分开写时作副词，表“每天”，通常置", "于句首或句尾使用。"]}, {"num": 4, "word": "company", "phonetic": "[ˈkAmpani]", "pos": "n.", "meaning": "公司", "examples": [], "sub_entries": []}, {"num": 5, "word": "replace", "phonetic": "[rˈples]", "pos": "vt.", "meaning": "取代", "examples": [{"en": "In modern cities, buses are being replaced with subways.", "zh": "在现代化都市里，公共汽车正逐渐被地铁所取代。"}], "sub_entries": ["replace Awith B用B取代A"]}, {"num": 6, "word": "telephone company", "phonetic": "", "pos": "短语", "meaning": "电话公司", "examples": [], "sub_entries": []}, {"num": 7, "word": "be no exception", "phonetic": "", "pos": "短语", "meaning": "不例外", "examples": [{"en": "Everyone should help clean this room and you are no exception.", "zh": "每个人都应帮忙打扫房间，而你也不例外。"}], "sub_entries": ["exception [ik'sepfan]n.例外"]}, {"num": 8, "word": "make a long-distance call", "phonetic": "", "pos": "短语", "meaning": "打长途电话", "examples": [{"en": "I made a call to my brother last night.", "zh": "昨晚我给我哥哥打了一次电话。"}], "sub_entries": ["make a call", "打电话", "long-distance [lon'distans] a. 长途的"]}, {"num": 9, "word": "pay phone", "phonetic": "", "pos": "短语", "meaning": "投币电话", "examples": [], "sub_entries": []}, {"num": 10, "word": "operator", "phonetic": "[ˈopaireta]", "pos": "n.", "meaning": "接线员，总机", "examples": [], "sub_entries": []}, {"num": 11, "word": "instead", "phonetic": "[inˈsted]", "pos": "adv.", "meaning": "相反地；代替", "examples": [{"en": "I didn't go to the library. Instead,I stayed home and studied. Instead of driving to work, I take the bus.", "zh": "我没去图书馆而待在家里念书。）（我不是开车而是乘公共汽车上班的。"}], "sub_entries": ["注@：", "a.使用该单词时，通常将其置于句首，其后置逗号，", "再接主语和动词。", "b.instead与介词of 并用时，形成\"insteadof+名", "词／动名词”的介词短语，表“非但不·……反而", ".…”之意。"]}, {"num": 12, "word": "wonder", "phonetic": "[ˈwAnda]", "pos": "n.", "meaning": "惊奇", "examples": [{"en": "Carl is very fat. Nowonder hedoesn't like to run.", "zh": "卡尔很胖，难怪他不喜欢跑步。"}], "sub_entries": ["Nowonder+主语+动词", "难怪····"]}, {"num": 13, "word": "take ..", "phonetic": "", "pos": "over.", "meaning": "接管...接收…···", "examples": [{"en": "The three brothers took over their father's business after he passed away.", "zh": "那三兄弟在他们的父亲过世后接管了他的事业。"}], "sub_entries": []}], "grammar": {"intro": "本课主要介绍状语从句变成分词短语的方法。", "items": [{"num": 1, "title": "When making a long-distance call on a pay phone in America, you will no longer talk to an operator.", "body": ["", "= When you make a long-distance call on a pay phone in America, you will no longer talk to an operator.（在美国，当你使用投币电话打长途电话时，你不 再对总机说话。）*以上第一句的划线部份即为分词短语。分词短语的形成：", "when（当）、while（在.…....·的时候）、if（如果）、unless（除非）、once（一…....·就.….…）、though（虽然）等均为连词，其所引导的状语从句 中，主语若与主句的主语相同时，该状语从句即可简 化为分词短语·简化原则如下：", "第一步：删除从句中的主语；第二步：主语之后的动词变成现在分词；第三步：若动词为be动词（如am、are、is、was、were)，则一律变成现在分词 being，而 being 均予省略。", "例：When I arn rich, I will buy a watch.", "being", "→ When being rich, I will buy a watch.", "→ When rich, I will buy a watch.（我有钱时会买只手表。）If he is late, he may be punished. being", "→ If being late, he may be punished.", "→ If late, he may be punished.（他若迟到，可能会受罚。）Unless X arn available, I won't do it. being", "→ Unless being available, I won't do it.-→ Unless available, I won't do it.（除非我有空，否则我不会做这件事。）Though be was ill, he didn't want to see being a doctor.", "→Though being ill, he didn't want to see a doctor.", "→Though ill, he didn't want to see a doctor.（他虽然病了却不愿看医生。）While I was there, I had a good time. being", "→ While being there, I had a good time.", "→ While there, I had a good time.（我在那里的时候玩得很愉快。）Once he was given first aid, the patient being was rushed to the hospital.-→ Once being given first aid, the patient was rushed to the hospital.", "→Once given first aid, the patient was rushed to the hospital.（病人一被急救后，就立刻被送到医院。）unless、once、though、if所引导的状语从句 简化成分词短语时，原从句的句子结构多为“主语+be动词”，但when或while所引导的从句简 化为分词短语时，原从句的句子结构则不一定要接 be 动词，接其他动词也可。: When you do the work, you must be doing careful.", "→ When doing the work, you must be careful.（你做这件事时必须谨慎。）While be reads, he enjoys listening to reading music.-→ While reading, he enjoys listening to music.（他看书的时候喜欢听音乐。）"]}, {"num": 2, "title": "时间状语从句化简为分词短语", "body": ["上列例句中的 When making a long-distance call... 是由时间状语从句 When you make a long-distance call... 化简而成的分词短语。化简步骤如下：", "=on a pay telephone 名词如phone（电话）丶radio（收音机）或TV（电视，television 的缩写形），多与介词on 并用。", "例：I had a pleasant chat with him in the phone", "last night.（×）-→I had a pleasant chat with him on the phone last night. (○)（我昨晚跟他在电话上聊得很愉快。）*in thephone暗示“人在电话机里面”，不合逻 辑。I heard him in the radio. (×)--> I heard him on the radio. (○)（我在收音机上听到他的声音。）*in theradio暗示“人在收音机里”，不合逻 辑。Do you know the girl in the TV? (×)Do you know the girl on the TV? (×)-→ Do you know the girl on TV? (○)", "=Do you know the girl on televison?（你认识电视上的那个女孩吗？）*in the TV暗示“人在电视机里面”，不合逻辑。on the TV则指“在电视机的上面”，亦不合逻 辑。on TV则指“在电视荧屏上”，合逻辑。换 言之，TV之前若有the或a，则指“电视机”，此时TV作可数名词。TV之前若无the或a，则 指“电视节目”，此时TV作不可数名词。", "例：He bought a TV yesterday. Unfortunately, the TV is broken.（他昨天买了一架电视机。不幸的是，这架电 视机现在坏了。）", "比较：I enjoy watching the TV.（×)-→ I enjoy watching TV. (○)（我喜欢看电视。）"]}]}, "substitution": [{"num": 1, "pairs": [{"en": "When making a long-distance call on a pay phone, you will no longer talk to an operator.", "zh": "当你使用投币电话打长途电话时，你不再对总机说话。"}, {"en": "Though poor, they were happy.", "zh": "虽然穷，但是他们很快乐。"}, {"en": "Unless sick, he always comes to work.", "zh": "除非生病，否则他总是会来上班。"}, {"en": "While in school, you must study hard.", "zh": "在学校时，你必须用功读书。"}], "en": "When making a long-distance call on a pay phone, you will no longer talk to an operator.", "zh": "当你使用投币电话打长途电话时，你不再对总机说话。"}, {"num": 2, "pairs": [{"en": "When making a long-distance call on a pay phone, you will no longer talk to an operator.", "zh": "当你使用投币电话打长途电话时，你不再对总机说话。"}, {"en": "Look, there's Bob on TV.", "zh": "瞧，鲍勃上电视了。"}, {"en": "My mother likes to listen to the news on the radio.", "zh": "我妈妈喜欢听收音机上播报的新闻。"}, {"en": "Call me on my beeper tomorrow.", "zh": "明天打BP机找我。"}], "en": "When making a long-distance call on a pay phone, you will no longer talk to an operator.", "zh": "当你使用投币电话打长途电话时，你不再对总机说话。"}], "exercises": null}, {"num": 92, "title_en": "Hold On, Please", "title_zh": "请等一下", "type": "dialogue", "category": "情境实战会话", "reading": null, "dialog": {"turns": [{"speaker_en": "Operator", "speaker_zh": "接线员", "en": "This is the operator. Is Mr. Ken Wang there, please?", "zh": "我是接线员。请问王肯先生在吗？"}, {"speaker_en": "Ken", "speaker_zh": "肯", "en": "Yes, this is he.", "zh": "在，我就是。"}, {"speaker_en": "Operator", "speaker_zh": "接线员", "en": "I have a collect call from England.", "zh": "我这里有一个从英国打来的对方付费电话。"}, {"speaker_en": "Ken", "speaker_zh": "肯", "en": "Who's calling?", "zh": "是谁打的？"}, {"speaker_en": "Operator", "speaker_zh": "接线员", "en": "It's a Mr. John Smith. Do you accept the charges?", "zh": "是一位叫做约翰·史密斯的先生打的。你愿意付费吗？"}, {"speaker_en": "Ken", "speaker_zh": "肯", "en": "Sure.", "zh": "愿意。"}, {"speaker_en": "Operator", "speaker_zh": "接线员", "en": "Hold on, please.", "zh": "请等一下。"}]}, "vocab": [{"num": 1, "word": "a collect call", "phonetic": "", "pos": "名词短语", "meaning": "向受话人收费的电话", "examples": [], "sub_entries": []}, {"num": 2, "word": "accept", "phonetic": "[akˈsept]", "pos": "vt.", "meaning": "接受", "examples": [{"en": "Why didn't you accept Mary's apology?", "zh": "你为何不接受玛丽的道歉呢？"}], "sub_entries": []}, {"num": 3, "word": "charge", "phonetic": "[tʃɑːrdʒ]", "pos": "n.", "meaning": "费用", "examples": [{"en": "The parking here is free of charge.", "zh": "这里的停车是免费的。"}], "sub_entries": []}, {"num": 4, "word": "hold on", "phonetic": "", "pos": "短语", "meaning": "（电话）不要挂断，等一下", "examples": [], "sub_entries": []}], "grammar": null, "substitution": [], "exercises": {"prompt": "Ⅲ·请选出下列各句中正确的一项", "questions": ["1.Welove to listen tothefootballgame", "radio.", "(A) in a (B) on the (C) on an (D) in the", "2. When", ",she cries.", "(A) is unhappy", "(B) been happy", "(C) unhappy", "(D) she being unhappy", "3. I want to buy", "TV. However,", "TV I", "want is very expensive.", "(A) a, a (B) the, a (C) the, the (D) a, the", "4.If", ", you should take a rest.", "(A) tire", "(B) tired(C) tires", "(D) tiring", "5. While", "he whistles.", "(A) he working", "(B) working", "(C) being working", "(D) works", "6. Bill gave Fred", "dacollect call. This sentence", "means that", "(A) Bill will pay for the call", "(B) Fred collected a call", "(C) Bill collected a call and told Fred", "(D) Fred will pay for the call"], "answers": ["解答>1.(B）2.(C)3.(D）4.(B）5.(B）6(D)"]}}, {"num": 93, "title_en": "Pride Comes before a Fall", "title_zh": "骄者必败", "type": "reading", "category": "进阶短文与语法探究", "reading": {"en": ["The teachings of Confucius tell us to be humble. People should not think too highly of themselves. No matter how great one is, there is always someone greater. Therefore, we should be humble in our words and actions. We should always remember the saying, \"Pride comes before a fall.\""], "zh": ["孔子教导我们要谦虚。人们不应该自视太高。不论一个人有多么了不起，总有人比他更了不起。因此，我们在言行上都应该谦虚。我们应当随时记住这句俗话：“骄者必败”。"], "sentences": [{"en": "The teachings of Confucius tell us to be humble.", "zh": "孔子教导我们要谦虚。"}, {"en": "People should not think too highly of themselves.", "zh": "人们不应该自视太高。"}, {"en": "No matter how great one is, there is always someone greater.", "zh": "不论一个人有多么了不起，总有人比他更了不起。"}, {"en": "Therefore, we should be humble in our words and actions.", "zh": "因此，我们在言行上都应该谦虚。"}, {"en": "We should always remember the saying, \"Pride comes before a fall.\"", "zh": "我们应当随时记住这句俗话：“骄者必败”"}]}, "dialog": null, "vocab": [{"num": 1, "word": "Pride", "phonetic": "[praid]", "pos": "n.", "meaning": "骄傲", "examples": [{"en": "That woman takes pride in her children's achievements.", "zh": "那位妇女以她孩子的成就为荣。"}], "sub_entries": ["proud[praud]a.骄傲的", "take pride in...", "以……·…为荣", "=be proud of..."]}, {"num": 2, "word": "fall", "phonetic": "[fol]", "pos": "n.", "meaning": "跌倒", "examples": [], "sub_entries": []}, {"num": 3, "word": "Pride", "phonetic": "", "pos": "fall.", "meaning": "骄者必败。（谚语）", "examples": [], "sub_entries": []}, {"num": 4, "word": "teachings", "phonetic": "[ˈtitfinz]", "pos": "n.", "meaning": "教导，学说", "examples": [{"en": "Are you familiar with the teachings of Plato?", "zh": "你熟悉柏拉图的学说吗？"}], "sub_entries": []}, {"num": 5, "word": "Confucius", "phonetic": "[kanˈfjufas]", "pos": "n.", "meaning": "子L子", "examples": [], "sub_entries": []}, {"num": 6, "word": "humble", "phonetic": "[ˈhAmbl]", "pos": "a.", "meaning": "谦虚的", "examples": [{"en": "Paul is very humble. He's never proud.", "zh": "保罗很谦虚。他从不骄傲。"}], "sub_entries": []}, {"num": 7, "word": "think ..", "phonetic": "", "pos": "of.", "meaning": "重视…·…，敬重…·", "examples": [{"en": "Our teacher thinks highly of Brian because he always studies.", "zh": "我们的老师很看重布赖恩，因为他总是在念书"}], "sub_entries": []}, {"num": 8, "word": "great", "phonetic": "[ɡreɪt]", "pos": "a.", "meaning": "伟大的", "examples": [], "sub_entries": []}, {"num": 9, "word": "action", "phonetic": "[ˈaekjan]", "pos": "n.", "meaning": "行为（可数）；行动（不可数）", "examples": [{"en": "Judge a person by his actions and not by his appearance. When the boss tells us to do something, we take action immediately.", "zh": "不要以一个人的外貌，而要以他的行为来判断他。）（当老板叫我们去做一件事时，我们便会马上采取行动。"}], "sub_entries": ["takeaction", "采取行动"]}], "grammar": {"intro": "本课介绍nomatterhow（不论多么.….….）的用法。", "items": [{"num": 1, "title": "No matter how great one is, there is always someone greater.", "body": ["=However great one is, there is always someone greater.（不论一个人有多么了不起，总有人比他更了不起。）以上第一句中 Nomatter how是连词，等于第二句 中的However，均表示“不论多么...”，引导状语 从句，修饰之后的主句。"]}, {"num": 2, "title": "no matter how（无论多么...）的造句法与用法", "body": ["由于 how 是副词，表示“多么地、如何地”，之后应接副词或形容词以供修饰。how 亦可修饰动词，此时 how 之后接主语再接动词即可。", "a. 修饰副词时，副词紧接于how之后。", "例：No matter how he tried hard, he couldn't adv.", "solve the math problem.（x)", "→No matter how hard he tried, he couldn't solve the math problem.（O)", "=However hard he tried, he couldn't solve the math problem.（不论他多费心，却仍未能解出那道数学题。）", "b. 修饰形容词时，形容词紧接于how之后。", "例：No matter how he is nice, I don't like", "a. him.(×)", "→No matter how nice he is, I don't like him.(○)", "=However nice he is, I don't like him.（不论他有多好，我就是不喜欢他。）本课阅读原文\"No matter how great one is\"即 属此结构。", "c. 修饰动词时，how之后接主语，再接动词。", ": No matter how you try, you won't succeed. vi.", "=However you try, you won't succeed.（不论你如何尝试，你不会成功的。）"]}, {"num": 3, "title": "由上得知，however有下列两种词性：", "body": ["a. 作副词用，表示“然而、不过”，此时however 之后要置逗号。", "例： He is nice. However, I don't like him.（他不错，不过我不喜欢他。）", "b. 作连词用，表示“不论多么·….….”，此时however 之后不得置逗号。", "例: However nice he is, I don't like him.", "=No matter how nice he is, I don't like him.（不论他有多好，我就是不喜欢他。）"]}, {"num": 4, "title": "no matter what（无论什么...）的造句法与用法", "body": ["no matter what 亦为连词，表示“不论什么...”，等于 whatever，引导状语从句修饰主句。what 是代词，在该从句中作主语、宾语或表语。", "a. 作主语", "例: No matter what happens, I'll support you.", "=Whatever happens, I'll support you.（不论发生什么事，我都会支持你。）", "b. 作宾语", "例: No matter what he says, I don't believe", "him.（what 作 says 的宾语）", "=Whatever he says, I don't believe him.（不论他说什么，我都不相信他。）", "c. 作be动词之后的主语补足语", "例: No matter what he is, he must obey the law.", "=Whatever he is, he must obey the law.（不管他是什么身份，他必须守法。）"]}, {"num": 5, "title": "类似的连词尚有下列几个：", "body": ["no matter when 不论何时，每当", "=whenever no matter where 不论何处", "=wherever no matter who 不论谁", "=whoever", "例: No matter when I see him, he is studying.", "=Whenever I see him, he is studying.（不论我何时见到他，他都在读书 每当我见 到他时，他都在读书。）", "No matter where he is, I'll find him.", "=Wherever he is, I'll find him.（不论他在何处，我都会找到他。）No matter who does it, it is none of my business.", "=Whoever does it, it is none of my business.（不论是谁做这件事，那都不干我的事。）"]}]}, "substitution": [{"num": 1, "pairs": [{"en": "No matter how great one is, there is always someone greater.", "zh": "不论一个人有么多了不起，总有人比他更了不起。"}, {"en": "However clever you think you are, there is always someone more clever.", "zh": "不论你认为自己有多聪明，总有人比你更聪明。"}, {"en": "No matter how hard you try to beat me, you will lose.", "zh": "不论你多么努力要打败我，你都会输。"}, {"en": "However hard you try to beat me, you will lose.", "zh": "不论你多么努力要打败我，你都会输。"}], "en": "No matter how great one is, there is always someone greater.", "zh": "不论一个人有么多了不起，总有人比他更了不起。"}, {"num": 2, "pairs": [{"en": "Therefore, we should be humble in our words and actions.", "zh": "因此，我们在言行上都应该谦虚。"}, {"en": "As a result, we should always be polite to our teachers.", "zh": "因此，我们应该随时对老师有礼貌。"}, {"en": "For that reason, we ought to be thoughtful and kind to others.", "zh": "因此，我们应该体谅并善以待人。"}, {"en": "So, we ought to respect our parents.", "zh": "因此，我们应该尊敬父母。"}], "en": "Therefore, we should be humble in our words and actions.", "zh": "因此，我们在言行上都应该谦虚。"}], "exercises": null}, {"num": 94, "title_en": "Congratulations", "title_zh": "恭禧", "type": "dialogue", "category": "情境实战会话", "reading": null, "dialog": {"turns": [{"speaker_en": "Don", "speaker_zh": "唐", "en": "Congratulations on your promotion, Sheila.", "zh": "希拉，恭禧你获得提升。"}, {"speaker_en": "Sheila", "speaker_zh": "希拉", "en": "Thanks. But it's nothing.", "zh": "谢谢。但那算不了什么。"}, {"speaker_en": "Don", "speaker_zh": "唐", "en": "Don't be so humble.", "zh": "别这么谦虚。"}, {"speaker_en": "Sheila", "speaker_zh": "希拉", "en": "Well, in fact, I am a bit proud of myself.", "zh": "，事实上，我有点儿以自己为荣。"}]}, "vocab": [{"num": 1, "word": "congratulation", "phonetic": "[kənˌɡrætʃəˈleʃən]", "pos": "n.", "meaning": "恭禧（在下列", "examples": [{"en": "Congratulations on getting an \"A\" on your biology test.", "zh": "恭禧你生物考试得了个\"A”。"}], "sub_entries": ["结构中要使用复数）", "Congratulations on+事物", "因……表示恭禧"]}, {"num": 2, "word": "It's", "phonetic": "", "pos": "nothing.", "meaning": "那算不了什么／那没啥了不起。", "examples": [], "sub_entries": ["=That's nothing."]}, {"num": 3, "word": "a ..", "phonetic": "", "pos": "bit.", "meaning": "有点儿···.", "examples": [{"en": "It's a bit hot today. a. He walked a bit slowly. adv.", "zh": "今天有点儿热。）（他走得有点儿慢。"}], "sub_entries": ["=a little...", "本短语作副词用，之后可接形容词或副词以供修饰。"]}, {"num": 4, "word": "proud", "phonetic": "[praud]", "pos": "a.", "meaning": "骄傲的", "examples": [{"en": "Our teacher is proud of us because we all did well on the exam.", "zh": "老师很以我们为荣，因为我们这一次考试都考得很好。"}], "sub_entries": ["be proud of...", "以…··…为荣"]}], "grammar": null, "substitution": [], "exercises": {"prompt": "Ⅲ·请选出下列各句中正确的一项", "questions": ["1. No matter how", "is, Nancy always does", "well.", "(A) the test difficult", "(B）difficult test", "(C) difficult the test", "(D) difficult the tests", "2.", "he does, he always does a good job.", "(A)", "Whenever", "(B) No matter", "(C) Whoever", "(D) Whatever", "3.However", ", I can swim faster.", "(A) he fast swims", "(B)fast he swim", "(C) he is fast", "(D） fast he swims", "4.", "I ride my bicycle, I feel happy.", "(A）", "Whenever", "(B) Whoever", "(C) Whatever", "(D) No matter what", "5. You play the piano very well.", "I think", "you should study music in university.", "(A) But,(B) And (C) Therefore，", "(D) Then", "6. Congratulations on", "(A) you for winning the game", "(B) winning the game", "(C) Bob's team won the game", "(D) won the game"], "answers": ["解答1.(C）2.(D）3.(D）4.(A）5.(C）6.(B)"]}}, {"num": 95, "title_en": "A Balanced Diet", "title_zh": "均衡的饮食", "type": "reading", "category": "进阶短文与语法探究", "reading": {"en": ["Some people eat to live, but there are others who live to eat. To live a long and healthy life, we must learn to have a balanced diet. A balanced diet simply means a bit of everything. A diet which includes meat, fish, vegetables and fruit is, of course, ideal. If you watch your diet, then you won't have to suffer the pain of going on a diet."], "zh": ["有些人吃东西为的是要生存，但也有些人生存为的是要吃东西。为了要过着长寿而文健康的生活，我们必须懂得吃均衡的饮菜和水果的饮食当然是最理想的。如果你注意饮食，那么你就不须受节食之苦。"], "sentences": [{"en": "Eating a balanced diet is, of course, ideal.", "zh": "保持均衡饮食无疑是最理想的健康习惯。"}, {"en": "If you watch your weight and health, it is a must.", "zh": "如果你注重体态与身体健康，这更是必不可少。"}, {"en": "Doctors and nutritionists are always telling us to eat more vegetables and less meat.", "zh": "医生和营养专家总是叮嘱我们要多吃果蔬、少摄入油腻红肉。"}, {"en": "The question is: Can we do it?", "zh": "关键问题在于：我们能持之以恒地做到吗？"}, {"en": "I think we can, if we really want to.", "zh": "我相信只要下定决心，每个人都能做到。"}]}, "dialog": null, "vocab": [{"num": 1, "word": "balanced", "phonetic": "[ˈbalanst]", "pos": "a.", "meaning": "均衡的；平衡的", "examples": [{"en": "He eats three balanced meals a day.", "zh": "他一天吃三餐均衡的饮食。"}], "sub_entries": []}, {"num": 2, "word": "diet", "phonetic": "[ˈdarat]", "pos": "n.", "meaning": "（规定的）饮食", "examples": [{"en": "You're too fat. You should go on a diet. I can't eat candy because I am on a diet.", "zh": "你太胖了，你应该要节食。）（我不能吃糖果，因为我在节食中。"}], "sub_entries": ["go on a diet．节食，照规定饮食", "be on a diet在节食中"]}, {"num": 3, "word": "healthy", "phonetic": "[ˈherdi]", "pos": "a.", "meaning": "健康的", "examples": [{"en": "Bobis not veryhealthybecause he never exercises.", "zh": "鲍勃不是很健康，因为他从不运动。"}], "sub_entries": []}, {"num": 4, "word": "simply", "phonetic": "[ˈsimpli]", "pos": "adv.", "meaning": "简单地；就是", "examples": [{"en": "Paul simply said that you need to work harder. I simply don't want to go to your party.", "zh": "保罗就是说你必须更努力些。）（我就是不想去参加你的宴会。"}], "sub_entries": []}, {"num": 5, "word": "mean", "phonetic": "[min]", "pos": "vt.", "meaning": "意谓；意欲", "examples": [{"en": "A red traffic light means that you must stop. I meant to call you yesterday, but I didn't have time.", "zh": "红灯表示你必须停下来。）（我昨天本来要打电话给你，但我没有时间。"}], "sub_entries": ["动词三态：mean，meant[ment]，meant", "mean+名词/that引导的名词性从句", "指的是意谓着····", "人+mean+to+动词原形", "某人打算·", "=人+intend+to+动词原形"]}, {"num": 6, "word": "bit", "phonetic": "[brt]", "pos": "n.", "meaning": "有点，些许", "examples": [{"en": "Would you like a bit of birthday cake? It's a bit colder today than it was yesterday.", "zh": "你想要来一点儿生日蛋糕吗？）（今天比昨天稍微冷一点。"}], "sub_entries": ["a bitof+名词", "一点儿·…..….（abitof在此处作", "形容词）", "abit+形容词/副词", "有一点.…..….，稍微…….….（a", "bit 在此处作副词）"]}, {"num": 7, "word": "include", "phonetic": "[inˈklud]", "pos": "vt.", "meaning": "包括", "examples": [], "sub_entries": []}, {"num": 8, "word": "meat", "phonetic": "[miːt]", "pos": "n.", "meaning": "肉（不可数）", "examples": [], "sub_entries": ["a piece of meat", "一块肉"]}, {"num": 9, "word": "vegetable", "phonetic": "[ˈvedʒtəbl]", "pos": "n.", "meaning": "蔬菜（可数）", "examples": [], "sub_entries": []}, {"num": 10, "word": "fruit", "phonetic": "[frut]", "pos": "", "meaning": "n．水果（通常不可数，表“种类”时则", "examples": [], "sub_entries": ["可数）"]}, {"num": 11, "word": "of course", "phonetic": "", "pos": "短语", "meaning": "当然", "examples": [], "sub_entries": ["*在本文中of course 为插人语，置于be 动词与补", "足语ideal之间；本句亦可将of course置于句", "首，即\"Of course，a diet which...is ideal.\"。"]}, {"num": 12, "word": "ideal", "phonetic": "[alˈdial]", "pos": "a.", "meaning": "理想的", "examples": [{"en": "This weather is ideal for bike riding.", "zh": "这种天气骑自行车很理想。"}], "sub_entries": []}, {"num": 13, "word": "suffer ..", "phonetic": "", "pos": "of.", "meaning": "遭受…·之苦", "examples": [{"en": "Roger just suffered a terrible loss. His wife died.", "zh": "罗杰刚遭受重大的损失。他太太过世了。"}], "sub_entries": ["suffer['sAfa]vt.遭受"]}], "grammar": {"intro": "本课旨在复习不定式短语作状语的用法。", "items": [{"num": 1, "title": "Some people eat to live, but there are others who live to eat.", "body": ["（有些人吃东西为的是要生存，但也有些人生存为的 是要吃东西。）上列句中的划线部份tolive及toeat皆为不定式 短语（即“虚词to+动词原形”所形成的短语），在", "·句中皆作状语，分别修饰之前的动词eat及live。"]}, {"num": 2, "title": "不定式短语作状语表目的（为了要...）", "body": ["不定式短语作状语时，可置于句首或句尾，用以表示目的，相当于中文的“为了要...”。该短语置于句首时短语之后应置逗号；置于句尾时之前则不可置逗号。", "a. 置于句首：", "To catch the train John got up early. (×)", "→To catch the train, John got up early. (○)（为了赶火车，约翰很早就起床。）", "b. 置于句尾：", "John got up early, to catch the train. (×)", "→ John got up early to catch the train. (○)（约翰早起是为了要赶火车。）"]}, {"num": 3, "title": "表示目的的不定式短语亦可用下列短语取代：", "body": ["to+动词原形 为了要·····", "=in order to+动词原形", "=soasto+动词原形", "=with a view to+动名词", "=withaneyeto+动名词*withaview及withan eye之后的to为介词，之后接动名词作其宾语；此处view及eye皆作“目的”解。", "例：He got up early to catch the train.", "=He got up early y in order to catch the train.", "=He got up early so as to catch the train.", "=He got up early with a view to catching the train.", "=He got up early with an eye to catching the train.（他早起是为了要赶火车。）一如不定式短语，inorderto所引导的短语亦可置于 句首，之后置逗号。但soasto引导的短语则通常只 置于句尾，而不置于句首·故上列各句可改写如下：", "To catch the train, he got up early.", "=In order to catch the train, he got up early.", "=With a view to catching the train, he got up early.", "=With an eye to catching the train, he got up early. So as to catch the train, he got up early. (罕)"]}, {"num": 4, "title": "To live a long and healthy life, we must learn to have a balanced diet.", "body": ["=We must learn to have a balanced diet to live a long and healthy life.（为了要过着长寿而又健康的生活，我们必须懂得吃 均衡的饮食。）", "a. live a...life 过着···的生活", "=lead a...life live可作不及物动词，作“居住”解，之后接表示 场所的介词短语或副词（如there，here）。", "例：They live the city.(×)", "→They live in the city. (○)介词短语（他们住在城市里。）He used to live there.(○)adv.（他以前住在那儿。）但live亦可作及物动词，表示“过（某种）生 活”的意思，此时，只能用life（生活）作其宾 语。", "例: They lived a happy life.", "=They led a happy life.（他们过着快乐的生活。）", "b. we must learn to have a balanced diet.（...…。我们必须懂得吃均衡的饮食。）", "本句中的learn是及物动词，表示“学习”、“懂 得”之意，之后的不定式短语具有名词的性质，作 learn的宾语。learnto+动词原形 懂得…．学会.·", "例：You should learn to get along well with people.（你应懂得与人和睦相处。）", "但learn之后亦可接\"howto+动词原形”所形成 的名词性短语作其宾语。learnhowto+动词原形 学习如何····", "例：You should learn how to get along with people.（你应学习如何与人相处。）"]}]}, "substitution": [{"num": 1, "pairs": [{"en": "Some people eat to live.", "zh": "有些人吃东西为的是要生存。"}, {"en": "I eat a lot of fruit in order to stay healthy.", "zh": "我吃很多水果为的是要保持健康。"}, {"en": "To improve her English, Kate studies every day.", "zh": "为了提高英文，凯蒂每天都在用功。"}, {"en": "In order to become a professional photographer, Billy is studying photography.", "zh": "为了成为职业摄影师，比利正在学习摄影。"}], "en": "Some people eat to live.", "zh": "有些人吃东西为的是要生存。"}, {"num": 2, "pairs": [{"en": "We must learn to have a balanced diet.", "zh": "我们必须懂得吃均衡的饮食。"}, {"en": "Barry should learn how to eat a balanced diet.", "zh": "巴里应该懂得如何吃均衡的饮食。"}, {"en": "I ought to learn how to talk politely to others.", "zh": "我应该要学习如何和人讲话有礼貌。"}, {"en": "You might want to learn how to knit some day.", "zh": "有一天你也许会想学如何编织。"}], "en": "We must learn to have a balanced diet.", "zh": "我们必须懂得吃均衡的饮食。"}], "exercises": null}, {"num": 96, "title_en": "You're Looking Great!", "title_zh": "你看起来棒极了！", "type": "dialogue", "category": "情境实战会话", "reading": null, "dialog": {"turns": [{"speaker_en": "Sid", "speaker_zh": "席德", "en": "Wow! Candy, you're looking great!", "zh": "哇！凯蒂，你看起来棒极了！"}, {"speaker_en": "Candy", "speaker_zh": "凯蒂", "en": "Really?", "zh": "真的吗？"}, {"speaker_en": "Sid", "speaker_zh": "席德", "en": "You look so slim. How did you do it?", "zh": "你看起来好苗条。你怎么做到的？"}, {"speaker_en": "Candy", "speaker_zh": "凯蒂", "en": "I went on a balanced diet.", "zh": "因为我吃均衡饮食。"}]}, "vocab": [{"num": 1, "word": "look", "phonetic": "[lʊk]", "pos": "vi.", "meaning": "看起来，显得", "examples": [{"en": "Candy, you're looking great!", "zh": "凯蒂，你看起来棒极了！"}], "sub_entries": []}, {"num": 2, "word": "slim", "phonetic": "[slɪm]", "pos": "a.", "meaning": "苗条的，纤细的", "examples": [{"en": "You look so slim.", "zh": "你看起来好苗条。"}], "sub_entries": []}, {"num": 3, "word": "balanced", "phonetic": "[ˈbælənst]", "pos": "a.", "meaning": "均衡的，平衡的", "examples": [{"en": "a balanced diet", "zh": "均衡的饮食"}], "sub_entries": []}, {"num": 4, "word": "diet", "phonetic": "[ˈdaɪət]", "pos": "n.", "meaning": "日常饮食；节食", "examples": [{"en": "I went on a balanced diet.", "zh": "因为我吃均衡饮食。"}], "sub_entries": []}], "grammar": null, "substitution": [], "exercises": {"prompt": "Ⅲ．请选出下列各句中正确的一项", "questions": ["1.Paul must learn", "speak English for his job.", "(A) how", "(B) how to", "(C) in order to", "(D) in order", "2. My brother lives in the city, but I live", "(A) in the country", "(B）at the country", "(C) on the country", "(D) over the country", "3. 1 listen very carefully to the teacher", "good student.", "(A) in order be", "(B) so that to be", "(C) so as to be", "(D) so to be", "4.To be on time for", "leave myhouse at 6:00", "a.m.", "(A) work, so", "(B) work, and I", "(C) work I", "(D) work, I", "5. When he was sixteen, he learned", "a car.", "(A) how to", "(B)how his father fix", "(C) how to fix", "(D) how to fixes", "6. Sue", "last month and now she looks great.", "(A) went dieting", "(B) went in a diet", "(C) went under a diet (D) went on a diet"], "answers": ["解答>1.(B）2.(A）3.(C）4.(D）5.(C）6(D)"]}}, {"num": 97, "title_en": "By Taxi", "title_zh": "乘坐出租车", "type": "reading", "category": "进阶短文与语法探究", "reading": {"en": ["One of the most convenient ways to get around a city is by taxi. However, it is also the most expensive way. In some cases, tipping is expected, too. On the other hand, a taxi driver knows the city like the back of his hand. He can quickly take you to any place you want to visit. The taxi ride might be expensive, but it's time-saving."], "zh": ["到城市走走最便捷的方法之一是乘坐出租车。不过，那也是最昂贵的方法·有时候还需要给小费。就另一方面来说，出租车司机对城市了如指掌。他可以带你到任何你想走访的地方。乘坐出租车或许贵了些，可是它倒蛮省时的。"], "sentences": [{"en": "One of the most convenient ways to get around a city is by taxi.", "zh": "到城市走走最便捷的方法之一是乘坐出租车。"}, {"en": "However, it is also the most expensive way.", "zh": "不过，那也是最昂贵的方法。"}, {"en": "In some cases, tipping is expected, too.", "zh": "有时候还需要给小费。"}, {"en": "On the other hand, a taxi driver knows the city like the back of his hand.", "zh": "就另一方面来说，出租车司机对城市了如指掌。"}, {"en": "He can quickly take you to any place you want to visit.", "zh": "他可以带你到任何你想走访的地方。"}, {"en": "The taxi ride might be expensive, but it's time-saving.", "zh": "乘坐出租车或许贵了些，可是它倒蛮省时的。"}]}, "dialog": null, "vocab": [{"num": 1, "word": "taxi", "phonetic": "[ˈteksi]", "pos": "n.", "meaning": "出租车，计程车", "examples": [], "sub_entries": ["taxi driver", "出租车司机", "driver['draiva ]n.司机"]}, {"num": 2, "word": "convenient", "phonetic": "[kanˈvinjant]", "pos": "a.", "meaning": "方便的", "examples": [{"en": "I likelivinginthe city. It'sveryconvenient.", "zh": "我喜欢住在城市，因为很方便。"}], "sub_entries": []}, {"num": 3, "word": "get around + 地方名词", "phonetic": "", "pos": "短语", "meaning": "在...观光，四处走动", "examples": [{"en": "How do you get around town if you don't have a car?", "zh": "如果没车的话，你如何能在城镇上四处走走？"}], "sub_entries": ["在某地到处走动／四处走走"]}, {"num": 4, "word": "expensive", "phonetic": "[ɪkˈspensɪv]", "pos": "a.", "meaning": "昂贵的", "examples": [{"en": "My father has an expensive watch.", "zh": "我父亲有一只很昂贵的手表。"}], "sub_entries": []}, {"num": 5, "word": "in some cases", "phonetic": "", "pos": "短语", "meaning": "在有些情况下，有时候", "examples": [{"en": "In some cases, it is better to say nothing at all. In many cases, it is better to give than to receive.", "zh": "有时候最好是什么话都别说。）（在许多情况下施比受更有福。"}], "sub_entries": ["in many cases", "在许多情况下", "in most cases", "在多数情况下，往往", "case[kes ]n.状况"]}, {"num": 6, "word": "tip", "phonetic": "[tup]", "pos": "vi.", "meaning": "给小费", "examples": [{"en": "In American restaurants tipping is proper and very common.", "zh": "在美国餐厅里，给服务员小费是恰当且非常普遍的事。"}], "sub_entries": []}, {"num": 7, "word": "expect", "phonetic": "[ikˈspekt]", "pos": "vt.", "meaning": "预期，期望", "examples": [{"en": "The movie star is expected to arrive tomorrow. The boss expected Bill to have the report finished, but he didn't.", "zh": "那位电影明星预期明天会到达。）（老板期望比尔会完成那份报告，但他并没完成。"}], "sub_entries": ["beexpectedto+动词原形", "被预期.··", "expect+（人）+to+动词原形", "期望（某人）·…··"]}, {"num": 8, "word": "know + 人/物 + like the back of one's hand", "phonetic": "", "pos": "短语", "meaning": "对...了如指掌", "examples": [{"en": "I will teach you how to use this computer. I know it likethe back of myhand.", "zh": "我会教你如何使用这部电子计算机。我对它了如指掌。"}], "sub_entries": ["了解某事物或人有如某人的手背-样，喻“对某事物", "或人了如指掌”。"]}, {"num": 9, "word": "visit", "phonetic": "[ˈvizit]", "pos": "vt.", "meaning": "拜访", "examples": [], "sub_entries": []}, {"num": 10, "word": "taxiride", "phonetic": "[ˈtaeksIraid]", "pos": "n.", "meaning": "乘坐出租车", "examples": [{"en": "A taxi rideis muchmore comfortablethan a bus ride.", "zh": "乘坐出租车比乘坐公共汽车要舒适多了。"}], "sub_entries": ["busride['bAsraid]n.乘坐公共汽车"]}, {"num": 11, "word": "time-saving", "phonetic": "[ˈtaim.sevin]", "pos": "a.", "meaning": "节省时间的", "examples": [], "sub_entries": []}], "grammar": {"intro": "本课主要介绍数量代词的用法，并介绍by与表示交通 工具的名词之间的关系。", "items": [{"num": 1, "title": "One of the most convenient ways to get around a city is by taxi.", "body": ["（到城市走走最便捷的方法之一是乘坐出租车。）", "a. 表示数量的代词（如one、two、some、many afew等）+of+the/these/those/所有格代词（如your、my、John's等）+复数名词….其中的...··.", "例：One of his hobbies is collecting stamps.（他的爱好之一就是集邮。）", "Five of thestudents failed theexam.（这些学生之中有五位没考及格。）Many of these ideas do not work.（这些主意中有许多行不通。）Some of John's friends are good at singing.（约翰的朋友有一些很会唱歌。）", "b. by taxi 乘坐出租车 介词by之后可置表示交通工具的名词如 taxi、train（火车）、bus（公共汽车）、car（小汽 车）丶plane（飞机）、ship（船）等，表示“乘 坐某种交通工具”的意思。这些名词之前不可再置 定冠词the或不定冠词a/ano", "例:We came here by the bus. (×)", "--→ We came here by bus. (○)（我们是搭乘公共汽车来的。）He decided to go there by a taxi. (×)-> He decided to go there by taxi. (○)（他决定乘坐出租车到那儿去。）Will he come by a train or by a plane?（×）", "→ Will he come by train or by plane? (○)（他会坐火车来还是坐飞机来？）"]}, {"num": 2, "title": "The taxi ride might be expensive, but it's time-saving.", "body": ["（乘坐出租车或许贵了些，可是它倒蛮省时的。）may与might均为助动词，亦均可用以表示某种事 物的可能性。一般而言，may表示较高的可能性，相 当于中文的“可能”；might则表示较低的可能性，相当于中文的“或许”、“大概”。", "例：You may be right, so I'll listen to you.（你的话可能有道理，因此我会接受你的建 议。）", "You might be right, but we can't be sure.（你的话或许有道理，不过我们无法确定。）"]}]}, "substitution": [{"num": 1, "pairs": [{"en": "One of the most convenient ways to get around a city is by taxi.", "zh": "到城市走走最便捷的方法之一是乘坐出租车。"}, {"en": "Some of the world's best poems are from China.", "zh": "世上最好的诗之中有些是来自中国。"}, {"en": "Many of these students will go abroad to study.", "zh": "这些学生中有许多会出国念书。"}, {"en": "Two of those computers are still broken.", "zh": "那些电子计算机中有两部仍然是有故障的。"}], "en": "One of the most convenient ways to get around a city is by taxi.", "zh": "到城市走走最便捷的方法之一是乘坐出租车。"}, {"num": 2, "pairs": [{"en": "The taxi ride might be expensive, but it's time-saving.", "zh": "乘坐出租车或许贵了些，可是它倒蛮省时的。"}, {"en": "He may be the man that the police are looking for.", "zh": "他可能是警方正在寻找的那个人。"}, {"en": "That may be the best way to do it, so let's try it.", "zh": "那可能是做此事的最佳方法，所以咱们就试试看吧。"}], "en": "The taxi ride might be expensive, but it's time-saving.", "zh": "乘坐出租车或许贵了些，可是它倒蛮省时的。"}], "exercises": null}, {"num": 98, "title_en": "Where to, Lady?", "title_zh": "小姐，你要到哪里去？", "type": "dialogue", "category": "情境实战会话", "reading": null, "dialog": {"turns": [{"speaker_en": "Taxi Driver", "speaker_zh": "出租车司机", "en": "Where to, lady?", "zh": "小姐，你要到哪里去？"}, {"speaker_en": "Passenger", "speaker_zh": "乘客", "en": "The train station, and make it fast.", "zh": "到火车站，开快点。"}, {"speaker_en": "Taxi Driver", "speaker_zh": "出租车司机", "en": "What's the hurry?", "zh": "你干嘛那么急？"}, {"speaker_en": "Passenger", "speaker_zh": "乘客", "en": "I must catch the first train to Shanghai.", "zh": "我必须赶去上海的第一班火车。"}]}, "vocab": [{"num": 1, "word": "Where", "phonetic": "", "pos": "", "meaning": "to,lady？（口语）", "examples": [], "sub_entries": ["= Where are you going, lady?(较正式)", "（小姐，你要到哪里去？）"]}, {"num": 2, "word": "...and", "phonetic": "", "pos": "fast.", "meaning": "·…·开快点。）", "examples": [], "sub_entries": ["= ...and drive quickly."]}, {"num": 3, "word": "What's the hurry?", "phonetic": "", "pos": "日常口语", "meaning": "你干嘛那么急？", "examples": [], "sub_entries": ["=What's the rush?", "=Why are you in such a hurry?", "hurry ['h31 ]n.匆忙(=rush [rʌʃ])"]}], "grammar": null, "substitution": [], "exercises": {"prompt": "Ⅲ，请选出下列各句中正确的一项", "questions": ["1. Our family enjoys traveling", "(A) by a train (B) on train", "(C) in train", "(D) by train", "2.", "are going camping this weekend.", "(A)Some us", "(B) We some", "(C) Some of us (D) Some in us", "3. Jill rides", "to work every day.", "(A) bus", "(B) by a bus", "(C) on bus", "(D) the bus", "4. According to Lesson 97, which is true?", "(A)It is convenient to travel by taxi.", "(B) A taxi ride is not expensive.", "(C) Traveling by taxi is very slow.", "(D) All taxis are pink.", "5. According to Lesson 97, which is not true?", "(A) Tipping is not expected.", "(B）A taxi driver knows the city well.", "(C) Traveling by taxi is very convenient.", "(D) Taxis are expensive.", "6. I'll talk to you later. I have to", "in ten", "minutes.", "(A) ride a bus", "(B) catch a bus", "(C) hold a bus", "(D) arrest a bus"], "answers": ["解答>1.(D）2.(C）3.(D）4.(A）5.(A）6.(B)"]}}, {"type": "song", "id": "song_05", "title_en": "Your Cheatin' Heart", "title_zh": "你不忠的心", "lyrics": [{"en": "Your cheatin' heart will make you weep. You'll cry and cry and try to sleep, but sleep won't come the whole night through. Your cheatin' heart will tell on you. When tears come down like falling rain, you'll toss around and call my name. You'll walk the floor the way I do. Your cheatin' heart will tell on you. Your cheatin' heart will pine someday, and crave the love you threw away. The time will come when you'll be blue. Your cheatin' heart will tell on you.", "zh": "你不忠的心会使你哭泣。你哭了又哭并想法子人睡，但你整夜都睡不着。你不忠的心有一天会泄露你的底细。当泪如雨下，你将辗转反侧呼唤我的名字。你会像我一样在地板上来去。你不忠的心有一天会泄露你的底细。重拾这份被你所抛弃的爱。你悲伤的时刻将会到来。你不忠的心有一天会泄露你的底细。"}], "category": "经典英文金曲赏析"}, {"num": 99, "title_en": "Asking for Directions", "title_zh": "问路", "type": "reading", "category": "进阶短文与语法探究", "reading": {"en": ["Being in an unfamiliar city can be frightening. And finding an address can be like looking for a needle in a haystack. Don't get angry. Just ask someone for directions. However, city people usually give directions very quickly. You may find it difficult to follow what they're saying. Therefore, you'd better draw the route on a map as you're listening to the directions."], "zh": ["置身于-个不熟悉的城市里可能是件令人害怕的事，而寻找一个地址也可能像是大海捞针一样。别发火。只要去找人问路就好了。不过，城市人通常在指引方向时话说得很快。你也许会发现要了解他们的话很困难·因此，当你在听方向指示时，最好在地图上画上路线。"], "sentences": [{"en": "Finding your way around an unfamiliar city can be difficult.", "zh": "在一个陌生的城市里认路确实并非易事。"}, {"en": "Looking for an address can sometimes be like looking for a needle in a haystack.", "zh": "寻找特定地址有时犹如大海捞针。"}, {"en": "Don't worry; just ask someone for directions.", "zh": "别着急，只要向路人礼貌问路就行。"}, {"en": "However, local people often speak very fast when giving directions.", "zh": "不过，当地人指路时往往语速极快。"}, {"en": "You may find it difficult to follow what they're saying.", "zh": "你可能会发现一时难以完全跟上他们的叙述。"}, {"en": "Therefore, you'd better draw the route on a map as you're listening to the directions.", "zh": "因此，在听对方指路时，最好边听边在地图或手机上勾画路线。"}]}, "dialog": null, "vocab": [{"num": 1, "word": "ask+（人）+for+事物", "phonetic": "", "pos": "", "meaning": "（向某人）询问／要求某事物", "examples": [], "sub_entries": [": Ask your father for advice. He'll know what", "to do.", "（去征询你父亲的意见。他会知道该怎么做。）"]}, {"num": 2, "word": "direction", "phonetic": "[daˈrekfan]", "pos": "n.", "meaning": "方向，指示", "examples": [{"en": "Can you give me directions to the train station, please?", "zh": "请你告诉我到火车站怎么走好吗？"}], "sub_entries": ["give directions", "指路，告诉如何走法"]}, {"num": 3, "word": "unfamiliar", "phonetic": "[.Anfeˈmiljo]", "pos": "a.", "meaning": "不熟悉的", "examples": [{"en": "I am not familiar with how to use a computer.", "zh": "我对如何操作电子计算机并不熟悉。"}], "sub_entries": ["familiar[fa'miljo]a.熟悉的", "人+be familiar with...", "某人对……·…·很熟悉"]}, {"num": 4, "word": "frightening", "phonetic": "[ˈfraitaniɡ]", "pos": "a.", "meaning": "ⅡF人的", "examples": [], "sub_entries": []}, {"num": 5, "word": "address", "phonetic": "[ˈadres/adres]", "pos": "n.", "meaning": "住址，地址", "examples": [], "sub_entries": []}, {"num": 6, "word": "look ..", "phonetic": "", "pos": "for.", "meaning": "寻找··", "examples": [{"en": "Ralph is looking for his house keys.", "zh": "拉尔夫正在找他房子的钥匙。"}], "sub_entries": []}, {"num": 7, "word": "be like looking for a needle in a haystack", "phonetic": "", "pos": "短语", "meaning": "如大海捞针", "examples": [{"en": "Trying to find a pencil in this messy room is like looking for a needle in a haystack.", "zh": "想在这乱七八糟的房间找一支铅笔就像是大海捞针一样。"}], "sub_entries": ["needle['nidl ]n.针", "haystack['hestak]n.大干草堆"]}, {"num": 8, "word": "get angry", "phonetic": "", "pos": "短语", "meaning": "生气", "examples": [{"en": "Carl got angry with his son because he skipped history class. Ted got angry at his motorcycle because it wouldn't start.", "zh": "卡尔对他儿子很生气，因为他逃了历史课。）（特德很气他的摩托车，因它发动不起来。"}], "sub_entries": ["=get mad", "(mad[mad]a.生气的）", "get angry", "with+人", "气某人", "at+事物", "某事物"]}, {"num": 9, "word": "usually", "phonetic": "[ˈjuːʒuəli]", "pos": "adv.", "meaning": "通常", "examples": [], "sub_entries": []}, {"num": 10, "word": "follow", "phonetic": "[falo]", "pos": "vt.", "meaning": "听得懂；跟随", "examples": [{"en": "There is a strange man following us.", "zh": "有一个奇怪的男人在跟踪我们。"}], "sub_entries": []}, {"num": 11, "word": "you'd ..", "phonetic": "", "pos": "better.", "meaning": "你最好…·····", "examples": [{"en": "Your sister is sad because you called her stupid. You'd better apologize to her.", "zh": "你妹妹很伤心，因为你说她很笨。你最好去向她道歉。"}], "sub_entries": ["=you had better...", "hadbetter+动词原形", "最好.…·", "*使用此短语时，若以代词作主语时，经常使用缩写", "形，如you'dbetter（你最好）、I'dbetter（我", "最好）、he'd better（他最好）.….…."]}, {"num": 12, "word": "draw", "phonetic": "[dr]", "pos": "vt.", "meaning": "画", "examples": [{"en": "John drew a picture of a rose and gave it to his girlfriend.", "zh": "约翰画了朵玫瑰送给他女友。"}], "sub_entries": ["动词三态：draw，drew，drawn."]}, {"num": 13, "word": "route", "phonetic": "[rut]", "pos": "n.", "meaning": "路线", "examples": [{"en": "What's the best route to take to get to Shanghai?", "zh": "要去上海最好走哪一条路线？"}], "sub_entries": []}, {"num": 14, "word": "map", "phonetic": "[mep]", "pos": "n.", "meaning": "地图", "examples": [], "sub_entries": []}, {"num": 15, "word": "...as", "phonetic": "", "pos": "directions.", "meaning": "当你在听方向指示时，···", "examples": [{"en": "Don't get nervous as you're taking the test. Don't yell at Fred as it was not his fault.", "zh": "考试时不要紧张。）（别对弗雷德吼叫，因为那不是他的错。"}], "sub_entries": ["=...when you're listening to the directions."]}], "grammar": {"intro": "本课主要介绍分词作形容词用的原则，并介绍find作不 完全及物动词的用法。", "items": [{"num": 1, "title": "分词作形容词使用的原则", "body": ["Being in an unfamiliar city can be frightening.（置身于一个不熟悉的城市里可能是件令人害怕的 事。）本句的frightening是现在分词，作形容词用，表示“令人害怕的”", "a. 现在分词与过去分词均可作形容词用，这些分词分 别有下列的意思：", "现在分词：令人…·…的 正在.·.··的（即将....的）过去分词：感到...…·的 已经.··的 换言之，表示“令人…··…·的”或“正在·…·…·的”时，应使用现在分词作形容词；表示“感到…·…的”或“已经·…·…·的”时，则应使用过去分词作形 容词。如普通形容词一样，这些分词或可置于be 动词之后，作主语补足语；或可置于名词之前，修 饰该名词。", "1）令人...的！感到…..…的", "例: It's a tiring trip.（这是很累人的一段行程。）", "He was tired after the long walk.（走完这段好长的路之后，他感到累了。）The news is encouraging.（这消息令人振奋。）I was encouraged when I heard the news.（我听到这消息时感到很振奋。）", "2）正在…·…·的（即将...·…的）／已经...…·的: The retiring teacher made a farewell speech.（这位即将退休的老师作了-次告别演说)", "The retired teacher was invited to give a speech yesterday.（这位退休的老师昨天应邀发表演说。）Don't touch the boiling water.（不要碰那正在沸腾的水。）You should drink boiled water.（你应当喝开水。）了解上列原则之后，我们就可轻易地分辨出下列错 误的分词用法：", "例：The question is confused.（×）（这问题感到糊涂。）", "-→ The question is confusing. (○)（这问题令人感到糊涂。）Give me some boiling water to drink, please.（x)（请给我一些正在开的水喝。一小心，您若真 地喝了下去，整个食道都会被烫烂的。）-> Give me some boiled water to drink, please.(○)（请给我一些开水喝。）"]}, {"num": 2, "title": "find作不完全及物动词的用法", "body": ["You may find it difficult to follow what they're saying.（你也许会发现要了解他们所说的话很困难。）在本句中，find作不完全及物动词，it是代词，作形 式宾语；difficult是形容词，作宾语补足语；to followwhat they're saying是不定式短语，也是真 正的宾语，但已被it取代。find之用法：", "a. find可作完全及物动词，亦可作不完全及物动词。", "完全及物动词就是只须加宾语，便可使句意完整的 动词。此时find相当于中文的“发现、找到”。", "例：Ifound themoney.（名词作宾语）（我找到这些钱了。）", "I found thathewas nice.（名词性从句作宾 语）（我发现他很好。）不完全及物动词就是，该及物动词加了宾语之后意 思并不完全，需要在该宾语之后另置宾语补足语，以使意思完全·这种宾语补足语通常是名词或形容 词。此时find相当于中文的“发现..…·是.....….”。", "例：Ifindhim.（×，意思不完全）（我发现他是...….。）", ")I find him nice.(○)宾语补足语（我发现他是好人。）I find him a good boy. 宾语补足语（我发现他是好男孩。）", "b. find作不完全及物动词时，可用名词、代词、动名 词作宾语。", "例: I find the work boring.", "名词（我发现这工作很无聊。）I find her a good girl. 代词（我发现她是好女孩。）I find swimming fun o 动名词（我发现游泳很有趣。）", "c. find作不完全及物动词时，不可直接用不定式短语 作宾语。应于find之后先置代词it，作形式宾语，次置宾语补足语，再置被it代替的不定式短语，该不定式短语是真正的宾语。句型如下：", "find it+宾语补足语（名词／形容词）+不定式短 语（to+动词原形）", "例：I find to work with him pleasant.（×)", "宾语 补足语", "→I find it pleasant to work with him.（O)（我发现与他共事很愉快。）The lazy boy found togo to school a bore.（x）", "→ The lazy boy found it a bore to go to school. (○)（这个懒小子发现上学是件很烦的事。）", "d. 比较下列find 的用法：", "I find it is pleasant to work with him. I find it pleasant to work with him. 以上两句均可译成“我发现与他共事很愉快。”在 第一句中find是完全及物动词，之后的\"itis pleasant toworkwithhim\"是由that引|导的名 词性从句，作find的宾语。由于该从句作及物动 词的宾语，that可予省略。在第二句中，find是不完全及物动词，以代词it 作形式宾语，形容词pleasant 作宾语补足语，to workwithhim则为不定式短语，亦是真正的宾 语。"]}, {"num": 3, "title": "think 作完全及物动词与不完全及物动词的用法", "body": ["think 亦可作完全及物动词及不完全及物动词。作完全及物动词时，think 相当于中文的“认为”；作不完全及物动词时，相当于中文的“认为...是...”及“相信...是...”。", "a. 作完全及物动词", "例：I think that he is nice.（名词性从句作宾", "语）（我认为他很好。）", "b. 作不完全及物动词", "例：I think him nice.", "宾语补足语（我认为他人很好。）He always thinks himself a hero. 宾语补足语（他总是认为自己是英雄。）", "c. 如同find一样，think作不完全及物动词时，不得 直接以不定式短语作宾语，应采下列句型：", "thinkit+宾语补足语（名词/形容词）+不定式短 语（to+动词原形）", "例: I think to learn English worthwhile. (×)", "宾语 补足语", "→I think it worthwhile to learn English.（0)（我认为学英文是值得的。）", "d. 比较下列think 的用法：", "I think it is worthwhile to learn English. I think it worthwhile to learn English. 以上两句均可译成“我认为学英文是值得的。”第 一句中，think是完全及物动词，之后\"it is worthwhile to learn English”是省略that的名词性从 句，作think之宾语，that已被省略。第二句中，think是不完全及物动词，以代词it作 形式宾语，再以形容词worthwhile作宾语补足 语，不定式短语 tolearn English是真正的宾 语。"]}]}, "substitution": [{"num": 1, "pairs": [{"en": "Being in an unfamiliar city can be frightening.", "zh": "置身于一个不熟悉的城市里可能是件令人害怕的事。"}, {"en": "Traveling long distances by train can be tiring.", "zh": "坐火车长途旅行可能很累人。"}, {"en": "Studying hard is rewarding.", "zh": "用功读书是有好处的。"}, {"en": "Climbing mountains is very exciting.", "zh": "爬山是很刺激的。"}], "en": "Being in an unfamiliar city can be frightening.", "zh": "置身于一个不熟悉的城市里可能是件令人害怕的事。"}, {"num": 2, "pairs": [{"en": "You may find it difficult to follow what they're saying.", "zh": "你也许会发现要了解他们的话很困难。"}, {"en": "Mary finds her new job a challenge.", "zh": "玛丽发现她的新工作是项挑战。"}, {"en": "I thought the job very easy.", "zh": "我以为这个工作非常简单。"}, {"en": "I think it rude to interrupt.", "zh": "我认为打断别人的话是很粗鲁的。"}], "en": "You may find it difficult to follow what they're saying.", "zh": "你也许会发现要了解他们的话很困难。"}], "exercises": null}, {"num": 100, "title_en": "Turn Right", "title_zh": "向右转", "type": "dialogue", "category": "情境实战会话", "reading": null, "dialog": {"turns": [{"speaker_en": "Foreigner", "speaker_zh": "老外", "en": "Excuse me. Could you tell me the way to the post office, please?", "zh": "对不起。可以请你告诉我到邮局怎么走吗？"}, {"speaker_en": "John", "speaker_zh": "约翰", "en": "Sure. Just walk down this street until you get to the police station. Then turn right and keep going for about two blocks. The post office is just across from the bank.", "zh": "当然可以。沿着这条街一直走到警察局。然后向右转一直走大约两个街区。邮局就在银行对面。"}, {"speaker_en": "Foreigner", "speaker_zh": "老外", "en": "Thanks a lot.", "zh": "多谢。"}]}, "vocab": [{"num": 1, "word": "turn right", "phonetic": "", "pos": "短语", "meaning": "向右转", "examples": [], "sub_entries": ["此处turn 是不及物动词，right 是副词。不可说成", "\"turn to right\"。", "turn left", "向左转"]}, {"num": 2, "word": "post office", "phonetic": "[ˈpost sfis]", "pos": "n.", "meaning": "邮局", "examples": [], "sub_entries": []}, {"num": 3, "word": "keep going", "phonetic": "", "pos": "短语", "meaning": "一直走", "examples": [{"en": "Keep going straight and you'll see the police station on the right.", "zh": "“一直走你就会在右手边看到警察局。"}], "sub_entries": ["keep+现在分词", "继续不断…···", "=keepon+现在分词"]}, {"num": 4, "word": "Thanks", "phonetic": "", "pos": "lot.", "meaning": "非常谢谢。", "examples": [], "sub_entries": ["=Thank you very much."]}], "grammar": null, "substitution": [], "exercises": {"prompt": "Ⅲ·请选出下列各句中正确的一项", "questions": ["1. Can I have some", "fish, please?", "(A) cooking", "(B) the cooking", "(C) cooked", "(D) cook", "2. 1 find", "foreign movies.", "(A) it fun to watch", "(B） funny watching", "(C) fun to watch", "(D) it to watch", "3. Traveling can be very", "(A) interested", "(B）interest", "(C) interesting", "(D）interests", "4.1", "interesting book in the library", "yesterday.", "(A) found", "(B）find an", "(C) find", "(D)found an", "5.I think", "(A) to do a good job rewarding", "(B) do a good job rewarding", "(C) it rewarding to do a good job", "(D) it rewards to do a good job", "6. When you get to 1st street,", "(A） turn to right", "(B) turn right", "(C)turn to left", "(D) right turn"], "answers": ["解答>1.(C）2.(A）3.(C）4.(D）5.(C）6.(B)"]}}, {"num": 101, "title_en": "Who Discovered America?", "title_zh": "谁发现了美洲？", "type": "reading", "category": "进阶短文与语法探究", "reading": {"en": ["Did   the Italian   explorer  Christopher Columbus really discover America? It's believed that travelers from China got there first. They crossed the Pacific to Mexico in the fifth century. In fact, Columbus landed in the Bahamas in 1492 and never got to North America. America was not even named after Christopher Columbus. It was named after Amerigo Vespucci, who landed in America in the late fifteenth century."], "zh": ["真的是意大利探险家克里斯多弗·哥伦布发现美洲的吗？一般相信来自中国的旅行者最先到达那里。他们在第5世纪时即横渡太平洋到了墨西哥。事实上，哥伦布在1492年登陆巴哈马群岛，但却未曾到达北美洲·美洲甚至不是以亚美利哥·维斯普奇的名字命名的。"], "sentences": [{"en": "Did the Italian explorer Christopher Columbus really discover America?", "zh": "真的是意大利探险家克里斯多弗·哥伦布发现了美洲吗？"}, {"en": "It's believed that travelers from China got there first.", "zh": "普遍认为来自古代中国的航海者更早抵达了那里。"}, {"en": "They crossed the Pacific to Mexico in the fifth century.", "zh": "他们早在公元5世纪便横渡太平洋登上了墨西哥海岸。"}, {"en": "In fact, Columbus landed in the Bahamas in 1492 and never got to North America.", "zh": "事实上，哥伦布于1492年登陆巴哈马群岛，从未真正踏上北美洲大陆。"}, {"en": "America was not even named after Christopher Columbus.", "zh": "“美洲”之名甚至不是源自克里斯多弗·哥伦布。"}, {"en": "It was named after Amerigo Vespucci, who landed in America in the late fifteenth century.", "zh": "它是以15世纪晚期探险美洲的航海家亚美利哥·维斯普奇的名字命名的。"}]}, "dialog": null, "vocab": [{"num": 1, "word": "discover", "phonetic": "[dɪˈskʌvɚ]", "pos": "vt.", "meaning": "发现", "examples": [{"en": "Bob,the explorer, discovered a new kind of flower in Peru.", "zh": "探险家鲍勃在秘鲁发现一·种新品种的花。"}], "sub_entries": []}, {"num": 2, "word": "Italian", "phonetic": "[Iˈteljan]", "pos": "a.", "meaning": "意大利（人）的&n.意大利人", "examples": [], "sub_entries": []}, {"num": 3, "word": "explorer", "phonetic": "[ikˈsplor]", "pos": "n.", "meaning": "探险家，探索者", "examples": [], "sub_entries": []}, {"num": 4, "word": "believe", "phonetic": "[brliv]", "pos": "vt.", "meaning": "相信", "examples": [{"en": "It is believed that Jim had sold his company.", "zh": "一般相信吉姆把他的公司卖掉了。"}], "sub_entries": ["It is believed+that引导的名词性从句", "一般相信······"]}, {"num": 5, "word": "traveler", "phonetic": "[ˈtravalo]", "pos": "n.", "meaning": "旅行者", "examples": [{"en": "The traveler is tired of living in hotels.", "zh": "这名旅客厌烦了住在旅馆里。"}], "sub_entries": []}, {"num": 6, "word": "cross", "phonetic": "[kros/kras]", "pos": "vt.", "meaning": "横越", "examples": [{"en": "It takes about a week to crossAmerica by car.", "zh": "开车横越美国大约要花·星期的时间。"}], "sub_entries": []}, {"num": 7, "word": "Mexico", "phonetic": "[ˈmeksi.ko]", "pos": "n.", "meaning": "墨西哥", "examples": [], "sub_entries": []}, {"num": 8, "word": "the fifth century", "phonetic": "", "pos": "名词短语", "meaning": "5世纪", "examples": [], "sub_entries": ["fifth[fife] a.第5的", "century['sentjari ]n.世纪", "*表示“第…….…世纪”时，需与定冠词the并用·如", "the twentieth century（20 世纪）。"]}, {"num": 9, "word": "land", "phonetic": "[laend]", "pos": "vi.", "meaning": "登陆，着陆", "examples": [{"en": "Neil Armstrong, the American astronaut, landed on the moon in 1969.", "zh": "美国太空人尼尔·阿姆斯特朗于1969年登陆月球。"}], "sub_entries": []}, {"num": 10, "word": "the Bahamas", "phonetic": "[baˈhamaz]", "pos": "n.pl.", "meaning": "巴哈马群岛", "examples": [], "sub_entries": ["*表示群岛时，需与定冠词the并用。如thePhilip", "pines（菲律宾群岛）。"]}, {"num": 11, "word": "North America", "phonetic": "", "pos": "短语", "meaning": "北美洲", "examples": [], "sub_entries": ["north[norθ]n.北方（此处作形容词用）"]}, {"num": 12, "word": "be ..", "phonetic": "", "pos": "after.", "meaning": "以...…·命名", "examples": [{"en": "Barry was named after his uncle.", "zh": "巴里是以他叔叔的名字来命名的。"}], "sub_entries": []}, {"num": 13, "word": "in the late fifteenth century", "phonetic": "", "pos": "短语", "meaning": "15世纪末", "examples": [], "sub_entries": ["in the mid fifteenth century", "15世纪中叶", "in theearlyfifteenth century", "15世纪初", "late[let]a.后期的", "mid[mid]a.中间的", "early['3li]a.初期的"]}], "grammar": {"intro": "本课主要介绍\"itis+过去分词+that引导的名词性从句\" 的句型变化。", "items": [{"num": 1, "title": "It's believed that travelers from China got there first.", "body": ["（一般相信来自中国的旅行者最先到达那里。）", "本句使用了\"It is+过去分词+that引导的名词性从", "句\"的句型。此类句型常见的有下列几个：", "It is said that...", "据说….", "It is believed that...", "一般相信····", "It is reported that...", "据报导…··", "It is estimated that...", "据估计…··", "例：It is said that Mary is leaving for London", "tomorrow.", "（据说玛丽明天要动身前往伦敦。）", "It is believed", "that printing", "gwasfirst", "invented by the Chinese.", "（一般相信印刷术最早是由中国人发明的。）", "It is reported that a traffic accident took", "place early this morning.", "（据报导今天清晨就有车祸发生。）", "It is estimated that ten people were killed", "in the accident.", "（据估计有10个人在这次车祸中丧生。）"]}, {"num": 2, "title": "It is said 句型的时态呼应与变化", "body": ["我们先以 \"It is said\" 为例，说明如下：", "a. It is said 之后由 that 引导的名词性从句之中的动词为现在式或现在进行式时，可将 that 引导的名词性从句中之主语移至句首，次接 is said 或 are said，再接虚词 to，并将 that 从句中的动词改成动词原形。", "例：It is said that he works hard.（从句为现在式）", "= He is said to work hard.（据说他工作很努力。）", "例：It is said that they are learning English.（从句为现在进行式）", "= They are said to be learning English.（据说他们正在学英语。）", "b. It is said 之后由 that 引导的名词性从句中的动词为过去式或现在完成式时，可将 that 从句中的主语移至句首，次接 is said 或 are said，再接虚词 to，并将动词一律改为 \"have + 过去分词\"。", "例：It is said that he left an hour ago.（从句为过去式）", "= He is said to have left an hour ago.（据说他一个小时前离开了。）", "例：It is said that they have come back.（从句为现在完成式）", "= They are said to have come back.（据说他们已经回来了。）", "\"It is believed\" 与 \"It is said\" 的变化完全相同。", "例：It is believed that his negligence caused the problem.（从句为过去式）", "↓", "= His negligence is believed to have caused the problem.（一般相信是他的疏忽造成了这个问题。）", "例：It is believed that he is innocent.（从句为现在式）", "= He is believed to be innocent.（一般相信他是无辜的。）", "*innocent ['ɪnəsnt] a. 无辜的", "故本课阅读的原句亦可有下列的变化：", "例：It is believed that travelers from China got there first.（从句为过去式）", "= Travelers from China are believed to have got there first.（一般相信来自中国的旅行者最先到达那儿。）"]}, {"num": 3, "title": "It seems + that 引导的名词性从句用法与转换", "body": ["“It seems + that 引导的名词性从句”（似乎...）亦有相同的句型转换变化。", "例：It seems", "s that he is a good boy.", "现在式", "=He seems to be a good boy.", "（他似乎是个好男孩。）", "It seems that they are hospitable.", "现在式", "=They seem to be hospitable.", "（他们似乎很好客。）", "*hospitable['haspitabl ]a.好客的", "It seems that he left without saying goodbye.", "过去式", "=He seems to have left without saying goodbye.", "（他似乎不告而别。）", "注意：", "seem 之后有 to be 时，to be 可予省略，故：", "He seems to be a good boy.", "=He seems a good boy.", "They seem to be hospitable.", "=They seem hospitable."]}]}, "substitution": [{"num": 1, "pairs": [{"en": "It is believed that travelers from China got there first.", "zh": "一般相信来自中国的旅行者最先到达那里。"}, {"en": "Travelers from China are believed to have got there first.", "zh": "一般相信来自中国的旅行者最先到达那里。"}, {"en": "It is said that Michael Jackson loves Asia.", "zh": "据说迈克尔·杰克逊喜爱亚洲。"}, {"en": "Michael Jackson is said to love Asia.", "zh": "据说迈克尔·杰克逊喜爱亚洲。"}], "en": "It is believed that travelers from China got there first.", "zh": "一般相信来自中国的旅行者最先到达那里。"}, {"num": 2, "pairs": [{"en": "America was not named after Christopher Columbus.", "zh": "美洲不是以克里斯多弗·哥伦布的名字命名的。"}, {"en": "Washington D.C. was named after George Washington.", "zh": "华盛顿特区是以乔治·华盛顿的名字命名的。"}, {"en": "In America the first son is often named after his father.", "zh": "在美国第一个出生的儿子通常是以他父亲的名字命名的。"}, {"en": "Were you named after anyone?", "zh": "你是以别人的名字命名的吗？。"}], "en": "America was not named after Christopher Columbus.", "zh": "美洲不是以克里斯多弗·哥伦布的名字命名的。"}], "exercises": null}, {"num": 102, "title_en": "The Same First Name", "title_zh": "同名", "type": "dialogue", "category": "情境实战会话", "reading": null, "dialog": {"turns": [{"speaker_en": "Molly", "speaker_zh": "莫莉", "en": "How come you have the same first name as your father?", "zh": "为什么你跟你父亲同名呢？"}, {"speaker_en": "Junior", "speaker_zh": "小三子", "en": "I was named after him.", "zh": "我是随他的名字取的。"}, {"speaker_en": "Molly", "speaker_zh": "莫莉", "en": "What about your sister?", "zh": "那你的妹妹呢？"}, {"speaker_en": "Junior", "speaker_zh": "小三子", "en": "She was named after my grandmother.", "zh": "她是随我祖母的名字取的。"}]}, "vocab": [{"num": 1, "word": "How come + 主语 + 动词...?", "phonetic": "", "pos": "句型", "meaning": "为什么...？（= Why...? 后面接陈述句语序）", "examples": [], "sub_entries": ["How come he hates her so much? (○) = Why does he hate her so much?", "How come does he hate her so much? (×)", "How come you are interested in learning English? (○)"]}, {"num": 2, "word": "the same... as...", "phonetic": "", "pos": "片语", "meaning": "和...同样的...", "examples": [], "sub_entries": ["注意：same 前面一定要加定冠词 the，as 之后接比较对象。", "I have the same book as that one. (○)", "I have a same book like that one. (×)"]}, {"num": 3, "word": "first name", "phonetic": "", "pos": "n.", "meaning": "名字（= given name）；last name 为姓氏（= surname = family name）", "examples": [{"en": "My name is Robert Smith. Smith is my last name, and Robert is my first name.", "zh": "我叫罗伯特·史密斯。史密斯是我的姓，罗伯特是我的名字。"}], "sub_entries": ["中国人习惯姓在前名在后；西方人习惯名在前姓在后。"]}, {"num": 4, "word": "be named after...", "phonetic": "", "pos": "片语", "meaning": "以...命名，随...的名字取名", "examples": [{"en": "He was named John after his grandfather.", "zh": "他随他祖父的名字取名为约翰。"}], "sub_entries": ["西方人有随父辈或祖辈名字取名的习惯以示尊敬。"]}, {"num": 5, "word": "What about + 名词?", "phonetic": "", "pos": "句型", "meaning": "那...呢？怎么样？（= How about + 名词?）", "examples": [], "sub_entries": ["What about / How about 之后亦可接动名词表示提议或询问。", "A: How about going to the movies tonight? （咱们今晚看电影去，你看如何？） B: Sounds great. （听起来是个好主意。）"]}, {"num": 6, "word": "grandmother / grandfather", "phonetic": "[ˈɡrændˌmʌðər / ˈɡrændˌfɑːðər]", "pos": "n.", "meaning": "祖母，外婆 / 祖父，外公", "examples": [], "sub_entries": ["grandson ['grænsʌn] n. 孙子，外孙", "granddaughter ['grænˌdɔːtər] n. 孙女，外孙女"]}], "grammar": null, "substitution": [], "exercises": {"prompt": "Ⅲ．请选出下列各句中正确的一项", "questions": ["1. Bob", "his grandfather.", "(A) was named", "(B) was named before", "(C) was named after", "(D）had the same name like", "to be from the south.", "(A）It is said that", "(B) That said", "(C) He said", "(D) They are said", "3.", "Paris is a beautiful city.", "(A） That's", "(B)It is say that", "(C) It is said that", "(D） It was says that", "4.How come", "always late?", "(A) are you", "(B) you are", "(C) do you come", "(D)you come", "5. Charlie drives", "car as yours.", "(A) a same", "(B) same", "(C) that", "(D） the same"], "answers": ["解答1.(C）2.(D）3.(C）4.(B）5.(D)"]}}, {"num": 103, "title_en": "Air Pollution", "title_zh": "空气污染", "type": "reading", "category": "进阶短文与语法探究", "reading": {"en": ["Why do people get headaches in a crowded, stuffy room? Because they are breathing bad air. People who breathe bad air for a long time can get really sick. They may even get lung cancer and die. People need fresh air. Fresh air cleans the blood. For our health's sake, we should all, therefore, do our part to fight against air pollution."], "zh": ["为什么人们在又挤又闷的房间中会头疼呢？因为他们呼吸着恶劣的空气。凡是长时间呼吸恶劣空气的人可能会生重病。他们甚至可能得肺癌死去。人们需要新鲜空气·新鲜空气能净化血液。为了健康起见，我们每个人都应该尽一已之力为反对空气污染而努力。"], "sentences": [{"en": "Why do people get headaches in a crowded, stuffy room?", "zh": "为什么人们在又挤又闷的房间中会头疼呢？"}, {"en": "Because they are breathing bad air.", "zh": "因为他们呼吸着恶劣的空气。"}, {"en": "People who breathe bad air for a long time can get really sick.", "zh": "凡是长时间呼吸恶劣空气的人可能会生重病。"}, {"en": "They may even get lung cancer and die.", "zh": "他们甚至可能得肺癌死去。"}, {"en": "People need fresh air.", "zh": "人们需要新鲜空气。"}, {"en": "Fresh air cleans the blood.", "zh": "新鲜空气能净化血液。"}, {"en": "For our health's sake, we should all, therefore, do our part to fight against air pollution.", "zh": "为了健康起见，我们每个人都应该尽一已之力为反对空气污染而努力。"}]}, "dialog": null, "vocab": [{"num": 1, "word": "pollution", "phonetic": "[paˈlufan]", "pos": "n.", "meaning": "污染", "examples": [{"en": "There's too much air pollution in the city. I want to move to the country.", "zh": "城市里的空气污染太严重了，我想搬到乡下去。"}], "sub_entries": ["air pollution", "空气污染", "water pollution", "水污染", "noise pollution", "噪音污染"]}, {"num": 2, "word": "headache", "phonetic": "[ˈhedek]", "pos": "n.", "meaning": "头痛", "examples": [{"en": "I have a headache and a sore throat. I think I have the flu.", "zh": "我头痛和喉咙痛，我想我得了流行性感冒了。"}], "sub_entries": []}, {"num": 3, "word": "crowded", "phonetic": "[ˈkraʊdɪd]", "pos": "a.", "meaning": "拥挤的", "examples": [{"en": "The train station was crowded with travelers waiting to buy tickets.", "zh": "火车站里挤满了等待购票的旅客。"}], "sub_entries": ["be crowded with...", "挤满了·····"]}, {"num": 4, "word": "stuffy", "phonetic": "[ˈstAfi]", "pos": "a.", "meaning": "空气不流通的", "examples": [{"en": "It's very stuffy in this room; open a window.", "zh": "这房间好闷，打开窗户吧。"}], "sub_entries": []}, {"num": 5, "word": "breathe", "phonetic": "[brio]", "pos": "vt.", "meaning": "呼吸", "examples": [], "sub_entries": []}, {"num": 6, "word": "air", "phonetic": "[er]", "pos": "n.", "meaning": "空气", "examples": [], "sub_entries": []}, {"num": 7, "word": "sick", "phonetic": "[sik]", "pos": "a.", "meaning": "生病的", "examples": [], "sub_entries": []}, {"num": 8, "word": "lung cancer", "phonetic": "", "pos": "短语", "meaning": "肺癌", "examples": [], "sub_entries": ["lung[lng ] n.肺", "cancer['kaens]n.癌症"]}, {"num": 9, "word": "fresh", "phonetic": "[freʃ]", "pos": "a.", "meaning": "新鲜的", "examples": [{"en": "This bread is two days old. It's not fresh.", "zh": "这面包放两天了，所以它并不新鲜。"}], "sub_entries": []}, {"num": 10, "word": "clean", "phonetic": "[klin]", "pos": "vt.", "meaning": "使干净，清洁", "examples": [{"en": "A cat cleans itself with its tongue.", "zh": "猫用舌头来舔净自己。"}], "sub_entries": []}, {"num": 11, "word": "blood", "phonetic": "[blad]", "pos": "n.", "meaning": "血液", "examples": [], "sub_entries": []}, {"num": 12, "word": "health", "phonetic": "[helθ]", "pos": "n.", "meaning": "健康", "examples": [{"en": "You shouldn't smoke. It's not good for your health. Mike is not healthy. He is always coughing. Oranges are a very healthful fruit.", "zh": "你不应该抽烟，那对你的健康不好。）（迈克不太健康，他老是在咳嗽。）（橙是很有盆健康的水果。"}], "sub_entries": ["healthy['helθ1]a.健康的", "healthful['helefal]a.有盆健康的"]}, {"num": 13, "word": "sake", "phonetic": "[sek]", "pos": "n.", "meaning": "缘故", "examples": [{"en": "For your own sake, you should go on a diet.", "zh": "为了你自己好，你应该要节食。"}], "sub_entries": ["for+所有格+sake", "为了·…·的缘故", "=for the sake of+名词"]}, {"num": 14, "word": "do one's part to + 动词原形", "phonetic": "", "pos": "短语", "meaning": "尽自己的本分去做...", "examples": [{"en": "We should all do our part to help clean up the park.", "zh": "我们每个人都应尽一己之力来打扫公园。"}], "sub_entries": ["尽某人一己之力做··."]}, {"num": 15, "word": "fight ..", "phonetic": "", "pos": "against.", "meaning": "对抗.···.", "examples": [{"en": "In World War 1I, England and America fought against Germany.", "zh": "第二次世界大战时，英国和美国一起对德国作战。"}], "sub_entries": ["fight[fait]vi.与.…….战斗/对抗", "动词三态：fight，fought，fought."]}], "grammar": {"intro": "", "items": [{"num": 1, "title": "本课为您介绍“get+形容词”的用法。", "body": ["a．一般而言，形容词多置于be动词或become（变 成）、seem（似乎）等系动词之后，作主语补足 语。", "例: The child is clever.（这孩子很聪明。）", "He became strong from exercising.（由于运动他变得强壮起来。）He seems angry.（他似乎生气了。）", "b. get亦可表示“变成”的意思，相当于become, 但become之后可置任何的形容词，get之后的形 容词则有所选择。", "例：He got clever.（×）", "-→ He became clever.(○)（他变得聪明了。）He got strong. (×)-> He became strong. (○)（他变得强壮了。）但:He got angry.（O)", "=He became angry.（他变得生气了。）一般而言：下列形容词可置于get之后：", "a. 与“生气”有关的形容词）、（）、（）得发狂的）。", "例：He got mad when he heard the news.（他听到这消息时，就生起气来。）", "b. 与“健康”有关的形容词 ill、sick（生病的）、well（身体健康的）。", "例：He got ill last week.（上星期他病了。）", "After taking the medicine, he soon got well.（吃了药之后，他很快好了起来。）", "注意：", "get ill（或sick)亦可用fall ill（或sick）取代。", "例：He fell ill but refused to see a doctor.（他病了，但却拒绝看医生。）", "c. get之后亦可接过去分词，形成被动语态，等于\"be动词+过去分词”。", "例：He was injured in the traffic accident.", "=He got injured in the traffic accident.（他在车祸中受伤。）", "About ten people were killedin the fire.", "=About ten people got killed in the fire.（这次火灾大约有十个人丧生。）", "d. get 若使用于现在进行时中，之后可接一般形容词，这些形容词多用比较级。即：", "be getting|more and more+ 形容词 比较级形容词+and+比较级形容词！变得越来越·", "例：She gets beautiful.（x）", "-→ She is getting more and more beautiful.（0)（她变得越来越漂亮了。）His English got good. (×)-→> His English is getting better and better.（o)（他的英文变得越来越好了。）"]}, {"num": 2, "title": "两个并列形容词修饰同一名词时的标点用法", "body": ["两个形容词共同修饰一个名词时，本应使用 and 连接，但亦可使用逗号取代 and，使该两个形容词的关系更加密切。", "Why do people get headaches in a crowded, stuffy room?", "=Why do people get headaches in a crowded and stuffyroom?（为什么人们在又挤又闷的房间中会头疼呢？）", "例：Nobody gets along with that selfish and mean guy.", "=Nobody gets along with that selfish, mean guy.（没有人与那个自私又卑鄙的家伙交往。）", "注意：", "有些形容词与名词并用，形成一个固定的用语（如an oldman老先生、a youngboy小男孩、αred car红车子），此时之前另置形容词时，该形容词之后 不得再置逗号或and。", "例：That kind and old man is his father.(×)", "That kind, old man is his father.（×)", "→That kind old man is his father.(○)（那位仁慈的老先生是他的父亲。）Who is that beautiful and young girl? (×)Who is that beautiful, young girl? (×)-→ Who is that beautiful young girl? (○)（那位漂亮的年轻女孩是谁？）"]}]}, "substitution": [{"num": 1, "pairs": [{"en": "People who breathe bad air for a long time get really sick.", "zh": "凡是长时间呼吸恶劣空气的人可能会生重病。"}, {"en": "Mary becomes so happy when she sees you.", "zh": "玛丽见到你时变得很高兴。"}, {"en": "Alice became sad and started to cry.", "zh": "艾丽斯变得很伤心便开始哭了起来。"}, {"en": "I suddenly became hungry when I smelled the delicious food.", "zh": "当我闻到食物的香味时，突然变得饿了起来。"}], "en": "People who breathe bad air for a long time get really sick.", "zh": "凡是长时间呼吸恶劣空气的人可能会生重病。"}, {"num": 2, "pairs": [{"en": "Why do people get headaches in a crowded, stuffy room?", "zh": "为什么人们在又挤又闷的房间中会头疼呢？"}, {"en": "This is a dirty, smelly bus.", "zh": "这是部又脏又臭的公共汽车。"}, {"en": "You are a rude, disgusting man.", "zh": "你是个粗鲁又令人厌恶的男人。"}, {"en": "Martha's son is a hardworking, intelligent young man.", "zh": "玛莎的儿子是个努力工作又聪明的年轻人。"}], "en": "Why do people get headaches in a crowded, stuffy room?", "zh": "为什么人们在又挤又闷的房间中会头疼呢？"}], "exercises": null}, {"num": 104, "title_en": "We Need Fresh Air", "title_zh": "我们需要新鲜空气", "type": "dialogue", "category": "情境实战会话", "reading": null, "dialog": {"turns": [{"speaker_en": "Joan", "speaker_zh": "琼", "en": "Boy, it's really stuffy in here.", "zh": "乖乖，这里面可真闷啊。"}, {"speaker_en": "Drake", "speaker_zh": "德雷克", "en": "You're right. We need some fresh air.", "zh": "你说得对。我们需要些新鲜空气。"}, {"speaker_en": "Joan", "speaker_zh": "琼", "en": "Let's turn on the air-con.", "zh": "咱们打开空调吧。"}, {"speaker_en": "Drake", "speaker_zh": "德雷克", "en": "Why not just open the window?", "zh": "为何不干脆打开窗户呢？"}, {"speaker_en": "Joan", "speaker_zh": "琼", "en": "That's even better.", "zh": "那就更好了。"}]}, "vocab": [{"num": 1, "word": "Boy,", "phonetic": "", "pos": "here.", "meaning": "乖乖，这里面可真闷啊。", "examples": [{"en": "Boy, it's really hot today. b. in here", "zh": "乖乖，今天真热啊。）在这里面here（这里）、there（那里）本来皆作副词，不可作介词的宾语。"}, {"en": "They will come tohere this afternoon. → They will come here this afternoon. (○) He is from Tokyo. I used to live in there. →He is from Tokyo. I used to live there.", "zh": "×)（他们下午会来这里。）（×)（0)（他来自东京。我以前曾在那儿住过。）但here 及 there 仍可作名词用，作介词in 的宾语，强调在某建筑物之内的意思。"}, {"en": "There is a study in his apartment. He feels comfortable studying in his study. =There is a study in his apartment. He feels comfortable studying in there. Don't you 1thinkit'salittlecrowdedin this room? =Don't you think it's a little crowded in here?", "zh": "他的公寓里有个书房。他在那里面看书觉得很舒服。）（你难道不觉得这房间里面有点儿挤吗？"}], "sub_entries": ["a.boy一词本作名词，表示“男孩”，此处作感叹", "词，可译成“乖乖”，表示惊叹的意思。"]}, {"num": 2, "word": "turn ..", "phonetic": "", "pos": "on.", "meaning": "打开（电器、瓦斯、水等）", "examples": [{"en": "Turn on the light; it's too dark in here. If you've finished watching TV, turn it off.", "zh": "将电灯打开，这里面太暗了。）（如果你看完电视了，就把它关掉。"}], "sub_entries": ["turn off...", "关掉（电器、瓦斯、水等）"]}, {"num": 3, "word": "air-con", "phonetic": "[ˈer.kan]", "pos": "n.", "meaning": "空调机，冷气机", "examples": [], "sub_entries": ["此单词为 air-conditioner [ˈɛrkənˌdɪʃənɚ] 的缩写形。"]}, {"num": 4, "word": "Why not just open the window?", "phonetic": "", "pos": "日常口语", "meaning": "为何不干脆打开窗户呢？", "examples": [{"en": "Why learn English? = Why must we/I learn English? Why not do it now? = Why don't you do it now?", "zh": "我们／我为什么要学英语呢？）（你们/你为何不现在就做这件事呢？"}], "sub_entries": ["= Why don't you just open the window?", "why 或why not之后可置动词原形，形成一个简化", "的问句。", "Why+动词原形...….?", "为什么要…·.·…·昵？", "Whynot+动词原形.....?", "为什么不要··呢？"]}], "grammar": null, "substitution": [], "exercises": {"prompt": "Ⅲ·请选出下列各句中正确的一项", "questions": ["1. Did you just see a", "child pass by here?", "(A) cute, young", "(B) cute and young", "(C) cute young", "(D) cute-young", "2.Paul finally", "angry.", "(A) got (B) made (C) gets (D) makes", "3. Al", "generous.", "(A) get", "(B) getting more and more", "(C) gets", "(D) is getting more and more", "4. Nancy and Jill will", "later tonight.", "(A) come to here", "(B) came here", "(C) come there", "(D) come here", "5. Why", "just take the bus to school?", "(A)don't(B)didn't (C) do(D) not", "6. If you're too fat,", "go on a diet?", "(A) why not just", "(B) why not don't you", "(C) why don't", "(D) why not don't"], "answers": ["解答>1.(C）2.(A）3.(D）4.(D）5.(D）6.(A)"]}}, {"num": 105, "title_en": "Recycling", "title_zh": "资源回收再利用", "type": "reading", "category": "进阶短文与语法探究", "reading": {"en": ["Garbage disposal is a major problem in most cities around the world. Finding places for garbage is getting more and more difficult. Recycling is, therefore, becoming very popular. In other words, more and more people are treating used material so that it can be reused. There is no doubt that recycling helps save our precious natural resources. It is in our own best interest to recycle."], "zh": ["垃圾处理在世界各地的大部分城市里是个大问题。寻找垃圾处理场越来越困难了。因此，资源回收变得很普遍·换言之，越来越多人在处理使用过的东西以便重新加以利用。毫无疑问，资源回收有助于节省珍贵的自然资源。资源回收对我们是最有利的。"], "sentences": [{"en": "Garbage disposal is a major problem in most cities around the world.", "zh": "垃圾处理在世界各地的大部分城市里是个大问题。"}, {"en": "Finding places for garbage is getting more and more difficult.", "zh": "寻找垃圾处理场越来越困难了。"}, {"en": "Recycling is, therefore, becoming very popular.", "zh": "因此，资源回收变得很普遍。"}, {"en": "In other words, more and more people are treating used material so that it can be reused.", "zh": "换言之，越来越多人在处理使用过的东西以便重新加以利用。"}, {"en": "There is no doubt that recycling helps save our precious natural resources.", "zh": "毫无疑问，资源回收有助于节省珍贵的自然资源。"}, {"en": "It is in our own best interest to recycle.", "zh": "资源回收对我们是最有利的。"}]}, "dialog": null, "vocab": [{"num": 1, "word": "recycle", "phonetic": "[riˈsaikl]", "pos": "vt. & vi.", "meaning": "重复利用（用过的物资），循环使用", "examples": [{"en": "Newspapers and plastic bottles can be recycled.", "zh": "报纸和塑胶瓶可以回收再利用。"}], "sub_entries": []}, {"num": 2, "word": "garbage", "phonetic": "[ˈɡɑːrbɪdʒ]", "pos": "n.", "meaning": "垃圾（不可数）", "examples": [], "sub_entries": []}, {"num": 3, "word": "disposal", "phonetic": "[dˈspoz!]", "pos": "n.", "meaning": "处理", "examples": [{"en": "Some uneducated people dispose of their garbage by throwing it into a river.", "zh": "有些未受过教育的人处理垃圾的方法是将它们丢到河里。"}], "sub_entries": ["dispose[dl'spoz]vi.处理", "dispose of...", "将.…加以处理"]}, {"num": 4, "word": "garbage disposal", "phonetic": "", "pos": "短语", "meaning": "垃圾处理", "examples": [], "sub_entries": []}, {"num": 5, "word": "major", "phonetic": "[ˈmeɪdʒər]", "pos": "a.", "meaning": "重要的，主要的", "examples": [{"en": "Myfather has to have a major operation next week.", "zh": "我父亲下星期必须开一个重大的手尤。"}], "sub_entries": []}, {"num": 6, "word": "problem", "phonetic": "[ˈprablam]", "pos": "n.", "meaning": "问题", "examples": [], "sub_entries": []}, {"num": 7, "word": "around the world", "phonetic": "", "pos": "短语", "meaning": "世界各地", "examples": [{"en": "Jim wants to travel around the world next year.", "zh": "吉姆明年想要去环游世界。"}], "sub_entries": ["=all over the world"]}, {"num": 8, "word": "difficult", "phonetic": "[ˈdifa.kAlt]", "pos": "a.", "meaning": "困 难的", "examples": [{"en": "Yesterday's history test was very difficult.", "zh": "昨天的历史测验很难。"}], "sub_entries": []}, {"num": 9, "word": "popular", "phonetic": "[ˈpapjala]", "pos": "a.", "meaning": "普遍的，流行的", "examples": [], "sub_entries": []}, {"num": 10, "word": "treat", "phonetic": "[trit]", "pos": "vt.", "meaning": "处理；对待", "examples": [{"en": "Paul treated his students with kindness.", "zh": "保罗对他的学生很好。"}], "sub_entries": []}, {"num": 11, "word": "used", "phonetic": "[juzd]", "pos": "a.", "meaning": "使用过的", "examples": [{"en": "There are some stores down the strcet that sell used furniture.", "zh": "这条街上有儿家卖旧家具的商店。"}], "sub_entries": []}, {"num": 12, "word": "material", "phonetic": "[maˈturial]", "pos": "n.", "meaning": "物质，材料（数、不u可数", "examples": [], "sub_entries": ["皆可）"]}, {"num": 13, "word": "reuse", "phonetic": "[rijuz]", "pos": "vt.", "meaning": "再使用", "examples": [], "sub_entries": []}, {"num": 14, "word": "There is no doubt that + 从句", "phonetic": "", "pos": "句型", "meaning": "毫无疑问...", "examples": [{"en": "There isnodoubtthatdrinkingtoomuch wine is bad for your health.", "zh": "喝太多酒对健康有害是毫无疑问的。"}], "sub_entries": ["毫无疑问·····", "doubt[daut]n.疑问，怀疑"]}, {"num": 15, "word": "save", "phonetic": "[sev]", "pos": "vt.", "meaning": "节省", "examples": [{"en": "If you don't finish the fish, save it for tomorrow.", "zh": "如果你没有把鱼吃完，就留到明天再吃。"}], "sub_entries": []}, {"num": 16, "word": "precious", "phonetic": "[ˈprefas]", "pos": "a.", "meaning": "珍贵的", "examples": [], "sub_entries": []}, {"num": 17, "word": "natural resources", "phonetic": "", "pos": "短语", "meaning": "自然资源（通常用复数）", "examples": [{"en": "That country has more natural resources than any other country.", "zh": "那个国家有比其它任何国家更多的自然资源。"}], "sub_entries": ["natural['netfaral]a.自然的", "resource[rrsors]n.资源（常用复数）"]}, {"num": 18, "word": "It", "phonetic": "", "pos": "", "meaning": "is inone's own best interest to+动词原形", "examples": [{"en": "It's in your own best interest to avoid arguing with others.", "zh": "避免和别人争论对你是最有利的。"}], "sub_entries": ["·….·…对某人是最有利的", "interest['intrist ]n.利益"]}], "grammar": {"intro": "本课介绍一些不可数名词丶连词sothat（以便...…·） 以及help的用法。", "items": [{"num": 1, "title": "Garbage disposal is a major problem.", "body": ["（垃圾处理是个大问题。）本句中的garbage 在句中为名词作形容词，修饰之后 的主语disposalo", "a. garbage是集合名词，是“垃圾”的总称，为不可 数名词，不可说agarbage、two garbages many garbages、some garbages、要说a piece ofgarbage（一件垃圾）、twopiecesof garbage（两件垃圾）、a lot of garbage（许多 垃圾）、somegarbage（·些垃坂）。", "例: The room is full of garbages. (×）", "> The room is full of garbage. (○)（房间里都是垃圾。）He picked up a garbage and threw it into the garbage bin. (×)>He picked up a piece_of garbage eand threw it into the garbage bin. (○)（他拾起一件垃圾把它扔到垃圾桶里。）", "b. rubbish ['rʌbɪʃ]亦表示“垃圾”，亦是不可数名 词，是garbage 的同义词，用法与 garbage 样。", "c. 其他常用的不可数名词尚有下列儿个：", "information[unf?'mefan]资讯，资料 baggage['bagid3]行李 luggage[lagid3 ]行李 advice[ad'vars]建议，忠告 junk[d3Agk]垃圾 music['mjuzik]音乐 news[njuz]消息，新闻 furniture[f3nitfo]家具 equipment[1kwipmant]设备 以上名词亦与apieceof、some、alotof、much、little 并用。", "例: How many luggages do you have? (×)", "-> How many pieces of luggage do you have?（0)（你一共有几件行李？）He gave me a good advice. (×)-→ He gave me a good piece of advice. (○)（他给我－个很好的建议。）That's really a good news. (×)-> That's really good news. (○)", "=That's really a good piece of news.（那实在是－·则好消息。）The couple bought a lot of furnitures.（×)> The couple bought a lot of furniture.(○)（那对夫妇买了许多家具。）"]}, {"num": 2, "title": "In other words, more and more people are treating used material so that it can be reused.", "body": ["（换言之，越来越多的人在处理使用过的东西以便重新 加以利用。）sothat为连词，表示“以便”的意思。sothat引 导状语从句，置于主句之后，修饰该主句。Sothat所 引导的状语从句要有助动词may、can 或will。句 子结构如下：", "主句+so that+主语+may/can/will+动词原形", "例：He studied hard so that he could pass the exam.（他努力读书以便能通过那项考试。）", "I need your help so that I may finish the work on time.（我需要你的帮助以便能准时完成这工作。）Tell himhow todoit sothat hewill not make the same mistake again.（告诉他怎么做，这样他就不会再犯同样的错误)证商：", "a. so that亦可被in order that取代。", "上列三句皆可改写如下：", "He studied hardin_order thathe could pass the exam. I need your help in order that I may finish the work on time. Tellhimhow to do it in order that he will not make the same mistake again.", "b. sothat或inorderthat所引导的状语从句中的 主语若与主句的主语相同时，该从句可改为\"soas 语不同时则不能采用此句法。", "例：He studied hard so that he could pass the exam.", "=He studied hard in order to pass the exam.", "=He studied hard so as to pass the exam.（他努力读书以便能通过那项考试·）I need your helpin order that 1 may finish it on time.", "=I need your help in order to finish it on time.", "=I need your help so as to finish 1iton time.（我需要你的帮助以便能准时完成这工作。）比较下列两句：", "例：He sang a song so that his wife might", "feel happy.（主语不同）（他唱一首歌好让太太高兴。）He sang a song so that the might feel happy.（主语相同）", "=He sang a song so as to feel happy.（他唱一首歌好让自己高兴。）", "c. soas to或inorder to与not并用时，应为 so as not to 或 in order not to,而非 so as to not 或in order to not。", "例：Ileftearly soas to not miss the train.（×)", "→Ileftearly soasnot to miss the train.（o)（我提早离开以免赶不上火车。）"]}, {"num": 3, "title": "There is no doubt that recycling helps save our precious natural resources.", "body": ["=There is nodoubt that recycling helps to save our precious natural resources.（毫无疑问，资源回收有助于节省珍贵的自然资源。）本句中help是及物动词，以to引导的不定式短语作 宾语，但to常予省略。即：", "help+(to)+动词原形 帮助·····", "例：Let's help to finish the work.", "=Let's help finish the work.（咱们来帮忙把这工作做完。）help 亦有下列的用法，to亦可省略：", "help+人+(to)+动词原形 帮助某人·", "例：He helped me to write the letter.", "=He helped me write the letter.（他帮我写这封信。）"]}]}, "substitution": [{"num": 1, "pairs": [{"en": "More and more people are treating used material so that it can be reused.", "zh": "越来越多的人正在处理旧材料，以便它能被再次使用。"}, {"en": "Sam left work early so that he could take his son to a baseball game.", "zh": "山姆早下班以便带他儿子去看棒球赛。"}, {"en": "I had to stay up late last night in order to finish writing this report.", "zh": "我昨晚必须熬夜以便写完这篇报告。"}, {"en": "Carl exercises every day so as not to get fat.", "zh": "卡尔每天运动以保持身材不发胖。"}], "en": "More and more people are treating used material so that it can be reused.", "zh": "越来越多的人正在处理旧材料，以便它能被再次使用。"}, {"num": 2, "pairs": [{"en": "There is no doubt that recycling helps (to) save our precious natural resources.", "zh": "毫无疑问，资源回收有助于节省我们的天然资源。"}, {"en": "Policemen help (to) protect us against criminals.", "zh": "警察帮助我们防范罪犯。"}, {"en": "My mother often helps me (to) prepare for my exams.", "zh": "我母亲经常帮助我准备考试。"}, {"en": "Nancy usually helps her sister (to) do her chores.", "zh": "南希通常帮助她妹妹做家务。"}], "en": "There is no doubt that recycling helps (to) save our precious natural resources.", "zh": "毫无疑问，资源回收有助于节省我们的天然资源。"}], "exercises": null}, {"num": 106, "title_en": "Litterbugs", "title_zh": "垃圾虫", "type": "dialogue", "category": "情境实战会话", "reading": null, "dialog": {"turns": [{"speaker_en": "Child", "speaker_zh": "小孩", "en": "Why is there so much garbage in the street, Mom?", "zh": "妈妈，为什么街上有这么多垃圾呢？"}, {"speaker_en": "Mother", "speaker_zh": "母亲", "en": "Because there are many litterbugs.", "zh": "因为有很多垃圾虫。"}, {"speaker_en": "Child", "speaker_zh": "小孩", "en": "What are litterbugs?", "zh": "什么是垃圾虫呢？"}, {"speaker_en": "Mother", "speaker_zh": "母亲", "en": "They're people who don't put their rubbish in trash cans.", "zh": "就是那些不把垃圾丢在垃圾箱里的人。"}]}, "vocab": [{"num": 1, "word": "litterbug", "phonetic": "[ˈlitaubaɡ]", "pos": "n.", "meaning": "垃圾虫，乱丢垃圾的人", "examples": [], "sub_entries": []}, {"num": 2, "word": "trash can", "phonetic": "[ˈtrae∫ken]", "pos": "n.", "meaning": "垃圾箱", "examples": [], "sub_entries": ["=garbage can"]}], "grammar": null, "substitution": [], "exercises": {"prompt": "Ⅲ：请选出下列各句中正确的一项", "questions": ["1. I just sold", "furniture.", "(A) a (B) a piece (C) many (D) a piece of", "2. He buys inexpensive clothes", "save money.", "(A) in order to", "(B)on order", "(C) so as", "(D) so that he", "3. Running helps me", "stay healthy.", "(A)be", "(B) am", "(C) to", "(D)of", "4. Talk softly", "wake my sleeping brother.", "(A) so as to", "(B) so as not to", "(C) so as to not", "(D) so not to", "5. This car is", "junk. It doesn't work.", "(A) a piece of (B) a piece (C) pieces of (D) a", "6.", "a litterbug; put your rubbish in a trash", "can.", "(A)Be", "(B)Why not be", "(C) Don't", "(D) Don't be"], "answers": ["解答1.(D）2.(A）3.(C）4.(B）5.(A）6.(D)"]}}, {"num": 107, "title_en": "The Secret of Longevity", "title_zh": "长寿的秘诀", "type": "reading", "category": "进阶短文与语法探究", "reading": {"en": ["Hong Ying, who comes from Guangdong, is known as the oldest person in China. She is 122 years old. Although she can hardly hear, her voice is loud and clear. In fact, she is still full of life. What's the secret of her longevity? Maybe it's her personality. According to her family and friends, she is humorous and easy to get along with."], "zh": ["籍贯广东的洪英（译音）是中国众所周知最长寿的老人。她现年122岁。虽然她几乎听不见，但她的声音宏亮又清晰。事实上，她仍充满了生命力。她长寿的秘诀是什么呢？也许在于她的个性。据她的家人和朋友说，她很幽默也容易相处。"], "sentences": [{"en": "Hong Ying, who comes from Guangdong, is known as the oldest person in China.", "zh": "籍贯广东的洪英（译音）是中国众所周知最长寿的老人。"}, {"en": "She is 122 years old.", "zh": "她现年122岁。"}, {"en": "Although she can hardly hear, her voice is loud and clear.", "zh": "虽然她几乎听不见，但她的声音宏亮又清晰。"}, {"en": "In fact, she is still full of life.", "zh": "事实上，她仍充满了生命力。"}, {"en": "What's the secret of her longevity?", "zh": "她长寿的秘诀是什么呢？"}, {"en": "Maybe it's her personality.", "zh": "也许在于她的个性。"}, {"en": "According to her family and friends, she is humorous and easy to get along with.", "zh": "据她的家人和朋友说，她很幽默也容易相处。"}]}, "dialog": null, "vocab": [{"num": 1, "word": "longevity", "phonetic": "[lɔːnˈdʒevəti]", "pos": "n.", "meaning": "长寿，长命", "examples": [], "sub_entries": []}, {"num": 2, "word": "be ..", "phonetic": "", "pos": "as.", "meaning": "以...··身份知名，是众所周知的...·", "examples": [{"en": "Michael Jordan is known as a great basketball player.", "zh": "众所周知迈克尔·乔丹是个杰出的篮球运动员。"}], "sub_entries": []}, {"num": 3, "word": "hardly", "phonetic": "[ˈhɑːrdli]", "pos": "adv.", "meaning": "几乎不", "examples": [{"en": "\"Come closer; I can hardly see you,\" said the old man.", "zh": "那老人说：“靠近一点，我儿乎看不到你。”"}], "sub_entries": []}, {"num": 4, "word": "voice", "phonetic": "[vois]", "pos": "n.", "meaning": "声音", "examples": [{"en": "Grace has a wonderful singing voice.", "zh": "格雷斯有副唱歌的好嗓子。"}], "sub_entries": []}, {"num": 5, "word": "loud", "phonetic": "[laud]", "pos": "a.", "meaning": "大声的", "examples": [{"en": "Turn down the radio; it's too loud.", "zh": "把收音机关小声-点，声音太大了。"}], "sub_entries": []}, {"num": 6, "word": "clear", "phonetic": "[klir]", "pos": "a.", "meaning": "清楚的，清晰的", "examples": [{"en": "The water in this polluted river used to be clean and clear.", "zh": "这条受过污染的河流，以前既清澈又干净。"}], "sub_entries": []}, {"num": 7, "word": "be ..", "phonetic": "", "pos": "of.", "meaning": "充满····", "examples": [{"en": "That restaurant is always full of customers.", "zh": "那家餐厅总是挤满了顾客。"}], "sub_entries": ["=be filled with...", "full[ful]a.充满的", "fill[fil] vt.使充满"]}, {"num": 8, "word": "personality", "phonetic": "[ˌpɜːrsəˈnæləti]", "pos": "n.", "meaning": "个性", "examples": [{"en": "Jessica has a wonderful personality. She's kind and considerate.", "zh": "杰西卡的个性很好。她既仁慈又体贴。"}], "sub_entries": []}, {"num": 9, "word": "according ..", "phonetic": "", "pos": "to.", "meaning": "根据·….", "examples": [], "sub_entries": []}, {"num": 10, "word": "humorous", "phonetic": "[ˈhjumaras]", "pos": "a.", "meaning": "幽默的，有幽默感的", "examples": [], "sub_entries": []}], "grammar": {"intro": "本课介绍\"beknown as+身份”及\"Sheiseasy to get alongwith.”的句子结构。", "items": [{"num": 1, "title": "Hong Ying... is known as the oldest person in China.", "body": ["（洪英·是中国众所周知最长寿的老人。）be known 之后，常用的介词有下列三个：", "a. be known as+身份 以某身份被人所知；是众所周知的·…·", "例: He is known as a great scientist.（众所周知他是杰出的科学家。）", "b. beknown for+事物 因某事物为人所知", "例：He is known for his musical talent.（他在音乐方面的天赋使他声名大噪。）", "c. be known to+人 被某人所知", "例: He is known to all of us.（我们都知道他。）", "注意：", "无下列用法：", "He is known by us. (×)"]}, {"num": 2, "title": "famous, renowned, noted 等表“出名的”形容词介词搭配", "body": ["形容词如 famous['feɪməs]、renowned[rɪ'naʊnd]、noted['noʊtɪd]，均表“出名的”，之后可使用介词 as 或 for。", "a. be noted as+身份 以某身份被人所知；fanous 是众所周知的····lrenowned", "例: He is renowned as a talented musician.（他是个颇富盛名才气洋溢的音乐家。）", "b. be noted for+事物 因某事物为人所知 famous renowned", "例：He is famous for his invention of the light bulb.（他因发明了电灯而声名大噪。）"]}, {"num": 3, "title": "...she is humorous and easy to get along with.", "body": ["（...…她很幽默也容易相处。）本句乃由下列句子简化而来：", "...she is humorous and she is easy to get along with.", "a. 试比较下列两句：", "She is easy to get along with others. (×)（她很容易与别人相处。）-> She is willing to get along with others. (○)（她愿意与别人相处。）以上两句的句子结构完全.一样，easy（容易的）、willing（愿意的）均为形容词，皆作主语补足语，误的，第二句却是正确的。理由何在？这完全与作 主语补足语的形容词有关。", "b. 请注意下列的句型：", "人+be动词+形容词+to+动词原形 在上列的句型中，形容词必须有“出自某人心中的 意愿”的涵义。常用的这些形容词有willing（愿意的）、glad（乐意的）、eager（渴望的）、longing（渴望 的）、anxious（渴望的）。这些形容词之后要接 虚词to引导的不定式短语。短语中若动词原形是 不及物动词，之后不得置宾语；若动词原形是及物 动词，之后应置宾语；若短语语尾有介词，亦应置 宾语。", "例:He is willing to go. (○)（他愿意去。）", "理由：g0是不及物动词，之后无需接宾语。He is eager to do. (×)理由：do是及物动词，故之后须接宾语。", "→He is eager to do it.（o)（他驱欲做这件事。）理由：do之后已有it作宾语。He is glad to do it with. (×)理由：with是介词，之后应有宾语。-→He is glad to do it with me. (○)（他乐意与我做这件事。）理由：with之后有me作宾语。由上得知：", "She is willing to get along with others.(○)理由：with是介词，others作其宾语。", "c. easy（容易的）、difficult（困难的）、hard（困 难的）等形容词，是修饰事情的形容词，不可用来 修饰人。", "例：He is easy.（×）", "人（他很容易。--无此用法。）The job is easy. (○)重（这工作很容易。）Singing is hard for me. (○)事（对我来说唱歌很困难。）To do the work is easy. (○)（做这工作很容易。）以上例句中，我们可用名词（The job）、动名词(Singing）、或不定式短语（Todothe work）作 主语，be 动词之后可接easy、hard（或diffi-cult)等形容词作主语补足语。d．不定式短语作主语时，若该短语最后-一个字是宾 语，可将该宾语变作主语，短语的其余部分则移至 句尾·该主语仍同时作句尾及物动词或介词的宾 语。", "例：To do the work is hard.", "主语（做这工作很难。）在上例中，the work 是不定式短语中动词 do的 宾语，故可变作主语，To do则移至句尾，即成：", "The work is hard to do.（这工作很难做。）在上句中，Thework仍作句尾do的宾语。故不 可写成：", "The work is hard to do it.（×，it 是多余 的宾语）又例: To get along with her is easy.（跟她相处很容易。）在上例中，her是不定式短语中介词with 的宾语，故可变作主语（但须将her 改成主格形态she)，To get along with则移至句尾，即成：", "She is easy to get along with.（她很容易相处。）在上句中，she 仍作句尾with 的宾语。故不可写成：", "She is easy to get along with others. ( x , others是多余的宾语）"]}]}, "substitution": [{"num": 1, "pairs": [{"en": "Hong Ying is known as the oldest person in China.", "zh": "洪英是中国众所周知最长寿的老人。"}, {"en": "Mack is known as a writer of children's books.", "zh": "麦克是位知名的儿童故事作家。"}, {"en": "Picasso is renowned as a painter.", "zh": "毕加索是位知名的画家。"}, {"en": "Connie is famous for her poetry.", "zh": "康妮以其诗而闻名。"}], "en": "Hong Ying is known as the oldest person in China.", "zh": "洪英是中国众所周知最长寿的老人。"}, {"num": 2, "pairs": [{"en": "She is humorous and easy to get along with.", "zh": "她很幽默也容易相处。"}, {"en": "She is willing to help others.", "zh": "她很乐意助人。"}, {"en": "They are anxious to go out and play.", "zh": "他们急着要出去玩。"}, {"en": "Charles is longing to see his girlfriend.", "zh": "卡洛斯渴望看到他的女友。"}], "en": "She is humorous and easy to get along with.", "zh": "她很幽默也容易相处。"}], "exercises": null}, {"num": 108, "title_en": "Slow Down", "title_zh": "慢下来", "type": "dialogue", "category": "情境实战会话", "reading": null, "dialog": {"turns": [{"speaker_en": "Rosa", "speaker_zh": "罗莎", "en": "Slow down, Carl. I can't keep up with you.", "zh": "卡尔，走慢一点。我跟不上你。"}, {"speaker_en": "Carl", "speaker_zh": "卡尔", "en": "You walk as slowly as a snail.", "zh": "你走得跟蜗牛·…样慢。"}, {"speaker_en": "Rosa", "speaker_zh": "罗莎", "en": "How do you keep so fit?", "zh": "你是怎么保持这么健康的呢？"}, {"speaker_en": "Carl", "speaker_zh": "卡尔", "en": "I work out as often as I can.", "zh": "我尽可能地经常运动。"}]}, "vocab": [{"num": 1, "word": "slow down", "phonetic": "", "pos": "短语", "meaning": "（指开车、走路或行动上）慢下来", "examples": [{"en": "John told the taxi driver to slow down as he was driving too fast.", "zh": "约翰叫出租车司机开慢-一点因他开得太快了"}], "sub_entries": []}, {"num": 2, "word": "keep ..", "phonetic": "", "pos": "with.", "meaning": "赶上...·…·的速度，不落于...·之后", "examples": [{"en": "The new student finds it difficult to keep up with the class.", "zh": "那位新来的学生发现自已很难赶上班上的进度。"}], "sub_entries": []}, {"num": 3, "word": "walk as slowly as a snail", "phonetic": "", "pos": "短语", "meaning": "走得与蜗牛一样慢", "examples": [], "sub_entries": ["snail[snel]n.蜗牛"]}, {"num": 4, "word": "keep fit", "phonetic": "", "pos": "短语", "meaning": "保持健康", "examples": [{"en": "I jog every day in order to keep fit.", "zh": "我每天慢跑以保持健康。"}], "sub_entries": ["fit[fit ]a.健康的"]}, {"num": 5, "word": "work out", "phonetic": "", "pos": "短语", "meaning": "运动（尤指体操、有氧舞蹈等增进体能", "examples": [{"en": "I used to work out at the gym every afternoon.", "zh": "我以前每天下午都到健身房去运动。"}], "sub_entries": ["的运动）"]}, {"num": 6, "word": "as often as I can", "phonetic": "", "pos": "短语", "meaning": "尽可能经常", "examples": [{"en": "You should be as careful 1aspossiblewhen doing the work. You must work as hard as you can.", "zh": "做这件工作时，你应尽量谨慎。）（你要尽量努力工作。"}], "sub_entries": ["=as often as possible", "as+形容词/副词+asonecan", "尽可能·….", "=as+形容词/副词+as possible"]}], "grammar": null, "substitution": [], "exercises": {"prompt": "Ⅲ．请选出下列各句中正确的一项", "questions": ["1.", "is very difficult to get along with.", "(A) The book", "(B) The boy", "(C) The job", "(D) The toy", "2. Carl is easy", "(A) to work along", "(B) to get along", "(C) to work alone", "(D) to work with", "3. Alice is longing", "home.", "(A) to go (B) going (C) for go (D) with", "4. I'm sorry. I am unable", "(A) go", "(B) to do (C) to go (D) do", "5.Shakespeare is known", "a great writer.", "(A) to (B) for", "(C) as", "(D) be", "6. 1 exercise", "(A) as often as I can", "(B) as often as I possible", "(C) as I possibly can", "(D) as possible as I can"], "answers": ["解答1.(B）2.(D）3.(A）4.(C）5.(C）6.(A)"]}}, {"num": 109, "title_en": "Discovering Africa", "title_zh": "探索非洲", "type": "reading", "category": "进阶短文与语法探究", "reading": {"en": ["David Livingstone was a doctor and explorer from Scotland. He is famous for traveling 29,000 miles in Africa during the 19th century. He discovered many rivers, lakes and mountains, including the Victoria Falls, the biggest waterfall in the world. Most of all, he is highly respected because he helped to abolish slave trade in Africa."], "zh": ["大卫·李文斯顿是来自苏格兰的医生及探险家。他于19世纪在非洲旅行了29000英里而声名大噪。他发现了许多河流、的是，他因促成废除非洲的奴隶买卖而备受尊敬。"], "sentences": [{"en": "David Livingstone was a doctor and explorer from Scotland.", "zh": "大卫·李文斯顿是来自苏格兰的杰出医生与探险家。"}, {"en": "He is famous for traveling 29,000 miles in Africa during the 19th century.", "zh": "他在19世纪徒步横穿非洲大陆漫游29000英里而名扬天下。"}, {"en": "He discovered many rivers, lakes and mountains, including the Victoria Falls, the biggest waterfall in the world.", "zh": "他探险发现了许多大河、高山及湖泊，其中包括世界著名的维多利亚瀑布。"}, {"en": "Most of all, he is highly respected because he helped to abolish slave trade in Africa.", "zh": "最受人敬仰的是，他倾尽毕生心血推动废除了非洲的残暴奴隶贸易。"}]}, "dialog": null, "vocab": [{"num": 1, "word": "Africa", "phonetic": "[ˈefrika]", "pos": "n.", "meaning": "非洲", "examples": [], "sub_entries": []}, {"num": 2, "word": "explorer", "phonetic": "[ikˈsplora]", "pos": "n.", "meaning": "探险家，探索者", "examples": [], "sub_entries": []}, {"num": 3, "word": "Scotland", "phonetic": "[ˈskatland]", "pos": "n.", "meaning": "苏格兰", "examples": [], "sub_entries": []}, {"num": 4, "word": "be ..", "phonetic": "", "pos": "for.", "meaning": "以·.…而出名", "examples": [{"en": "Herman Melville is famous for writing Moby Dick.", "zh": "赫曼·梅尔威尔因写《白鲸》一书而出名。"}], "sub_entries": ["famous[femas]a.出名的"]}, {"num": 5, "word": "travel", "phonetic": "[ˈtravl]", "pos": "vt.", "meaning": "&vi.旅行", "examples": [{"en": "The explorers traveled the world looking for treasure. Last year I traveled around Asia.", "zh": "那些探险家们到世界各地去旅行寻宝·）（去年我从事一趟环亚之旅。"}], "sub_entries": []}, {"num": 6, "word": ".mile", "phonetic": "[mail]", "pos": "n.", "meaning": "英里，哩", "examples": [], "sub_entries": []}, {"num": 7, "word": "river", "phonetic": "[ˈriv]", "pos": "n.", "meaning": "河流", "examples": [], "sub_entries": []}, {"num": 8, "word": "lake", "phonetic": "[lek]", "pos": "n.", "meaning": "湖泊", "examples": [], "sub_entries": []}, {"num": 9, "word": "mountain", "phonetic": "[ˈmauntin]", "pos": "n.", "meaning": "山", "examples": [], "sub_entries": []}, {"num": 10, "word": "including", "phonetic": "[inˈkludiɡ]", "pos": "prep.", "meaning": "包括，包含", "examples": [{"en": "Everyone help clean the classroom, including you, Jerry.", "zh": "每个人都要帮忙打扫教室，包括你杰丽。"}], "sub_entries": []}, {"num": 11, "word": "the Victoria Falls", "phonetic": "", "pos": "名词短语", "meaning": "维多利亚瀑布", "examples": [], "sub_entries": ["fall[fol]n.瀑布", "*用来指某瀑布时，fall置在专有名词之后，通常需", "加-S，且专有名词前需置定冠词the，如：the", "NiagaraFalls（尼加拉瀑布）。"]}, {"num": 12, "word": "waterfall", "phonetic": "[ˈwoto.fol]", "pos": "n.", "meaning": "瀑布", "examples": [], "sub_entries": []}, {"num": 13, "word": "most of all", "phonetic": "", "pos": "短语", "meaning": "更重要的是，尤其是", "examples": [{"en": "I love seafood. Most of all, I love to eat tuna fish.", "zh": "我喜欢海鲜。我尤其喜欢吃鱼。"}], "sub_entries": []}, {"num": 14, "word": "be highly respected", "phonetic": "", "pos": "短语", "meaning": "很受尊敬", "examples": [{"en": "Larry is highly respected because he has a doctor's degree.", "zh": "拉里很受人尊敬；因为他有博士学位。"}], "sub_entries": []}, {"num": 15, "word": "abolish", "phonetic": "[aˈbaljf]", "pos": "vt.", "meaning": "废除，废止", "examples": [{"en": "Paul believes the death penalty shouldn't be abolished.", "zh": "保罗认为死刑不应被废除。"}], "sub_entries": []}, {"num": 16, "word": "slave trade", "phonetic": "", "pos": "短语", "meaning": "奴隶买卖／交易", "examples": [], "sub_entries": ["slave[slev ]n.奴隶", "trade[tred]n.交易，买卖"]}], "grammar": {"intro": "本课介绍可作介词的现在分词及名词同位语的用法。 He discovered many rivers, lakes and mountains, including the Victoria Falls, the biggest waterfall in the world. （他发现了许多河流、湖泊和山i峦，包括世界上最大的 瀑布一～-维多利亚瀑布。）", "items": [{"num": 1, "title": "including 的介词用法与标点规范", "body": ["此处 including 虽是现在分词的形态，实际却是介词，表示“包括”的意思，使用时通常其前置一逗号，其后接宾语。", "后置宾语。若宾语在句尾，则之后置句号。若宾语在", "句中，之后置逗号。", "a.宾语置句尾：", "例: He has many hobbies, including_singing", "and stamp collecting.", "（他有许多爱好，包括唱歌和集邮。）", "b.宾语置句中：", "例：A few students, including John, passed", "the exam.", "（包括约翰在内，有几名学生考及格了。）"]}, {"num": 2, "title": "除 including 以外，有少数现在分词亦可作介词用：", "body": ["常用的有 regarding [rɪ'ɡɑːrdɪŋ] 及 concerning [kən'sɜːrnɪŋ]，均表示“有关”的意思，这两个介词多出现于文章中，与 on（有关）同义。about 亦可表示“有关”，多用于口语中。", "例：He is writing a paper regarding / concerning / on air pollution.（他正在写一篇有关空气污染的论文。）", "Tell us more about his background.（多告诉我们一些有关他的背景。）"]}, {"num": 3, "title": "名词同位语的用法", "body": ["...including the Victoria Falls, the biggest waterfall in the world.", "（......·包括世界上最大的瀑布一维多利亚瀑布。）", "上列句中，the biggest waterfall in the world就是", "the Victoria Falls的名词同位语。", "a.所谓名词同位语，就是在名词之后另置一名词，而", "两个名词地位相等。此时我们称第二个名词为第一·", "个名词的同位语。", "例：This is John, a friend of mine.", "（这是约翰，他是我的朋友。）", "本句中afriend ofmine是John的同位语。由", "于John 在句中作宾语，故我们称afriend of", "mine为宾语同位语。", "又例:John, an English professor, teaches very", "well.", "（约翰是英文教授，书教得很好。）", "本句中an English professor 是John 的同位", "语·由于John在句中作主语，故我们称an", "English professor为主语同位语。", "又例：He is John, my idol.", "（他是约翰，也是我的偶像。）", "*idol['aidl]n.偶像", "本句中myidol是John的同位语·由于John", "在句中作主语补足语，故我们称 myidol为补足", "语同位语。", "b.名词同位语乃由下列定语从句简化而成：", "who/which+be动词+名词", "例: This is John, who is a friend of mine.", "=This is John, a friend of mine.", "John, who is an English professor, teaches", "very well.", "=John, an English professor, teaches very", "well.", "He is John, who is my idol.", "=He is John, my idol.", "又例：The dandelion, which is a small wild", "flower, can be found almost everywhere.", "=The dandelion, a small wild flower, can", "be found almost everywhere.", "（蒲公英是一种小野花，几乎到处可以见", "到。）", "*dandelion [ˈdændɪlaɪən] n. 蒲公英", "I enjoy reading The Old Man and the Sea,", "which is a classic by Ernest Hemingway.", "=I enjoy reading The Old Man and the Sea,", "a classic by Ernest Hemingway.", "（我喜欢看《老人与海》，那是海明威的经典之", "作。）", "*classic [ˈklæsɪk] n. 杰作", "Horses, which are animals that were once", "used for transportation, have been replaced", "by cars.", "=Horses, animals that were once used for", "transportation, have been replaced by cars.", "（马是一度曾被用作运输的动物，现在已被汽车取", "代了。）", "故本课阅读原文中：", "...including the Victoria Falls, the biggest", "waterfall in the world.", "=..including the Victoria Falls, which is the", "biggest waterfall in the world.", "c.由于名词同位语均由非限制性定语从句（即关系代", "词who或which之前要有逗号）简化而成，故名", "词同位语之前亦应有逗号。若名词同位语在句中出", "现时，之后亦应置逗号；若在句尾出现时则置句", "号。", "句中：", "例：David, a historian, knows a lot about the", "history of China.", "（大卫是史学家，对中国史很了解。）", "句尾：", "例: Here comes Rover, my pet dog:", "（我的爱犬来福来了。）"]}]}, "substitution": [{"num": 1, "pairs": [{"en": "David Livingstone was a doctor and explorer from Scotland.", "zh": "大卫·李文斯顿是来自苏格兰的医生及探险家。"}, {"en": "David Livingstone, a doctor and explorer, was from Scotland.", "zh": "大卫·李文斯顿是医生及探险家，他来自苏格兰。"}, {"en": "Tangerines, a kind of fruit, are good for you.", "zh": "柑橘是一种水果，对你有好处。"}, {"en": "I want to go to Switzerland, a country in Europe.", "zh": "我想到瑞士去，那是位于欧洲的国家。"}], "en": "David Livingstone was a doctor and explorer from Scotland.", "zh": "大卫·李文斯顿是来自苏格兰的医生及探险家。"}, {"num": 2, "pairs": [{"en": "He discovered many rivers and lakes, including the Victoria Falls.", "zh": "他发现了许多河流和湖泊，包括维多利亚瀑布。"}, {"en": "I want to travel to many countries, including Spain and Portugal.", "zh": "我想到许多国家去旅行，包括西班牙和葡萄牙。"}, {"en": "The singer sang many songs, including some of my favorites.", "zh": "这位歌手唱了许多歌，包括一些我最喜欢的歌。"}, {"en": "Larry can play many musical instruments, including the violin and saxophone.", "zh": "拉里可以弹奏许多种乐器，包括小提琴和萨克斯风。"}], "en": "He discovered many rivers and lakes, including the Victoria Falls.", "zh": "他发现了许多河流和湖泊，包括维多利亚瀑布。"}], "exercises": null}, {"num": 110, "title_en": "Easier Said Than Done", "title_zh": "说来容易做来难", "type": "dialogue", "category": "情境实战会话", "reading": null, "dialog": {"turns": [{"speaker_en": "Tina", "speaker_zh": "蒂娜", "en": "Don't be a slave to work, Ralph!", "zh": "拉尔夫，别成为工作的奴隶！"}, {"speaker_en": "Ralph", "speaker_zh": "拉尔夫", "en": "I can't help it. I'm always busy.", "zh": "我没办法。我总是很忙。"}, {"speaker_en": "Tina", "speaker_zh": "蒂娜", "en": "You must take it easy sometimes.", "zh": "你有时必须放轻松点。"}, {"speaker_en": "Ralph", "speaker_zh": "拉尔夫", "en": "Easier said than done.", "zh": "说来容易做来难。"}]}, "vocab": [{"num": 1, "word": "Easier said than done.", "phonetic": "", "pos": "（习语）", "meaning": "说来容易做来难。", "examples": [{"en": "A: Good luck at today's job interview. I know you'll get the job. B: Easier said than done.", "zh": "甲：祝你今天求职面试好运。我知道你会得到这份工作的。 乙：说来容易做来难。"}], "sub_entries": ["原句由 \"It is easier to be said than to be done.\" 简化而来。"]}, {"num": 2, "word": "be a slave to...", "phonetic": "", "pos": "片语", "meaning": "作...的奴隶，被...所驱使", "examples": [{"en": "Oliver is a slave to his job. He's always at the office.", "zh": "奥利弗成了工作的奴隶。他总是在办公室里。"}], "sub_entries": ["slave [slev] n. 奴隶"]}, {"num": 3, "word": "I can't help it.", "phonetic": "", "pos": "口语表达", "meaning": "我没办法；我情不自禁。", "examples": [], "sub_entries": ["cannot help + 动名词：忍不住，禁不住", "I couldn't help laughing when I heard the joke. (○)", "I couldn't help to laugh when I heard the joke. (×)"]}, {"num": 4, "word": "take it easy", "phonetic": "", "pos": "口语表达", "meaning": "放轻松，别紧张，休息一下", "examples": [{"en": "A: I feel really terrible. I flunked my Spanish test. B: Take it easy; you'll do better next time.", "zh": "甲：我感觉糟透了。我的西班牙文测验考砸了。 乙：放轻松，别急，下次你会考好的。"}], "sub_entries": []}], "grammar": null, "substitution": [], "exercises": {"prompt": "Ⅲ．请选出下列各句中正确的一项", "questions": ["1. I love exercising,", "running and swimming.", "(A)and include", "(B)including", "(C) regarding", "(D) concerning", "to go to Mexico.", "(A) Kate, my sister, wants", "(B)Kate my sister wants", "(C) Kate, my sister, want", "(D） Kate my sister, wants", "3. The mother spoke about problems", "her", "son's education.", "(A) including", "(B) concern", "(C) concerning", "(D) regard", "4. The cake was so good that Todd couldn't help", "it all.", "(A) eat", "(B) eats (C) to eat", "(D) eating", "5. I don't like Harry, and I can't help", "angry", "when I see him.", "(A) to get (B) going (C) to become(D) getting"], "answers": ["解答>1.(B）.2.(A）3.(C）4.(D）5.(D)"]}}, {"num": 111, "title_en": "Confucius", "title_zh": "孔子", "type": "reading", "category": "进阶短文与语法探究", "reading": {"en": ["Confucius is respected by most Chinese as the greatest teacher of all time. Perhaps the most important word he taught was \"ren,\" which means \"benevolence.\" According to Confucius, benevolence means courtes loyalty and unseifishness. In fact, benevo\" lence is the essence of his teachings. Every teacher should, therefore, follow in his footsteps and emphasize benevolence when teaching."], "zh": ["孔子被许许多多中国人尊为自占以来最伟大的老师。或许他所传授的最重要的一个字就是“：”，也就是英文的benevolence“根据孔子的说法，仁的意思就是礼貌、忠贞以及无私。事实上，仁是他教义的精髓。因此，每个老师在教学时，应效法孔子并强调仁的道理。"], "sentences": [{"en": "Confucius is respected by most Chinese as the greatest teacher of all time.", "zh": "孔子被许许多多中国人尊为自占以来最伟大的老师。"}, {"en": "Perhaps the most important word he taught was \"ren,\" which means \"benevolence.\" According to Confucius, benevolence means courtes loyalty and unseifishness.", "zh": "或许他所传授的最重要的一个字就是“：”，也就是英文的benevolence“根据孔子的说法，仁的意思就是礼貌、忠贞以及无私。"}, {"en": "In fact, benevo\" lence is the essence of his teachings.", "zh": "事实上，仁是他教义的精髓。"}, {"en": "Every teacher should, therefore, follow in his footsteps and emphasize benevolence when teaching.", "zh": "因此，每个老师在教学时，应效法孔子并强调仁的道理。"}]}, "dialog": null, "vocab": [{"num": 1, "word": "be ..", "phonetic": "", "pos": "as.", "meaning": "被尊为.·…", "examples": [{"en": "Carl is respected as great writer of children's books.", "zh": "卡尔被尊为是撰写儿童书籍的伟大作家。"}], "sub_entries": []}, {"num": 2, "word": "of all time", "phonetic": "", "pos": "短语", "meaning": "白古以来", "examples": [{"en": "Some people say that Mozart was the greatest composer of all time.", "zh": "有些人说莫札特是自古以来最伟大的作曲家。"}], "sub_entries": ["*该短语常与有最高级形容词修饰的名词并用。"]}, {"num": 3, "word": "benevolence", "phonetic": "[baˈnevalans]", "pos": "n.", "meaning": "1:慈", "examples": [{"en": "Jim's benevolence won him the respect of the entire city.", "zh": "吉姆的仁慈赢得整个城市对他的尊敬。"}], "sub_entries": []}, {"num": 4, "word": "courtesy", "phonetic": "[ˈkɝtəsɪ]", "pos": "n.", "meaning": "礼貌，谦恭的态度", "examples": [{"en": "It is common courtesy to say \"excuseme\" when you bump into someone. Bob is a very courteous man, so everyone likes him.", "zh": "当你撞到别人时，说声“对不起”是平常的礼貌。）(鲍勃是个很有礼貌的人，因此每个人都喜欢他"}], "sub_entries": ["courteous['katias]a.谦恭的，有礼的"]}, {"num": 5, "word": "loyalty", "phonetic": "[loralti]", "pos": "n.", "meaning": "忠贞，忠诚", "examples": [{"en": "A good dog is very loyal to its master.", "zh": "好狗对其主人非常忠实。"}], "sub_entries": ["loyal[loral ]a.忠实的，忠贞的", "be loyal to...", "对…··.忠诚／忠实"]}, {"num": 6, "word": "unselfishness", "phonetic": "[Anˈselfijnis]", "pos": "n.", "meaning": "无私", "examples": [{"en": "Don't be selfish; give me a piece of the cake.", "zh": "别自私了，给我-～块蛋糕吧。"}], "sub_entries": ["unselfish[An'sslfif]a.无私的", "selfish['selfif]a.自私的"]}, {"num": 7, "word": "essence", "phonetic": "[ˈcsans]", "pos": "n.", "meaning": "精髓；要素", "examples": [{"en": "He said a lot, but his argument had no essence.", "zh": "他说了很多，但他的论调却都没有重点。"}], "sub_entries": []}, {"num": 8, "word": "follow in one's footsteps", "phonetic": "", "pos": "短语", "meaning": "效法某人，以某人为榜样", "examples": [{"en": "Fred followed in his father's footsteps and became a professional golfer.", "zh": "弗雷德效法他父亲成为一位职业的高尔夫选手"}], "sub_entries": ["footstep['futstep]n.脚步"]}, {"num": 9, "word": "emphasize", "phonetic": "[ˈcmfa.saiz]", "pos": "vt.", "meaning": "强调", "examples": [{"en": "The father emphasized the importance of being a gentleman to his son.", "zh": "那位父亲向他儿子强调做个君子的重要性。"}], "sub_entries": []}], "grammar": {"intro": "本课介绍according to的用法，并复习“when+现在 分词”的句型。", "items": [{"num": 1, "title": "According to Confucius, benevolence means courtesy, loyalty and unselfishness.", "body": ["（根据孔子的说法，仁的意思就是礼貌、忠贞以及无 私。）according to... 根据…·. according to视为介词，之后通常接名词作宾语。", "例：According to a medical report, smoking can", "n. cause lung cancer.（根据-份医学报告，抽烟会导致肺癌。）", "但不可说：", "According to his words, five people were killed in the traffic accident.（x）虽然有名词his words 作宾语，但这是洋泾浜英语，正规的英语应为：", "According to him, five people were killed in the traffic accident.（根据他的说法，这次车祸有五个人丧生。）下列是另一典型的洋泾浜英语的例子：", "Can you express your meaning in English?（×)应改为：", "Can you express yourself in English? (○)（你可以用英语表达你的意思吗？）要避免错误的洋泾浜英语，唯一途径就是多读英美人 士所写的文章，并不时背诵，才能牢记固定的用语。每一个英语说得流利的人都有背诵文章的好习惯。"]}, {"num": 2, "title": "Every teacher should, therefore, follow in his footsteps and emphasize benevolence when teaching.", "body": ["=Every teacher should...when he teaches.（因此，每个老师在教学时，应效法孔子并强调仁的 道理。）我们曾经介绍过when、while、if、once though、unless等六个连词所引导的状语从句简化 成分词短语的方法。现在我们再复习·遍。上述的状语从句中，若主语与主句的主语相同时，可 将从句中的主语删除，并将之后的动词变成现在分 词。若动词是be动词（如is、are、was、were 等），一律变成现在分词being，而being 再予省略。", "例: When you do the work, you must be careful.", "主语相同-- When you do the work, you must be careful. doing-> When doing the work, you must be careful.（做这工作时，你必须谨慎。）又例: Though he is poor, he is happy. 主语相同-> Though be x poor, he is happy. being", "→ Though (being) poor, he is happy.> Though poor, he is happy.（他虽然穷，却很快乐。）"]}]}, "substitution": [{"num": 1, "pairs": [{"en": "According to Confucius, benevolence means courtesy, loyalty and unselfishness.", "zh": "根据孔子的说法，仁的意思就是礼貌、忠贞以及无私。"}, {"en": "According to the weatherman, it will snow all day tomorrow.", "zh": "根据气象预报员的报导，明天整天都会下雪。"}, {"en": "According to your teacher, your English is improving.", "zh": "根据你的老师表示，你的英文正在进步。"}, {"en": "According to Mack, it is more fun to ride a bus than drive a car.", "zh": "根据麦克所说，乘坐公共汽车比开车更有趣。"}], "en": "According to Confucius, benevolence means courtesy, loyalty and unselfishness.", "zh": "根据孔子的说法，仁的意思就是礼貌、忠贞以及无私。"}, {"num": 2, "pairs": [{"en": "Every teacher should follow in his footsteps when teaching.", "zh": "因此，每个老师在教学时应效法他。"}, {"en": "When driving a car, you should be alert.", "zh": "开车时，你应该谨慎。"}, {"en": "While watching TV, I fell asleep.", "zh": "看电视时，我睡着了。"}, {"en": "Though very rich, he still rides the bus to work.", "zh": "他虽然很有钱，却还是乘坐公共汽车去上班。"}], "en": "Every teacher should follow in his footsteps when teaching.", "zh": "因此，每个老师在教学时应效法他。"}], "exercises": null}, {"num": 112, "title_en": "It's My Pleasure", "title_zh": "不客气", "type": "dialogue", "category": "情境实战会话", "reading": null, "dialog": {"turns": [{"speaker_en": "Man", "speaker_zh": "男士", "en": "Excuse me. Would you like to sit down?", "zh": "对不起。您要坐吗？"}, {"speaker_en": "Old Lady", "speaker_zh": "老妇人", "en": "That's very nice of you. Thank you.", "zh": "你人真好。谢谢你。"}, {"speaker_en": "Man", "speaker_zh": "男士", "en": "It's my pleasure.", "zh": "不客气。"}, {"speaker_en": "Old Lady", "speaker_zh": "老妇人", "en": "You're a very courteous gentleman.", "zh": "你真是一位有礼貌的绅士。"}, {"speaker_en": "Man", "speaker_zh": "男士", "en": "Thank you.", "zh": "谢谢您。"}]}, "vocab": [{"num": 1, "word": "Would you like to + 动词原形？", "phonetic": "", "pos": "句型", "meaning": "你想要...吗？", "examples": [{"en": "Would you like to go swimming with us?", "zh": "你想跟我们去游泳吗？（比较：Do you like to go swimming with us? 你喜欢跟我们去游泳吗？）"}], "sub_entries": []}, {"num": 2, "word": "That's kind of you.", "phonetic": "", "pos": "口语", "meaning": "你真好。", "examples": [], "sub_entries": ["（你真好。）", "=It's very nice of you.", "本句在本文中是下列句子的简化：", "It's very nice of you to ask me to sit down.", "在对话中，若对方帮了我们一个忙，我们可使用下列", "的句子表达我们的谢意：", "That's very nice/kind of you. Thank you.", "= You've been very kind. Thank you.", "（你真好。谢谢你。）", "亦可说：", "You've been very helpful. Thank you.", "（你帮了大忙。谢谢你。）"]}, {"num": 3, "word": "gentleman", "phonetic": "[ˈdʒentlmən]", "pos": "n.", "meaning": "君子，绅士", "examples": [], "sub_entries": []}], "grammar": null, "substitution": [], "exercises": {"prompt": "Ⅲ·请选出下列各句中正确的一项", "questions": ["1.", "the doctor, I'm very healthy.", "(A) Regarding to", "(B) Concerning", "(C) According", "(D) According to", "2. When", "to your teacher, you must be", "polite.", "(A) saying", "(B) you say", "(C) talking", "(D) you to talk", "3. Though", ", mountain climbing is fun.", "(A) is dangerous", "(B) danger", "(C) dangerous", "(D) danger you", "4. Mary is able to", "in sevendifferent", "languages.", "(A) express her meaning", "(B) express her words", "(C) express herself", "(D) express her", "5.", "dinner with me this evening?", "(A) Do you like to eating", "(B)Would you like eat", "(C) Would you like to eat", "(D) Did you want eat", "6. Jack: Let me help you.", "Sue : That's very", "(A) nice of you", "(B) nice to you", "(C) nice for you", "(D） kind with you"], "answers": ["解答>1.(D）2.(C）3.(C）4.(C）5.(C）6.(A)"]}}, {"num": 113, "title_en": "Something Well Begun Is Half Done", "title_zh": "好的开始是成功的一半", "type": "reading", "category": "进阶短文与语法探究", "reading": {"en": ["Work is a very important part of life. People work in order to earn a living. A country can only make progress if its people work. It is, therefore, important for us to be hardworking. When we work, there is one golden rule we should always remember: Something well begun is half done."], "zh": ["工作是生活中非常重要的一部分。人们为了谋生而工作。、个国家只有在其人民工作下才会进步。因此，努力工作对我们很重要。在工作时，有一则我们必须牢记的金科玉律就是：好的开始是成功的一半。"], "sentences": [{"en": "Work is a very important part of life.", "zh": "工作是生活中非常重要的一部分。"}, {"en": "People work in order to earn a living.", "zh": "人们为了谋生而工作。"}, {"en": "A country can only make progress if its people work.", "zh": "、个国家只有在其人民工作下才会进步。"}, {"en": "It is, therefore, important for us to be hardworking.", "zh": "因此，努力工作对我们很重要。"}, {"en": "When we work, there is one golden rule we should always remember: Something well begun is half done.", "zh": "在工作时，有一则我们必须牢记的金科玉律就是：好的开始是成功的一半。"}]}, "dialog": null, "vocab": [{"num": 1, "word": "Well begun is half done.", "phonetic": "", "pos": "谚语", "meaning": "好的开始是成功的一半。", "examples": [], "sub_entries": ["好的开始是成功的-一半。（谚语）", "half [haef ] adv.一半地"]}, {"num": 2, "word": "be a part of...", "phonetic": "", "pos": "短语", "meaning": "是...的一部分", "examples": [{"en": "Traffic jams are a part of city life.", "zh": "交通阻塞是都市生活的一部分。"}, {"en": "Paul played an important part in our company's success.", "zh": "保罗在我们公司的成功中扮演了很重要的角色。"}], "sub_entries": ["part [part] n. 部分", "play an important part / role in... 在……中扮演重要角色", "role [rol] n. 角色"]}, {"num": 3, "word": "earn ..)", "phonetic": "", "pos": "by.", "meaning": "（靠...…·）谋生，为生", "examples": [{"en": "Chris earns a living by teaching in a kindergarten.", "zh": "克里斯在幼儿园中教书为生。"}], "sub_entries": ["= make a living (by...)", "earn[3n]vt.挣（钱）", "living['livig ] n.生活"]}, {"num": 4, "word": "progress", "phonetic": "[ˈproɡres]", "pos": "n.", "meaning": "进步（常与动词make并用）", "examples": [{"en": "You should be proud. Your son is making good progress in English.", "zh": "你应该觉得骄傲。你儿子的英文正进步得很快。"}], "sub_entries": ["make progress", "进步"]}, {"num": 5, "word": "hardworking", "phonetic": "[ˈhɑːrdwɜːrkɪŋ]", "pos": "a.", "meaning": "努力工作的", "examples": [{"en": "The boss gave Fred a raise because he is very hardworking.", "zh": "老板给弗雷德加薪，因为他非常努力工作。"}], "sub_entries": []}, {"num": 6, "word": "golden rule", "phonetic": "", "pos": "短语", "meaning": "金科玉律", "examples": [{"en": "Son, the golden rule is to listen to your elders.", "zh": "儿子，有一则金科玉律就是要听从长辈的话。"}, {"en": "That child has beautiful golden hair.", "zh": "那孩子有一头漂亮的金发。"}], "sub_entries": ["golden['goldn]a.宝贵的；黄金般的", "rule[rul]n.规则，法规"]}], "grammar": {"intro": "本课介绍定语从句省略关系代词或简化为分词短语的用 法。", "items": [{"num": 1, "title": "省略关系代词", "body": ["When we work, there is one golden rule we should always remember...", "=When we work, there is one golden rule which we should always remember...（在工作时，有一则我们必须牢记的金科玉律·…·）关系代词所引导的定语从句若属限制性修饰（即关系 代词之前无逗号），且该关系代词在该从句中作及物动 词或介词的宾语时，该关系代词可予以省略。a．关系代词作及物动词的宾语", "例：He is a man whom we can trust.", "vt.", "=He is a man we can trust.（他是我们可以信赖的人。）There is nothing that he doesn't know. vt.", "=There is nothing he doesn't know.（他无所不知。）", "b. 关系代词作介词的宾语", "例:John is the man whom you can depend on.", "prep.", "=John is the man you can depend on.（约翰是个你可以依赖的人。）故在下列句中：", "When we work, there is one golden rule which weshould always remember... which作remember的宾语，故可省略如下：", "When we work, there is one golden rule we should always remember...", "注意：", "若介词置于句尾，关系代词可予省略；但若介词置于 关系代词之前，则该关系代词不可省略。", "例：The place which I work at is not far from prep.", "my house.", "=The place eI work at is not far from my house.", "=The place at which I work is not far from my house.", "=The place where I work is not far from my house.（我工作的地点离我家不远。）但：", "The place at I work is not far from my house.（x)"]}, {"num": 2, "title": "定语从句可简化为分词短语：Something well begun is half done.", "body": ["= Something that is well begun is half done.（好的开始是成功的一半。）关系代词所引导的定语从句若属限制性修饰，且该关 系代词在从句中作主语时，可将该从句简化为分词短 语，步骤如下：", "第一步：删除关系代词；第二步：将关系代词之后的动词变成现在分词；第三步：若动词是be 动词，变成现在分词being 之 后再予省略。", "例: The girl wh6 liyes next to my house is my living classmate.", "=The girl living next to my house is my classmate.（住在我家隔壁的那个女孩子是我的同班同学。)John is a young boy who is full of energy.(being)", "=John is a young boy full of energy.（约翰是个活力十足的年轻小子。）Have you ever read the book which was(being)writtenby thatauthor?", "=Have you ever read the book written by that author?（你有没有看过那位作者所写的那本书？）故在下列句中：", "Something that is well begun is half done.\"that is well begun”是定语从句，其中关系代词 that等于which，在该从句中作主语，故可删除，其 后动词 is 变成现在分词being，而being可予省略，即成：", "Something well begun is half done."]}]}, "substitution": [{"num": 1, "pairs": [{"en": "There is one golden rule (which) we should always remember.", "zh": "有一·则我们必须牢记的金科玉律。"}, {"en": "This is the kind of food (that) everyone likes.", "zh": "这是一种每个人都喜欢的食物。"}, {"en": "The University (which) my brother studies at is around the corner.", "zh": "我哥哥就读的那所大学就在转角处。"}, {"en": "The University at which we study is around the corner.", "zh": "我们就读的那所大学就在转角处。"}], "en": "There is one golden rule (which) we should always remember.", "zh": "有一·则我们必须牢记的金科玉律。"}, {"num": 2, "pairs": [{"en": "Something (that is) well begun is half done.", "zh": "好的开始是成功的一半。"}, {"en": "Treasure Island is a book (that is）full of adventure.", "zh": "《金银岛》是一本充满冒险故事的书。"}, {"en": "This is the car (which was） driven by my brother in the race.", "zh": "这就是我哥哥在比赛时所开的那部车。"}], "en": "Something (that is) well begun is half done.", "zh": "好的开始是成功的一半。"}], "exercises": null}, {"num": 114, "title_en": "No Pain, No Gain", "title_zh": "一分耕耘，一分收获", "type": "dialogue", "category": "情境实战会话", "reading": null, "dialog": {"turns": [{"speaker_en": "Rachel", "speaker_zh": "雷切尔", "en": "What does John do for a living?", "zh": "约翰是靠什么谋生的？"}, {"speaker_en": "Derek", "speaker_zh": "德里克", "en": "He's a salesman.", "zh": "他是个推销员·"}, {"speaker_en": "Rachel", "speaker_zh": "雷切尔", "en": "That's a difficult way to make a living.", "zh": "以那种方式谋生是很困难的。"}, {"speaker_en": "Derek", "speaker_zh": "德里克", "en": "Well, remember: No pain, no gain.", "zh": "嗯；要记住：一分耕耘，一分收获。"}]}, "vocab": [{"num": 1, "word": "No pain, no gain.", "phonetic": "", "pos": "谚语", "meaning": "一分耕耘，一分收获。", "examples": [], "sub_entries": ["-分耕耘，“-分收获。（谚语）"]}, {"num": 2, "word": "living", "phonetic": "[ˈlivin]", "pos": "n.", "meaning": "谋生", "examples": [{"en": "He makes a living by teaching.", "zh": "他靠教书谋生。）b.动词+for a living从事以谋生"}, {"en": "He teaches for a living.", "zh": "他教书谋生。"}], "sub_entries": ["通常使用于下列两个短语中：", "a.make a living by+动名词", "藉.…··…·谋生"]}, {"num": 3, "word": "salesman", "phonetic": "[ˈselzman]", "pos": "n.", "meaning": "推销员，业务员", "examples": [], "sub_entries": []}], "grammar": null, "substitution": [], "exercises": {"prompt": "Ⅲ·请选出下列各句中正确的一项", "questions": ["1. The park", "basketball at is closed.", "(A） that we", "(B) at which play", "(C) which we play", "(D) at we play", "2. Gale listens to classical music", "relax.", "(A) order to", "(B) to order in", "(C) in order", "(D) in order to", "3. A company will do well if", "workers are", "hardworking.", "(A)its", "(B)it's", "(C) their's", "(D) their", "4. The music", "by that band is great for", "dancing.", "(A） which playing", "(B) who is played", "(C) that played", "(D) which is played", "5. She is,", ",always late for work.", "(A) so(B)therefore (C)whom is (D）one", "6. Larry's father", "a living by selling cars.", "(A) gets (B) does (C) makes", "(D） gives"], "answers": ["解答1.(C）2.(D）3.(A）4.(D）5.(B）6.(C)"]}}, {"num": 115, "title_en": "Wait and See", "title_zh": "静候观望", "type": "reading", "category": "进阶短文与语法探究", "reading": {"en": ["Cliff and Bonnie have known each other for two years. They have talked about getting married since last year. Cliff has already decided that Bonnie is the right girl for him. However, Bonnie has not really made up her mind about him yet. She likes Cliff a lot, but she thinks he's not ambitious enough. Bonnie knows that getting married is a serious matter, so she's going to wait and see before she makes a final decision."], "zh": ["克里夫和邦妮彼此相识已有两年了。自从去年以来，他们就在讨论结婚的事。克里夫已经认定邦妮就是适合他的女孩。然而，邦妮对他尚未打定主意。她很喜欢克里夫，但是她认为他还不够有抱负。邦妮知道结婚是件严肃的事情，因此在她下最后决定前，她将静候观望。"], "sentences": [{"en": "Cliff and Bonnie have known each other for two years.", "zh": "克里夫和邦妮彼此相识已有两年了。"}, {"en": "They have talked about getting married since last year.", "zh": "自从去年以来，他们就在讨论结婚的事。"}, {"en": "Cliff has already decided that Bonnie is the right girl for him.", "zh": "克里夫已经认定邦妮就是适合他的女孩。"}, {"en": "However, Bonnie has not really made up her mind about him yet.", "zh": "然而，邦妮对他尚未打定主意。"}, {"en": "She likes Cliff a lot, but she thinks he's not ambitious enough.", "zh": "她很喜欢克里夫，但是她认为他还不够有抱负。"}, {"en": "Bonnie knows that getting married is a serious matter, so she's going to wait and see before she makes a final decision.", "zh": "邦妮知道结婚是件严肃的事情，因此在她下最后决定前，她将静候观望。"}]}, "dialog": null, "vocab": [{"num": 1, "word": "each other", "phonetic": "", "pos": "短语", "meaning": "彼此", "examples": [{"en": "Bob and Jessica have loved each other for ten years.", "zh": "鲍勃和杰西卡彼此相爱已有十年了。"}], "sub_entries": []}, {"num": 2, "word": "talk about...", "phonetic": "", "pos": "短语", "meaning": "谈论...，讨论...", "examples": [{"en": "They are talking about going to Ireland for their honeymoon.", "zh": "他们正在讨论要到爱尔兰去度蜜月。"}], "sub_entries": ["谈论.….…，讨论….··", "talk[tok]vi.讨论，商谈"]}, {"num": 3, "word": "get married", "phonetic": "", "pos": "短语", "meaning": "结婚", "examples": [{"en": "Ted and Vivien are getting married this July.", "zh": "特德和费雯将于今年7月结婚。"}], "sub_entries": ["married['merrd]a.结婚的（此为marry['mar]", "的过去分词，在此处作形容词）", "A and B get married.", "A与B结婚。", "=A marry B."]}, {"num": 4, "word": "already", "phonetic": "[ɔːlˈredi]", "pos": "adv.", "meaning": "已经", "examples": [{"en": "Sally is already at the store waiting for us; let's hurry.", "zh": "萨莉已经在店里等我们了，咱们快··点·"}], "sub_entries": []}, {"num": 5, "word": "right", "phonetic": "[rait]", "pos": "a.", "meaning": "适当的；正确的", "examples": [{"en": "This job seems just right for you.", "zh": "这份工作似乎很适合你。"}], "sub_entries": []}, {"num": 6, "word": "make", "phonetic": "", "pos": "", "meaning": "up one's mind+|about+名词(短语)", "examples": [{"en": "Have you made up your mind about where to study? Laura made up her mind to find a husband and get married.", "zh": "你已经决定到那里去就读了吗？）（劳拉决定找个丈夫结婚。"}], "sub_entries": ["Ito+动词原形", "对……··.下决心，下决心做……···", "mind[maind]n.主意，想法"]}, {"num": 7, "word": "not...yet", "phonetic": "", "pos": "短语", "meaning": "尚未...", "examples": [{"en": "Helen has not decided what to do yet.", "zh": "海伦尚未决定要做什么。"}], "sub_entries": ["尚未·····.", "yet[jet]adv.尚未（常用于否定句或疑问句中）"]}, {"num": 8, "word": "She ..", "phonetic": "", "pos": "lot.", "meaning": "她很喜欢克里夫·…·.", "examples": [], "sub_entries": ["=She likes Cliff very much...", "*此处alot作副词用，即等于very much."]}, {"num": 9, "word": "ambitious", "phonetic": "[emˈbijas]", "pos": "a.", "meaning": "有野心的，有抱负的", "examples": [{"en": "Young Joe is so ambitious that I think he'll be president of the company some day.", "zh": "年轻的乔是如此野心勃勃，因此我认为有…天他会成为公司的总裁。）10 serious['srras]a.严肃的；认真的"}, {"en": "Are you serious about studying the violin?", "zh": "你是认真要学小提琴的吗？"}], "sub_entries": []}, {"num": 11, "word": "matter", "phonetic": "[ˈmato]", "pos": "n.", "meaning": "事情", "examples": [{"en": "I'm sorry, but I don't know anything about that matter.", "zh": "很抱歉，我对那件事一无所知。"}], "sub_entries": []}, {"num": 12, "word": "make a decision", "phonetic": "", "pos": "短语", "meaning": "做决定", "examples": [{"en": "Have you made a decision about where to go on your vacation?", "zh": "你已经决定要到哪里去度假了吗？"}], "sub_entries": ["decision[dr'si3an ]n.决定，决心"]}, {"num": 13, "word": "final", "phonetic": "[ˈfainl]", "pos": "a.", "meaning": "最后的", "examples": [], "sub_entries": []}], "grammar": {"intro": "本课介绍现在完成时及since的用法。", "items": [{"num": 1, "title": "Cliff and Bonnie have known each other for two years.", "body": ["（克里夫和邦妮彼此相识已有两年了。）", "a. 现在完成时的句型", "主语+have/has+过去分词", "例：He has finished the work.（他已经把工作做完了。）", "They haven't received his letter yet.（他们尚未收到他的信。）", "b. 现在完成时的功能", "1）现在完成时可用以表示从过去某时·直持续到 现在的动作。", "例: I have lived here for ten years.（我住在这里已有十年了。）", "He has learned English for only half a year, but he hasmadealotof progress.（他英文才学了半年，但却进步神速。）", "2）现在完成时亦可用以表示过去某时已完成的动 作。", "例： John has finished the work.（约翰已经把工作做完了。）", "这句话笼统表示约翰在过去某时做完了这工作，可能是在五分钟前、昨天或上星期·然而现在 完成时并不强调时间的明确性，只强调到现在 为止已完成的动作。故现在完成时不得与明确 的过去时间状语并用。", "例：He has finished the work", "five minutes ago. (×)（他五分钟前已把工作做完了。）原因：有明确的过去时间状语。He has told her the secret last month.（×)（他上个月已把秘密告诉了她。）原因：有明确的过去时间状语。以上两句应改为：", "He has finished the work.(○)（他已把工作做完了。）He has told her the secret.(○)（他已把秘密告诉了她。）", "注意：", "明确的过去时间状语在句中出现时，时态应采 过去时。故：He finished the work five minutes ago.（O)（他五分钟前已把工作做完了。）He told her the secret last month.(O）（他上个月把秘密告诉了她。）", "3）现在完成时亦可表示未来将完成的动作。此时 表示条件的状语从句（多由if“如果...·when 乐”、after“在.….…·之后\"”、as soon as“", "·就.·..”等连词引导）采现在 完成时，而主句则采将来时·", "例：If I have finished all the chores, I'll go fishing with you.（我若把所有的杂务做完之后，就会跟你去 钓鱼。）", "As soon as I have finished 1allthe chores, I'll go fishing with you.（我一把所有的杂务做完，就会跟你去钓 鱼。）When I have finished all the chores, I'll go fishing with you.（我把所有的杂务做完的时候，就会跟你去 钓鱼。）After I have done all the chores, I'li go fishing with you.（我把所有的杂务做完之后，就会跟你去钓 鱼。）"]}, {"num": 2, "title": "使用现在完成时应注意事项", "body": ["a. 现在完成时与“for+一段时间”所形成的状语并 用时，句中的动词必须有持续发生的特性。", "例: He has lived here for ten years. (○)（他住在这里已有十年了。）", "理由：", "live表示“住”，有“持续发生”的特性。我们可 以说：“他每天都住在这里，连续住了十年。”故 本例是正确的句子。", "例： He has learned English for five months.（0)（他学英语已有五个月之久。）", "理由：", "learn表示“学习\"”，亦有“持续发生”的特性。我们可以说：“他每天都学英语，连续学了五个 月。”故本例是正确的句子。以上这些具有“持续发生”特性的动词所造成的现 在完成时亦可被现在完成进行时（主语+have/has been+现在分词）取代，意思不变，但现在完成进 行时更强调动作的持续性。故以上两例均可改写 为：", "He has been living here for ten years.（他住在这里已有十年了。）He has been learning English for five months.（他学英语已有五个月之久。）", "b. 动词若无“持续发生”的特性，仍能使用于现在完 成时，但不可与“for+一段时间”所形成的状语 并用。", "例：He has finished the work. (○)（他已做完这工作了。）", "He has finished the work for ten days.（×)（他做完这工作已有十天了。）理由：", "finish表示“做完”，无“持续发生\"的特性。我 们不会说：“他每天做完这工作，连续做完十 天。”故上列第二例是错误的句子。又例：He has married Jane.（O）（他娶了简。）He has married Jane for ten years.(×)（他娶了简已有十年了。）理由：", "marry表示“娶、嫁”，无“持续发生”\"的特性 我们不会说：“他每天娶简·次·连续娶了十 年。”故上列第二例是错误的句子。又例：He has passed away.（O)（他已过世了。）He has passed away for a month. (×)（他已过世…·个月了。）理由：", "passaway表示“过世”，是die（死）的委婉用 语，不论passaway或die，均无“持续发生”的 特性。我们不会说：“他每天都过世一次，连续过 世一个月。”故上列第二例是错误的句子。", "c. 上列无“持续发生”特性的动词可采下列句型，以 补救其无“持续发生”的特性：", "It is+一段时间+since引导的过去时状语从句 自从…····以来已有...···时间了", "例： He has married Jane for ten years. (×)", "→ It is ten years since he married Jane.(○)", "=It has been ten years since he married", "Jane.", "=Ten years have passed since he married Jane.（他与简结婚已有十年了。）He has passed away for a month. (×)--> It is a month since he passed away. (○)", "=It has been a month since he passed away.", "=A month has passed since he passed away.（他过世已有一个月了。）He has finished the work for ten days.（×）>It is ten days since he finished the work.（0)", "=It has been ten days since he finished the work.", "=Ten days have passed since he finished the work.（他做完这工作已有十天了。）", "注意：", "这些不具“持续发生”特性的动词在现在完成时的 句子结构中，虽无法与“for+·段时间”并用，但我们仍可使用与这些动词意思相同的形容词，置 于be 动词的现在完成式（即havebeen或has been)之后，表示持续发生的状态，句型如下：", "主语+have/has been+形容词+for+··段时间", "例：He has died for ten years.（×）", "> He has been dead for ten years. (○)", "=It is ten years since he died.（他已过世十年了。）He has married Jane for five years. (×)-→He and Jane have been married for five years.(○)", "=It is five years since he married Jane.（他和简结婚已有五年了。）"]}, {"num": 3, "title": "since的用法", "body": ["since可表示“由于”或“自从”。", "a. 表示“由于”时，since是连词，引导状语从句，修饰主句，句中的时态不受特殊限制，只要合乎句 意即可。", "例：Since I'm quite busy now, I don't think I", "can go to the movies with you.（由于我现在很忙，我想我不能跟你们去看电 影。）", "b. 表示“自从”时，since可作连词、介词或副词。", "用法如下：", "1）作连词：", "since引导状语从句，修饰主要子句。从句的时 态为过去时，主句则为现在完成时或现在完成 进行时。", "例：Since he attended high school, he has worked very hard.（自从他念中学后，他就很用功。）", "He has been learning English since he moved here.（他搬到这里之后，就一直在学英语。）", "2）作介词 since之后接名词或动名词作其宾语，形成状 语，修饰主句。主句仍使用现在完成时或现在 完成进行时。", "例: Since attending high school, he has worked very hard.（自从念中学后，他就很用功。）", "He has been learning English since moving here.（自从搬到这里之后，他就…直在学英语 He has been waiting for her since ten o'clock.（他自十点钟就一直等候着她。）", "3）作副词 since译成“之后”，置于完成时助动词have/has之后或置于句尾，乃下列句子变化而成：", "例：Since he moved here in 1990, he has", "连词 明确的时间 been learning English.（他自从1990年搬到这里之后，就一直在学 英语。）", "=He moved here in 1990 and has since 副词 been learning English.", "=He moved here in 1990 and has been learning English since. 副词（他于1990年搬到这里，之后就一直在学英 语。）又例: Since I met her two days ago, I have been 连词 明确的时间 in love with her.（自从我两天前见到她后，我就与她坠人情网 了。)", "=I met her two days ago and have since 副词 been in love with her.", "=I met her two days ago and have been in love with her since. 副词(我两天前见到她，之后就与她坠人情网了)"]}]}, "substitution": [{"num": 1, "pairs": [{"en": "Cliff and Bonnie have known each other for two years.", "zh": "克里夫和邦妮彼此相识已有两年了。"}, {"en": "Nancy and Barry have been together for ten years.", "zh": "南希和巴里在一起已有十年了。"}, {"en": "Stacey and Jack have dated for some time.", "zh": "史黛西和杰克约会已有一段时间了·。"}, {"en": "Steve has worked at this company for only a short time.", "zh": "史蒂夫在这家公司工作只有很短的时间。"}], "en": "Cliff and Bonnie have known each other for two years.", "zh": "克里夫和邦妮彼此相识已有两年了。"}, {"num": 2, "pairs": [{"en": "They have talked about getting married since last year.", "zh": "自从去年以来，他们就在讨论结婚的事。"}, {"en": "He has been very busy since he started his new job.", "zh": "自从他开始新工作后，他就…·直很忙。"}, {"en": "Since May, the price of bread has gone up three times.", "zh": "自从五月以来，面包的价格已经涨了三次。"}, {"en": "They have been working on this project since last month.", "zh": "自从上个月以来，他们就一直着手这项计划。"}], "en": "They have talked about getting married since last year.", "zh": "自从去年以来，他们就在讨论结婚的事。"}], "exercises": null}, {"num": 116, "title_en": "We're Engaged", "title_zh": "我们订婚了", "type": "dialogue", "category": "情境实战会话", "reading": null, "dialog": {"turns": [{"speaker_en": "Charles", "speaker_zh": "查尔斯", "en": "How long have you known each other?", "zh": "你们彼此认识已有多久了？"}, {"speaker_en": "Diana", "speaker_zh": "黛安娜", "en": "We've known each other since we were kids.", "zh": "自从孩提时我们就已认识了。"}, {"speaker_en": "Charies", "speaker_zh": "查尔斯", "en": "Has he proposed to you yet?", "zh": "他向你求婚了吗？"}, {"speaker_en": "Diana", "speaker_zh": "黛安娜", "en": "Yes. In fact, we're engaged.", "zh": "是的。事实上，我们订婚了。"}]}, "vocab": [{"num": 1, "word": "engaged", "phonetic": "[ɪnˈɡeɪdʒd]", "pos": "a.", "meaning": "订婚的", "examples": [{"en": "They got engaged ten days ago.", "zh": "他们十天前订婚了。"}, {"en": "He was engaged to Lucy ten days ago.", "zh": "十天前他与露西订婚了。"}, {"en": "He married Lucy yesterday.", "zh": "他昨天和露西结婚了。"}, {"en": "They got married yesterday.", "zh": "他们昨天完婚了。"}], "sub_entries": ["get engaged 订婚", "be engaged to + 人 与某人订婚（不可用 with）", "marry [ˈmæri] vt. 结婚", "get married 结婚", "be married to + 人 与某人结婚（不可用 with）"]}, {"num": 2, "word": "kid", "phonetic": "[krd]", "pos": "n.", "meaning": "（口语）小孩", "examples": [{"en": "Do you know that kid standing in the corner over there?", "zh": "你认识站在那边角落的那个小孩吗？"}], "sub_entries": []}, {"num": 3, "word": "propose", "phonetic": "", "pos": "", "meaning": "to + 人", "examples": [{"en": "Bob got on his knees and proposed to Grace.", "zh": "鲍勃跪下来向格雷斯求婚。"}], "sub_entries": ["向某人求婚", "propose[pra'poz]vi.求婚"]}], "grammar": null, "substitution": [], "exercises": {"prompt": "Ⅲ·请选出下列各句中正确的一项", "questions": ["1. It has rained", "past three weeks.", "(A) since (B) for", "(C)since the", "(D) for the", "2. _______ friends for five years.", "(A) Dave and Betty has", "(B) Dave and Betty are being", "(C) Dave and Betty have been", "(D) Dave together with Betty have been", "3. It has been three weeks", "I saw her last.", "(A) since：", "(B) for", "(C) when", "(D)where", "4. I've been", "for this bus for forty minutes.", "(A) waited", "(B) wait (C) waiting (D) awaiting", "5.", "have finished cleaning your room, you can", "watch TV.", "(A）After", "(B) When you", "(C) With", "(D) With you", "6.Mack", "last year.", "(A) was married with Sally", "(B) was engaged with Sally", "(C) married with Sally", "(D) was married to Sally"], "answers": ["解答→1.(D）2.(C）3.(A）4.(C）5.(B）6.(D)"]}}, {"type": "song", "id": "song_06", "title_en": "Will You Still Love Me Tomorrow?", "title_zh": "明天你是否依然爱我？", "lyrics": [{"en": "Tonight you're mine completely. You give your love so sweetly. Tonight, the light of love is in your eyes, but will you love me tomorrow? is this a lasting treasure, or just a moment's pleasure? Can I believe the magic of your sighs? Will you still love me tomorrow? Tonight, with words unspoken, you say that I'm the only one. But will my heart be broken when the night meets the morning sun? I have to know that your love is a love I can be sure of. So tell me now and I won't ask again. Will you still love me tomorrow?", "zh": "今晚你是完全属于我的。你给我的爱是那么的甜美。今晚，我可以看见你的眼里闪烁爱的光芒，但明天你是否依然爱我？我俩的爱是一种长久的关系，抑或只是一夜之欢呢？我能相信你那奇妙的叹息声是真的表示着你爱我吗？明天你是否依然爱我？今晚虽然你没说半句话，但你的行为已告诉了我我是你唯一深爱的人。但是，我的心会不会因第二天的来临而破碎呢？我必须知道你的爱是我所能确信的。因此，现在就告诉我你是真心的爱着我，那么我将再也不用问这个问题。明天你是否依然爱我？"}], "category": "经典英文金曲赏析"}, {"num": 117, "title_en": "Time Flies", "title_zh": "光阴似箭", "type": "reading", "category": "进阶短文与语法探究", "reading": {"en": ["Time is precious. Nobody can afford to waste time. Once time has gone by, it will never return. You can never turn the clock back. Time passes very quickly. In fact, people say time flies. Time and tide wait for no man. We should, therefore, make the best use of our time."], "zh": ["时间是很宝贵的，谁都浪费不起时间。时间一旦消逝，就永不再回来了。你永远也无法让时光倒流·时间过得很快，事实间。"], "sentences": [{"en": "Time is precious. Nobody can afford to waste time.", "zh": "时间弥足珍贵，谁也挥霍不起大好光阴。"}, {"en": "Once time has gone by, it will never return.", "zh": "时光一旦流逝，就再也不会重来。"}, {"en": "You can never turn the clock back.", "zh": "你永远也无法让时光倒流。"}, {"en": "Time passes very quickly. In fact, people say time flies.", "zh": "时间走得飞快，正所谓光阴似箭。"}, {"en": "Time and tide wait for no man.", "zh": "岁月不饶人。"}, {"en": "We should, therefore, make the best use of our time.", "zh": "因此，我们务必珍惜分秒，充分利用宝贵的时间。"}]}, "dialog": null, "vocab": [{"num": 1, "word": "Time flies.", "phonetic": "", "pos": "谚语", "meaning": "光阴似箭。", "examples": [], "sub_entries": ["光阴似箭。（谚语）"]}, {"num": 2, "word": "precious", "phonetic": "[ˈprejas]", "pos": "a.", "meaning": "宝贵的，珍贵的", "examples": [{"en": "Gold is a precious metal.", "zh": "黄金是一种珍贵的金属。"}], "sub_entries": []}, {"num": 3, "word": "can", "phonetic": "", "pos": "", "meaning": "afford+to+动词原形", "examples": [{"en": "Chris can afford to' buy a new car. Kelly couldn't afford an expensive watch, so she bought a cheap one.", "zh": "克里斯买得起一辆新车。）（凯利买不起昂贵的手表，因此她买了一只便宜的手表。"}], "sub_entries": ["名词", "负担得起/力足以…·····", "cannotafford+|to+动词原形", "名词", "负担不起／力不足以……··", "afford[aford]vt．负担得起，力足以", "*使用该单词时，须与助动词can/cannot并用，其", "后宾语则可为名词或不定式短语。"]}, {"num": 4, "word": "waste", "phonetic": "[west]", "pos": "vt.", "meaning": "浪费", "examples": [{"en": "If you don't waste paper, you might help to save a tree.", "zh": "如果你不浪费纸张的话，你便可能救了·棵树。"}], "sub_entries": []}, {"num": 5, "word": "once", "phonetic": "[wAns]", "pos": "conj.", "meaning": "一旦", "examples": [], "sub_entries": []}, {"num": 6, "word": "go by", "phonetic": "", "pos": "短语", "meaning": "（时间等）过去", "examples": [{"en": "When you are bored, time goes by slowly.", "zh": "当你无聊时，时间就过得很慢。"}], "sub_entries": ["=pass by"]}, {"num": 7, "word": "return", "phonetic": "[rɪˈtɜːrn]", "pos": "vi.", "meaning": "回来，返回", "examples": [{"en": "When will Todd return from the supermarket?", "zh": "托德什么时候会从超级市场回来？"}], "sub_entries": []}, {"num": 8, "word": "turn the clock back", "phonetic": "", "pos": "短语", "meaning": "将时钟倒转，即指让时光倒流", "examples": [], "sub_entries": ["clock[klak]n.时钟"]}, {"num": 9, "word": "Time passes quickly.", "phonetic": "", "pos": "口语", "meaning": "时间过得真快。", "examples": [], "sub_entries": ["=Time passes by very quickly.", "=Time goes by very quickly.", "（时间过得很快。）", "*此处by为副词，用来强调动词passes和goes。"]}, {"num": 10, "word": "fly", "phonetic": "[flal]", "pos": "vi.", "meaning": "飞（行）", "examples": [{"en": "An eagle looks so graceful when it flies through the air.", "zh": "老鹰在空中飞翔时看起来非常优雅。"}], "sub_entries": ["动词三态：fly，flew，flown."]}, {"num": 11, "word": "Time and tide wait for no man.", "phonetic": "", "pos": "谚语", "meaning": "岁月不待人。", "examples": [], "sub_entries": ["岁月不待人。（谚语）", "tide[taid ] n.潮汐"]}, {"num": 12, "word": "make use of...", "phonetic": "", "pos": "短语", "meaning": "充分利用...", "examples": [{"en": "While in China, Larry made the best use of his time and studied kung fu.", "zh": "在中国时，拉里充分利用了时间去学功夫。"}], "sub_entries": ["充分利用…···"]}], "grammar": {"intro": "本课复习现在完成时在表示条件的状语从句中的用法。 Once time has gone by, it will never return. （时间一旦消逝，就永不再回来了。） 上列句中，\"Once time has gone by”乃连词once 引导 的状语从句，修饰主句\"it will never return\"o 表示条件的状语从句通常由连词unless（除非）、if （如果）、once（…-旦，等于assoonas）、when （当）、after（在...之后）引导，这种从句时态多为现 在时或现在完成时，主句则与助动词will（表示未来状 态）、can（表示能力）、may（表示许可）等并用。 例: Unless I have extra money, I won't buy it.（现在时） （除非我有额外的钱，否则我是不会买这东西的。） Unless he has told me the truth, I won't forgive him.（现在完成时） （除非他向我说实话，否则我不会原谅他。） If he works hard, he'll get somewhere.（现在时） （他若努力，就会有出息。） If he has done all the work, he may go to the movies with you tonight.（现在完成时） （他若把工作都做完，今晚就可与你去看电影。） When I have money, I can travel with you.（现在时） （我有钱时，就能与你一块儿旅游了。） When I have earned enough money, I can travel with you.（现在完成时） （我挣钱时，就能与你一块去旅游。） After you finish the work, you may go home.（现在时）\n= After you have finished the work, you may go home.（现在完成时） （你做完工作后，便可回家了。）", "items": []}, "substitution": [{"num": 1, "pairs": [{"en": "Nobody can afford to waste time.", "zh": "谁都浪费不起时间。"}, {"en": "You're wasting your breath talking to that rude man.", "zh": "你和那个无礼的男人谈话只是在浪费自己的唇舌罢了。"}, {"en": "Why do you waste your money buying that useless stuff?", "zh": "你干嘛浪费金钱买那无用的东西？"}], "en": "Nobody can afford to waste time.", "zh": "谁都浪费不起时间。"}, {"num": 2, "pairs": [{"en": "Once time has gone by, it will never return.", "zh": "时间…-旦消逝，就永不再回来了。"}, {"en": "After I have eaten my breakfast, I will drive you to school.", "zh": "我吃完早餐后，就开车送你到学校去。"}, {"en": "When they have finished cleaning the yard, tell them to wash the car.", "zh": "他们打扫完院子后，告诉他们去洗车。"}, {"en": "As soon as Sally has arrived, we'll start the party.", "zh": "萨莉一到达，我们就开始我们的宴会。"}], "en": "Once time has gone by, it will never return.", "zh": "时间…-旦消逝，就永不再回来了。"}], "exercises": null}, {"num": 118, "title_en": "The Eiffel Tower", "title_zh": "艾菲尔铁塔", "type": "dialogue", "category": "情境实战会话", "reading": null, "dialog": {"turns": [{"speaker_en": "Ivy", "speaker_zh": "艾薇", "en": "Have you ever been to Paris?", "zh": "你曾去过巴黎吗？"}, {"speaker_en": "Homer", "speaker_zh": "荷马", "en": "No, I haven't.", "zh": "不，我没去过。"}, {"speaker_en": "Ivy", "speaker_zh": "艾薇", "en": "Then you have never seen the Eiffel Tower?", "zh": "那么你从未见过艾菲尔铁塔？"}, {"speaker_en": "Homer", "speaker_zh": "荷马", "en": "No, I haven't.", "zh": "是的，我没见过。"}, {"speaker_en": "Ivy", "speaker_zh": "艾薇", "en": "What a pity!", "zh": "真可惜！"}]}, "vocab": [{"num": 1, "word": "the Eiffel Tower", "phonetic": "", "pos": "名词短语", "meaning": "艾菲尔铁塔（位于法国巴黎）", "examples": [], "sub_entries": ["Eiffel['aif!]n.艾菲尔", "tower['taua]n.塔，高楼"]}, {"num": 2, "word": "Have you ever been to Paris?", "phonetic": "", "pos": "日常口语", "meaning": "你有没有去过巴黎？", "examples": [{"en": "I have been to Japan many times. He has never been to Shanghai.", "zh": "我去过日本许多次。）（他从未到过上海。"}, {"en": "He has been to Shanghai twice. I have been to Shanghai before. I have been to Shanghai ago. (×) I went to Shanghai two years ago. (○) I was in Shanghai two years ago. (○) Has", "zh": "他去过上海两次。）（我曾去过上海。）不可说：理由：ago应使用于过去时的句子中。故：（两年前我曾到上海去。）（两年前我在上海。）c.|Have|+人+ever been to+地方名词？某人去过某地没有？"}, {"en": "Have you ever been to Guilin? Has he ever been to Nanjing?", "zh": "你有没有去过桂林？）（他去过南京吗？"}, {"en": "If you ever do it again, Ill punish you.", "zh": "你若再做这件事，我就会处罚你。）3)最高级形容词修饰的名词，之后有关系代词引导的定语从句亦可使用ever来加强语气。"}, {"en": "He is the best 、 student that I've ever taught. Have you met him before? (○) Will he come? (○) Did he come yesterday?（O) If you do it again, I'll punish you.(○) He is the best student that I've taught.", "zh": "最高级（他是我教过最好的学生。）以上所有的例句中，ever 皆可省略。故：（0)4)不可随意在肯定句中i使用ever作“曾经”解。"}, {"en": "I have ever met him. (×) I have ever been to Xi'an. (×) I have met him before. (○) I have been to Xi'an before. (○)", "zh": "我曾见过他。）（我曾去过西安。）以上两句应改为：（我曾见过他。）（我曾去过西安。"}], "sub_entries": ["a.人+|have|+been+to+地方名词", "Ihas", "某人曾去过某地"]}, {"num": 3, "word": "What a pity!", "phonetic": "", "pos": "日常口语", "meaning": "真遗憾！", "examples": [{"en": "It's a pity that she didn't come to the party last night. =It's a shame that she didn't come to the party last night.", "zh": "很遗憾她昨晚没参加那个宴会。"}], "sub_entries": ["= What a shame!", "pity['piti]n.遗憾"]}], "grammar": null, "substitution": [], "exercises": {"prompt": "Ⅲ·请选出下列各句中正确的一项", "questions": ["1. 1", "the movie Five Girls and a Rope.", "(A) have never seen", "(B) have ever seen", "(C) ever saw", "(D) never have see", "2. Carios has been to Tokyo", "(A) ago", "(B) for three years", "(C) four times", "(D) since last year", "3.", "reading the newspaper, I will take the", "dog for a walk.", "(A）If I finished", "(B）After I have finished", "(C) When I has finished", "(D) When finished", "4.Have", "this book?", "(A) ever you read", "(B) you ever readed", "(C) you never readed", "(D) you ever read", "5.Bill is not here. He", "to America.", "(A）has been", "(B) has gone", "(C) has went", "(D) goes", "6.We", "to California many times.", "(A) have been", "(B) have ever been", "(C) have ever gone", "(D) have gone"], "answers": ["解答1.(A）2.(C）3.(B）4.(D）5.(B）6.（A)"]}}, {"num": 119, "title_en": "My Name Isn't Jack", "title_zh": "我的名字不是杰克", "type": "reading", "category": "进阶短文与语法探究", "reading": {"en": ["My father has never done anything exciting in his life. He has never traveled abroad. He has never smoked, drunk wine, or gone dancing. He has never even gone to a movie. One day I asked him, \"Don't you know that all work and no play makes Jack a dull boy?\" He said, \"Well, son, it's a good thing that my name isn't Jack.\""], "zh": ["我父亲一生中从未做过任何令人兴奋的事情。他从未出国旅行，从未抽过烟、喝过酒或跳过舞。他甚至未曾去看过一场电影。有一天我问他：“难道你不知道‘只工作不玩耍，聪明孩子也变傻’吗？”他说：“嗯，儿子，还好我的名字不是杰克。”"], "sentences": [{"en": "My father has never done anything exciting in his life.", "zh": "我父亲这一辈子从未做过什么刺激冒险的事。"}, {"en": "He has never traveled abroad.", "zh": "他从未出境旅行过。"}, {"en": "He has never smoked, drunk wine, or gone dancing.", "zh": "他从不抽烟，不沾酒精，也从不去跳舞。"}, {"en": "He has never even gone to a movie.", "zh": "甚至未曾进电影院看过一场电影。"}, {"en": "One day I asked him, \"Don't you know that all work and no play makes Jack a dull boy?\" He said, \"Well, son, it's a good thing that my name isn't Jack.\"", "zh": "有一天我打趣地问他：“难道您没听过‘只工作不玩耍，聪明孩子也变傻’吗？”他笑着答道：“好在儿子，老爸我的名字不叫杰克。”"}]}, "dialog": null, "vocab": [{"num": 1, "word": "exciting", "phonetic": "[ɪkˈsaɪtɪŋ]", "pos": "", "meaning": "a．令人兴奋的，刺激的", "examples": [{"en": "Mountain climbing is a very exciting sport. Johnny is very excited today because it's his birthday.", "zh": "爬山是一种很令人兴奋的运动。）（约翰尼今天很兴奋，因为今天是他的生日。"}], "sub_entries": ["excited [ɪkˈsaɪtɪd] a. 感到兴奋的，受刺激的"]}, {"num": 2, "word": "abroad", "phonetic": "[əˈbrɔːd]", "pos": "adv.", "meaning": "在国外", "examples": [{"en": "I have never been abroad.", "zh": "我从未到过国外。"}], "sub_entries": []}, {"num": 3, "word": "drink", "phonetic": "[driɡk]", "pos": "vt.", "meaning": "喝", "examples": [{"en": "I drink a cup of coffee every morning before I leave for work.", "zh": "每天早上出门上班前我都会喝一杯咖啡。"}], "sub_entries": ["动词三态：drink，drank，drunk."]}, {"num": 4, "word": "wine", "phonetic": "[wain]", "pos": "n.", "meaning": "酒", "examples": [], "sub_entries": ["liquor[lik]n.酒（类）", "*wine通常指水果酿成的酒，尤其是葡萄酒。", "而liquor则指蒸馏制成的烈酒。"]}, {"num": 5, "word": "go dancing", "phonetic": "", "pos": "短语", "meaning": "去跳舞", "examples": [{"en": "Have you ever danced in a disco before?", "zh": "你以前曾在迪斯科舞厅跳过舞吗？"}], "sub_entries": ["dance[dans]vi.跳舞"]}, {"num": 6, "word": "go to a movie", "phonetic": "", "pos": "短语", "meaning": "（特指）看场电影", "examples": [{"en": "I went to the movies with my dad last weekend.", "zh": "上个周末我和爸爸一起去看电影。"}], "sub_entries": ["go to the movies", "（泛指）看电影", "movie['muvi]n.电影"]}, {"num": 7, "word": "All work and no play makes Jack a dull boy.", "phonetic": "", "pos": "谚语", "meaning": "只工作而不游戏使人无精打采。", "examples": [], "sub_entries": ["只工作而不游戏使人无精打采。（谚语）", "dull[dal]a.乏味的，无精打采的"]}], "grammar": {"intro": "本课复习现在完成时，并介绍现在完成时的否定句型及 “go+现在分词”的用法。", "items": [{"num": 1, "title": "My father has never done anything exciting in his life.", "body": ["（我父亲一生中从未做过任何令人兴奋的事情。）have/has+never+过去分词 从未·…·", "例：Hehas never been out of his hometown.（他从未离开过家乡。）", "I have never had the opportunity to meet her.（我从来就没有机会碰见她。）"]}, {"num": 2, "title": "He has never smoked, drunk wine, or gone dancing.", "body": ["（他从未抽过烟、喝过酒或跳过舞。）“go+现在分词”可用以表示从事短暂而具娱乐性的 活动。常用的此类短语有下列数个：", "go dancing 去跳舞 go hunting 去打猎 go picnicking 去野餐 go bowling 去打保龄球 go golfing 去打高尔夫球 go hiking 去徒步旅行（远足）go mountain climbing 去爬山", "例：My brother went hunting and shot a deer.（我哥哥去打猎时射杀了一只鹿。）", "The Smith family loves to go picnicking during the summer.（夏天时史密斯一家人喜欢去野餐。）I'd love to go bowling with you, but I don't know how to bowl.（我很想和你一起去打保龄球，但我不会打。）"]}, {"num": 3, "title": "All work and no play makes Jack a dull boy.", "body": ["（只工作而不游戏使人无精打朵。）", "注意：", "a. 本句的主语为 all work and no play，照理此处有 连词 and 连接名词 all work 及 noplay，主语应 视为复数，但作者将 all work and no play 视为-一个完整的单一现象（即“只工作而不游戏”这种 情形），因此 all work and no play 视为单数主 语，故之后的动词makes亦为第三人称单数动 词。", "b. Jack原为人名，此处指任何．个人。"]}]}, "substitution": [{"num": 1, "pairs": [{"en": "He has never done anything exciting in his life.", "zh": "他一生中从未做过任何令人兴奋的事情。"}, {"en": "Bill has always arrived on time for work; he has never been late.", "zh": "比尔总是准时去上班，他从未迟到过。"}, {"en": "I have never heard Connie sing, but I heard she sings well.", "zh": "我从未听过康妮唱歌，但我听说她唱得很好。"}, {"en": "Carl has never been to a baseball game, but he has watched many on TV.", "zh": "卡尔从未去看过棒球比赛，但他在电视上看了很多。"}], "en": "He has never done anything exciting in his life.", "zh": "他一生中从未做过任何令人兴奋的事情。"}, {"num": 2, "pairs": [{"en": "He has never smoked or gone dancing.", "zh": "他从未抽过烟或跳过舞。"}, {"en": "William has seldom gone picnicking because he lives in the city.", "zh": "威廉很少去野餐，因为他住在城市里。"}, {"en": "I've never gone golfing because it is too expensive.", "zh": "我从未去打过高尔夫球，因为太贵了。"}, {"en": "Sally and Roger have gone dancing at that disco for the past year.", "zh": "萨莉和罗杰过去一年来都去那家迪斯科舞厅跳舞。"}], "en": "He has never smoked or gone dancing.", "zh": "他从未抽过烟或跳过舞。"}], "exercises": null}, {"num": 120, "title_en": "It's My Treat", "title_zh": "由我作东", "type": "dialogue", "category": "情境实战会话", "reading": null, "dialog": {"turns": [{"speaker_en": "Dale", "speaker_zh": "戴尔", "en": "Have you eaten yet?", "zh": "你吃过了吗？"}, {"speaker_en": "Molly", "speaker_zh": "莫莉", "en": "No.", "zh": "还没。"}, {"speaker_en": "Dale", "speaker_zh": "戴尔", "en": "I haven't, either. Let's have lunch together.", "zh": "我也还没吃·那咱们-一起吃午饭吧。"}, {"speaker_en": "Molly", "speaker_zh": "莫莉", "en": "I didn't bring enough money.", "zh": "我没带够钱。"}, {"speaker_en": "Dale", "speaker_zh": "戴尔", "en": "Don't worry about it. It's my treat.", "zh": "别担心，由我作东。"}, {"speaker_en": "Molly", "speaker_zh": "莫莉", "en": "Thanks!", "zh": "谢谢！"}]}, "vocab": [{"num": 1, "word": "It's my treat.", "phonetic": "", "pos": "口语", "meaning": "由我作东。", "examples": [{"en": "Uncle Jim said he would treat us all to dinner tonight.", "zh": "吉姆叔叔说今晚要请我们大家去吃晚餐。"}], "sub_entries": ["（由我作东。）", "treat[trit]n.&vt.请客", "treat+人+to|dinner", "请某人吃饭/看电影", "amovie"]}, {"num": 2, "word": "Have you eaten yet?", "phonetic": "", "pos": "日常口语", "meaning": "你吃过了吗？", "examples": [{"en": "He has not come back yet. I haven't heard from him yet.", "zh": "他尚未回来。）（我还没收到他的音讯。）b.用于现在完成时的疑问句中，yet译成“已经”。通常置于疑问句之句尾，作强调语气，也可予以省略。"}, {"en": "Has he come back (yet)? Have you done it (yet)?", "zh": "他已回来了吗？）（这件事你做完了吗？。）至于already[ol'redi]亦可表示“已经”的意思，通常用于肯定句中，若用于问句则表示强调惊讶的语气，不可使用于否定句中。"}, {"en": "He has come back already. =He has already come back. I have done it already. =I have already done it. Has he come back already? Have you done it already?", "zh": "他已经回来了。）（我已经把这事做完了。）（他真的已经回来了啊？）（你真的已经做完了啊？"}], "sub_entries": ["yet的用法：", "a.使用于现在完成时的否定句中，与not并用，形成", "下列的用法：", "have not...yet", "尚未…···，还没……"]}, {"num": 3, "word": "I haven't eaten either.", "phonetic": "", "pos": "口语", "meaning": "我也还没吃。", "examples": [{"en": "He is nice, and so is she. =He is nice, and she is, too. He was going home, and so was she. =He was going home, and she was, too.", "zh": "他人很好，她也很好。）（他即将回家，她也是。）与助动词连用："}, {"en": "He will come, and so will she. =He will come, and she will, too. He has gone, and so has she. =He has gone, and she has, too.", "zh": "他要来，她也要来。）（他走了，她也走了。）与一般动词连用："}, {"en": "He came, and so did she. =He came, and she did, too. He has a book, and so does she. =He has a book, and she does, too.", "zh": "他来了，她也来了。）（他有书，她也有。"}, {"en": "A: He is stupid. B: So he is. A: You can't do it. B: So I can't.", "zh": "甲：他很蠢。）（乙：是啊。）（甲：你不会做这事。）（乙：是啊。）b.否定简应句用 neither、nor 或either。neither与either 皆为副词，故 and不可省略；nor则为连词，前面不必置and。使用neither与nor时须使用倒装句子结构，而使用either时则与not 并用，不须倒装。与be动词连用："}, {"en": "He isn't nice, and neither is she. =He isn't nice, nor is she. =He isn't nice, and she isn't, either. He wasn't going home, and neither was she. =He wasn't going home, nor was she. =He wasn't going home, and she wasn't, either.", "zh": "他不好，她也不好。）（他不回家，她也不回家。）与助动词连用："}, {"en": "He won't come, and neither will she. =He won't come, nor will she. =He won't come, and she won't, either. He hasn't gone, and neither has she. =He hasn't gone, nor has she. =He hasn't gone, and she hasn't, either.", "zh": "他不来，她也不来。）（他没去，她也没去。）与-一般动词连用："}, {"en": "He never tells a lie, and neither does she. =He never tells a lie, nor does she. =He never tells a lie, and she doesn't, either. He has no book, and neither does she. =He has no book, nor does she. =He has no book, and she doesn't, either.", "zh": "他绝不说谎，她也绝不说谎。）（他没有书，她也没有。"}], "sub_entries": ["（我也还没吃。）", "*此处either是副词，专用于否定的简应句中。简应句", "有肯定简应句及否定简应句之分。", "a.肯定简应句与so或too连用。与so连用时，简", "应句须采倒装句子结构；与too连用时，简应句不", "须倒装。", "与be动词连用："]}], "grammar": null, "substitution": [], "exercises": {"prompt": "Ⅲ·请选出下列各句中正确的一项", "questions": ["1. Charlie is very honest. He", "a lie.", "(A) have ever told", "(B) has ever told", "(C) have never tell", "(D) has never told", "2. Have you", "dancing with Butch?", "(A) before gone", "(B) ever gone to", "(C) ever gone", "(D) never go", "3. Gale hates people who smoke. She likes me. I", "have", "(A) ever smoked", "(B) never smoked", "(C) smoked", "(D） often smoked", "4.1", "(A) haven't seen that movie yet", "(B) haven't seen that movies already", "(C) have seen that movie yet", "(D) have ever seen that movie yet", "5. Larry isn't tall and his brother", "(A) is,too", "(B) isn't, either", "(C) is, either", "(D) isn't as well"], "answers": ["解答→1.(D）2.(C）3.(B）4.(A）5.(B)"]}}, {"num": 121, "title_en": "The Greatest Killers", "title_zh": "最大的杀手", "type": "reading", "category": "进阶短文与语法探究", "reading": {"en": ["Alcohol and cigarettes are the two greatest killers in the world. Hundreds of thousands of people have died because of these two social evils. As a result, some governments are trying to control the use of these drugs. For example, in many countries, the legal age for drinking has been raised from eighteen to twenty-one. Some countries have even banned smoking in public places. People can help each other live longer by simply discouraging these bad habits."], "zh": ["酒和烟是全世界最大的两个杀手。有数十万计的人死于这两种有害于社会的东西。因此，有些政府正设法控制这些嘛醉剂的使用。例如，在许多国家中，喝酒的合法年龄已从18岁提高为21岁·有些国家甚至禁止在公共场所抽烟。而人们只要劝别人改掉这些坏习惯，就可以帮助彼此活得久一点。"], "sentences": [{"en": "Alcohol and cigarettes are the two greatest killers in the world.", "zh": "酒和烟是全世界最大的两个杀手。"}, {"en": "Hundreds of thousands of people have died because of these two social evils.", "zh": "有数十万计的人死于这两种有害于社会的东西。"}, {"en": "As a result, some governments are trying to control the use of these drugs.", "zh": "因此，有些政府正设法控制这些嘛醉剂的使用。"}, {"en": "For example, in many countries, the legal age for drinking has been raised from eighteen to twenty-one.", "zh": "例如，在许多国家中，喝酒的合法年龄已从18岁提高为21岁。"}, {"en": "Some countries have even banned smoking in public places.", "zh": "有些国家甚至禁止在公共场所抽烟。"}, {"en": "People can help each other live longer by simply discouraging these bad habits.", "zh": "而人们只要劝别人改掉这些坏习惯，就可以帮助彼此活得久一点。"}]}, "dialog": null, "vocab": [{"num": 1, "word": "killer", "phonetic": "[ˈkilo]", "pos": "n.", "meaning": "杀人者", "examples": [{"en": "In the movie, the butler was the killer.", "zh": "在这部电影中，男管家是凶手。"}], "sub_entries": []}, {"num": 2, "word": "alcohol", "phonetic": "[ˈaelka.hol]", "pos": "n.", "meaning": "酒，酒精（不可数）", "examples": [], "sub_entries": []}, {"num": 3, "word": "cigarette", "phonetic": "[ˈsiɡa.ret]", "pos": "n.", "meaning": "香烟", "examples": [], "sub_entries": []}, {"num": 4, "word": "hundreds of thousands of + 复数可数名词", "phonetic": "", "pos": "短语", "meaning": "数十万的...，成千上万的...", "examples": [{"en": "Dozens of reporters were waiting at the airport for the movie star to arrive.", "zh": "数十位记者在机场等候那位电影明星的抵达。"}], "sub_entries": ["数十万的···", "*表数量的名词加\"-s\"后，与of并用时，作形容词", "使用，可修饰其后的复数可数名词，如：", "dozens of...", "数十的···….", "hundreds of...", "数百的····", "thousandsof...数千的....."]}, {"num": 5, "word": "social", "phonetic": "[ˈsojal]", "pos": "a.", "meaning": "社会的", "examples": [{"en": "Mrs. Wang is a member of the women's social club.", "zh": "王太太是妇女联谊会的-一员。"}], "sub_entries": []}, {"num": 6, "word": "evil", "phonetic": "[ˈivl]", "pos": "n.", "meaning": "（邪）恶，恶事&a.邪恶的，坏的", "examples": [{"en": "Don't be so selfish;there is already too much evil in this world. That man is so evil that he would even steal from his own mother.", "zh": "别这么自私，世上邪恶的事已经太多了。）（那个人坏到甚至会偷自己母亲的东西。"}], "sub_entries": []}, {"num": 7, "word": "as a result", "phonetic": "", "pos": "短语", "meaning": "因此，结果", "examples": [{"en": "In the fifth inning，it began to pour. As a result, the baseball game was canceled.", "zh": "在第五局时下起了倾盆大雨，因此棒球比赛便取消了。"}], "sub_entries": ["result[r'zAlt]n.结果"]}, {"num": 8, "word": "government", "phonetic": "[ˈɡAvanmant]", "pos": "n.", "meaning": "政府", "examples": [], "sub_entries": []}, {"num": 9, "word": "control", "phonetic": "[kanˈtrol]", "pos": "vt.", "meaning": "控制，管理", "examples": [{"en": "The substitute teacher had a hard time controlling the students.", "zh": "那位代课老师管学生管得很辛苦。"}], "sub_entries": []}, {"num": 10, "word": "drug", "phonetic": "[drnɡ]", "pos": "n.", "meaning": "药品（本文指麻醉品）", "examples": [], "sub_entries": []}, {"num": 11, "word": "legal", "phonetic": "[ˈliɡ!]", "pos": "a.", "meaning": "合法的，法律上的", "examples": [{"en": "It is not legal to spit on the street in Singapore.", "zh": "在新加坡的街道上吐痰是不合法的。"}], "sub_entries": []}, {"num": 12, "word": "raise", "phonetic": "[rez]", "pos": "vt.", "meaning": "提高，提升", "examples": [{"en": "My landlord said he was going to raise my rent again this year.", "zh": "我的房东说今年他还要再涨我的房租。"}], "sub_entries": []}, {"num": 13, "word": "ban", "phonetic": "[ban]", "pos": "vt.", "meaning": "下令禁止", "examples": [{"en": "During the 1920's alcohol was banned in the United States.", "zh": "在1920年代的美国，喝酒是被禁止的。"}], "sub_entries": []}, {"num": 14, "word": "public", "phonetic": "[ˈpablik]", "pos": "a.", "meaning": "公共的，公开的&", "examples": [{"en": "There is a public restroom in the train station. Do you think it's okay for people to kiss in public?", "zh": "火车站内有-间公厕。）（你觉得人们当众接吻安当吗？"}], "sub_entries": ["n.公开；大众", "in public places", "在公共场所", "in public", "公开地，当众地"]}, {"num": 15, "word": "discourage", "phonetic": "[dɪsˈkɜːrɪdʒ]", "pos": "vt.", "meaning": "阻止，使气", "examples": [{"en": "A teacher should encourage his students, not discourage them.", "zh": "老师应该要鼓励学生，而不是使他们气。"}], "sub_entries": ["encourage[in'k3id3 ]vt.鼓励"]}, {"num": 16, "word": "habit", "phonetic": "[ˈhabit]", "pos": "n.", "meaning": "习惯", "examples": [{"en": "My father is in the habit of going to bed early and getting up early.", "zh": "我父亲有早睡早起的习惯。"}], "sub_entries": ["be in the habit of...", "有…·…·的习惯", "=have the habit of.."]}], "grammar": {"intro": "本课介绍现在完成时的被动语态，并复习help 的用法。", "items": [{"num": 1, "title": "In many countries, the legal age for drinking has been raised from eighteen to twenty-one.", "body": ["（在许多国家中，喝酒的合法年龄已从18岁提高为21 岁。)本句的\"has been raised”为现在完成时的被动语 态。分词”。", "例: He was punished for lying.（他因说谎而被处罚。）", "I believe (that) the whole project will be completed by tomorrow.（我相信整个计划将于明天以前完成。）", "b. 现在完成时的被动语态则为：", "have/has+been+过去分词", "例：The whole project has been completed.（整个计划已告完成。）", "Have you ever been courted by a girl?（你有没有被女孩子追求过？）"]}, {"num": 2, "title": "help的用法", "body": ["a. help+人+(to)+动词原形 帮某人·…··", "例:He helped me (to) draw up the speech.（他帮助我写这篇演讲稿。）", "Could you help me (to) set the table?（你可不可以帮我摆桌子准备吃饭？）", "b. help+人+with+名词 帮某人·…··…·", "例：He helped me with all the chores.", "=He helped me (to) do all the chores.（他帮我料理所有的杂务。）", "c. help(to)+动词原形 帮忙·····", "例: Please help (to) clean off the table.（请帮忙把餐桌清理干净。）", "He helped (to) write the letter.（他帮忙写这封信。）", "d. help+with+名词 帮忙··…", "例: He won't help my work. (×)", "→ He won't help with my work. (○)（对我的工作，他不愿帮忙。）", "注意：", "help若作及物动词，多以人作宾语，如\"help John\"、\"help me\"等，故无\"help my work\"、\"help the chores\"、\"help the plan\"的说法，而 应说“help（me）withmywork\"、\"help（him)with all“the chores\"或“help（us）with the plan\"。"]}]}, "substitution": [{"num": 1, "pairs": [{"en": "The legal age for drinking has been raised.", "zh": "喝酒的合法年龄已经提高了。"}, {"en": "The price of cigarettes was raised last week.", "zh": "香烟的价格上星期提高了。"}, {"en": "The bank teller has been fired because she stole.", "zh": "那位银行出纳员因为偷窃而已经被并除了。"}, {"en": "These songs were written for children.", "zh": "这些歌曲是为儿童所写的。"}], "en": "The legal age for drinking has been raised.", "zh": "喝酒的合法年龄已经提高了。"}, {"num": 2, "pairs": [{"en": "People can help each other live longer by simply discouraging these bad habits.", "zh": "人们只要劝别人改掉这些坏习惯，就可以帮助彼此活得久一点。"}, {"en": "Mymother helps me watch the children when I'm at work.", "zh": "我母亲在我工作时帮我看小孩。"}, {"en": "Sally often helps her younger brother with his homework.", "zh": "萨莉经常帮助她弟弟做功课。"}, {"en": "Some doctors, like psychologists, help people with their problems.", "zh": "有些医生，例如心理医生，帮助人们解决他们的问题。"}], "en": "People can help each other live longer by simply discouraging these bad habits.", "zh": "人们只要劝别人改掉这些坏习惯，就可以帮助彼此活得久一点。"}], "exercises": null}, {"num": 122, "title_en": "I Quit Smoking", "title_zh": "我戒烟了", "type": "dialogue", "category": "情境实战会话", "reading": null, "dialog": {"turns": [{"speaker_en": "Gary", "speaker_zh": "加里", "en": "Hi, Susan! Do you have a light?", "zh": "嗨，苏珊！借个火好吗？"}, {"speaker_en": "Susan", "speaker_zh": "苏珊", "en": "No. I quit smoking long ago.", "zh": "不。很久以前我就戒烟了。"}, {"speaker_en": "Gary", "speaker_zh": "加里", "en": "That's good. Congratulations!", "zh": "那很好·祝贺你！"}, {"speaker_en": "Susan", "speaker_zh": "苏珊", "en": "Why don't you quit as well?", "zh": "你何不也戒掉呢？"}, {"speaker_en": "Gary", "speaker_zh": "加里", "en": "It's really difficult.", "zh": "那真得很困难。"}, {"speaker_en": "Susan", "speaker_zh": "苏珊", "en": "Come on; where there's a will, there's a way.", "zh": "别这样嘛；有志者事竟成。"}]}, "vocab": [{"num": 1, "word": "quit smoking", "phonetic": "", "pos": "短语", "meaning": "戒烟", "examples": [{"en": "After my father had a heart attack, he quit smoking. George doesn't work here anymore; he quit.", "zh": "我父亲在一次心脏病发作后便戒烟了。）（乔治不在此工作了，他辞职了。"}], "sub_entries": ["quit[kwit ]vt.&vi.戒除，辞职"]}, {"num": 2, "word": "light", "phonetic": "[lait]", "pos": "n.", "meaning": "原意指“光线”，此处指火柴或打火", "examples": [], "sub_entries": ["机打出来的“火”", "\"Do you have alight?”相当于中文“借个火好吗？”"]}, {"num": 3, "word": "Why don't you quit as well?", "phonetic": "", "pos": "日常口语", "meaning": "你何不也戒掉呢？", "examples": [{"en": "Mary sings well; she is good at dancing as well. =Mary sings well; she is good at dancing, too. =Mary sings well; she is also good at dancing.", "zh": "玛丽歌唱得很好，她跳舞也很在行。"}], "sub_entries": ["= Why don't you quit, too?", "本句形式上虽为否定，实则含有肯定的意味，因为对", "人家说：“你何不也戒掉呢？”就是用来劝别人戒掉", "的意思，故aswell表示“也”的意思时，用于肯定", "句中，相当于副词too，使用时置于句尾。"]}, {"num": 4, "word": "come on", "phonetic": "", "pos": "短语", "meaning": "别这样嘛", "examples": [{"en": "Come on! Cheer up!", "zh": "别这样嘛！振作起来吧！"}], "sub_entries": []}, {"num": 5, "word": "Where there is a will, there is a way.", "phonetic": "", "pos": "谚语", "meaning": "有志者事竟成。", "examples": [{"en": "Where there is a will, there is a way. =In the place where there is a will, there is a way. =In the place in which there is a will, there is a way.", "zh": "在有意志的地方，就有一条路。即：有志者事竟成。）*will[wil]n.意志"}], "sub_entries": ["有志者事竟成。（谚语）", "本谚语句首的Where等于In theplacewhere", "（在.….…·的地方），亦即等于In theplacein which"]}], "grammar": null, "substitution": [], "exercises": {"prompt": "Ⅲ．请选出下列各句中正确的一项", "questions": ["1. Sally decided to study Latin.", "(A) Bill decided to study Latin", "(B）Bill decided to study Latin as well", "(C) As well Bill decided to study Latin", "(D) Too Bill decided to study Latin", "2. Chuck", "my car yesterday.", "(A） helped fix me", "(B）helped with me fix", "(C) helped me fix", "(D) helped with fix", "3.I told David I would help", "(A) him with his homework", "(B）his homework", "(C) his homeworks", "(D) his with him homework", "4. Joe", "here by his father.", "(A) brought", "(B) has brought", "(C) was brought", "(D) was to bring", "5. The books", "yet.", "(A) have been written", "(B）have not been written", "(C) have never been written", "(D） have written", "6. I'm studying English.", "(A) Carl is a teacher as well", "(B) Carl is a student at another school, too", "(C) Carl is studying English as well", "(D) Carl is an American as well"], "answers": ["解答1.(B）2.(C）3.(A）4.(C）5.(B）6.(C)"]}}, {"num": 123, "title_en": "An Accident", "title_zh": "一桩事故", "type": "reading", "category": "进阶短文与语法探究", "reading": {"en": ["Sally and her husband, Jack, have both been driving for three years. Jack has always driven very carefully. He has never been in an accident. Sally, however, has never been a good driver. She has already gotten into four accidents this year. Each time she has had an accident, she has claimed that it was not her fault. Yesterday, Sally drove into a tree. She blamed it on the tree, saying that she honked the horn, but the tree didn't get out of the way."], "zh": ["萨莉和她丈夫杰克两人开车已有三年了。杰克开车总是很小她的错。昨天萨莉撞到一棵树，她把她的错归罪于那棵树，她说她按了喇叭，但那棵树就是不让路。"], "sentences": [{"en": "Sally and her husband, Jack, have both been driving for three years.", "zh": "萨莉和丈夫杰克各自开车都满三年了。"}, {"en": "Jack has always driven very carefully. He has never been in an accident.", "zh": "杰克开车一贯小心谨慎，从未发生过任何交通事故。"}, {"en": "Sally, however, has never been a good driver.", "zh": "然而，萨莉向来都不是个让人放心的司机。"}, {"en": "She has already gotten into four accidents this year.", "zh": "光是今年她就已经撞了四次车。"}, {"en": "Each time she has had an accident, she has claimed that it was not her fault.", "zh": "每次撞车出事故，她总辩解说这绝非自己的过错。"}, {"en": "Yesterday, Sally drove into a tree.", "zh": "昨天，萨莉一头撞在了一棵大树上。"}, {"en": "She blamed it on the tree, saying that she honked the horn, but the tree didn't get out of the way.", "zh": "她把事故全怪在树头上，辩称自己明明按了喇叭，那棵树却偏偏不肯躲开。"}]}, "dialog": null, "vocab": [{"num": 1, "word": "accident", "phonetic": "[ˈeksadant]", "pos": "n.", "meaning": "事故", "examples": [{"en": "On my way to work this morning, I saw a terrible traffic accident.", "zh": "今早我去上班途中看见一起可怕的交通事故。"}], "sub_entries": []}, {"num": 2, "word": "drive", "phonetic": "[draiv]", "pos": "vi.", "meaning": "开车&vt.开（车），驾驶", "examples": [{"en": "I drove down to the seashore yesterday. Peter loves driving his new car.", "zh": "我昨天开车到海边。）（彼得很喜欢开他的新车。"}], "sub_entries": ["动词三态：drive，drove，driven"]}, {"num": 3, "word": "carefully", "phonetic": "[ˈkerfall]", "pos": "adv.", "meaning": "小心地，谨慎地", "examples": [], "sub_entries": []}, {"num": 4, "word": "driver", "phonetic": "[ˈdraivo]", "pos": "n.", "meaning": "司机，驾驶员", "examples": [], "sub_entries": []}, {"num": 5, "word": "get into + 麻烦/事故", "phonetic": "", "pos": "短语", "meaning": "陷入...，卷入...", "examples": [{"en": "Larry has gotten into trouble again.", "zh": "拉里又惹上癫烦了。"}], "sub_entries": ["遭遇………"]}, {"num": 6, "word": "claim", "phonetic": "[klem]", "pos": "vt.", "meaning": "宣称；夺去（人命）", "examples": [{"en": "Mary, that ugly man over there claims that he's your boyfriend. Is it true?", "zh": "玛丽，那边那名丑男子宣称是你的男朋友·那是真的吗？"}, {"en": "The earthquake claimed twenty-one people. → The earthquake claimed twenty-one lives.", "zh": "×)(○)（地震夺去了21条人命。"}], "sub_entries": ["claim+that引导的名词性从句宣称.…."]}, {"num": 7, "word": "fault", "phonetic": "[folt]", "pos": "n.", "meaning": "错误，过失", "examples": [{"en": "I didn't break the window; it's not my fault. Who's at fault for starting the fight?", "zh": "我没有打破窗户，那不是我的错。）（引起这场争吵是谁的错呢？"}], "sub_entries": ["beone'sfault是某人的错", "be at fault有过错"]}, {"num": 8, "word": "blame", "phonetic": "[blem]", "pos": "vt.", "meaning": "责备，归咎", "examples": [{"en": "The police blamed the traffic accident on bad weather conditions. Don't blame me for your failures.", "zh": "警方将这场交通事故归咎于恶劣的天气。）（别将你的失败怪在我身上。"}], "sub_entries": ["blame+事+on+人／事将某事归咎于某人／某事", "blame+人+for+事", "为某事责备某人"]}, {"num": 9, "word": "honk the horn", "phonetic": "", "pos": "短语", "meaning": "按喇叭", "examples": [{"en": "A: If I want the person in front of me to drive faster, I honk my horn. B: I think that's very rude!", "zh": "甲：如果我想要前面的人开快一点，我会按喇叭。）（乙：我认为那样很不礼貌！"}], "sub_entries": ["honk.[hapk]vt.按（汽车喇叭）", "horn[horn]n.喇叭"]}], "grammar": {"intro": "本课复习现在完成时及现在完成进行时，并介绍动词变成 现在分词作补足语的用法。", "items": [{"num": 1, "title": "Sally and her husband, Jack, have both been driving for three years.", "body": ["（萨莉和她丈夫杰克两人开车已有三年了。)本句为现在完成进行时。现在完成进行时的结构为：", "have/has+been+现在分词", "例：He has been working on the math problem for two hours.（他研究这道数学题已达两个小时之久。）", "注意：", "a. 在许多情况之下，现在完成时可取代现在完成进行 时，意思大致相近。", "例: He has lived here for ten years.", "=He has been living here for ten years.（他住在这里已有十年了。）", "b. 但严谨的语法规定某动作到说话的时刻已经完", "成，而不再持续时，应使用现在完成时；若某动作 到说话的时刻仍在进行时，应使用现在完成进行 时。", "例：He has worked out the math problem.（他已解出这道数学题了。一一动作已经完 成。）", "He has been working on the math problem for two hours.（他研究这道数学题已过两个小时之久。·研究的动作到现在还在持续。）阿明与阿德一块儿去应征一份需要英语能力的工作。口试的经理问两人相同的问题：“你英语学多久 了？”阿明说：\"I've learned English for five years.\"阿德说：\"I've been learning English for five years. 经理听完，立即录取阿德·阿明心里很难过，事后忍 不住向阿德说：“论长相，我赢你；论口才，我更比 你略胜-一筹，干嘛这位经理却录取了你？”阿德不慌 不忙地说道：“我使用现在完成进行时，表示五年来 我一直在学英语，到现在还未中断。而你只使用现在 完成时，那表示五年来你也在学英语，很可能现在不 继续学了·经理显然认为我比你用功，就录取了 我！”"]}, {"num": 2, "title": "She blamed the fault on the tree, saying that she honked the horn, but the tree didn't get out of the way.", "body": ["（她把她的错归罪于那棵树，她说她按了喇叭，但那 棵树就是不让路。）", "a.-个句子若出现有两个动词，这两个动词应有连词 and连接·故上列例句本可写成如下列句子：", "She blamed the fault on the tree, and said that she...", "b. 但有时作者故意不使用and连接两个动词，以表 示两个动作同时发生。此时应将第二个动词变成现 在分词，形成分词短语，称作主语补足语。故上句 可将and省略，并将第二个动词 said改成现在分 词saying·故可改成如本文的句子，即：", "She blamed the fault on the tree, saying that she... 又例:He sat there read a newspaper.（x)", "→ He sat there reading a newspaper. (○)（他坐在那里看报纸。）", "注意：", "这种分词短语形成的主语补足语之前通常无逗号，如上例：", "He sat there reading a newspaper. 但有些分词短语却需置逗号，以免造成句意错误，如本文最后一句之saying之前非要有逗号不可，若无逗号，会造成saying修饰之前名词thetree 的错误联想。即：", "She blamed the fault on the tree, saying that she... (×)", "=She blamed the fault on the tree which said that she...(×)（她把她的错归罪于那棵树，那棵树说她·…···", "c. 两个动词无连词连接，而第二个动词为be动词时，亦应变成现在分词being 之后，再将being予以 省略。", "例:He died was young. (×)(being)", "→ He died young. (○)（他英年早世。）又例: I left home was a child and came back(being)was an old man. (×)(being)-→I left home a child and came back an old man. (○)（少小离家老大回。）"]}]}, "substitution": [{"num": 1, "pairs": [{"en": "They have both been driving for three years.", "zh": "他们两人开车已有三年了。"}, {"en": "Frank has driven a motorcycle for five years.", "zh": "弗兰克骑摩托车已有五年了。"}, {"en": "She has been studying for her exams all night.", "zh": "她为了考试已读了一-整夜的书了。"}, {"en": "Susan has studied for her exams all night.", "zh": "苏珊为了考试一整夜都在念书。"}], "en": "They have both been driving for three years.", "zh": "他们两人开车已有三年了。"}, {"num": 2, "pairs": [{"en": "She blamed it on the tree, saying that she honked the horn.", "zh": "她把她的错归罪于那棵树，她说她按了喇叭。"}, {"en": "Vicky pointed at her husband, saying that he was a sloppy man.", "zh": "维基指着她丈夫，说他是一个邀逼鬼。"}, {"en": "Steve sat in a chair in the corner, sleeping like a baby.", "zh": "史蒂夫坐在角落的椅子上，睡得像个婴儿似的。"}, {"en": "Ralph walked down the street, looking at every girl that walked by.", "zh": "拉尔夫走在街上，看着每-个路过的女孩。"}], "en": "She blamed it on the tree, saying that she honked the horn.", "zh": "她把她的错归罪于那棵树，她说她按了喇叭。"}], "exercises": null}, {"num": 124, "title_en": "Beautiful Shanghai", "title_zh": "美丽的上海市", "type": "dialogue", "category": "情境实战会话", "reading": null, "dialog": {"turns": [{"speaker_en": "Alan", "speaker_zh": "艾伦", "en": "Have you ever been to Guilin?", "zh": "你有没有去过桂林？"}, {"speaker_en": "Galen", "speaker_zh": "盖伦", "en": "No. But I've been to Shanghai.", "zh": "没有。但我去过上海·"}, {"speaker_en": "Alan", "speaker_zh": "艾伦", "en": "Did you have a good time?", "zh": "你玩得愉快吗？"}, {"speaker_en": "Galen", "speaker_zh": "盖伦", "en": "Yes. Shanghai is a beautiful city.", "zh": "愉快。上海是个美丽的城市·"}]}, "vocab": [{"num": 1, "word": "Have", "phonetic": "", "pos": "", "meaning": "you ever been to+ 地方名词?", "examples": [{"en": "A: Have you ever been to Nanjing? B: Yes. Quite a few times.", "zh": "甲：你有没有去过南京？）（乙：有，去过不少次了。"}], "sub_entries": ["你有没有去过某地？"]}, {"num": 2, "word": "have a good time", "phonetic": "", "pos": "短语", "meaning": "玩得很愉快", "examples": [{"en": "I had a good timetochatwithherlast night.（×) →I had a good 1timechatting withherlast night.（O) We had a lot of fun to dance at the party. -→> We had a lot of fun dancing at the party.", "zh": "昨晚我跟她聊天聊得很愉快。）（×)（o)（我们在宴会上跳舞跳得很愉快。"}], "sub_entries": ["=have fun", "注意：", "本短语常使用于下列结构中：", "have|a good time", "+(in)+动名词", "a wonderful time", "a great time", "fun", "从事··…玩得很愉快"]}], "grammar": null, "substitution": [], "exercises": {"prompt": "Ⅲ．请选出下列各句中正确的一项", "questions": ["1. Edward", "at this company for twenty years.", "(A) has working", "(B) has been working", "(C) has work", "(D) has being", "2. Henry skipped down the street,", "a song.", "(A) whistling", "(B)whistled", "(C) whistle", "(D) had whistle", "3. We had", "at the school picnic.", "(A) time", "(B) wonderful time", "(C) a fun", "(D) a great time", "4. David had", "at the lake.", "(A) fun to swim", "(B)fun swimming", "(C) a fun swimming", "(D) fun swim", "5.We", "at the party last night. We had a", "wonderful time.", "(A) dancing and singing", "(B) danced and singed", "(C) danced and sang", "(D) dance and sang", "6. Did you have fun", "last weekend?", "(A) to go camp", "(B) to camping", "(C) camping", "(D) on camping"], "answers": ["解答1.(B)2.(A）3.(D）4.(B）5.(C）6.(C)"]}}, {"num": 125, "title_en": "Studying Seriously", "title_zh": "认真地学", "type": "reading", "category": "进阶短文与语法探究", "reading": {"en": ["John has been trying to learn how to play the guitar. He has been taking lessons for half a year. However, he hasn't been studying seriously. He has only been going to his lessons every now and then. Moreover, he seldom practices. On the other hand, his cousin, Tim, has been playing the guitar for about three months. He plays much better than John. Tim isn't more talented than John, though. He is just more determined."], "zh": ["约翰一直在学吉他。他去上课已有半年了。不过，他并不是很认真地在学。他只是偶尔才去上一次课。而且他很少练习。另一方面，他的表哥蒂姆学吉他只有三个月左右。他弹奏得要比约翰好多了。然而蒂姆并不比约翰有天份，他只是更有决心而已。"], "sentences": [{"en": "John has been trying to learn how to play the guitar.", "zh": "约翰这半年一直在努力学弹吉他。"}, {"en": "He has been taking lessons for half a year.", "zh": "他去辅导班上课已有整整六个月了。"}, {"en": "However, he hasn't been studying seriously.", "zh": "遗憾的是，他平时练得并不够用心。"}, {"en": "He has only been going to his lessons every now and then.", "zh": "他只是偶尔三天打鱼两天晒网去上一次课。"}, {"en": "Moreover, he seldom practices.", "zh": "而且回到家里几乎从不主动练习。"}, {"en": "On the other hand, his cousin, Tim, has been playing the guitar for about three months.", "zh": "相反，他的表弟蒂姆才刚刚开始学了三个月。"}, {"en": "He plays much better than John.", "zh": "蒂姆现在的演奏水平已经远远超过了约翰。"}, {"en": "Tim isn't more talented than John, though. He is just more determined.", "zh": "其实蒂姆并没有更高的音乐天赋，他只是更有毅力、更加坚韧不拔而已。"}]}, "dialog": null, "vocab": [{"num": 1, "word": "seriously", "phonetic": "[ˈsiriasli]", "pos": "adv.", "meaning": "认真地；严重地", "examples": [{"en": "Are you seriously thinking about moving to Paris? Frank was seriously hurt when a bus hit his bicycle.", "zh": "你是否在认真考虑要搬到巴黎去呢？）（当一辆公共汽车撞上弗兰克的自行车时，他受了重伤。"}], "sub_entries": []}, {"num": 2, "word": "try", "phonetic": "", "pos": "", "meaning": "to+动词原形", "examples": [{"en": "The little boy tried to pick up the heavy box, but couldn't.", "zh": "那小男孩设法拿起那个重箱子，但却拿不起来。"}], "sub_entries": ["设法要····"]}, {"num": 3, "word": "guitar", "phonetic": "[ɡiˈtar]", "pos": "n.", "meaning": "吉他", "examples": [], "sub_entries": []}, {"num": 4, "word": "take lessons", "phonetic": "", "pos": "短语", "meaning": "修习课程", "examples": [{"en": "My daughter has been taking dancing lessons for ten years.", "zh": "我女儿上舞蹈课已有十年了。"}], "sub_entries": []}, {"num": 5, "word": "half a year/a month/an hour", "phonetic": "", "pos": "短语", "meaning": "半年／半个月／半小时", "examples": [{"en": "Last night I was stuck in an elevator for about half an hour.", "zh": "昨晚我被困在电梯里大约半个小时。"}], "sub_entries": []}, {"num": 6, "word": "everynow and then", "phonetic": "", "pos": "短语", "meaning": "偶尔", "examples": [{"en": "Unfortunately, I only see Chris every now and then.", "zh": "遗憾的是，我偶尔才会见到克里斯。"}], "sub_entries": []}, {"num": 7, "word": "moreover", "phonetic": "[morˈov]", "pos": "adv.", "meaning": "并且，此外", "examples": [{"en": "Jim was accepted by Harvard Law School. Moreover, he received a scholarship.", "zh": "吉姆被获准进入哈佛法学院。此外，他还获得奖学金。"}], "sub_entries": []}, {"num": 8, "word": "seldom", "phonetic": "[ˈseldam]", "pos": "adv.", "meaning": "不常，很少", "examples": [{"en": "I used to play tennis every weekend. But now I seldom play.", "zh": "我以前常在周末打网球。但现在我已很少打了"}], "sub_entries": []}, {"num": 9, "word": "practice", "phonetic": "[ˈpraektis]", "pos": "vi.", "meaning": "& vt.练习", "examples": [{"en": "Joe got a new job. Now he has notime to practice music.", "zh": "乔有了一份新工作。现在他没有时间练习音乐了。"}], "sub_entries": []}, {"num": 10, "word": "cousin", "phonetic": "[kAzn]", "pos": "n.", "meaning": "表兄弟（姊妹）；堂兄弟（姊妹）", "examples": [], "sub_entries": []}, {"num": 11, "word": "talented", "phonetic": "[ˈtalantid]", "pos": "a.", "meaning": "有天份的，有才华的", "examples": [{"en": "Phyllis is a very talented writer. Bob has a real talent for telling jokes.", "zh": "菲莉斯是个很有才华的作家。）（鲍勃很有讲笑话的天份。"}], "sub_entries": ["talent['taelant]n.才华，天份"]}, {"num": 12, "word": "determined", "phonetic": "[dɪˈtɜːrmɪnd]", "pos": "a.", "meaning": "坚决的，决意的", "examples": [{"en": "Sam isdetermined tobethe best salesman in his company.", "zh": "山姆决意要成为他公司里最好的业务员。"}], "sub_entries": []}], "grammar": {"intro": "本课仍继续复习现在完成进行时的句型运用，并复习修饰 比较级的副词用法·由于现在完成进行时至此已复习了数 遍，在此不再赞述，特就修饰比较级的副词用法再作复 习·请看下列本课阅读部分的原文句子： He plays much better than John. （他弹奏得要比约翰好多了。） 此处much为副词，修饰副词well的比较级bettero 副词或形容词变成比较级时，通常可被much、far、a lot、agreatdeal、still、even等六个副词修饰·其 中又以 much、far、alot、even 最为常用。 例：You must be|much|more careful next time. far la lot! （下次你要更加小心才是。） He has been admitted to that university. What's even better, he has also won a scholarship. （他已获准进人该大学念书。更好的是，他还获得了一 份奖学金。） 注意： a.much丶far、alot亦可以修饰副词too（太....）。 例：It's| much} too cold today. far ia lot （今天天气太冷了。） b.byfar 则可用来修饰最高级，表示“程度很大”或 “差距很大”，作强调用法。 例：He is by far the best student I've ever taught. （他是我教过最好的-一位学生。） Don't you think that she is by far the most beautiful girl in our class? （你难道不认为她是我们班上最美的女孩子吗？）", "items": []}, "substitution": [{"num": 1, "pairs": [{"en": "He plays much better than John.", "zh": "他弹奏得要比约翰好多了。"}], "en": "He plays much better than John.", "zh": "他弹奏得要比约翰好多了。"}, {"num": 2, "pairs": [{"en": "George is a far better dancer than I.", "zh": "乔治是个比我好很多的舞者。"}], "en": "George is a far better dancer than I.", "zh": "乔治是个比我好很多的舞者。"}, {"num": 3, "pairs": [{"en": "Frank said America is beautiful. But I think Europe is even more beautiful.", "zh": "弗兰克说美国很漂亮，但我认为欧洲更漂亮。"}], "en": "Frank said America is beautiful. But I think Europe is even more beautiful.", "zh": "弗兰克说美国很漂亮，但我认为欧洲更漂亮。"}, {"num": 4, "pairs": [{"en": "Studying Latin is a great deal more difficult than studying English.", "zh": "学拉丁文要比学英文来得困难多了。"}], "en": "Studying Latin is a great deal more difficult than studying English.", "zh": "学拉丁文要比学英文来得困难多了。"}], "exercises": null}, {"num": 126, "title_en": "Playing the Piano", "title_zh": "弹钢琴", "type": "dialogue", "category": "情境实战会话", "reading": null, "dialog": {"turns": [{"speaker_en": "Able", "speaker_zh": "亚伯", "en": "How long have you been playing the piano. Nancy?", "zh": "南希，你弹钢琴弹多久了？"}, {"speaker_en": "Nancy", "speaker_zh": "南希", "en": "For about ten years.", "zh": "大约十年了。"}, {"speaker_en": "Able", "speaker_zh": "亚伯", "en": "Wow! That's a long time. Can you teach me how to play?", "zh": "哇！那真是很久了。你可以教我弹钢琴吗？"}, {"speaker_en": "Nancy", "speaker_zh": "南希", "en": "No problem.", "zh": "没问题。"}]}, "vocab": [{"num": 1, "word": "play the piano", "phonetic": "", "pos": "短语", "meaning": "弹钢琴", "examples": [{"en": "He is good at playing|the piano. the .trumpet. the guitar.", "zh": "他擅于弹钢琴／吹小喇叭／弹吉他。）b.表示玩某种球类运动时，应说：play+表示球类运动的名词"}, {"en": "He plays the basketball well.(×) -→ He plays basketball well. (○)", "zh": "他篮球打得很好。）其他球类运动如：rugby['r^gbr]（橄榄球）badminton['badmintan]（羽毛球）、soccer['sako]（英式足球）、volleyball['vall.bol]（排球）、tennis['tenis]（网球）等，与play并用时，之前均不可置定冠词the。"}], "sub_entries": ["play[ple]vt.演奏；玩（球类运动）", "piano[pr'eno]n.钢琴"]}, {"num": 2, "word": "For about ten years.", "phonetic": "", "pos": "口语", "meaning": "大约十年了。", "examples": [{"en": "Some twenty passengers were injured in the traffic accident. =About twenty passengers... = Approximately twenty passengers...", "zh": "那起交通事故中大约有20名乘客受伤。"}], "sub_entries": ["此处 about 是副词，作“大约”解，之后接明确的数字。", "= about / some / around / approximately + 数字 + 名词：大约……", "* approximately [əˈprɑːksɪmətli] adv. 大约"]}], "grammar": null, "substitution": [], "exercises": {"prompt": "Ⅲ.请选出下列各句中正确的一项", "questions": ["1. Betty", "kindergarten for approximately", "twelve years.", "(A) has teaching", "(B) has been teaching", "(C) teached", "(D) was teaching", "2. Steve is a", "student than his brother, Larry.", "(A) even better", "(B) great better", "(C) far better", "(D) lot better", "3.Charlie has been", "1studying", "g the organfor ten", "years. As a result,", "(A) he is really good at playing the organ", "(B) he isn't good at playing the organ", "(C) he is good to play the organ", "(D) he is really bad at playing the organ", "fifty people came to the job interview.", "(A）Around", "(B)Round", "(C) Approximate", "(D) Somewhat", "5. Grace is very good at", "(A) play tennis", "(B) playing the tennis", "(C) playing tennis", "(D) the tennis and playing"], "answers": ["解答→1.(B）2.(C）3.(A）4.(A）5.(C)"]}}, {"num": 127, "title_en": "An Honest Man", "title_zh": "诚实的人", "type": "reading", "category": "进阶短文与语法探究", "reading": {"en": ["If you are honest, people will trust you. It is important for a person to have a reputation for being honest. If a person is dishonest, no one will want to be his friend. He will soon become an outcast. On the other hand, an honest man wins the respect of others. Honesty is, indeed, the best policy."], "zh": ["你若诚实，人们就会信任你。对一个人来说，拥有诚实的信誉是很重要的。一个人若不诚实，就没有人会想和他做朋友。不久他就会被人拒于千里之外。另一方面说来，诚实的人会赢得别人的尊敬。诚实确实是上策。"], "sentences": [{"en": "If you are honest, people will trust you.", "zh": "你若诚实，人们就会信任你。"}, {"en": "It is important for a person to have a reputation for being honest.", "zh": "对一个人来说，拥有诚实的信誉是很重要的。"}, {"en": "If a person is dishonest, no one will want to be his friend.", "zh": "一个人若不诚实，就没有人会想和他做朋友。"}, {"en": "He will soon become an outcast.", "zh": "不久他就会被人拒于千里之外。"}, {"en": "On the other hand, an honest man wins the respect of others.", "zh": "另一方面说来，诚实的人会赢得别人的尊敬。"}, {"en": "Honesty is, indeed, the best policy.", "zh": "诚实确实是上策。"}]}, "dialog": null, "vocab": [{"num": 1, "word": "honest", "phonetic": "[ˈonist]", "pos": "a.", "meaning": "诚实的", "examples": [{"en": "Don't believe anything Kirk says; he's very dishonest.", "zh": "别相信柯克所说的任何话，他很不诚实。"}], "sub_entries": ["dishonest[dis'onist]a.不诚实的", "honesty['anisti]n.诚实"]}, {"num": 2, "word": "trust", "phonetic": "[trast]", "pos": "vt.", "meaning": "信任，相信", "examples": [{"en": "Barbara is so naive; she trusts every one she meets.", "zh": "巴巴拉很天真，她相信她所碰到的每个人。"}], "sub_entries": []}, {"num": 3, "word": "reputation", "phonetic": "[repjeˈtejen]", "pos": "n.", "meaning": "名声，名誉", "examples": [{"en": "That restaurant has a reputation for good foodand service.", "zh": "那家餐厅在食物和服务方面有很好的名声。"}], "sub_entries": []}, {"num": 4, "word": "outcast", "phonetic": "[ˈaut.kaest]", "pos": "n.", "meaning": "被排斥的人，被驱逐的人", "examples": [{"en": "Poor Frank has never had any friends. He's always been an outcast.", "zh": "可怜的弗兰克从没有过一位朋友。他总是被人拒于千里之外。"}], "sub_entries": []}, {"num": 5, "word": "respect", "phonetic": "[rˈspekt]", "pos": "n.", "meaning": "&vt.尊敬", "examples": [{"en": "The employees have a lot of respect for the boss. You should respectyour elders.", "zh": "那些职员都很尊敬他们的老板。）（你应当要尊敬长辈。"}], "sub_entries": []}, {"num": 6, "word": "Honesty", "phonetic": "", "pos": "", "meaning": "is the best policy．诚实为上策。（谚语）", "examples": [], "sub_entries": ["policy['palasi]n.政策"]}], "grammar": {"intro": "本课介绍if形成的虚拟语气及其用法。 连词if引导一个状语从句，修饰主句·整个句意相当中 的状况，我们称为虚拟语气。", "items": [{"num": 1, "title": "一般而言，if 形成的虚拟语气有下列四种句型：", "body": ["a. 表示纯粹的条件：", "句型：If + 主语 + 动词现在式，主语 + (will / may / can / should) + 动词原形", "例：If John has money, he will build a library in his neighborhood.（约翰若是有钱，就会在住处附近盖一座图书馆。）", "从本例判断，我们并不能确定约翰现在是否有钱，只能确定他盖图书馆的行动必须建立在他有钱的条件上。此时 if 引导的状语从句是一种纯粹的条件从句，与 when、once（一旦）、unless（除非）引导的从句一样，句中的动词必须是现在式，而主句则须有助动词 will、may、can、should 等。", "例：If I have time, I may call you.（我若有空，就会打电话给你。）", "If you don't help me, I can't finish on time.（你若不帮助我，我就无法准时做完。）", "本课阅读部分中 if 形成的虚拟语气，即属此用法：", "例：If you are honest, people will trust you.（你若诚实，人们就会信任你。）", "b. 表示与现在的事实相反：", "句型：If + 主语 + 动词过去式，主语 + (would / might / could / should) + 动词原形", "例：If John had money, he would build a school.（约翰若有钱，就会盖一所学校。——但他现在没钱。）", "本句在 if 所引导的从句中，had 为 have（有）的过去式，主句亦使用助动词 will 的过去式 would。故本句乃暗示约翰现在并没有钱，整句乃表示与现在事实相反的虚拟语气。", "注意：if 引导的从句有 be 动词时，不论主语为第几人称，一律使用 were。", "例：If you were in my shoes, what would you do?（你若处于我的立场，你会怎么做？）", "If he were here, he might enjoy a happy life.（他若在这里，也许生活会很愉快。）", "c. 表示与过去的事实相反：", "句型：If + 主语 + had + 过去分词，主语 + (would / might / could / should) + have + 过去分词", "例：If he had seen the result yesterday, he would have been disappointed.（昨天他若看到这个结果，就会感到失望。——但他昨天并未看到结果，因此并未感到失望。）", "If I had met Jane ten years ago, I might have married her.（如果十年前我见到简的话，我也许会娶她。——但十年前我并未见到简，因此并未娶她。）", "d. 与未来的状况相反：", "句型：If + 主语 + should + 动词原形，主语 + (would / might / could / should) + 动词原形", "例：If it should rain, I would stay at home.（万一下雨的话，我就会待在家里。）", "If he should be late again, I might punish him.（万一他又迟到，我可能会处罚他。）", "注意：", "1）与未来状况相反的虚拟语气中，if 引导的从句应使用助动词 should，表示“万一...”或“如果真是”的意思。", "例：If he should be willing to help me, I could finish all the work in no time.（如果他真的肯帮我，我就能够很快地把所有的工作做完。）", "2）由于未来的状况难预料，因此如果我们认为未来的状况极可能发生时，主句的助动词可改用 will、can、may 等，以强调极大的可能性；但我们若认为未来的状况不太可能发生时，主句的助动词则使用过去式如 would、could、might 等。", "比较：If it should rain tomorrow, we would cancel the picnic.（明天万一下雨的话，我们会取消野餐。——我想明天不会下雨。）", "If it should rain tomorrow, we will cancel the picnic.（明天万一下雨的话，我们会取消野餐。——我想明天很可能会下雨。）"]}, {"num": 2, "title": "条件状语从句中 if 的省略与倒装", "body": ["if引导的从句中若有were、should或“had+过去", "分词”时，可将if省略，并将were、should或", "had置于主语前。", "例：If he were ill, I would take care of him.", "=Were he ill, I would take care of him.", "（他若生病，我会照顾他。）", "If he should stop helping me, my plan could", "be ruined.", "=Should he stop helping me, my plan could", "be ruined.", "（万－他不再帮助我，我的计划就要泡汤了。）", "If he had learned about the result, he might", "have been angry.", "=Had he learned about the result, he might", "have been angry.", "（他当时要是知道这结果，也许会生气。）"]}]}, "substitution": [{"num": 1, "pairs": [{"en": "If you are honest, people will trust you.", "zh": "你若诚实；人们就会信任你。"}, {"en": "If it doesn't rain tomorrow, we will have a barbeque.", "zh": "如果明天没有下雨，我们就会到野外吃烤肉。"}, {"en": "You can go to Greg's party if you get an \"A\" on your test.", "zh": "如果你考了个\"A”，你就可以去参加葛雷格的宴会。"}, {"en": "If I'm accepted, I may go to Harvard to study management.", "zh": "如果我被接受；我便可以去哈佛读管理。"}], "en": "If you are honest, people will trust you.", "zh": "你若诚实；人们就会信任你。"}, {"num": 2, "pairs": [{"en": "If a person is dishonest, no one will want to be his friend.", "zh": "一个人若不诚实，就没有人会想和他做朋友。"}, {"en": "If Kathy had the time, she would visit you.", "zh": "如果凯茜有时间，她就会去拜访你。"}, {"en": "I might call him if I knew his phone number.", "zh": "如果我知道他的电话号码，我可能会打电话给他。"}, {"en": "He wouldn't have been angry if you had spoken morepolitely.", "zh": "如果你当时讲话有礼貌一点，他就不会生气了。"}], "en": "If a person is dishonest, no one will want to be his friend.", "zh": "一个人若不诚实，就没有人会想和他做朋友。"}], "exercises": null}, {"num": 128, "title_en": "The Job Interview", "title_zh": "工作面试", "type": "dialogue", "category": "情境实战会话", "reading": null, "dialog": {"turns": [{"speaker_en": "Carrie", "speaker_zh": "卡丽", "en": "Howdid thejobinterviewgo?", "zh": "面试进行得如何？"}, {"speaker_en": "Jock", "speaker_zh": "裘克", "en": "It went very well. Thanks.", "zh": "进行得很顺利，谢谢。"}, {"speaker_en": "Carrie", "speaker_zh": "卡丽", "en": "What's the name of the company?", "zh": "公司的名称是什么？"}, {"speaker_en": "Jock", "speaker_zh": "裘克", "en": "Chunghwa Computers.", "zh": "中华电子计算机。"}, {"speaker_en": "Carrie", "speaker_zh": "卡丽", "en": "I've heard it has a good reputation.", "zh": "我听说它的名声很好。"}, {"speaker_en": "Jock", "speaker_zh": "裘克", "en": "That's why I applied for a job there.", "zh": "那就是我去那里求职的原因。"}]}, "vocab": [{"num": 1, "word": "interview", "phonetic": "[ˈnto.vju]", "pos": "n.", "meaning": "面试；访问", "examples": [{"en": "I always wear my best clothes to an interview.", "zh": "我总是穿上我最好的衣服去面试。"}], "sub_entries": []}, {"num": 2, "word": "How did the job interview go?", "phonetic": "", "pos": "日常口语", "meaning": "面试进行得如何？", "examples": [{"en": "Everything is going very well. How is your plan going?", "zh": "现在一切进行得很顺利。）（你的计划现在进行得如何？"}], "sub_entries": ["此处go表示“进行”的意思。"]}, {"num": 3, "word": "company", "phonetic": "[ˈkʌmpəni]", "pos": "n.", "meaning": "公司", "examples": [], "sub_entries": []}, {"num": 4, "word": "reputation", "phonetic": "[repjeˈtejan]", "pos": "n.", "meaning": "名声，名誉", "examples": [{"en": "Peter has a reputation as a grammarian.", "zh": "彼得有文法专家的美名。"}], "sub_entries": []}, {"num": 5, "word": "apply", "phonetic": "[əˈplaɪ]", "pos": "vi.", "meaning": "申请", "examples": [{"en": "After his graduation, Chris immediately applied for a job.", "zh": "毕业后，克里斯马上去求职。"}], "sub_entries": ["apply for a job", "应征工作，求职"]}], "grammar": null, "substitution": [], "exercises": {"prompt": "Ⅲ·请选出下列各句中正确的一项", "questions": ["1. If she had been in school, 1", "her..", "(A) might see", "(B) will see", "(C) would have seen", "(D) may have seeing", "2. If I see your brother, 1", "him you are looking for him.", "(A) will tell", "(B) would have told", "(C) might have told", "(D) can told", "3. Chris told his girlfriend if he had enough money,", "he", "her a car.", "(A)would have bought", "t(B)will buy", "(C) wouldn't have", "(D)would buy", "4. If Helen doesn't go,I", "either.", "(A)will", "(B)won't", "(C) might", "(D) wouldn't", "5.He", "it to you if you had asked him.", "(A) would given", "(B) will give", "(C) would have given", "(D) would have gave", "6.How is", "？", "(A) you going", "(B) your day going", "(C) you're going with your day", "(D) your day to gone"], "answers": ["解答1.(C)2.(A）3.(D）4.(B）5.(C）6.(B)"]}}, {"num": 129, "title_en": "Seven Years' Bad Luck", "title_zh": "七年的背运", "type": "reading", "category": "进阶短文与语法探究", "reading": {"en": ["I have a very superstitious friend called Mack. He thinks that if he breaks a mirror, he will have seven years' bad luck. As a result, Mack doesn't have any mirrors in his house. But not all superstitions are about bad luck. For instance, Mack also believes that if he drops his chopsticks, someone will invite him to dinner. So, Mack is always dropping his chopsticks and waiting for an invitation."], "zh": ["我有个非常迷信的朋友名叫麦克。他认为他若打破镜子，他将会有七年的背运。因此，麦克的屋子里什么镜子也没有。不过，并非所有的迷信都与背运有关。举例来说，麦克也相信他若把筷子掉下去，就会有人请他吃晚餐·因此，麦克总是把筷子掉下去，然后等着别人来邀请。"], "sentences": [{"en": "I have a very superstitious friend called Mack.", "zh": "我有个非常迷信的朋友名叫麦克。"}, {"en": "He thinks that if he breaks a mirror, he will have seven years' bad luck.", "zh": "他认为他若打破镜子，他将会有七年的背运。"}, {"en": "As a result, Mack doesn't have any mirrors in his house.", "zh": "因此，麦克的屋子里什么镜子也没有。"}, {"en": "But not all superstitions are about bad luck.", "zh": "不过，并非所有的迷信都与背运有关。"}, {"en": "For instance, Mack also believes that if he drops his chopsticks, someone will invite him to dinner.", "zh": "举例来说，麦克也相信他若把筷子掉下去，就会有人请他吃晚餐。"}, {"en": "So, Mack is always dropping his chopsticks and waiting for an invitation.", "zh": "因此，麦克总是把筷子掉下去，然后等着别人来邀请。"}]}, "dialog": null, "vocab": [{"num": 1, "word": "luck", "phonetic": "[lak]", "pos": "n.", "meaning": "运气", "examples": [{"en": "I really had good luck today. I found $100 on the street.", "zh": "我今天真地很走运。我在街上捡到美金一百元"}], "sub_entries": ["bad/good luck", "背运/好运"]}, {"num": 2, "word": "superstitious", "phonetic": "[supaˈstufas]", "pos": "a.", "meaning": "迷信的", "examples": [{"en": "Superstitious people believe that Friday the 13th is an unlucky day.", "zh": "迷信的人相信十三号星期五是不祥的日子。"}], "sub_entries": ["superstition[supa'stijfan]n.迷信"]}, {"num": 3, "word": "break", "phonetic": "[brek]", "pos": "vt.", "meaning": "打破；弄坏", "examples": [{"en": "I'm sorry. I accidently dropped your radio and broke it.", "zh": "我很抱歉。我不小心把你的收音机掉下去而把它弄坏了。"}], "sub_entries": ["动词三态：break，broke，broken."]}, {"num": 4, "word": "mirror", "phonetic": "[ˈmira]", "pos": "n.", "meaning": "镜子", "examples": [], "sub_entries": []}, {"num": 5, "word": "chopstick", "phonetic": "[ˈtfap.stik]", "pos": "n.", "meaning": "筷子（常用复数）", "examples": [], "sub_entries": ["a pair of chopsticks", "“双筷子"]}, {"num": 6, "word": "invite", "phonetic": "[inˈvait]", "pos": "vt.", "meaning": "邀请", "examples": [{"en": "Did you get invited to Professor Chen's retirement party?", "zh": "你被邀请去参加陈教授的退休宴会了吗？"}], "sub_entries": ["invite+人+to dinner/lunch", "邀请某人吃晚餐/午餐"]}, {"num": 7, "word": "wait", "phonetic": "[wet]", "pos": "vi.", "meaning": "等候，等待", "examples": [{"en": "The driver said to the passengers, \"Wait for the bus to stop before you stand up.\"", "zh": "司机对乘客说：“等到公共汽车停下来大家再站起来。”"}], "sub_entries": ["wait for+名词", "等待..··"]}, {"num": 8, "word": "invitation", "phonetic": "[.invaˈtefan]", "pos": "n.", "meaning": "邀请", "examples": [{"en": "I went to the wedding at the invitation of the bride.", "zh": "我应新娘之邀去参加婚礼。"}], "sub_entries": ["at the invitation of+人", "=at one's invitation", "在某人的邀请下，应某人之邀"]}], "grammar": {"intro": "本课介绍时间名词作所有格的用法，以及not与all形 成的部分否定用法。", "items": [{"num": 1, "title": "时间名词所有格的构成与用法", "body": ["表示时间的名词，如同表示人的名词一样，可用作所有格。如：two hours' drive（两小时车程）、ten minutes' walk（步行十分钟）。", "例: The city's traffic is getting worse and worse.", "=The traffic of the city is getting worse and worse.（这个城市的交通越来越糟。）", "I'm attracted to Beijing's scenery.", "= I'm attracted to the scenery of Beijing.（北京的风景很吸引我。）"]}, {"num": 2, "title": "not与all并用时，形成部分否定。", "body": ["But not all superstitions are about bad luck.（不过，并非所有的迷信都与背运有关。）", "a. all可作形容词（所有的）或代词（所有的人或事", "物），之前若置副词not时，即形成部分否定，相 当于中文“并非全部...”的意思。", "例：Not all the students passed the exam.（并非所有的学生考试都及格。）", "He doesn't keep all the money.（他并没有保管所有的钱。）", "注意：", "按严谨的语法，not不论置于all之前或之后均形 成部分否定，因此有人认为下列两句意思相等。", "例：Not all the students passed the exam.（并非所有的学生都考及格。）", "=All the students didnotpassthe exam.（所有的学生并非都考及格。）All that glitters is not gold.（所有会发亮的东西并非都是黄金一-中看未 必中用。）", "=Not all that glitters is gold.（并非所有会发亮的东西都是黄金…-中看未 必中用。)但在现代美语中，仍有不少人认为not置于 all之 后应视为完全否定。", "All the students did not pass the exam.（所有的学生都没考及格。）但有些固定成语，not置于all之后，不可视为完 全否定，如下例：", "All that glitters is not gold.（所有会发亮的东西并非都是黄金。）而讲求语法的人主张应采下列的写法，才算是完全 否定。", "None of the students passed the exam.（所有的学生都没考及格。）", "b. all、both、every之前置not均形成部分否定。", "not all... 并非全部...·（三者或三者以上）not every... 并非每个都·…···（三者或三者以上）not both... 并非两个都··…（两者）", "例: Not all my friends can sing.（我的朋友并非个个都会唱歌。）", "Not everything he says is correct.（他的话并非每一句都是对的。）", "Not all my parents enjoy reading. (×)", "→ Not both my parents enjoy reading. (○)（我父母并非都喜欢阅读。）", "理由：parents 指父母两人，应说 both my parents（我父母）。all my parents 则暗示父母有三个或三个以上，故无此用法。", "parents指父母两人，应说bothmyparents（我父母）。all myparents则暗示父母有三个或 三个以上，故无此用法。", "c. 表示完全否定应采下列用法：", "none of +数量有三个或三个以上的名词或代词 都不··.··. neither of+数量只有两个的名词或代词 都不.….··", "例: None of the three girls enjoys singing.（这三个女孩子没有一个喜欢唱歌。）", "None of my friends is（或 are）fond of music.（我朋友中没有一个喜欢音乐。）None of my parents smokes. (×)", "→ Neither of my parents smokes. (○)（我爸妈都不抽烟。）"]}]}, "substitution": [{"num": 1, "pairs": [{"en": "If he breaks a mirror, he will have seven years? bad luck.", "zh": "他若打破镜子，他将会有七年的背运。"}, {"en": "Have you done the day's shopping yet?", "zh": "你今天的购物都购全了吗？"}, {"en": "Time flies; we're already at the year's end.", "zh": "光阴似箭，已经到了年底了。"}, {"en": "The boss told me to finish the month's accounting before I leave.", "zh": "老板告诉我在我离开前要把这个月的帐结清。"}], "en": "If he breaks a mirror, he will have seven years? bad luck.", "zh": "他若打破镜子，他将会有七年的背运。"}, {"num": 2, "pairs": [{"en": "But not all superstitions are about bad luck.", "zh": "不过，并非所有的迷信都与背运有关。"}, {"en": "Not every superstition is about good luck.", "zh": "并非每一-种迷信都与好运有关。"}, {"en": "Not both of the brothers enjoy fishing.", "zh": "这两兄弟并非都喜欢钓鱼。"}, {"en": "Neither of the two children saw that movie.", "zh": "这两个孩子都没有看过那部电影。"}], "en": "But not all superstitions are about bad luck.", "zh": "不过，并非所有的迷信都与背运有关。"}], "exercises": null}, {"num": 130, "title_en": "He Will Bite You", "title_zh": "它会咬你", "type": "dialogue", "category": "情境实战会话", "reading": null, "dialog": {"turns": [{"speaker_en": "Mother", "speaker_zh": "母亲", "en": "Don't pull the dog's tail!", "zh": "不要扯狗的尾巴！"}, {"speaker_en": "Son", "speaker_zh": "儿子", "en": "Why? What will happen if I do?", "zh": "为什么？如果我扯的话会怎么样？"}, {"speaker_en": "Mother", "speaker_zh": "母亲", "en": "If you pull his tail, he will bite you.", "zh": "如果你扯它的尾巴，它就会咬你。"}, {"speaker_en": "Son", "speaker_zh": "儿子", "en": "No, he won't. I pulled out all his teeth this morning.", "zh": "不，它不会。今天早上我把它全部的牙齿都拔光了。"}]}, "vocab": [{"num": 1, "word": "bite", "phonetic": "[bant]", "pos": "vt.", "meaning": "咬", "examples": [{"en": "Rover, my dog, loves to bite holes in my shoes.", "zh": "我的狗儿来福很喜欢在我的鞋子上咬洞。"}], "sub_entries": ["动词三态为：bite，bit，bitten."]}, {"num": 2, "word": "pull", "phonetic": "[pul]", "pos": "vt.", "meaning": "拉，扯", "examples": [{"en": "Pull the door hard, and it will open.", "zh": "用力拉门，它就会开了。"}], "sub_entries": []}, {"num": 3, "word": "tail", "phonetic": "[tel]", "pos": "n.", "meaning": "尾巴", "examples": [], "sub_entries": []}, {"num": 4, "word": "teeth", "phonetic": "[tio]", "pos": "n.", "meaning": "牙齿（为tooth[tuθ]的复数形）", "examples": [{"en": "I went to the dentist to have two of my teeth pulled out.", "zh": "我去看医生，让他拔了两颗牙齿。"}], "sub_entries": ["have one's tooth|pulled out]", "某人把牙齿拔了", "lextracted"]}], "grammar": null, "substitution": [], "exercises": {"prompt": "Ⅲ·请选出下列各句中正确的一项", "questions": ["1.", "everything you read in the newspaper is", "true.", "(A) All", "(B)Neither", "(C) Both", "(D) Not", "2. Steve's house is about two", "ride from my", "house.", "(A)minute (B) hours (C) days'(D) day's", "3.", "thetwobooks is good for children to", "read.", "(A) None of", "(B）Neither of", "(C) Not all", "(D) AII", "4.Not all the beaches on this island are beautiful.", "This sentence means", "(A) all the beaches on this island are ugly", "(B) none of the beaches on this island are ugly", "(C) the beaches on this island are all beautiful", "(D) the beaches on this island are not all beautiful", "5. The", "are all very kind to the patients.", "(A) nurses' of the hospital", "(B) nurses of the hospitals'", "(C) nurses of that hospital", "(D) hospital nurses of that", "6. Look at that! Your terrible dog", "my poor", "cat.", "(A)has bitten", "(B)bitted", "(C) has biting", "(D) bite"], "answers": ["解答>1.(D）2.(C）3.(B）4.(D）5.(C）6.(A)"]}}, {"num": 131, "title_en": "If I Were a Millionaire", "title_zh": "假如我是百万富翁", "type": "reading", "category": "进阶短文与语法探究", "reading": {"en": ["What would you do if you were a millionaire? Many people would buy a house or travel the world. As for me, I would start a school. If I had a school, I would be able to educate many children and teach them right from wrong. Anyone will tell you that children are a country's future. If my dream comes true, I will be very happy because I will be doing my country a good service."], "zh": ["你若是百万富翁，你会怎么做？许多人会买幢房子或到世界各地旅行·至于我，我会办一所学校·如果我有一所学校，我就可以教育许多小孩并且教他们分辨是非。每个人都会说孩子是国家的未来。我的梦想若实现的话，我将会很高兴，因为我将对国家大有贡献。"], "sentences": [{"en": "What would you do if you were a millionaire?", "zh": "如果你拥有百万身家，你会做些什么？"}, {"en": "Many people would buy a house or travel the world.", "zh": "许多人会购置豪宅或去环游世界。"}, {"en": "As for me, I would start a school.", "zh": "而我若有这笔财富，则希望能创办一所学校。"}, {"en": "If I had a school, I would be able to educate many children and teach them right from wrong.", "zh": "如果拥有一所学校，我就能教育资助许多孩子，教他们明辨是非曲直。"}, {"en": "Anyone will tell you that children are a country's future.", "zh": "任谁都会赞同：孩子才是国家的明天与希望。"}, {"en": "If my dream comes true, I will be very happy because I will be doing my country a good service.", "zh": "倘若这个心愿能够成真，我将无比欣慰，因为我为自己的国家奉献了实实在在的力量。"}]}, "dialog": null, "vocab": [{"num": 1, "word": "were", "phonetic": "[wɚ]", "pos": "vi.", "meaning": "be动词的复数过去式。文中在由if", "examples": [{"en": "If I were you, I wouldn't do it.", "zh": "我若是你，就不会做这件事。"}], "sub_entries": ["引导的从句中用作be动词的虚拟语态。"]}, {"num": 2, "word": "millionaire", "phonetic": "[.miljeˈner]", "pos": "n.", "meaning": "百万富翁，大富豪", "examples": [], "sub_entries": []}, {"num": 3, "word": "as", "phonetic": "", "pos": "", "meaning": "for+人....", "examples": [{"en": "You two go out and have a good time. As for me, I'm going to bed.", "zh": "你们两个出去好好玩。至于我嘛，我要去睡觉了。"}], "sub_entries": ["至于某人，·.", "*使用时通常置句首，后面加逗号再接主要子句。"]}, {"num": 4, "word": "start", "phonetic": "[start]", "pos": "vt.", "meaning": "开创；开始", "examples": [{"en": "Father started his own business last year.", "zh": "父亲去年自己创业。"}], "sub_entries": []}, {"num": 5, "word": "educate", "phonetic": "[ˈedʒʊkeɪt]", "pos": "vt.", "meaning": "教育", "examples": [{"en": "Peter is Chinese,but was educated in America.", "zh": "彼得是中国人，但却在美国受教育。"}], "sub_entries": []}, {"num": 6, "word": "children", "phonetic": "[ˈtildran]", "pos": "n.", "meaning": "小孩，儿童（child[tfaild ]", "examples": [], "sub_entries": ["的复数形)"]}, {"num": 7, "word": "teach+", "phonetic": "", "pos": "", "meaning": "人 +right from wrong", "examples": [{"en": "That man always getsintotrouble because he can't tell right from wrong.", "zh": "那个人因为无法分辨是非，总是惹上癫烦。"}], "sub_entries": ["=teach+ 人 +to tell right from wrong", "教某人分辨是非", "* tell right from wrong分辨是非"]}, {"num": 8, "word": "country", "phonetic": "[ˈkAntrr]", "pos": "n.", "meaning": "国家", "examples": [], "sub_entries": []}, {"num": 9, "word": "future", "phonetic": "[ˈfjutfo]", "pos": "n.", "meaning": "&a.未来（的），将来（的）", "examples": [{"en": "Young Andrew has a very promising future. This is where I want to build my future home.", "zh": "年轻的安德鲁拥有光明的前程。）（这就是我想兴建未来家园的地方。"}], "sub_entries": []}, {"num": 10, "word": "dream", "phonetic": "[drim]", "pos": "n.", "meaning": "梦想；梦", "examples": [{"en": "Last night I had a dream that I could fly like a bird.", "zh": "昨晚我梦到自己能像小鸟一样地飞翔。"}], "sub_entries": []}, {"num": 11, "word": "come true", "phonetic": "", "pos": "短语", "meaning": "成真，实现", "examples": [{"en": "His hard work made his dream come true.", "zh": "他的努力使他实现了梦想。"}], "sub_entries": []}, {"num": 12, "word": "do...a good service", "phonetic": "", "pos": "短语", "meaning": "对...·大有贡献／助益", "examples": [{"en": "Joe thinks by joining the army he can do a good service for his country.", "zh": "乔认为他去从军会对国家大有贡献。"}], "sub_entries": []}], "grammar": {"intro": "本课为读者复习与现在事实相反的虚拟语气。", "items": [{"num": 1, "title": "What would you do if you were a millionaire?", "body": ["（你若是百万富翁，你会怎么做？）本问句的if从句中使用了be 动词的过去式were，且主句（即问句）亦使用了助动词will的过去式 would，故属与现在事实相反的虚拟语气。万万不可 写出下列的句子：", "What will you do if you were a millionaire?（×)"]}, {"num": 2, "title": "注意本篇阅读的最后一句：", "body": ["If my dream comes true, I will be very happy because I will be doing my country a good service.（我的梦想若实现的话，我将会很高兴，因为我将对 国家大有贡献。）*此处if引导的从句使用动词现在式comes，故属纯 粹的条件从句，主句及because 所引导的状语从句 亦应使用助动词will，以求时态的一致。"]}, {"num": 3, "title": "表示梦想的“实现”有下列数种说法：", "body": ["Thanks to his hard work, his dream 1hascome true.", "=Thanks to his hard work, his dream has materialized.", "=Thanks to his hard work, his dream has been realized.（由于他的努力，他的梦想实现了。）*materialize[ma'turia.laiz]vi.（梦想）实现 realize['ria.laiz]vt.实现（梦想）"]}]}, "substitution": [{"num": 1, "pairs": [{"en": "What would you do if you were a millionaire?", "zh": "你若是百万富翁，你会怎么做？"}], "en": "What would you do if you were a millionaire?", "zh": "你若是百万富翁，你会怎么做？"}, {"num": 2, "pairs": [{"en": "If you had only two weeks to live, what would you do?", "zh": "若你只剩两个星期的寿命，你会怎么做？"}], "en": "If you had only two weeks to live, what would you do?", "zh": "若你只剩两个星期的寿命，你会怎么做？"}, {"num": 3, "pairs": [{"en": "If you could travel to any country in the world, where would you visit?", "zh": "你若可以到世界任何一个国家去旅行，你会去哪玩？"}], "en": "If you could travel to any country in the world, where would you visit?", "zh": "你若可以到世界任何一个国家去旅行，你会去哪玩？"}, {"num": 4, "pairs": [{"en": "If you were me, what would you do?", "zh": "如果你是我，你会怎么做？"}], "en": "If you were me, what would you do?", "zh": "如果你是我，你会怎么做？"}], "exercises": null}, {"num": 132, "title_en": "A Good Citizen", "title_zh": "好公民", "type": "dialogue", "category": "情境实战会话", "reading": null, "dialog": {"turns": [{"speaker_en": "Student", "speaker_zh": "学生", "en": "How can I be a good citizen?", "zh": "我要如何成为一个好公民？"}, {"speaker_en": "Teacher", "speaker_zh": "老师", "en": "Well, always ask yourself what you can do for your country, and not what your country can do for you.", "zh": "嗯，要问自己能为国家做什么，而不是国家能为你做什么。"}, {"speaker_en": "Student", "speaker_zh": "学生", "en": "Wow! That was very well said.", "zh": "哇！说得真好。"}]}, "vocab": [{"num": 1, "word": "citizen", "phonetic": "[ˈsɪtɪzn]", "pos": "n.", "meaning": "公民，国民", "examples": [], "sub_entries": []}, {"num": 2, "word": "That is well said.", "phonetic": "", "pos": "口语", "meaning": "说得真好。", "examples": [{"en": "The articleis wellwritten. The company is well organized. The job is well done.", "zh": "这篇文章写得很好。）（这家公司很有组织。）（这工作做得很好。"}], "sub_entries": ["well 作副词时，通常可置于过去分词之前，修饰该分词。"]}], "grammar": null, "substitution": [], "exercises": {"prompt": "Ⅲ·请选出下列各句中正确的一项", "questions": ["1. If I had a car, I", "you home.", "(A） will drive", "(B) would have drived", "(C) would have driven", "(D) would drive", "2. Where", "if you could live anywhere in the", "world?", "(A) would you have lived", "(B) would you live", "(C) will you have lived", "(D) will you live", "3. If I lose my keys, I", "my landlord because", "she will come to my house and open the door", "for me.", "(A) would have call", "(B) will call", "(C) will have called", "(D) would have called", "4. That movie was very", "(A) well", "(B)well made", "(C) well in making", "(D) well to do", "5. John and Mary will go to the movies tonight.", ", I'll stay home and do some reading.", "(A）As about me", "(B）As for me", "(C) As on me", "(D)As with me"], "answers": ["解答1.(D）2.(B）3.(B)", "4. (B)", "5. (B)"]}}, {"type": "song", "id": "song_07", "title_en": "El Condor Pasa", "title_zh": "老鹰之歌", "lyrics": [{"en": "I'd rather be a sparrow than a snail. Yes, I would. If I could, I surely would. I'd rather be a hammer than a nail. Yes, I would. If I only could, I surely would. Away,I'd rather sail away like a swan that's here and gone. A man gets tied up to the ground. He gives the world its saddest sound, its saddest sound. I'dratherbe·aforestthanastreet. Yes, I would. If I could, I surely would. I'd rather feel the earth beneath my feet. Yes, I would. If I only could, I surely would.", "zh": "我宁愿当一只麻雀而不愿当只蜗牛。是的，我宁愿如此。如我宁愿如此·如果我能，我当然愿意。我宁愿像只天鹅般四处悠游。人被地面所束缚着，他是世界上最可怜的生物。我宁愿是-座森林而不愿是一条街。是的，我宁愿如此。如果我能，我当然愿意。我宁愿感受地球在我脚下的感觉。是的，我宁愿如此。如果我能，我当然愿意。本篇歌咏对自由的向往，悲怜人类身陷现代文明的图。歌词简易，却发人深省。"}], "category": "经典英文金曲赏析"}, {"num": 133, "title_en": "Dealing with Exams", "title_zh": "应付考试", "type": "reading", "category": "进阶短文与语法探究", "reading": {"en": ["Examinations are an important part of every student's life. Students must, therefore, know how to deal with them. There are three important things a student must do to get ready for an exam. First, he must work out a study plan. Second, he must always .keep his mind fresh by setting aside some time for exercise. And last but not least, he must review what he has studied at least three times. After all, success can only be achieved through hard work."], "zh": ["考试是每位学生生活中重要的一部分·因此，学生必须知道如何应付考试。学生在准备考试时有三件大事必须做。首先，他必须制定一个学习计划。其次，他必须拨出时间来运动以保持头脑清楚·最后也是相当重要的就是，他必须把念过的书至少复习三遍。毕竟，唯有经由努力才能获致成功。"], "sentences": [{"en": "Examinations are an important part of every student's life.", "zh": "考试是每位学生生活中重要的一部分。"}, {"en": "Students must, therefore, know how to deal with them.", "zh": "因此，学生必须知道如何应付考试。"}, {"en": "There are three important things a student must do to get ready for an exam.", "zh": "学生在准备考试时有三件大事必须做。"}, {"en": "First, he must work out a study plan.", "zh": "首先，他必须制定一个学习计划。"}, {"en": "Second, he must always .keep his mind fresh by setting aside some time for exercise.", "zh": "其次，他必须拨出时间来运动以保持头脑清楚。"}, {"en": "And last but not least, he must review what he has studied at least three times.", "zh": "最后也是相当重要的就是，他必须把念过的书至少复习三遍。"}, {"en": "After all, success can only be achieved through hard work.", "zh": "毕竟，唯有经由努力才能获致成功。"}]}, "dialog": null, "vocab": [{"num": 1, "word": "deal with...", "phonetic": "", "pos": "短语", "meaning": "应付/处理...", "examples": [{"en": "You have to be a very patient teacher to deal with these naughty students.", "zh": "你必须是位很有耐性的老师，才能应付这些顽皮的学生。"}], "sub_entries": ["应付！处理…····"]}, {"num": 2, "word": "examination", "phonetic": "[iɡzamaˈnejan]", "pos": "n.", "meaning": "考试（缩写形为 exam [ɪgˈzæm]）", "examples": [{"en": "I have to take my last final examination at 2:00 p.m.", "zh": "我必须在下午两点钟去参加期末考的最后“一场考试。"}], "sub_entries": ["take an examination 参加考试"]}, {"num": 3, "word": "get ready for + 名词", "phonetic": "", "pos": "短语", "meaning": "为...作准备", "examples": [{"en": "The bride is in her room getting ready for the wedding banquet.", "zh": "·（新娘正在房里准备出席婚宴。"}], "sub_entries": []}, {"num": 4, "word": "work out + 名词", "phonetic": "", "pos": "短语", "meaning": "制定/拟定计划等；算出...", "examples": [{"en": "Have you worked out all the arrangements for your wedding?", "zh": "你已经做好你婚礼的各种安排了吗？"}], "sub_entries": []}, {"num": 5, "word": "study plan", "phonetic": "", "pos": "短语", "meaning": "学习/读书计划", "examples": [], "sub_entries": []}, {"num": 6, "word": "keep one's mind fresh", "phonetic": "", "pos": "短语", "meaning": "保持头脑清楚", "examples": [{"en": "It is important for a pilot to keep his mind fresh when flying a plane.", "zh": "飞行员在开飞机时保持头脑清楚是很重要的"}], "sub_entries": ["fresh[fre]a.清新的"]}, {"num": 7, "word": "set aside...", "phonetic": "", "pos": "短语", "meaning": "留作...之用", "examples": [], "sub_entries": ["留作··之用", "=put aside...", "：You should set aside some time to visit", "your mother this weekend.", "(这个周末你应该拨出一些时间去看看你母亲)"]}, {"num": 8, "word": "least", "phonetic": "[list]", "pos": "adv.", "meaning": "最少地&a.最少的", "examples": [{"en": "Of all the shirts, this one is the least expensive.", "zh": "这些衬衫中，这件是最便宜的。"}], "sub_entries": []}, {"num": 9, "word": "review", "phonetic": "[rrvju]", "pos": "vt.", "meaning": "复习", "examples": [], "sub_entries": [": The teacher reviewed the lessons with the", "students all morning.", "（那位老师一整个早上都在帮学生复习功课。）"]}, {"num": 10, "word": "after all", "phonetic": "", "pos": "短语", "meaning": "毕竟", "examples": [{"en": "Don't be so angry at your mother. After all, she was only trying to help you.", "zh": "别这么生你母亲的气。毕竟，她只是想帮你而已。"}], "sub_entries": []}, {"num": 11, "word": "success", "phonetic": "[sakˈses]", "pos": "n.", "meaning": "成功", "examples": [], "sub_entries": ["succeed[sak'sid ]vi.成功", "succeed in...", "在·…方面获得成功", "W: Everyone loved your speech. You were a", "big success.", "（每个人都很喜欢你的演讲。你真是太成功了)", "Jill succeeded in persuading the boss to give", "her the day off.", "（吉儿成功地说服老板放她一天假。）"]}, {"num": 12, "word": "achieve", "phonetic": "[aˈtiv]", "pos": "vt.", "meaning": "获致，达成", "examples": [{"en": "\"You can achieve nothing if you don't work hard,\"the teacher said.", "zh": "老师说：“你若不努力，就什么也做不成\""}], "sub_entries": []}], "grammar": {"intro": "本课介绍在陈述概念丶想法时，表示“第一点”、“第 二点”等序数词的表示法。 ...First, he must work out a study plan. Second, he must always...And last but not least, he must review. ..After all, success can only be achieved through hard work. （·首先，他必须制定一个学习计划·其次，他必 须…。最后也是相当重要的就是，他必须复习 …··毕竟，唯有经由努力才能获致成功。） a.以上短文中，作者藉由序数词“First”（首先）、 \"Second\"（其次）及\"lastbutnotleast\"（最后也是 相当重要的就是）的引导，条理分明地说出学生应如 何准备考试。并以短语\"Afterall\"（毕竟），引导结 论句\"success can only be achieved through hard work\"。 我们亦可运用上列的序数词轻易地写出下列的文章： There is no shortcut to the mastery of English. What, then, should we do? First,we should buy a good English-Chinese dictionary. Second, we shouldread as manyEnglisharticles as we can. If we run into a word we don't understand, we must consult the dictionaryto find outwhat this word means and how to use it.And last but not least, we must encourage ourselves to speak English whenever possible. After all, Rome wasn't built in a day. However, as long as we are determined, someday we'll all have a good commandofEnglish. （精通英语无捷径。那么我们该怎么做呢？首先，我 们应买-本好的英汉字典。其次，我们应尽量多读 英文文章。我们若看到不懂的单词，必须查字典来 了解这个字的意思及用法。最后也是相当重要的是， 我们必须激励自己尽可能地说英语。毕竟，罗马不 是-天建成的。不过，只要我们有决心，将来我们 都能把英语掌握得很好。） b.下列是常用的序数词及其他表示“起承转合”的用 语，读者宜熟记并多加运用。 首先：first, firstly，to begin with, in the first place 其次：second, secondly,furthermore, moreover, besides, in addition 最后：last，lastly，finally 毕竟：after all 总之：in conclusion, to sum up,in short 最后也是相当重要地：lastbutnotleast 注意： 1）以上用语使用时，之后均置逗号。 nottheleastimportantis+that引导的名词性 从句”简化而成。 例： What is the last but not the least importantis that youshould always remain determined. -> Last but not least, you should always remain determined. （最后也是相当重要地，你必须始终有决心", "items": []}, "substitution": [{"num": 1, "pairs": [{"en": "There are some things you should do before going for a job interview.", "zh": "在去工作面试前有几件事是你必须做的。"}], "en": "There are some things you should do before going for a job interview.", "zh": "在去工作面试前有几件事是你必须做的。"}, {"num": 2, "pairs": [{"en": "First, you should prepare a good resume.", "zh": "首先，你必须准备一份好的履历表。"}, {"en": "Firstly, you should prepare a good resume.", "zh": "首先，你必须准备一份好的履历表。"}, {"en": "To begin with, you should prepare a good resume.", "zh": "首先，你必须准备一份好的履历表。"}, {"en": "In the first place, you should prepare a good resume.", "zh": "首先，你必须准备一份好的履历表。"}], "en": "First, you should prepare a good resume.", "zh": "首先，你必须准备一份好的履历表。"}, {"num": 3, "pairs": [{"en": "Second, you should dress properly.", "zh": "其次，你必须穿着得体。"}, {"en": "Secondly, you should dress properly.", "zh": "其次，你必须穿着得体。"}, {"en": "Furthermore, you should dress properly.", "zh": "此外，你必须穿着得体。"}, {"en": "Moreover, you should dress properly.", "zh": "再者，你必须穿着得体。"}], "en": "Second, you should dress properly.", "zh": "其次，你必须穿着得体。"}, {"num": 4, "pairs": [{"en": "Last, you should think of some questions and answers for the interview.", "zh": "最后，你必须想一些面试会问的问题和答案。"}, {"en": "Lastly, you should think of some questions and answers for the interview.", "zh": "最后，你必须想一些面试会问的问题和答案。"}, {"en": "Finally, you should think of some questions and answers for the interview.", "zh": "最终，你必须想一些面试会问的问题和答案。"}], "en": "Last, you should think of some questions and answers for the interview.", "zh": "最后，你必须想一些面试会问的问题和答案。"}], "exercises": null}, {"num": 134, "title_en": "Guess What?", "title_zh": "你猜怎么了？", "type": "dialogue", "category": "情境实战会话", "reading": null, "dialog": {"turns": [{"speaker_en": "Mack", "speaker_zh": "麦克", "en": "Guess what, Mom?", "zh": "妈，你猜怎么了？"}, {"speaker_en": "Mother", "speaker_zh": "母亲", "en": "What?", "zh": "怎么了？"}, {"speaker_en": "Mack", "speaker_zh": "麦克", "en": "I got through the exams with flying colors.", "zh": "我考试高分过关。"}, {"speaker_en": "Mother", "speaker_zh": "母亲", "en": "Well done, son! I'm really proud of you.", "zh": "儿子，干得好，我真以你为荣。"}]}, "vocab": [{"num": 1, "word": "Guess what, Mom?", "phonetic": "", "pos": "日常口语", "meaning": "妈，你猜怎么了？", "examples": [{"en": "If you don't know the answer to the question, try and guess it.", "zh": "如果你不知道这问题的答案，试着用猜的。）*mom[mam]n.妈妈（mother的通俗用语）dad[ded]n.爸（father 的通俗用语"}], "sub_entries": ["=Can you guess what happened, Mom?", "guess[ges]vt.猜想"]}, {"num": 2, "word": "get through an exam with flying colors", "phonetic": "", "pos": "短语", "meaning": "考试高分过关", "examples": [], "sub_entries": ["=pass an exam with flying colors", "with flying colors", "大为成功", "*此处colors为复数，乃指五颜六色的旌旗。古时作", "战部队打了胜仗凯旋而归时，五颜六色的族旗在空", "中飘扬，故用withflyingcolors表示“大为成", "功”之意。"]}, {"num": 3, "word": "Well", "phonetic": "", "pos": "", "meaning": "done，son！（儿子，干得好！）", "examples": [], "sub_entries": ["\"Well done，son!\" 乃由 \"The job was well done,", "son!”简化而成，用来称赞某人的优良表现。小张昨", "日参加演讲比赛得了第一名，父亲一听心中大喜，便", "说：\"Well done!\"（“干得好!”）"]}], "grammar": null, "substitution": [], "exercises": {"prompt": "Ⅲ.请选出下列各句中正确的一项", "questions": ["1. Kitty has a dog.", ", she also has a cat.", "(A) To sum up", "(B)Firstly", "(C) In addition", "(D) To begin with", "2. After saving up money for two years, Jeff", "bought a car.", "(A) firstly", "(B) finally", "(C) moreover", "(D) in the first place", "3. You did a good job.", ",Betty.", "(A) Well doing", "(B)Well making", "(C) Well done", "(D) Well made", "4.Chris", "got through all his", "exams with flying", "colors. This means he", "(A)did his exams quickly", "(B) didn't pass his exams", "(C) passed only some of his exams", "(D) did well on all of his exams", "5. David wants to be a professional pianist. He", "must,", "_, practice playing the piano every", "day.", "(A) moreover", "(B) therefore", "(C) besides", "(D) in addition"], "answers": ["解答>1.(C）2.(B）3.(C）4.(D）5.(B)"]}}, {"num": 135, "title_en": "Just Do It", "title_zh": "即说即做", "type": "reading", "category": "进阶短文与语法探究", "reading": {"en": ["Many people put off until tomorrow what they can do today. They always look for excuses to postpone doing something. In the end, it never gets done. If we leave things undone, we will eventually worry. This will then cause unnecessary stress. Therefore, if you have this bad habit, it's best to get rid of it and do things as soon as possible."], "zh": ["许多人把今天能做的事推到明日。他们总是找藉口拖延做事·到头来事情总是没做完。我们若没把事情做完，终究还是会操心，而这样会造成不必要的压力。因此，如果你有这种坏习惯的话，最好是戒掉它并且尽快把事情做好。"], "sentences": [{"en": "Many people put off until tomorrow what they can do today.", "zh": "许多人习惯于把今天能完成的事情推拖到明天。"}, {"en": "They always look for excuses to postpone doing something.", "zh": "他们总是在为拖延找各种各样的借口。"}, {"en": "In the end, it never gets done.", "zh": "拖到最后，该做的事情永远也做不好。"}, {"en": "If we leave things undone, we will eventually worry.", "zh": "积压的任务若悬而不决，内心终归会深陷焦虑。"}, {"en": "This will then cause unnecessary stress.", "zh": "这种无谓的拖延只会徒增沉重的精神内耗。"}, {"en": "Therefore, if you have this bad habit, it's best to get rid of it and do things as soon as possible.", "zh": "因此，若有拖延的坏习惯，务必趁早戒除，雷厉风行、即说即做。"}]}, "dialog": null, "vocab": [{"num": 1, "word": "put off...", "phonetic": "", "pos": "短语", "meaning": "拖延...，将...延期", "examples": [{"en": "I can't put off doing this report any longer; it's due tomorrow.", "zh": "我这篇报告不能再拖延，明天就要交了。"}], "sub_entries": ["拖延…··…，将.….·…·延期"]}, {"num": 2, "word": "look for...", "phonetic": "", "pos": "短语", "meaning": "寻找...", "examples": [{"en": "Sally is looking for her house keys.", "zh": "萨莉正在找她房子的钥匙。"}], "sub_entries": ["寻找…·"]}, {"num": 3, "word": "excuse", "phonetic": "[rkˈskjus]", "pos": "n.", "meaning": "藉口，理由", "examples": [{"en": "Stop making excuses. If you don't want to see a movie with me, just say so.", "zh": "别再找藉口了。如果你不想和我去看电影，你就直说好了。"}], "sub_entries": ["make an excuse", "找藉口，编理由"]}, {"num": 4, "word": "postpone", "phonetic": "[postˈpon]", "pos": "vt.", "meaning": "延期，拖延", "examples": [{"en": "The boss is sick, so the company meeting will be postponed till tomorrow.", "zh": "老板生病了，因此公司的会议将延到明天。"}], "sub_entries": []}, {"num": 5, "word": "in the end", "phonetic": "", "pos": "短语", "meaning": "到头来，最后", "examples": [{"en": "In the end, everyone suffered because of the war.", "zh": "到头来，每个人都遭受战争之苦。"}], "sub_entries": ["in the beginning", "起初，最初", "*上列两个短语皆作副词用，使用时通常置句首，后", "加逗号，再接主语及动词。"]}, {"num": 6, "word": "...it is never done.", "phonetic": "", "pos": "口语", "meaning": "永远做不完。", "examples": [], "sub_entries": ["=...it is never done.", "=...it has never been done.", "（…………·事情总是没做完。）", "*此处gets 即等于is，但gets 置于never 之后，is", "则置于never之前。"]}, {"num": 7, "word": "leave... undone", "phonetic": "", "pos": "短语", "meaning": "使...搁置未做", "examples": [{"en": "I cleaned the house but left-the dishes undone.", "zh": "我打扫了屋子但却没有洗碗盘。"}], "sub_entries": ["留下.…·…没做", "undone[An'dan]a.未做完的，未完成的"]}, {"num": 8, "word": "eventually", "phonetic": "[rventual]", "pos": "adv.", "meaning": "最后，终于", "examples": [], "sub_entries": []}, {"num": 9, "word": "worry", "phonetic": "[ˈwɜːri]", "pos": "vi.", "meaning": "担心，操心&vt.使担心，使操心", "examples": [{"en": "Don't worry about Jeff; he'll be alright.", "zh": "别担心杰夫了，他会没事的。"}], "sub_entries": ["worry about...", "担心／操心····", "=be worried about..."]}, {"num": 10, "word": "cause", "phonetic": "[koz]", "pos": "vt.", "meaning": "引起，造成", "examples": [{"en": "A broken engine caused the plane to crash.", "zh": "引擎故障造成那架飞机坠毁。"}], "sub_entries": []}, {"num": 11, "word": "unnecessary", "phonetic": "[ʌnˈnɛsəˌsɛrɪ]", "pos": "", "meaning": "a．不必要的，不需要的", "examples": [{"en": "\"Going on a trip to Hawaii is an unnecessary expense,\" Father told Mother.", "zh": "爸爸告诉妈妈说：“到夏威夷旅游是一笔不必要的花费。”"}], "sub_entries": []}, {"num": 12, "word": "stress", "phonetic": "[stres]", "pos": "n.", "meaning": "压力", "examples": [{"en": "He has been under a lot of stress from work these days.", "zh": "他近来饱受工作压力。"}], "sub_entries": ["under a lot of stress", "饱受压力"]}, {"num": 13, "word": "get rid of...", "phonetic": "", "pos": "短语", "meaning": "摆脱/除掉...", "examples": [{"en": "When are you going to get rid of that old bicycle and buy a new one?", "zh": "你什么时候才要把那辆旧自行车丢掉，另买·辆新的呢？"}], "sub_entries": ["摆脱/除掉.··", "rid[rrd]vt.除去，摆脱", "动词三态皆为rid。", "法，rid为过去分词，但getridof为习惯用法，", "而不用beridof。"]}, {"num": 14, "word": "as soon as possible", "phonetic": "", "pos": "短语", "meaning": "尽快地", "examples": [{"en": "That girl is about as cute as one can be. Roger ran as quickly as he could, but still lost the race.", "zh": "那个女孩可爱极了。）（罗杰尽快地跑，但还是输了比赛。"}], "sub_entries": ["as+形容词/副词+aspossible", "尽可能地…·…", "as+形容词/副词+asonecan"]}], "grammar": {"intro": "本课复习少数以动名词作宾语的用法，并介绍动词leave 作“让”、“任由”的用法。", "items": [{"num": 1, "title": "Many people put off until tomorrow what they can do today.", "body": ["（许多人把今天能做的事推到明日。）本句中，主语为 Many people，putoff 则为短语动 词，视为及物动词，表示“延期”的意思，宾语则为 名词性从句what they can do today（他们今天所 能做的事），untiltomorrow等于tilltomorrow，是 表示时间的介词短语，作副词用，修饰putoff。本 句原本为：", "Many people put off what they can do today 主语 动词 宾语 until tomorrow. 时间副词短语 但句尾today紧接until tomorrow，容易让读者念成 todayuntil tomorrow（今天直到明天），而误将 todayuntil tomorrow视为一短语；产生下列错误的 译文：", "许多人把今天一直到明天能做的事延期了。（×）因此until tomorrow宜置于putoff 及what引导 的从句之间，使untiltomorrow明确修饰putoff。本句源自下列谚语：", "Never put off until tomorrow what you can do today.（今日事，今日毕。)"]}, {"num": 2, "title": "只能接动名词作宾语的及物动词", "body": ["我们曾介绍过少数及物动词只可用动名词作宾语，不得以不定式（即 to + 动词原形）作宾语。此处 postpone 之后接动名词 doing 又是一例。常见的动词如下：", "enjoy（喜欢）、resent（憎恨）、resist（抗拒）、practice（练习）、mind（介意）、suggest（建议）、recommend（建议）、regret（后悔）、anticipate（期望）、deny（否认）、admit（承认）。", "例：The thief admitted stealing the car.（那名窃贼承认偷车。）", "Have you practiced writing your calligraphy recently?（你最近有没有练习书法？）' I anticipate seeing her tomorrow.（我期待明天和她碰面。）When I asked for my teacher's advice, he recommended studying abroad.（当我请教老师意见时，他建议我出国念书。）"]}, {"num": 3, "title": "If we leave things undone, we will eventually worry.", "body": ["（我们若没把事情做完，终究还是会操心。）本句的leave是不完全及物动词，作“任由”或“让”解，undone则是动词do转变而成的过去分 词，作形容词用，表示“未做的”或“未做完的”。undone在本句中作宾语things的补足语。leave 作不完全及物动词时，多以分词或一般形容词 作补足语，句型如下：", "leave+宾语+一般形容词 任由／让···分词", "例： The flood left many people homeless.", "形容词（洪水使得许多人无家可归。）Leave the window open. 形容词（让窗子开着。）The mother left her baby crying. 分词（这位妈妈任由她的婴儿哭着。）Leave the door closed. 分词（让门关着。）注意：", "1）leave之后若以现在分词作宾语补足语，乃表 示主动的概念；若以过去分词作宾语补足语，则表示被动的概念。上列第三例句句尾之所以 使用现在分词crying，乃因该句之宾语her baby主动会哭，故使用crying表示主动的概 念。第四例句句尾之所以使用过去分词closed，乃因宾语thedoor不可能主动关闭，一定是 被人关闭，故使用closed，表示被动的概念。", "2）leave亦表“离开”，可作及物动词或不及物 动词，均可与介词for并用，再接表示场所的 名词。", "例: When will you leave to Shanghai?（×)", "vi", "→ When will you leave for Shanghai?（0)vi.（你什么时候前往上海去？）He left Beijing to Shanghai the day vt. before yesterday. (×)", "→ He left Beijing for Shanghai the vt. day before yesterday. (○)（他前天离开北京往上海去了。）"]}]}, "substitution": [{"num": 1, "pairs": [{"en": "They always look for excuses to postpone doing something.", "zh": "他们总是找籍口拖延做事。"}, {"en": "Steve really enjoys swimming at the city pool.", "zh": "史蒂夫真的很喜欢在市立游泳池游泳。"}, {"en": "Mack suggested writing a letter to the editor of the newspaper.", "zh": "麦克建议写一封信给那份报纸的编辑。"}, {"en": "It is difficult for Willie to resist smoking.", "zh": "威利很难抗拒抽烟。"}], "en": "They always look for excuses to postpone doing something.", "zh": "他们总是找籍口拖延做事。"}, {"num": 2, "pairs": [{"en": "If we leave things undone, we will eventually worry.", "zh": "我们若没把事情做完，终究还是会操心。"}, {"en": "Jack left home when he was eighteen..", "zh": "杰克在18岁时离家。"}, {"en": "Look, you left the TV on again.", "zh": "看，你又让电视开着没关。"}], "en": "If we leave things undone, we will eventually worry.", "zh": "我们若没把事情做完，终究还是会操心。"}], "exercises": null}, {"num": 136, "title_en": "Are You Free?", "title_zh": "你有空吗？", "type": "dialogue", "category": "情境实战会话", "reading": null, "dialog": {"turns": [{"speaker_en": "Dick", "speaker_zh": "狄克", "en": "Hi, Lisa! Are you free this Saturday?", "zh": "嗨，丽莎！这个星期六你有空吗？"}, {"speaker_en": "Lisa", "speaker_zh": "丽莎", "en": "Yes. Why?", "zh": "有啊。干嘛？"}, {"speaker_en": "Dick", "speaker_zh": "狄克", "en": "Would you like to go to a party with me?", "zh": "你想不想和我一起去参加晚会？"}, {"speaker_en": "Lisa", "speaker_zh": "丽莎", "en": "I'd love to, but you have to pick me up at my house.", "zh": "我很想去，但是你必须到我家来接我。"}, {"speaker_en": "Dick", "speaker_zh": "狄克", "en": "Sure. Is eight o'clock alright?", "zh": "当然可以。八点钟好吗？"}, {"speaker_en": "Lisa", "speaker_zh": "丽莎", "en": "That'll be fine.", "zh": "太好了。"}, {"speaker_en": "Dick", "speaker_zh": "狄克", "en": "See you then.", "zh": "到时见。"}]}, "vocab": [{"num": 1, "word": "free", "phonetic": "[friː]", "pos": "a.", "meaning": "有空的", "examples": [{"en": "Are you free now? = Are you available now? = Do you have time now?", "zh": "你现在有空吗？"}], "sub_entries": ["*available [əˈveɪləbl] a. 有空的"]}, {"num": 2, "word": "pick + 人 + up", "phonetic": "", "pos": "短语", "meaning": "接某人", "examples": [{"en": "James picks his wife up from work every day.", "zh": "詹姆士每天都去接他老婆下班。"}], "sub_entries": []}], "grammar": null, "substitution": [], "exercises": {"prompt": "Ⅲ.请选出下列各句中正确的一项", "questions": ["1. Don't", "doing the work until tomorrow.", "(A) wait for", "(B) take off", "(C) call off", "(D) put off", "2. When will you leave", "America?", "(A) to .", "(B) for", "(C) as", "(D) in", "3.The thief denied", "the money.", "(A) to steal", "(B) stealed", "(C) stealing", "(D) that he stealing", "4. He left his girlfriend", "the train station.", "(A) crying in", "(B) cried in", "(C) with crying in", "(D) for crying in", "5.It is not good to", "becausewewill", "begin to worry someday.", "(A) leave things to be not done", "(B)leave things undone", "(C) leave things for not being done", "(D) leave undone things"], "answers": ["解答>1.(D）2.(B）3.(C）4.(A）5.(B)"]}}, {"num": 137, "title_en": "Van Gogh", "title_zh": "梵高", "type": "reading", "category": "进阶短文与语法探究", "reading": {"en": ["It cannot be denied that Van Gogh was a great artist. However, he was considered an outcast by other artists of his time. Many of his most famous paintings were painted at a time when he was isolated by society. Today these paintings are admired as masterpieces, and are sold for large sums of money. Clearly, it was Van Gogh's destiny to be a painter."], "zh": ["不可否认，梵高是位伟大的艺术家。不过，他那个时代的其他艺术家都认为他是个被社会所排斥的人。他许多最有名的画都是在梵高命中注定要做个画家。"], "sentences": [{"en": "It cannot be denied that Van Gogh was a great artist.", "zh": "无可否认，梵高是人类艺术史上一位伟大的巨匠。"}, {"en": "However, he was considered an outcast by other artists of his time.", "zh": "然而在他生活的时代，同侪画家普遍将他视作怪异的边缘人。"}, {"en": "Many of his most famous paintings were painted at a time when he was isolated by society.", "zh": "他诸多最负盛名的传世杰作，恰恰创作于他被世俗社会孤立排斥的幽暗岁月。"}, {"en": "Today these paintings are admired as masterpieces, and are sold for large sums of money.", "zh": "如今这些画布被全世界视为无价珍宝，拍卖出天文数字。"}, {"en": "Clearly, it was Van Gogh's destiny to be a painter.", "zh": "显而易见，以灵魂作画正是梵高命中注定的神圣宿命。"}]}, "dialog": null, "vocab": [{"num": 1, "word": "Van Gogh", "phonetic": "[væn ˈɡoʊ]", "pos": "n.", "meaning": "梵高（1853~1890，荷兰画家）", "examples": [], "sub_entries": []}, {"num": 2, "word": "deny", "phonetic": "", "pos": "vt.", "meaning": "否认", "examples": [{"en": "Don't deny it; we know you broke the window.", "zh": "别否认了，我们知道是你打破窗戶的。"}], "sub_entries": []}, {"num": 3, "word": "artist", "phonetic": "[ˈartist]", "pos": "n.", "meaning": "艺术家", "examples": [], "sub_entries": []}, {"num": 4, "word": "consider", "phonetic": "[kanˈsido]", "pos": "vt.", "meaning": "认为，视为", "examples": [{"en": "I considered you (to be） an honest man, but I was wrong.", "zh": "我认为你是个诚实的人，但我错了。"}], "sub_entries": ["consider A（to be）B", "视A为B"]}, {"num": 5, "word": "outcast", "phonetic": "[ˈaut.kest]", "pos": "n.", "meaning": "被排斥的人", "examples": [], "sub_entries": []}, {"num": 6, "word": "painting", "phonetic": "[ˈpentin]", "pos": "n.", "meaning": "画", "examples": [{"en": "Connie is very good at painting pictures of mountain landscapes.", "zh": "康妮很擅长画山岳的风景。"}], "sub_entries": ["paint[pent ]vt.绘画，画"]}, {"num": 7, "word": "isolate", "phonetic": "[ˈaisa.let]", "pos": "vt.", "meaning": "使孤立，隔离", "examples": [{"en": "Those people have been isolated from society because they're criminals.", "zh": "那些人被与社会隔离，因为他们是罪犯。"}], "sub_entries": ["be isolated from...", "与.……隔离"]}, {"num": 8, "word": "society", "phonetic": "[səˈsaɪəti]", "pos": "n.", "meaning": "社会", "examples": [{"en": "The role of women in society is changing rapidly. We live in a modern society.", "zh": "女性在社会中的角色正快速地转变。）（我们居住在现代化的社会里。"}], "sub_entries": ["society通常为不可数名词，前面不加任何冠词。但若", "前有形容词时，则可在形容词前加冠词a/an。"]}, {"num": 9, "word": "admire", "phonetic": "[adˈmair]", "pos": "vt.", "meaning": "赞赏", "examples": [{"en": "Jessica is admired by her colleagues because she is so successful.", "zh": "杰西卡为她的同事们所赞赏，因她非常地成功"}], "sub_entries": []}, {"num": 10, "word": "masterpiece", "phonetic": "[ˈmasto.pis]", "pos": "n.", "meaning": "杰作", "examples": [], "sub_entries": []}, {"num": 11, "word": "sum", "phonetic": "[sAm]", "pos": "n.", "meaning": "数目，金额", "examples": [{"en": "That country spends a large sum of money on defense.", "zh": "那个国家在国防方面花了-一大笔钱。"}], "sub_entries": ["a large/small sum of...", "巨／小额的…···"]}, {"num": 12, "word": "clearly", "phonetic": "[ˈklɪrli]", "pos": "adv.", "meaning": "显然地，清楚地", "examples": [{"en": "Connie is clearly the smartest girl in the class.", "zh": "康妮显然是那个班上最聪明的女孩。"}], "sub_entries": []}, {"num": 13, "word": "destiny", "phonetic": "[ˈdestani]", "pos": "n.", "meaning": "命运，宿命", "examples": [{"en": "It is that young child's destiny to be king.", "zh": "那个小孩命中注定要当国王。"}], "sub_entries": []}, {"num": 14, "word": "painter", "phonetic": "[ˈpento]", "pos": "n.", "meaning": "画家", "examples": [], "sub_entries": []}], "grammar": {"intro": "本课介绍动词deny、consider的用法，另介绍介词for 表示价格的用法。", "items": [{"num": 1, "title": "deny", "body": ["deny为及物动词，有下列重要用法：", "a. It cannot be denied+that引导的名词性从句 不可否认·…··", "例： It cannot be denied that hard work leads to success.", "=No one can deny that hard work leads to success.", "=There is no denying that hard work leads to success.（不可否认，努力导致成功。）本课阅读部分的第一句即采用此句型：", "It cannot be denied that Van Gogh was a great artist.（不可否认，梵高是位伟大的艺龙家。）Thereis no+动名词", "=It is impossible to+动词原形", "=Noonecan+动词原形 没有人能···", "例：There is no reasoning with such a stubborn man as John.", "=It is impossible to reason with such a stubborn manas John.", "=No one can reason with such a stubborn man as John.（谁都无法与像约翰这样固执的人讲理。）", "b. deny+动名词 否认·.··", "=deny+that引导的名词性从句", "例: He denied to have stolen Mary's money,", "but I knew he was telling a lie. (×)", "→He denied having stolen Mary's money, but I knew he was telling a lie. (○)", "=He denied that he had stolen Mary's money, but I knew he was telling a lie.（他否认偷了玛丽的钱，但我知道他在说谎)"]}, {"num": 2, "title": "consider", "body": ["consider可作完全及物动词，亦可作不完全及物动 词。", "a. consider作完全及物动词时，作“考虑”解，可用 名词、动名词或that引导的名词性从句作宾语。", "例：He has never considered the consequences of being fired.（他从未考虑到被开除的后果。）", "I'll probably consider to study abroad.（×)", "→ I'll probably consider studying abroad.（0)（我可能会考虑出国念书。）We consider that he is too old for this job.(我们考虑到他年龄太大而不适合这份工作)", "b. consider作不完全及物动词时，表示“认为.... 是·…”之意，接宾语之后，另须接名词或形容词 作宾语补足语。用法如下：", "consider+名词/代词+名词或形容词（作宾语补 足语）", "例：We all consider him a hero.（我们都认为他是英雄。）", "She considers John competent.（她认为约翰有能力。）", "注意：", "上列两句亦可采被动语态，句型如下：", "beconsidered+名词或形容词（作主语补足语）故上列两例亦可改写如下：", "He is considered a hero (by all of us). John is considered competent (by her). 下列为本课阅读部分的句子，即采此句型：", "However, he was considered an outcast other artists of his time.", "=However, other artists of his time considered him an outcast.（不过，他那个时代的其他艺龙家都认为他是个被 社会所排斥的人。）"]}, {"num": 3, "title": "介词 for 表示“当作”之意时的搭配", "body": ["介词 for 可表示“当作”之意，之后常接表示金钱或三餐之类的名词。", "例：I bought it with ten dollars.（×）", "-→ I bought it for ten dollars. (○)（这个东西我是十块钱买的。-我买了它当作 块钱的价值。）What can you buy with one dollar? (×)-→ What can you buy for one dollar? (○)（你一块钱能买什么？）下列为本课阅读部分的原句，句中的for即属此用 法：", "Todaythese paintings are admired as masterpieces, and are sold for large sums of money.（今天这些画被赞为杰作，卖价甚高。）What would you like at breakfast? （×）", "→ What would you like for breakfast? ( O）（你早餐想吃什么？·你想吃什么当作早餐？）I had two boiled eggs and some fruit at breakfast.（×）", "→I had twoboiled eggs and some fruit forbreakfast.（O)（我早餐吃了两个水煮蛋和一些水果。）：", "be at breakfast 在吃早餐 lunch 午餐 dinner 晚餐！", "例： I was at lunch when he came.", "=I was having lunch when he came.（我正在吃午饭的时候，他来了。）"]}]}, "substitution": [{"num": 1, "pairs": [{"en": "It cannot be denied that Van Gogh was a great artist.", "zh": "不可否认，梵高是位伟大的艺龙家。"}, {"en": "No one can deny that smoking is bad for your health.", "zh": "不可否认，抽烟对健康不好。"}, {"en": "There's no denying that it is more convenient to live in the city than in the country.", "zh": "不可否认，住在城市比住在乡下方便。"}, {"en": "There is no doubt that computers are more efficient than typewriters.", "zh": "毫无疑问，电子计算机比打字机更有效率。"}], "en": "It cannot be denied that Van Gogh was a great artist.", "zh": "不可否认，梵高是位伟大的艺龙家。"}, {"num": 2, "pairs": [{"en": "Today these paintings are sold for large sums of money.", "zh": "今天这些画卖价甚高。"}, {"en": "Simon wants to lose weight, so he doesn't eat anything for lunch.", "zh": "西蒙想减肥，因此他午餐时什么也没吃。"}, {"en": "I usually have sandwiches for lunch, but rice for dinner.", "zh": "我午餐通常吃三明治，但晚餐则吃米饭。"}], "en": "Today these paintings are sold for large sums of money.", "zh": "今天这些画卖价甚高。"}], "exercises": null}, {"num": 138, "title_en": "You're Beautiful", "title_zh": "你很漂亮", "type": "dialogue", "category": "情境实战会话", "reading": null, "dialog": {"turns": [{"speaker_en": "Eric", "speaker_zh": "埃里克", "en": "May I take your photograph, Jane?", "zh": "简，我可以帮你照张相吗？"}, {"speaker_en": "Jane", "speaker_zh": "简", "en": "Please don't.", "zh": "请不要。"}, {"speaker_en": "Eric", "speaker_zh": "埃里克", "en": "Why not? You're beautiful.", "zh": "为什么不要？你很漂亮啊。"}, {"speaker_en": "Jane", "speaker_zh": "简", "en": "Well, I do not consider myself photogenic.", "zh": "咂，我不认为自己很上相。"}]}, "vocab": [{"num": 1, "word": "take someone's photograph / photo / picture", "phonetic": "", "pos": "短语", "meaning": "take someone's photograph / photo / picture 帮某人拍照", "examples": [{"en": "I took a picture of that model. Don't take my picture before I'm ready.", "zh": "我拍了那模特儿一张照片。）（我没准备好前不要对我拍照。"}], "sub_entries": ["= take a photograph / photo / picture of someone"]}, {"num": 2, "word": "photogenic", "phonetic": "[ˌfoʊtəˈdʒenɪk]", "pos": "a.", "meaning": "上相的，上镜头的", "examples": [{"en": "That model is not only beautiful but photogenic as well.", "zh": "那个模特儿不仅很漂亮，而且还很上相。"}], "sub_entries": []}], "grammar": null, "substitution": [], "exercises": {"prompt": "Ⅲ·请选出下列各句中正确的一项", "questions": ["1.They all consider Bobby a generous man.", "Whichof thesentencesbelowmeans thesame", "as the example sentence?", "(A)Not everyone thinks that Bobby is a", "generous man.", "(B) Bobby is considered a generous man", "by all of us.", "(C) Bobby is considered a generous man", "by all of they.", "(D） Bobby is considered a generous man", "by all of them.", "2. Larry", "George's homework.", "(A) denied to copy", "(B) denied that he had copied", "(C) denied to have copied", "(D) denying that he copied", "3.What did you have", "dinner last night?", "(A) at", "(B)in", "(C) for", "(D) around", "4.", "that Frank is a hard worker.", "(A) No one cannot", "(B) There's no denying", "(C)It cannot deny", "(D） There cannot be denied", "5.Jim", "Jane and I yesterday.", "(A) made a picture of", "(B) made a picture at", "(C) took a picture at", "(D) took a picture of"], "answers": ["解答→1.(D）2.(B）3.(C）4.(B）5.(D)"]}}, {"num": 139, "title_en": "Don't Be Shy", "title_zh": "不要害羞", "type": "reading", "category": "进阶短文与语法探究", "reading": {"en": ["Our English teacher often says that we should not be afraid to make mistakes. She also says that people can learn from their mistakes. Therefore, she tells us that we shouldn't be shy when we speak English. I believe what she says is right, but there is one thing that I don't understand. Every time we speak in class, she tells us to shut up!"], "zh": ["我们的英文老师常说我们应该不要怕犯错。她也说人可以从错误中学习。因此，她告诉我们说英文时不要害羞。我相信她所说的是正确的，但有一件事我不明白。每次我们在课堂上讲话，她就叫我们闭嘴！"], "sentences": [{"en": "Our English teacher often says that we should not be afraid to make mistakes.", "zh": "我们的英文老师常说我们应该不要怕犯错。"}, {"en": "She also says that people can learn from their mistakes.", "zh": "她也说人可以从错误中学习。"}, {"en": "Therefore, she tells us that we shouldn't be shy when we speak English.", "zh": "因此，她告诉我们说英文时不要害羞。"}, {"en": "I believe what she says is right, but there is one thing that I don't understand.", "zh": "我相信她所说的是正确的，但有一件事我不明白。"}, {"en": "Every time we speak in class, she tells us to shut up!", "zh": "每次我们在课堂上讲话，她就叫我们闭嘴！"}]}, "dialog": null, "vocab": [{"num": 1, "word": "shy", "phonetic": "[far]", "pos": "a.", "meaning": "害羞的，怕羞的", "examples": [{"en": "Tommy is afraid to talk to people he doesn't know. He's very shy.", "zh": "汤米很怕和不认识的人说话。他很害羞。"}], "sub_entries": []}, {"num": 2, "word": "be afraid to + 动词原形", "phonetic": "", "pos": "短语", "meaning": "害怕做...，不敢做...", "examples": [{"en": "Lenny is afraid to walk alone at night. Please hurry; I'm afraid that we might miss the train.", "zh": "兰妮很怕晚上单独走动。）（请快一点，我担心我们可能会错过火车。"}], "sub_entries": ["害怕担心····", "beafraid+that引导的状语从句", "害怕／担心····", "afraid[a'fred]a.害怕的，担心的"]}, {"num": 3, "word": "make mistakes", "phonetic": "", "pos": "短语", "meaning": "犯错", "examples": [{"en": "I made a few silly mistakes on my test and, as a result, only got a \"C\".", "zh": "我考试时犯了几个愚蠢的错误。结果，我只得了个\"℃\"。"}], "sub_entries": ["mistake[ma'stek]n.错误"]}, {"num": 4, "word": "right", "phonetic": "[rait]", "pos": "a.", "meaning": "对的，正确的", "examples": [], "sub_entries": []}, {"num": 5, "word": "understand", "phonetic": "[Andaˈstaend]", "pos": "vt.", "meaning": "了解，懂", "examples": [{"en": "What language was he speaking? I didn't understand a word he said.", "zh": "他说的是什么语言？他说的我连-一个字也听不懂。"}], "sub_entries": []}, {"num": 6, "word": "in class", "phonetic": "", "pos": "短语", "meaning": "在课堂上，上课中", "examples": [{"en": "Students are not allowed to eat food in class.", "zh": "学生在课堂上不准吃东西。"}], "sub_entries": []}, {"num": 7, "word": "shut up", "phonetic": "", "pos": "短语", "meaning": "闭嘴，住嘴", "examples": [{"en": "Shut up! You're giving me a headache.", "zh": "闭嘴！你真今我头疼。"}], "sub_entries": ["shut[∫At]vi.&vt.（使）关闭，关"]}], "grammar": {"intro": "本课介绍 say及tell的用法。 say及tell均作及物动词，前者表示“说”的意思，后 者则表示“告诉”或“说”的意思。兹将两者之用法介 绍如下：", "items": [{"num": 1, "title": "say常见的用法如下：", "body": ["a. say+that 引导的名词性从句（that 可省略）", "例：He said (that) he would be late for an hour or two.（他说他会迟到一两个小时。）", "Father often says (that) one should be filial to his parents.（父亲常说做人要孝顺父母。）*filial['filial]a.孝顺的", "b. say+逗号+引号句（句号置于引号之内）", "例：When I asked him where he lived, he", "said: \"I live in Tianjin\".(×)", "→When I asked him where he lived, he said,\"I live in Tianjin.\"(○)（我问他住在哪里时，他说：“我住在天津。”）", "c. say+名词／代词 say作及物动词时，可用名词或代词作宾语，名词 多为words（话），代词则为 something（一些 话）、nothing（没有一句话）。", "例：I have some words to say about the matter.", "=I have something to say about the matter.（对这件事，我有一些话要说。）When I asked him what he thoughtabout the teacher, he said nothing.（当我问他对老师的看法如何时，他没说一句 话。）", "d. 下列为有关 say 之惯用语，读者宜牢记·say hello to+人 向某人打招呼", "例:Carl is friendly. He says hello to everyone he meets.(卡尔很亲切，他向每个他遇到的人打招呼)", "say goodbye to+ 人 向某人道别", "例: I won't see John before he leaves; say goodbye to him for me, please.（我不会在约翰离开前看到他·请代我向他道 别。）", "say prayers 祷告", "例: I say my prayers every night before going to bed.（每晚睡觉前我都会祷告。）"]}, {"num": 2, "title": "tell常见的用法如下：", "body": ["a. tell+人+that 引导的名词性从句（that可省略）", "例: When Father comes back, I'll tell him(that)you've broken the glass.（父亲回来时，我要告诉他你把玻璃杯打破 了。)", "b. tell+人+疑问词（when、what、how whether...）引导的名词性从句", "例：Tell me when he'll be back.（告诉我他什么时候回来。）", "He is willing to tell me how helearned English.（他愿意告诉我他是怎么学英文的。）", "c. tell+人+to+动词原形 叫某人·….·…·", "例： He told me to open all the windows.（他叫我把所有的窗户都打开。）", "d．表示“说故事”、“说谎”、“说实话”时，要 说\"tell a story\"、\"tell a lie\"或\"tell the truth\"。", "例：John is good at saying_stories; no wonder", "all the children here like him.（x)", "→ John is good at telling stories; no wonder all the children here like him.（O)（约翰擅长说故事，难怪这里的孩子都喜欢 他。）He's saying lies again. (×)", "→ He's telling lies again. (○)（他又在说谎了。）You must say the truth, or I'll punish you.（×)", "→You must tell (me)_the truth, or I'll punish you.(○)（你必须（对我）说实话，否则我就处罚你)"]}]}, "substitution": [{"num": 1, "pairs": [{"en": "Our English teacher says that we should not be afraid to make mistakes.", "zh": "我们的英文老师说我们应该不要怕犯错。"}, {"en": "Larry's mother says that he won't be home until late tonight.", "zh": "拉里的母亲说他今晚要很晚才会回家。"}, {"en": "Don't look at me; I have nothing to say.", "zh": "别看我，我没有什么好说的。"}], "en": "Our English teacher says that we should not be afraid to make mistakes.", "zh": "我们的英文老师说我们应该不要怕犯错。"}, {"num": 2, "pairs": [{"en": "Every time we speak in class, she tells us to shut up!", "zh": "每次我们在课堂上讲话，她就叫我们闭嘴！"}, {"en": "My mother told me to apologize to my sister for being mean to her.", "zh": "我母亲叫我去向姐姐道，因我对她很凶。"}, {"en": "Please tell me why you don't want to go to Connie's party.", "zh": "请告诉我为什么你不想去参加康妮的宴会。"}, {"en": "We sat around the campfire telling ghost stories.", "zh": "我们围坐在营火前说鬼故事。"}], "en": "Every time we speak in class, she tells us to shut up!", "zh": "每次我们在课堂上讲话，她就叫我们闭嘴！"}], "exercises": null}, {"num": 140, "title_en": "What's New?", "title_zh": "近况如何？", "type": "dialogue", "category": "情境实战会话", "reading": null, "dialog": {"turns": [{"speaker_en": "Walter", "speaker_zh": "沃尔特", "en": "Hi, Kelly! What's new?", "zh": "嗨，凯利！近况如何？"}, {"speaker_en": "Kelly", "speaker_zh": "凯利", "en": "My father told us that we'll soon be moving.", "zh": "我父亲告诉我们说我们最近要搬家。"}, {"speaker_en": "Walter", "speaker_zh": "沃尔特", "en": "That's awful.", "zh": "那真糟糕。"}, {"speaker_en": "Kelly", "speaker_zh": "凯利", "en": "Uh...why?", "zh": "...·…·为什么？"}, {"speaker_en": "Walter", "speaker_zh": "沃尔特", "en": "I won't have anyone to make fun of anymore.", "zh": "我再也没有可取笑的对象了。"}]}, "vocab": [{"num": 1, "word": "What's new?", "phonetic": "", "pos": "日常口语", "meaning": "近况如何？", "examples": [{"en": "A: What's new, Jerry? B: Oh, nothing much. How are you doing?", "zh": "甲：杰丽，近况如何？）（乙：噢，没什么。你也好吗？"}], "sub_entries": ["= What's up?", "*这是极为通俗的问候语，可别译成“什么是新的？”"]}, {"num": 2, "word": "move", "phonetic": "[muv]", "pos": "vi.", "meaning": "搬家", "examples": [{"en": "Many young people are moving to the city to look for work.", "zh": "许多年轻人搬到大都市去找工作。"}], "sub_entries": []}, {"num": 3, "word": "awful", "phonetic": "[ˈo:ful]", "pos": "a.", "meaning": "糟糕的", "examples": [], "sub_entries": [": I had an awful day today; everything went", "wrong.", "（我今天过得很糟，每件事都不对劲。）"]}, {"num": 4, "word": "make fun of...", "phonetic": "", "pos": "短语", "meaning": "取笑某人", "examples": [{"en": "We must never make fun of the handicapped.", "zh": "我们决不可以取笑残障者。"}], "sub_entries": []}], "grammar": null, "substitution": [], "exercises": {"prompt": "Ⅲ·请选出下列各句中正确的一项", "questions": ["1. Billy", "(A) said \"that he would be late for work today. \"", "(B) said: \"I will be late for work today.\"", "(C) said that he would be late for work today.", "(D) told to me that he would be late for work", "today and tomorrow.", "2.Let's not decide yet. Mike might", "to say", "about it.", "(A) have nothing", "(B) have some sentences", "(C) have some thing", "(D) have something", "3. Can you tell", "use this computer?", "(A) me what to", "(B) me how to", "(C) why to", "(D) they when to", "4.He said he didn't do it, but I", "the truth.", "(A) don't think he's telling", "(B) don't think he says", "(C) think he's telling", "(D) think he's saying", "5.Mike is often", "because he is ugly.", "(A) making fun", "(B) made fun of", "(C) made fun of himself (D) make fun of"], "answers": ["解答>1.(C）2.(D）3.(B）4.(A）5.(B)"]}}, {"num": 141, "title_en": "Global Warming", "title_zh": "全球气温上升", "type": "reading", "category": "进阶短文与语法探究", "reading": {"en": ["Have you noticed that it's getting warmer and warmer every year? To put it simply, that's because of air pollution. Scientists tell us that because of air pollution, the earth's heat cannot escape. This is known as global warming. If this situation is allowed to continue, it will just keep getting hotter and hotter. Then, can you imagine what will happen? We should ail, therefore, do our part to stop polluting the air and help save the world."], "zh": ["你有没有注意到天气一年比一年变得还要暖和了呢？简言之，那是因为空气污染的缘故。科学家告诉我们由于空气污染，地球的热气无法散出去·这就是为人所知的全球变暖。如果我们任由这种情形一直持续下去，地球就会变得越来越热。那么，你能想像会发生什么事吗？因此，我们全都应该尽一已之力来防止污染空气并拯救地球。"], "sentences": [{"en": "Have you noticed that it's getting warmer and warmer every year?", "zh": "你有没有注意到天气一年比一年变得还要暖和了呢？"}, {"en": "To put it simply, that's because of air pollution.", "zh": "简言之，那是因为空气污染的缘故。"}, {"en": "Scientists tell us that because of air pollution, the earth's heat cannot escape.", "zh": "科学家告诉我们由于空气污染，地球的热气无法散出去。"}, {"en": "This is known as global warming.", "zh": "这就是为人所知的全球变暖。"}, {"en": "If this situation is allowed to continue, it will just keep getting hotter and hotter.", "zh": "如果我们任由这种情形一直持续下去，地球就会变得越来越热。"}, {"en": "Then, can you imagine what will happen?", "zh": "那么，你能想像会发生什么事吗？"}, {"en": "We should ail, therefore, do our part to stop polluting the air and help save the world.", "zh": "因此，我们全都应该尽一已之力来防止污染空气并拯救地球。"}]}, "dialog": null, "vocab": [{"num": 1, "word": "notice", "phonetic": "[ˈnotis]", "pos": "vt.", "meaning": "注意，留意", "examples": [{"en": "I've noticed that you've been coming to work early these days.", "zh": "我注意到你最近都很早来上班。"}], "sub_entries": ["notice+that引导的名词性从句"]}, {"num": 2, "word": "warm", "phonetic": "[worm]", "pos": "a.", "meaning": "温暖的", "examples": [{"en": "The old lady wore a fur coat to keep warm.", "zh": "那名老妇人穿了件毛皮大衣来保暖。"}], "sub_entries": []}, {"num": 3, "word": "to put it simply", "phonetic": "", "pos": "短语", "meaning": "简言之", "examples": [{"en": "To put it simply, you're annoying me.", "zh": "简言之，你是在烦我。"}], "sub_entries": ["simply['simpl1]adv.简单地"]}, {"num": 4, "word": "scientist", "phonetic": "[ˈsalantist]", "pos": "n.", "meaning": "科学家", "examples": [], "sub_entries": []}, {"num": 5, "word": "earth", "phonetic": "[ɜːrθ]", "pos": "n.", "meaning": "地球", "examples": [{"en": "The earth is part of the solar system. The whale is the biggest animal on earth.", "zh": "地球是太阳系的一部分。）（鲸鱼是世界上最大的动物。"}], "sub_entries": ["on earth", "世界上", "=in the world"]}, {"num": 6, "word": "heat", "phonetic": "[hit]", "pos": "n.", "meaning": "热（气）", "examples": [{"en": "The heat in this room is making me sleepy.", "zh": "房里的热气使我想睡觉。"}], "sub_entries": []}, {"num": 7, "word": "escape", "phonetic": "[aˈskep]", "pos": "vi.", "meaning": "&vt.逃出，逃避", "examples": [{"en": "The prisoners escaped from prison. The students lied in order to escape punishment.", "zh": "囚犯们逃狱了。）（学生们说谎来逃避惩罚。"}], "sub_entries": []}, {"num": 8, "word": "global warming", "phonetic": "", "pos": "短语", "meaning": "全球气温上升", "examples": [{"en": "Pollution is a global problem.", "zh": "污染是全球性的问题。"}], "sub_entries": ["global['globl]a．全球的，全世界的"]}, {"num": 9, "word": "situation", "phonetic": "[sitfuˈefan]", "pos": "n.", "meaning": "情形，情况（常与介词in", "examples": [{"en": "Ed is in a bad financial situation.", "zh": "艾德的经济状况很不好。"}], "sub_entries": ["并用）"]}, {"num": 10, "word": "continue", "phonetic": "[kanˈtinju]", "pos": "vi.", "meaning": "&vt.继续", "examples": [{"en": "Bob continued talking but no one was listening.", "zh": "鲍勃一直讲个没完，但却没人在听。"}], "sub_entries": []}, {"num": 11, "word": "imagine", "phonetic": "[ɪˈmædʒɪn]", "pos": "vt.", "meaning": "想像，幻想", "examples": [{"en": "The little boy imagined he was in Disneyland.", "zh": "那小男孩幻想自己是在狄斯尼乐园里。"}], "sub_entries": []}, {"num": 12, "word": "happen", "phonetic": "[ˈhapan]", "pos": "vi.", "meaning": "发生", "examples": [{"en": "The accident happened so quickly that I don't know whose fault it was.", "zh": "那件事故突如其来地发生，因此我不知道是谁的错。"}], "sub_entries": ["=occur [k3]"]}, {"num": 13, "word": "pollute", "phonetic": "[pelut]", "pos": "vt.", "meaning": "污染", "examples": [{"en": "People shouldn't pollute the rivers with their garbage.", "zh": "人们不应该用垃圾来污染河流。"}], "sub_entries": []}], "grammar": {"intro": "本课复习一些实用的不定式短语用法，并介绍助动词 can与not并用时应知事项，以及动词allow的用法。", "items": [{"num": 1, "title": "下列为常用的不定式短语：", "body": ["to tell(you） the truth（跟你）说实话", "to be frank (with you)", "坦白（跟你）说(=frankly speaking)to put it simply 简言之 to put it differently 换言之(=in other words)to sum up 总而言之，总的来说 to do+人+justice 为某人说句公道话 以上这些短语使用时通常置于句首，之后置逗号，修 饰全句。", "例：To tell you the truth, he is not the kind of person you can trust.（跟你说实话，他不是那种你可信任的人。）", "To be frank with you, I don't know the answer to the question, either.（坦白跟你说，我也不知道这个问题的答案。）He is ill-tempered, selfish and unwilling to learn anything. To put it simply, he is a good-for-nothing.（他脾气坏、自私、又什么都不肯学。简言之，他是废物一个。）No one is immortal. To put it differently, everyone will die someday.（没有人是长生不老的。换言之，每个人都会有 过世的一天。）To sum up, mastering English is not an overnight job.（总而言之，精通英语不是一而就的事。）To do him justice, he is not as bad as you might think.（帮他说句公道话，他并没有你想的那么坏。）下列为本课阅读部分的原句，本句就使用了\"toput itsimply”的短语：", "To put it simply, that's because of air pollution.（简言之，那是因为空气污染的缘故。）"]}, {"num": 2, "title": "cannot, can't 与 could not, couldn't 的写法与规范", "body": ["can 与 not 并用时，应写成 cannot 或 can't，而非 can not。但 could 与 not 并用时，应写成 could not 或 couldn't，而非 couldnot。can't 或 couldn't 多用于口语中，cannot 或 couldnot 则多用于正式文章中。", "例:I'm sorry, but I can not make any promises", "now.（x）--> I'm sorry, but I cannot (或 can't） make any promises now. (○)（很抱歉，我现在不能作任何的承诺。）I couldnot tell him the truth then. (×)", "→I could not（或couldn't）tellhim the truth then.(○)（我当时不能把真相告诉他。）下列为本课阅读部分的原句，本句就使用了cannot:", "Scientists tell us that because of air pollution, the earth's heat cannot escape.（科学家告诉我们由于空气污染，地球的热气无法散 出去。）"]}, {"num": 3, "title": "allow的用法", "body": ["allow可作及物动词，亦可作不及物动词。", "a. 作及物动词", "allow作“尤许”解，有下列用法：", "1）allow+人或事物+to+动词原形", "例：He won't allow me to try again.（他不会允许我再试一-遍的。）", "The father allowed his daughter to stay out until eight at night.（这位父亲尤许他的女儿晚上在外面待到八 点才回家。）以上两句均可采被动语态（即beallowed to+动词原形）如下：", "例: I won't be allowed to try again.（我将不获准再试一遍。）", "The daughter was allowed to stay out until eight at night.（这个女儿获准晚上可在外面待到八点才回 家。）本课阅读部分的原句即采allow的被动语态：", "If this situation is allowed to continue, it will just keep getting hotter and hotter.", "=If we allow this situation to continue, it will just keep getting hotter and hotter.（如果我们任由这种情形一直持续下去，地球 就会变得越来越热。）", "2）allow+动名词 We don't allow to smoke here.（x）", "→ We don't allow smoking here. (○)", "=Smoking isn't allowed here.（这里禁烟。）", "b. 作不及物动词", "allow与介词for或of并用，分别有下列意思：", "1) allow for... 体谅.…..．考虑.….··", "例：Before you ask him to do it, you should allowfor his situation.（你要求他做这件事之前，应先体谅他的处 境。）", "2) allow of... 容有·…····的余地（通常用于否定句中）", "例： This article is perfect. It allows of no criticism.（那文章完美得不容批评。）"]}]}, "substitution": [{"num": 1, "pairs": [{"en": "To put it simply, that's because of air pollution.", "zh": "简言之，那是因为空气污染的缘故。"}, {"en": "To be frank with you, our idea wasn't accepted by the boss.", "zh": "坦白跟你说，我们的主意没有被老板接受。"}, {"en": "To tell you the truth, I don't think you look good in black.", "zh": "跟你说实话，我认为你穿黑色不好看。"}, {"en": "Frankly speaking, it would be better for you to study history.", "zh": "坦白说，你念历史比较好。"}], "en": "To put it simply, that's because of air pollution.", "zh": "简言之，那是因为空气污染的缘故。"}, {"num": 2, "pairs": [{"en": "If this situation is allowed to continue, it will just keep getting hotter and hotter.", "zh": "如果我们任由这种情形一直持续下去，地球就会变得越来越热。"}, {"en": "He is just a child. You shouldn't allow him to stay up so late.", "zh": "他只是个孩子。你不应该让他熬夜到这么晚。"}, {"en": "My parents never allowed me to watch TV when I was young.", "zh": "小时候我父母从不让我看电视。"}, {"en": "Talking is not allowed in the library.", "zh": "在图书馆里不准讲话。"}], "en": "If this situation is allowed to continue, it will just keep getting hotter and hotter.", "zh": "如果我们任由这种情形一直持续下去，地球就会变得越来越热。"}], "exercises": null}, {"num": 142, "title_en": "No Smoking", "title_zh": "禁止吸烟", "type": "dialogue", "category": "情境实战会话", "reading": null, "dialog": {"turns": [{"speaker_en": "Customer", "speaker_zh": "客", "en": "Can I have an ashtray, please?", "zh": "请给我个烟灰缸好吗？"}, {"speaker_en": "Waitress", "speaker_zh": "女服务员", "en": "I'm sorry, sir. This is a non-smoking section.", "zh": "抱，先生·这里是禁烟区。顾"}, {"speaker_en": "Customer", "speaker_zh": "客", "en": "Where's the smoking section?", "zh": "吸烟区在哪儿？"}, {"speaker_en": "Waitress", "speaker_zh": "女服务员", "en": "Over there. 顾", "zh": "在那边。"}]}, "vocab": [{"num": 1, "word": "customer", "phonetic": "[ˈkʌstəmɚ]", "pos": "n.", "meaning": "顾客", "examples": [], "sub_entries": []}, {"num": 2, "word": "waitress", "phonetic": "[ˈweɪtrɪs]", "pos": "n.", "meaning": "（餐厅、旅馆的）女服务员", "examples": [], "sub_entries": ["waiter [ˈweɪtɚ] n. 男服务员"]}, {"num": 3, "word": "ashtray", "phonetic": "[ˈæʃtreɪ]", "pos": "n.", "meaning": "烟灰缸", "examples": [], "sub_entries": []}, {"num": 4, "word": "non-smoking section", "phonetic": "", "pos": "短语", "meaning": "（公共场所内）禁烟区", "examples": [], "sub_entries": ["smoking section 吸烟区", "section [ˈsɛkʃən] n. 区域"]}], "grammar": null, "substitution": [], "exercises": {"prompt": "Ⅲ·请选出下列各句中正确的一项", "questions": ["1. My mother", "cook, but my father can.", "(A) is a", "(B）", "cannot", "(C) can", "(D) couldnot", "2. Move your car; we", "(A) allow parking here", "(B)don't allow parking here", "(C) not allow parking here", "(D） allow not parking here", "3. 1", "use a computer when I was young, but", "now I can.", "(A) couldnot", "(B) could", "(C) can not", "(D） couldn't", "4. You should", "delays when you are traveling", "by plane.", "(A) allow", "(B) allow for", "(C) allow with", "(D) allow in", "5. Choose the best item:", "thank you for your help over the year.", "(A) To sum up", "(B) To be frank with you", "(C）Frankly speaking (D） To tell the truth"], "answers": ["解答1.(B）2.(B）3.(D）4.(B）5.（A)"]}}, {"num": 143, "title_en": "Man's Best Friend", "title_zh": "人类最好的朋友", "type": "reading", "category": "进阶短文与语法探究", "reading": {"en": ["The dog is man's best friend. He can do many things for us. He can protect our homes. He can guide the blind. He is loyal to his master and never asks for a pay raise. The dog has also made many contributions to English. For example, if there were no dogs, how could a husband tell his wife her cooking tastes like dog food? How could the weatherman say, \"It's raining cats and dogs?\" So the next time a dog lifts a leg to your bicycle, don't kick him. Bend down and say,\"Take your time.\""], "zh": ["狗是人类最好的朋友。它可以为我们做许多事情。它可以保护我们的家。它可以引导盲人。它对主人忠实而且从不要求加薪。狗还对英文有许多的贡献。举例来说，如果没有狗的话，做丈夫的如何告诉他太太她煮的菜吃起来像狗食？气象播报员又如何能用猫和狗来表示雨下得很大呢？因此下次有狗对你的自行车"], "sentences": [{"en": "The dog is man's best friend.", "zh": "狗是人类最好的朋友。"}, {"en": "He can do many things for us.", "zh": "它可以为我们做许多事情。"}, {"en": "He can protect our homes.", "zh": "它可以保护我们的家。"}, {"en": "He can guide the blind.", "zh": "它可以引导盲人。"}, {"en": "He is loyal to his master and never asks for a pay raise.", "zh": "它对主人忠实而且从不要求加薪。"}, {"en": "The dog has also made many contributions to English.", "zh": "狗还对英文有许多的贡献。"}, {"en": "For example, if there were no dogs, how could a husband tell his wife her cooking tastes like dog food?", "zh": "举例来说，如果没有狗的话，做丈夫的如何告诉他太太她煮的菜吃起来像狗食？"}, {"en": "How could the weatherman say, \"It's raining cats and dogs?\" So the next time a dog lifts a leg to your bicycle, don't kick him.", "zh": "气象播报员又如何能用猫和狗来表示雨下得很大呢？"}, {"en": "Bend down and say,\"Take your time.\"", "zh": "因此下次有狗对你的自行车。"}]}, "dialog": null, "vocab": [{"num": 1, "word": "man", "phonetic": "[maen]", "pos": "n.", "meaning": "人类；男人", "examples": [{"en": "Man is mortal. A man came to see you today.", "zh": "人都会死。）（今天有一个人来看你。"}], "sub_entries": []}, {"num": 2, "word": "protect", "phonetic": "[praˈtekt]", "pos": "vt.", "meaning": "保护", "examples": [{"en": "The rich man hired a bodyguard to protect him.", "zh": "那个有钱人雇了一名保镖来保护他。"}], "sub_entries": []}, {"num": 3, "word": "guide", "phonetic": "[ɡard]", "pos": "vt.", "meaning": "引导，指导", "examples": [{"en": "The boy guided the old lady to the post office.", "zh": "那个男孩引导那名老妇人到邮局去。"}], "sub_entries": []}, {"num": 4, "word": "blind", "phonetic": "[blaind]", "pos": "a.", "meaning": "盲的", "examples": [{"en": "The rich should not look down on the poor.", "zh": "富人不应当瞧不起穷人。"}], "sub_entries": ["the blind", "盲人", "=blind people"]}, {"num": 5, "word": "be loyal to...", "phonetic": "", "pos": "短语", "meaning": "对...忠实", "examples": [{"en": "Jack is loyal to his wife.", "zh": "杰克对他老婆很忠实。"}], "sub_entries": ["对………忠实", "loyal[loral]a.忠实的，忠诚的"]}, {"num": 6, "word": "master", "phonetic": "[ˈmesta]", "pos": "n.", "meaning": "主人", "examples": [], "sub_entries": []}, {"num": 7, "word": "ask for...", "phonetic": "", "pos": "短语", "meaning": "要求...", "examples": [{"en": "Dan is too proud to ask for help.", "zh": "丹太骄傲而不肯向他人求助。"}], "sub_entries": ["要求…….·."]}, {"num": 8, "word": "pay raise", "phonetic": "[ˈpe rez]", "pos": "n.", "meaning": "加薪", "examples": [], "sub_entries": []}, {"num": 9, "word": "contribution", "phonetic": "[kantra.bjufan]", "pos": "n.", "meaning": "贡献；捐助", "examples": [{"en": "The rich man made a contribution to the school.", "zh": "那名富翁捐助那所学校。"}], "sub_entries": ["makeacontribution to+事物", "对·….有所贡献；", "捐助··.…."]}, {"num": 10, "word": "husband", "phonetic": "[ˈhAzband]", "pos": "n.", "meaning": "丈夫", "examples": [], "sub_entries": []}, {"num": 11, "word": "wife", "phonetic": "[waif]", "pos": "n.", "meaning": "妻子", "examples": [], "sub_entries": []}, {"num": 12, "word": "cooking", "phonetic": "[ˈkukin]", "pos": "n.", "meaning": "烹饪", "examples": [{"en": "Many men like cooking.", "zh": "有许多男人喜欢烹饪。"}], "sub_entries": []}, {"num": 13, "word": "weatherman", "phonetic": "[ˈweoa.men]", "pos": "n.", "meaning": "气象播报员", "examples": [], "sub_entries": []}, {"num": 14, "word": "It's raining cats and dogs.", "phonetic": "", "pos": "成语", "meaning": "下倾盆大雨。", "examples": [], "sub_entries": ["下倾盆大雨。", "= It's raining heavily.", "= It's pouring.", "*pour[por]vi.倾注；下倾盆大雨", "It's drizzling.", "下毛毛雨。", "* drizzle['drzl]vi.下毛毛雨"]}, {"num": 15, "word": "The", "phonetic": "", "pos": "", "meaning": "next time+主语+动词，主语+动词", "examples": [{"en": "The next time I see John, I'll tell him to stop bothering you.", "zh": "下一次我看到约翰时，我会告诉他不要再来烦你。"}], "sub_entries": []}, {"num": 16, "word": "lift", "phonetic": "[lift]", "pos": "vt.", "meaning": "抬起，举起", "examples": [{"en": "Alice is not strong enough to lift that desk.", "zh": "艾丽斯不够强壮，因此抬不起那张桌子。"}], "sub_entries": []}, {"num": 17, "word": "leg", "phonetic": "[lcɡ]", "pos": "n.", "meaning": "腿", "examples": [], "sub_entries": []}, {"num": 18, "word": "kick", "phonetic": "[kik]", "pos": "vt.", "meaning": "踢", "examples": [{"en": "The silly boy kicked the ball instead of catching it.", "zh": "那笨男孩没有接球反而踢球。"}], "sub_entries": []}, {"num": 19, "word": "bend", "phonetic": "[bend]", "pos": "vi.", "meaning": "弯曲", "examples": [{"en": "This steel ruler won't bend.", "zh": "这支钢制的尺无法弯曲。"}], "sub_entries": ["动词三态：bend，bent, bent o", "bend down", "弯腰"]}], "grammar": {"intro": "本课介绍人称代词、冠词的特定用法，以及the next time作连词的用法。", "items": [{"num": 1, "title": "动物单数人称代词的拟人化用法", "body": ["常态之下，动物的单数人称代词应为 it，但动物亦可拟人化（即将动物视作人物看待），此时可使用代词 he/him 或 she/her。", "例：The dog is man's best friend. He can do many things.（狗是人类最好的朋友。它能做许多事。）", "My pet is a female dog. I named her Spotty. She's really cute.（我的宠物是只母狗。我给它取名为小花。它真可 爱。）"]}, {"num": 2, "title": "定冠词 the 与不定冠词 a/an 的基本区别", "body": ["常态之下，单数可数名词之前须置定冠词 the 或不定冠词 a/an；the 指限定的某个特定事物，相当于中文“这个”或“那个”；a/an 则指非限定的事物，相当于中文“某个”、“一个”。", "例：There is dog there.（×）", "-- There is a dog there. (○)（那里有只狗。）It's old dog. (×)It's an old dog. (○)（那是只老狗。）The dog is old but cute.（那只狗高龄但挺可爱。）但冠有the或 a/an 的单数可数名词亦可泛指同一类 全体的人或事物。", "例: The clog is man's best friend.", "=A dog is man's best friend.", "=Dogs are man's best friends.（狗是人类最好的朋友。）", "比较: The dogs are raised by John.（这些狗是约翰养的。）又例: The rich man is not necessarily happy.", "=A rich man is not necessarily happy.", "= Rich people are not necessarily happy.", "=The rich are not necessarily happy.（有钱人未必就快乐。）", "比较：The rich people are John's relatives.（这些有钱人是约翰的亲戚。）", "注意：", "现代美语中习惯用the取代 a/an来表示泛指同一类 全体的人或事物。", "例：The pen is mightier than the sword.（笔的力量要大于剑一文胜于武。—谚语）", "*mightier为形容词mighty的比较级。mighty['maiti]a.强大的，有力的"]}, {"num": 3, "title": "for example（举例来说）的用法与标点", "body": ["for example 表示“举例来说”，等于 for instance，均为介词短语，具有副词功能，通常置于前一个完整句子之后，并用逗号隔开。", "例：He has many hobbies. For example, he enjoys swimming and collecting stamps.", "He has many hobbies; for example, he enjoys swimming and collecting stamps.（他有许多爱好。譬如，他喜欢游泳和集邮。）"]}, {"num": 4, "title": "the next time 作连词引导时间状语从句", "body": ["the next time 可作连词，表示“下次...的时候”，引导时间状语从句修饰主句。the next time 亦可简化为 next time。", "例：The next time he comes, tell him plainly that I don't like him.", "=Next time he comes, tell him plainly that I don't like him.（下次他来的时候，坦白地告诉他我不喜欢他。）本课阅读部分的 the next time即属此用法。So the next time a dog lifts a leg to your bicycle, don't kick him.", "=So next time a dog lifts a leg to your bicycle, don't kick him.（因此下次有狗对你的自行车抬腿撒尿时，可别踢 它。）"]}]}, "substitution": [{"num": 1, "pairs": [{"en": "The dog is man's best friend.", "zh": "狗是人类最好的朋友。"}, {"en": "A dog is a loyal and obedient animal.", "zh": "狗是忠诚和服从的动物。"}, {"en": "A kind man gives money to charity.", "zh": "好心人会将钱捐给慈善机构。"}], "en": "The dog is man's best friend.", "zh": "狗是人类最好的朋友。"}, {"num": 2, "pairs": [{"en": "So the next time a dog lifts a leg to your bicycle, don't kick him.", "zh": "下次有狗对你的自行车抬腿撒尿时，可别踢它。"}, {"en": "Next time you see·your brother, tell him I said, \"Hello.\"", "zh": "下次你看到你哥哥时，请告诉他我向他问好。"}, {"en": "The next time you eat at that restaurant, you should try the lobster.", "zh": "下次你在那家餐厅用餐时，你应该试一下龙虾。"}, {"en": "Next time you give a speech, you ought to speak louder.", "zh": "下次你再演讲时，你应当说大声一点。"}], "en": "So the next time a dog lifts a leg to your bicycle, don't kick him.", "zh": "下次有狗对你的自行车抬腿撒尿时，可别踢它。"}], "exercises": null}, {"num": 144, "title_en": "The Year of the Dog", "title_zh": "狗年", "type": "dialogue", "category": "情境实战会话", "reading": null, "dialog": {"turns": [{"speaker_en": "Tracy", "speaker_zh": "特蕾西", "en": "When were you born?", "zh": "你何时出生的？"}, {"speaker_en": "Ivan", "speaker_zh": "伊凡", "en": "In the Year of the Dog.", "zh": "狗年出生的。"}, {"speaker_en": "Tracy", "speaker_zh": "特蕾西", "en": "What does that mean?", "zh": "那是什么意思？"}, {"speaker_en": "Ivan", "speaker_zh": "伊凡", "en": "Oh. That's one of the twelve Chinese horoscope animals. I was born in 1970.", "zh": "哦。那是中国的十二生肖之-。我出生于1970年。"}, {"speaker_en": "Tracy", "speaker_zh": "特蕾西", "en": "That's interesting. I was born in 1971. What animal am I?", "zh": "真有趣。我出生于197]年。我属于什么生肖？"}, {"speaker_en": "Ivan", "speaker_zh": "伊凡", "en": "You're a pig!", "zh": "你属猪！"}]}, "vocab": [{"num": 1, "word": "When were you born?", "phonetic": "", "pos": "日常口语", "meaning": "你何时出生的？", "examples": [{"en": "Although Jill is bearing a child, she still went swimming. Sallybore a childwhen she wasonly sixteen.", "zh": "虽然吉儿怀了小孩，她还是去游泳。）（萨莉在16岁时就生了一个小孩。"}, {"en": "The woman has borne five children in all.", "zh": "这名妇女共生了五个孩子。）2） be borne+by +人被某人所生"}, {"en": "They say the boy was borne by Mary, not Jane.", "zh": "据说这男孩是玛丽所生，而非简所生。）b.born则用于beborn 的形态中，之后除不得与介词by并用外，可与任何介词并用。"}, {"en": "He was born in Nanjing. He was born into a poor family. He was born of a poor couple. He was born on May 1, 1990.", "zh": "他是在南京出生的。）（他出生寒门。）（他是…-对穷苦的夫妇所生的。）（他是1990年5月1日出生的。"}], "sub_entries": ["此处的born是bear的过去分词。", "bear [ber ] vt.生", "动词三态：bear, bore,borne/born o"]}, {"num": 2, "word": "the twelve Chinese horoscope animals", "phonetic": "", "pos": "短语", "meaning": "中国的十二生肖", "examples": [], "sub_entries": ["horoscope['hora.skop]n.占星术"]}], "grammar": null, "substitution": [], "exercises": {"prompt": "Ⅲ·请选出下列各句中正确的一项", "questions": ["1. Look at", "over there. It's beautiful.", "(A) that bird (B) a bird (C) bird (D) birds", "2.Connie thinks that", "are disgusting animals.", "(A) a cats", "(B) cats", "(C) the cat (D) a cat", "3.Chris was", "New York, but grew up in Los", "Angeles.", "(A) borne in", "(B) born", "(C) borne on", "(D) born in", "4.Scott loves outdoor", "he often cycles, jogs,", "and swims.", "(A) activities, for example,", "(B) activities; For example,", "(C) activities; for example,", "(D) activity, for example,", "5. My mother has", "and raised ten children.", "(A)borne", "(B)born", "(C) bornes(", "(D) borns"], "answers": ["解答>1.(A）2.(B）3.(D）4.(C）5.(A)"]}}, {"num": 145, "title_en": "Billy's Goal in Life", "title_zh": "比利的人生目标", "type": "reading", "category": "进阶短文与语法探究", "reading": {"en": ["Some people have goals in life. For these people it is important to achieve their goals. As for my brother Billy, his goal in life is to make people happy. He tries to accomplish this by being a good student and an obedient son. In this way, he is able to give joy to those who are dearest to him-his teachers and his family. It's too bad we don't all have goals like Billy."], "zh": ["有些人的人生有目标。对这些人来说，达到他们的目标是很重要的。至于我哥哥比利，他人生的目标是让别人快乐。他设法以做一名好学生和乖儿子来完成这个目标。这样一来，他就能将快乐给予跟他最亲的人一也就是他的老师和家人。令人遗憾的是，并不是所有的人都像比利一样有人生目标。"], "sentences": [{"en": "Some people have goals in life.", "zh": "有些人的人生有目标。"}, {"en": "For these people it is important to achieve their goals.", "zh": "对这些人来说，达到他们的目标是很重要的。"}, {"en": "As for my brother Billy, his goal in life is to make people happy.", "zh": "至于我哥哥比利，他人生的目标是让别人快乐。"}, {"en": "He tries to accomplish this by being a good student and an obedient son.", "zh": "他设法以做一名好学生和乖儿子来完成这个目标。"}, {"en": "In this way, he is able to give joy to those who are dearest to him-his teachers and his family.", "zh": "这样一来，他就能将快乐给予跟他最亲的人一也就是他的老师和家人。"}, {"en": "It's too bad we don't all have goals like Billy.", "zh": "令人遗憾的是，并不是所有的人都像比利一样有人生目标。"}]}, "dialog": null, "vocab": [{"num": 1, "word": "goal", "phonetic": "[ɡol]", "pos": "n.", "meaning": "目标", "examples": [], "sub_entries": []}, {"num": 2, "word": "achieve", "phonetic": "[aˈtiv]", "pos": "vt.", "meaning": "达到（目的），完成", "examples": [{"en": "Beth achieved her goal of becoming a teacher.", "zh": "贝思达到当老师的目标。"}], "sub_entries": ["achieve one's goal", "达到某人的目标", "=attain one's goal", "*attain[a'ten]vt.达到"]}, {"num": 3, "word": "accomplish", "phonetic": "[aˈkampljf]", "pos": "vt.", "meaning": "达到，完成（任务等）", "examples": [{"en": "The boyscout accomplished the task without any difficulty.", "zh": "那位童子军毫无困难地完成了任务。"}], "sub_entries": []}, {"num": 4, "word": "obedient", "phonetic": "[aˈbidiant]", "pos": "a.", "meaning": "服从的", "examples": [{"en": "Students should be obedient to their teachers. You must train your dog to obey you.", "zh": "学生应该要服从老师。）（你应该训练你的狗服从你。"}], "sub_entries": ["obey[a'be]vt.服从", "be obedient to...", "服从／顺从····"]}, {"num": 5, "word": "In this way...", "phonetic": "", "pos": "短语", "meaning": "这样一来，以这种方式...", "examples": [{"en": "Peter worked day and night. In this way, he became very successful.", "zh": "彼得日以继夜地工作。这样一来，他变得很成功。"}], "sub_entries": []}, {"num": 6, "word": "joy", "phonetic": "[dʒɔɪ]", "pos": "n.", "meaning": "快乐，欢乐", "examples": [{"en": "Our cute pet dog gives joy to the whole family. My graduation was a joyful occasion.", "zh": "我们可爱的宠物狗给我们全家带来欢乐。）（我的毕业典礼是很欢乐的场合。"}], "sub_entries": ["joyful['d3oifal]a.快乐的，欢乐的", "give joy to+人", "给人带来欢乐"]}, {"num": 7, "word": "dear", "phonetic": "[dir]", "pos": "a.", "meaning": "亲爱的，心爱的", "examples": [{"en": "This watch which my wife gave me is very dear to me.", "zh": "我太太给我的这只手表是我的心爱宝贝。"}], "sub_entries": ["*dearest['dirist]为 dear 的最高级。", "be dear to+人", "·…是某人亲爱的／心爱的宝贝"]}, {"num": 8, "word": "It's too bad that + 从句", "phonetic": "", "pos": "句型", "meaning": "可惜/遗憾的是...", "examples": [{"en": "It's too bad (that)you can't get along with Bert.", "zh": "你无法与伯特好好相处，真是遗憾。"}], "sub_entries": ["可惜的是.，遗憾的是.…", "*此处that可予以省略。"]}], "grammar": {"intro": "本课介绍way（方法）并续谈\"beable to\"（能够）及 it代替名词性从句的用法。", "items": [{"num": 1, "title": "way的用法", "body": ["In this way, he is able to give joy to those who are dearest to him -—his teachers and his family.（这样的话，他就能将快乐给予跟他最亲的人一—也 就是他的老师和家人。）", "a. way可作“方法”或“态度、样子”解，皆与介词 in并用。", "例：You should do it in my way.（你应当用我的方法来做这件事。）", "In this way, you can achieve your goal much faster.（这样一-来，你可以更快达到你的目标。）I don't like the way in which he looks at me.（我不喜欢他看我的那个样子。）You shouldn't talk to your parents in such a way.（你不应当以这样的态度对你父母说话。）b．way 之前若有指示形容词如 this、that，或所有格 代词如 my、your、her、his等，之前的介词 in可予省略。但way之前若有不定冠词a/an 时，之前的in则不可省略。", "例：You should do it in my way.", "= You should do it my way.（你应当用我的方法来做这件事。）", "In this way, you can achieve your goal much faster.", "=This way, you can achieve your goal much faster.（这样-来，你可以更快达到你的目标。）He did it an easy way. (×)", "→ He did it in an easy way. (○)（他用很简单的方法做这件事。）同理，本课阅读部分的原文：", "In this way, he is able to give joy to those whoare dearest to him teachers and his family.", "=This way, he is able to give joy to those who are...", "注意：", "in one's way（以某人的方法）习惯上置于句尾，修饰句中动词，in可予省略，但置于句首时，则不 可省略in。in this/that way可置于句首或句尾，均可省略in。", "例：If you can do it in my way, you'll be as successful as I am.", "=If you can do it my way, you'll be as successful as I am.（你若以我的方式来做这件事，就会和我-样 成功。）My way, you'll easily achieve success.（×）> In this way, you'll easily achieve success.（o)", "=This way, you'll easily achieve success.（这样的话，你会很容易获致成功。）You'll make few mistakes if you do it in that way.", "=You'll make few mistakes if you do it that way.（如果你以那种方法做这件事，犯的错就会很 少。）", "c. the way之后可用\"in+关系代词which”引导定 语从句，修饰way。", "例：That's the way in which I deal with .such problems.（那就是我处理这类问题的方式。）", "I don't like the way in which he looks at me.（我不喜欢他看我的那个样子。）", "注意：", "way之后的in which 可用that 取代，故上例可 改写为：", "That's the way that I deal with such problems. I don't like the way that he looks at me. 然而 that亦可予省略，形成下列更常见、更实用 的句子：", "That's the way I deal with such problems.", "I don't like the way he looks at me.", "d. way亦可表示“路途”的意思，形成下列重要的短 语：", "1) on one's way to+地方名词 地方副词（如home、there here)在某人往...··的途中 此短语可置于be动词之后，作主语补足语；但亦可置于句尾或句首，修饰一般动词。", "例: Peter: Where are you going, John?", "John: I'm on my way home. (home 是 地方副词，之前不置to)（彼得：约翰，你要去哪儿呀？）（约翰：我正往回家的路上。）On my way to school, I ran into a friend of mine.", "=I ran into a friend of mine on my way to school.（school是地方名词，之 前应置to)（我上学途中遇到一位朋友。）", "2) in one's way 挡某人的路", "例： Don't stand in my way, John.（约翰；别挡我的路。）"]}, {"num": 2, "title": "续谈beableto的用法", "body": ["...he is able to give joy to those who are dearest to him -- his teachers and his family.", "=...he can give joy to those who are dearest to him-his teachers and his family.（...…。他就能将快乐给予跟他最亲的人一 也就是他 的老师和家人。）此处我们特别指出中国人使用 able 时常犯的两个毛 病。", "a. 无\"canbeableto\"的用法。", "例：He can be able tohandle the problem", "alone.（x)（他能够独立处理这个问题。）改正：", "He can handle the problem alone. (○)", "=He is able to handle the problem alone.", "=He is capable of handling the problem alone.（他能够独立处理这个问题。）", "b. 无\"make+人+able to\"的用法。", "例：His timely help made me able to solve", "the problem.（×)（他适时的帮助使我能够解决这个问题。）理由", "1）make作“使·….….”解时，为不完全及物动词，之后可置宾语，并以形容词或名词作宾语补足 语，如：", "He made me happy.", "a.（他使我快乐。）", "He has made me a good boy.", "n.（他使我成为好孩子。）", "2）按1)项的解说，下列例子，able为形容词，作宾语me之补足语，应无错误：", "His timely help made me able to solve", "a. the problem.(×)但英语表示“使….…·能够”另有动词enable 一字，用法如下：", "enable+人+to+动词原形", "例：His timely help enabled me to solve", "the problem.（O)（他适时的帮助使我能够解决这个问题。）故无下列用法：", "His timely help made me able to solve the problem. (×)"]}, {"num": 3, "title": "形式主语 it 代替 that 引导的名词性从句", "body": ["it 可代替 that 引导的名词性从句，在句中作形式主语；此时，that 常常可以省略。", "例：It's too bad that we don't all have goals like Billy.", "=It's too bad we don''t all have goals like", "Billy.", "=It's a pity that we don't...", "=It's a pity we don't...（令人遗憾的是，并不是所有的人都像比利一样有 人生目标。）*此处toobad作“令人遗憾”解，不可译成“太 坏的”。", "例： A: John didn't pass the test.", "B: That's too bad.（甲：约翰考试没及格。）（乙：真遗憾。）"]}]}, "substitution": [{"num": 1, "pairs": [{"en": "In this way, he is able to give joy to those who aredearest to him.", "zh": "这样的话，他就能将快乐给予跟他最亲的人。"}, {"en": "This way, you will be able to finish much faster.", "zh": "这样的话，你将能够完成得快多了。"}, {"en": "Why do you always like to do things the hard way?", "zh": "你为何老是喜欢用困难的方法来做事呢？"}], "en": "In this way, he is able to give joy to those who aredearest to him.", "zh": "这样的话，他就能将快乐给予跟他最亲的人。"}, {"num": 2, "pairs": [{"en": "In this way, he is able to give joy to those who are dearest to him.", "zh": "这样的话，他就能将快乐给予跟他最亲的人。"}, {"en": "He is not capable of being a manager.", "zh": "他无法胜任经理的职务。"}, {"en": "Dennis can speak seven different languages.", "zh": "丹妮斯能够说七种不同语言。"}, {"en": "Bob's help enabled me to finish early.", "zh": "鲍勃的帮忙使我能够提前完成。"}], "en": "In this way, he is able to give joy to those who are dearest to him.", "zh": "这样的话，他就能将快乐给予跟他最亲的人。"}], "exercises": null}, {"num": 146, "title_en": "Being Happy", "title_zh": "快乐", "type": "dialogue", "category": "情境实战会话", "reading": null, "dialog": {"turns": [{"speaker_en": "Bill", "speaker_zh": "比尔", "en": "What's your goal in life, Kathy?", "zh": "凯茜，你的人生目标是什么？"}, {"speaker_en": "Kathy", "speaker_zh": "凯茜", "en": "My goal is to be rich. What about you?", "zh": "我的目标就是要有钱。你的目标呢？"}, {"speaker_en": "Bill", "speaker_zh": "比尔", "en": "I just want to be happy.", "zh": "我只想要快乐。"}, {"speaker_en": "Kathy", "speaker_zh": "凯茜", "en": "What?", "zh": "什么？"}, {"speaker_en": "Bill", "speaker_zh": "比尔", "en": "I think being happy is more important than having all the money in the world.", "zh": "我认为快乐要比拥有世上所有的钱来得重要。"}]}, "vocab": [{"num": 1, "word": "My goal is to be rich.", "phonetic": "", "pos": "口语", "meaning": "我的目标就是要有钱。", "examples": [{"en": "My dream is being a doctor. (×) -→ My dream is to be a doctor. (○) My purpose is simply saying goodbye to you. > My purpose is simply to say goodbye to you.", "zh": "我的理想就是要当医生。）（×)（o)（我的目的就是要向你辞行。"}], "sub_entries": ["（我的目标就是要有钱。）", "名词如 goal（目标）、plan（计划）丶purpose（目", "的）、dream（梦想、理想）、intention（意图）、", "wish（愿望）等，均表示一种未完成或想要完成的愿", "望、企图·故此类名词作主语，之后有be动词时，", "不可接动名词作补足语，而应接to引导的不定式短", "语，以表示此类未完成的愿望或企图。"]}, {"num": 2, "word": "I think being happy is more important than", "phonetic": "", "pos": "短语", "meaning": "我认为快乐要比拥有世上所有的钱来得重要。", "examples": [], "sub_entries": ["having all the money in the world.", "=I think that being happy is more important...", "本句乃由that引导的名词性从句作及物动词think", "的宾语，原句省略了that。", "在该从句中，作者以being happy作主语，与than", "之后的主语having all the money in the world 相", "互呼应，均为动名词短语。但不定式短语亦可作主语，", "故本句亦可改为如下：", "I think (that) to be happy is more important", "than to have all the money in the world ."]}], "grammar": null, "substitution": [], "exercises": {"prompt": "Ⅲ.请选出下列各句中正确的一项", "questions": ["1.My timely help", "find a good job.", "(A) made him able to", "(B) enabled him", "(C) made him capable of (D) enabled him to", "2.I saw Billy this morning", "to the library.", "(A) on way", "(B)my way", "(C) on that way", "(D) on my way", "3. That's the way George treats his children. This", "means", "(A) that's in the way George treats his children", "(B) that's the way in which George treats his", "children", "(C) that's way George treats his children", "(D) George's children are that way", "4. I'm the boss, so you will do it", "(A) in which way", "(B) my way", "(C) an easy way", "(D) in a way", "5. Frank's goal in life is", "(A) a lawyer", "(B)be a lawyer", "(C) to be a lawyer", "(D) to make lawyer", "6. I feel", "is more important than to be", "rich.", "(A) to be healthful", "(B)that being healthful", "(C) that to be healthy", "(D) being healthy"], "answers": ["解答1.(D）2.(D）3.(B）4.(B）5.(C）6.(C)"]}}, {"num": 147, "title_en": "Television Addiction", "title_zh": "电视迷", "type": "reading", "category": "进阶短文与语法探究", "reading": {"en": ["Television provides us with a wide range of information and entertainment. However, it's a pity that it may also have a bad influence on young minds. For instance, some TV shows have too much violence and crime. These programs may lead youngsters astray. It is easy for students to become addicted to the excitement of these programs and neglect their homework. Parents must, therefore, keep an eye on what their children watch."], "zh": ["电视给我们提供广泛的信息和娱乐。不过，遗憾的是，它也会对年轻人的思想有不良的影响。举例来说，有些电视节目有太多的暴力和犯罪·这样的节目可能使年轻人误人歧途。学生很容易沉溺于这些刺激的节目中而忽视了他们的功课。因此，父母们应该留意孩子所看的电视节目。"], "sentences": [{"en": "Television provides us with a wide range of information and entertainment.", "zh": "电视给我们提供广泛的信息和娱乐。"}, {"en": "However, it's a pity that it may also have a bad influence on young minds.", "zh": "不过，遗憾的是，它也会对年轻人的思想有不良的影响。"}, {"en": "For instance, some TV shows have too much violence and crime.", "zh": "举例来说，有些电视节目有太多的暴力和犯罪。"}, {"en": "These programs may lead youngsters astray.", "zh": "这样的节目可能使年轻人误人歧途。"}, {"en": "It is easy for students to become addicted to the excitement of these programs and neglect their homework.", "zh": "学生很容易沉溺于这些刺激的节目中而忽视了他们的功课。"}, {"en": "Parents must, therefore, keep an eye on what their children watch.", "zh": "因此，父母们应该留意孩子所看的电视节目。"}]}, "dialog": null, "vocab": [{"num": 1, "word": "addiction", "phonetic": "[aˈdikjan]", "pos": "n.", "meaning": "沉溺，上瘾", "examples": [], "sub_entries": []}, {"num": 2, "word": "provide", "phonetic": "[praˈvaid]", "pos": "vt.", "meaning": "提供", "examples": [{"en": "The rich man provided food for the orphanage.", "zh": "那位有钱人提供食物给那所孤儿院。"}], "sub_entries": ["provide+人+with+物", "提供某人某物", "=provide+物+for+人"]}, {"num": 3, "word": "a wide range of...", "phonetic": "", "pos": "短语", "meaning": "广泛的...", "examples": [{"en": "There's a wide range of baseball bats at that sporting goods store.", "zh": "那家体育用品店有各式各样的球棒。"}], "sub_entries": ["广泛的….··", "wide[waid ]a.广泛的", "range[rend3]n.范围"]}, {"num": 4, "word": "information", "phonetic": "[ˌɪnfərˈmeɪʃən]", "pos": "n.", "meaning": "信息（不可数）", "examples": [], "sub_entries": []}, {"num": 5, "word": "entertainment", "phonetic": "[εntaˈtenmant]", "pos": "n.", "meaning": "娱乐", "examples": [{"en": "To entertain his guests, Gary played the piano.", "zh": "加里弹钢琴来娱乐他的客人。"}], "sub_entries": ["entertain[snta'ten]vt.使娱乐，招待"]}, {"num": 6, "word": "It's a pity that + 从句", "phonetic": "", "pos": "句型", "meaning": "遗憾的是...", "examples": [{"en": "It's a pity that we don't have enough money to buy that beautiful house.", "zh": "遗憾的是，我们没有足够的钱来买那幢漂亮的房子。"}], "sub_entries": ["=It's toobad+that引|导的名词性从句", "遗憾的是…···", "pity['pitu]n.遗憾"]}, {"num": 7, "word": "influence", "phonetic": "[ˈinfluans]", "pos": "n.", "meaning": "影响", "examples": [], "sub_entries": []}, {"num": 8, "word": "mind", "phonetic": "[maind]", "pos": "n.", "meaning": "思想", "examples": [{"en": "What's on your mind? = What's bothering you? .", "zh": "你心里有什么事在烦着？"}], "sub_entries": []}, {"num": 9, "word": "show", "phonetic": "[fo]", "pos": "n.", "meaning": "节目", "examples": [{"en": "My mother likes to watch TV game shows.", "zh": "我母亲喜欢看电视上的游戏节目。"}], "sub_entries": []}, {"num": 10, "word": "violence", "phonetic": "[ˈvaralans]", "pos": "n.", "meaning": "暴力（不可数）", "examples": [{"en": "There's too much street violence in the States. When Ken gets drunk, he becomes violent.", "zh": "在美国有太多的街头暴力。）（肯喝醉时，就会变得狂暴。"}], "sub_entries": ["violent{'varalant]a.暴力的；猛烈的"]}, {"num": 11, "word": "crime", "phonetic": "[kraim]", "pos": "n.", "meaning": "罪（行）（可数、不可数皆可）", "examples": [{"en": "Your reputation will be ruined if you commit a crime.", "zh": "如果你犯罪的话，你的名声就毁了。"}], "sub_entries": ["commit a crime", "犯罪", "*commit[ka'mit]vt.犯，作"]}, {"num": 12, "word": "program", "phonetic": "[ˈproɡram]", "pos": "n.", "meaning": "节目", "examples": [{"en": "There is an interesting program on TV tonight.", "zh": "今晚有一个很有趣的电视节目。"}], "sub_entries": []}, {"num": 13, "word": "lead + 人 + astray", "phonetic": "", "pos": "短语", "meaning": "引诱某人误入歧途", "examples": [{"en": "If you associate with gangsters, they will lead you astray. My pet dog went astray in the park and got lost.", "zh": "如果你与帮派为伍的话，他们就会使你误人歧途。）（我的爱犬在公园里迷路而走失了。"}], "sub_entries": ["使某人误人歧途", "go astray", "误人歧途；迷路", "astray[a'stre]adv.迷途地，误人歧途地"]}, {"num": 14, "word": "youngster", "phonetic": "[jaɡsto]", "pos": "n.", "meaning": "年轻人", "examples": [], "sub_entries": []}, {"num": 15, "word": "addict", "phonetic": "[aˈdikt]", "pos": "vt.", "meaning": "沉溺；使上瘾", "examples": [{"en": "My friend, Paul, is addicted to smoking.", "zh": "我的朋友保罗抽烟上瘾了。"}], "sub_entries": ["beaddictedto+名词/动名词", "沉溺于·…·；·有…···的瘾"]}, {"num": 16, "word": "excitement", "phonetic": "[ɪkˈsaɪtmənt]", "pos": "n.", "meaning": "刺激", "examples": [], "sub_entries": []}, {"num": 17, "word": "neglect", "phonetic": "[nrˈɡlekt]", "pos": "vt.", "meaning": "忽视，疏忽", "examples": [{"en": "A soldier must never neglect his duty.", "zh": "军人绝不可以疏忽职守。"}], "sub_entries": []}, {"num": 18, "word": "homework", "phonetic": "[ˈhoʊmwɜːrk]", "pos": "n.", "meaning": "家庭作业（不可数）", "examples": [], "sub_entries": ["schoolwork['skul.w3k]n.学业（不可数）"]}, {"num": 19, "word": "keep on...", "phonetic": "", "pos": "短语", "meaning": "继续...", "examples": [{"en": "I helped my mother keep an eye on my little sister when she went shopping.", "zh": "我母亲去购物时，我帮忙照顾小妹。"}], "sub_entries": []}], "grammar": {"intro": "本课介绍及物动词provide及名词influence的用法。", "items": [{"num": 1, "title": "provide+人+with+物", "body": ["提供某人某物", "=supply+人+with+物", "例: I'll provide you everything (that) you need.（×)", "→ I'll provide you with everything(that）you need. (○)", "=I'll supply_you with everything (that) you need.（我会提供你所需要的一切。）同理：Television provides us a wide range of information and entertainment.（x）", "→ Television provides us with a wide range of information and entertainment.（电视给我们提供广泛的信息和娱乐。）"]}, {"num": 2, "title": "influence, impact, effect 与介词 on 的搭配用法", "body": ["influence、impact['ɪmpækt]、effect[ɪ'fɛkt] 均要与介词 on 并用，形成固定的动词短语搭配。", "have a good/bad/deep influence|on+人或事物 effect impact 对某人或某事物有好的／坏的／很深的影响", "例: The students' naughty behavior had a bad influence on the newstudent.（那些学生顽皮的行为对那位新来的学生有不良 的影响。）", "同理：However, it's a pity that it may also have a bad influence on young minds.（不过，遗憾的是，它也会对年轻人的思想有不 良的影响。）"]}]}, "substitution": [{"num": 1, "pairs": [{"en": "Television provides us with a wide range of informationand entertainment.", "zh": "电视给我们提供广泛的信息和娱乐。"}, {"en": "Harry's company has provided him with a car.", "zh": "哈里的公司提供一部车子供他使用。"}, {"en": "We will supply you with all the tools you need to do the job.", "zh": "我们将为你提供完成这项工作所需的所有工具。"}], "en": "Television provides us with a wide range of informationand entertainment.", "zh": "电视给我们提供广泛的信息和娱乐。"}, {"num": 2, "pairs": [{"en": "It's a pity that it may also have a bad influence on young minds.", "zh": "遗憾的是，它也会对年轻人的思想有不良的影响。"}, {"en": "Working on a farm last summer had a good influence on Mack.", "zh": "去年夏天在农场上工作对迈克有良好的影响。"}, {"en": "Their divorce had a bad effect on the children.", "zh": "他们的离婚对其孩子有不良的影响。"}], "en": "It's a pity that it may also have a bad influence on young minds.", "zh": "遗憾的是，它也会对年轻人的思想有不良的影响。"}], "exercises": null}, {"num": 148, "title_en": "Hurry Back", "title_zh": "快点回来", "type": "dialogue", "category": "情境实战会话", "reading": null, "dialog": {"turns": [{"speaker_en": "Shella", "speaker_zh": "席拉", "en": "Hey, Stan, can you do me a favor?", "zh": "嘿，斯坦，你可以帮我一个忙吗？"}, {"speaker_en": "Stan", "speaker_zh": "斯坦", "en": "Sure. What is it?", "zh": "当然可以。什么忙？"}, {"speaker_en": "Shella", "speaker_zh": "席拉", "en": "Can you keep an eye on the kids while I go to the doctor's?", "zh": "你可以在我去看医生时帮我看一下小孩吗？"}, {"speaker_en": "Stan", "speaker_zh": "斯坦", "en": "OK, but hurry back!", "zh": "好，但快一点回来！"}]}, "vocab": [{"num": 1, "word": "hurry back", "phonetic": "", "pos": "短语", "meaning": "迅速回来", "examples": [{"en": "Hurry up! We're late for school.", "zh": "快点！我们上学就要迟到了。"}], "sub_entries": ["hurry['h3r]vi.赶快（常与副词up并用）"]}, {"num": 2, "word": "do+", "phonetic": "", "pos": "", "meaning": "人 +a favor", "examples": [{"en": "A: Can you do me a favor? B: No problem. A: Can you lend me $10?", "zh": "甲：你可以帮我·个忙吗？）（乙：没问题。）（甲：你可以借我美金十块钱吗？"}], "sub_entries": ["帮某人·个忙", "favor[fev] n.恩惠"]}, {"num": 3, "word": "...while I go to the doctor's?", "phonetic": "", "pos": "日常口语", "meaning": "在我去看医生时...？", "examples": [{"en": "I go to the barber's once a month.", "zh": "我每个月去理发店一次。"}], "sub_entries": ["=...while I go to the doctor's office?", "在英语中，有the引导的所有格，若很清楚地表示出", "某人的职业时，其后表示上班场所的名词可予省略。", "常用的此类所有格有下列数个：", "the doctor's office → the doctor's", "医生诊疗室", "the dentist's clinic -→the dentist's", "牙医诊所", "the barber's shop → the barber's", "理发店", "the butcher's shop → the butcher's", "肉店"]}], "grammar": null, "substitution": [], "exercises": {"prompt": "Ⅲ·请选出下列各句中正确的一项", "questions": ["1. Felix", "enough money to play video games", "for an hour.", "(A) provided with", "(B) provided us with", "(C) provided Felix with (D) provided us", "2.Chuck's hard work has had a", "his grades.", "(A) bad effect in", "(B) bad influence on", "(C) good effect on", "(D) good influence in", "3. Bob kept an eye on his younger brother. This", "sentence means", "(A) Bob watched his younger brother with one", "eye", "(B) Bob put an eye on his brother", "(C) Bob kept his brother", "(D） Bob watched his younger brother", "4.Mikehadastomachache,sohewenttothe", "(A) dentist's clinic", "(B) doctors", "(C) doctor's office", "(D) doctors clinic", "5. My friend, Chris, is", "smoking cigarettes.", "(A) addicted to", "(B) addicted with", "(C) addicting to", "(D) addicted at", "6. The teacher said to Billy. \"you're", "by", "letting him copy your homework.\"", "(A) doing Jack a favor", "(B) not doing Jack a favor", "(C) not giving him a favor", "(D) making him a big favor"], "answers": ["解答>1.(B）2.(C）3.(D）4.(C）5.(A）6.(B)"]}}, {"type": "song", "id": "song_08", "title_en": "Be My Baby", "title_zh": "作我的宝贝", "lyrics": [{"en": "The night we met, I knew I needed you so. And if I had the chance, I'd never let you go. So won't you say you love me? I'll make you so proud of me. We'll make them turn their heads every place we go. So won't you please (be my, be my baby) be my little baby? (my heart and only baby) Say you'll be my darling, (be my, be my baby) be my baby now. Oh... I'll make you happy, baby; just wait and see. For every kiss you give me, I'll give you three. Oh, since the day I saw you, I have been waiting for you. You know I will adore you till eternity.", "zh": "当我们相遇的那晚，我便知道自己是如此地需要你。如果我有机会的话：我绝对不会让你离开我。因此，何不说你爱我呢？我将会使你以我为荣。不论我们走到哪里，我们将使人们注意我们。因此，请你作我的宝贝好吗？现在就告诉我你是我的宝贝。哦·..….亲爱的，等着瞧，我将会使你快乐。如果你对我好，我会加倍地对你更好。噢，自从我认识你那天起，我便始终等待着你。你知道我将永远地爱慕你。"}], "category": "经典英文金曲赏析"}];